void AutomationEngineTests::gotoCrossCompetitionRequiresNeutralAndAbortsOwnedShot()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.minimumHoldMs = 0.0;
    engine.applyConfig(config, LearningData{});

    ControllerState crossUp;
    crossUp.buttons |= XINPUT_GAMEPAD_A;
    crossUp.rightStickY = -127;
    ControllerState output = engine.process(crossUp);
    engine.advanceTestClock(300.0);
    output = engine.process(crossUp);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.shotsAttempted(), 0);
    QVERIFY((output.buttons & XINPUT_GAMEPAD_A) != 0);
    QCOMPARE(output.rightStickY, crossUp.rightStickY);

    // Releasing Cross while the same RS-up remains held is not a fresh Go-To.
    ControllerState up = crossUp;
    up.buttons &= ~XINPUT_GAMEPAD_A;
    engine.advanceTestClock(300.0);
    output = engine.process(up);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.shotsAttempted(), 0);
    QCOMPARE(output.rightStickY, up.rightStickY);

    // Three genuine neutral polls close the competing gesture. A later deliberate
    // RS-up remains fully functional and may be owned normally.
    ControllerState neutral;
    engine.process(neutral);
    engine.process(neutral);
    engine.process(neutral);
    output = engine.process(up);
    engine.advanceTestClock(270.0);
    output = engine.process(up);
    QCOMPARE(engine.context().mode, ShotMode::GoToStick);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.shotsAttempted(), 1);

    QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
    output = engine.process(crossUp);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("goto_competing_cross_abort"));
    QCOMPARE(aborted.count(), 1);
    QCOMPARE(engine.shotsReleased(), 0);
    QVERIFY2((output.buttons & XINPUT_GAMEPAD_A) != 0,
             "aborting a competing Go-To must preserve the user's Cross command");
}

