void AutomationEngineTests::classifiesLeftAndRightFadeDistinctly()
{
    // A fade is ALWAYS a Left or Right fade (corner/wing/top-of-key all reduce to a side),
    // keyed on the HORIZONTAL stick sign. The "up a little" the player adds is part of every
    // fade, NOT a separate shot — so an up-DOMINANT fade still buckets by its left/right sign
    // (previously these became bogus "Back/Front Fade" buckets that mixed left+right fades and
    // fragmented per-type calibration). The bot can't see court position from the controller,
    // so Left Fade / Right Fade / Standstill are the only meaningful buckets here.
    auto fadeTypeFor = [](int leftX, int leftY) -> QString {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        LearningData learning;
        engine.applyConfig(config, learning);
        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        physical.leftStickX = leftX;
        physical.leftStickY = leftY;
        engine.process(physical);
        engine.advanceTestClock(220);
        engine.process(physical);
        return engine.context().shotType;
    };
    QCOMPARE(fadeTypeFor(-100, 0), QStringLiteral("Left Fade"));
    QCOMPARE(fadeTypeFor(100, 0), QStringLiteral("Right Fade"));
    // up-dominant fades (stick up = negative Y) still classify by left/right, not Back/Front.
    QCOMPARE(fadeTypeFor(-40, -100), QStringLiteral("Left Fade"));
    QCOMPARE(fadeTypeFor(40, -100), QStringLiteral("Right Fade"));
    QCOMPARE(fadeTypeFor(40, 100), QStringLiteral("Right Fade"));
    QCOMPARE(fadeTypeFor(0, 0), QStringLiteral("Standstill"));     // no deflection
}

void AutomationEngineTests::greenTrackerAdaptiveTargetByWidth()
{
    // Exercise the width-adaptive target THROUGH the engine (GreenWindowTracker is
    // internal): drive a standstill hold, feed several green-window samples of a
    // given width to confirm the window, and read back the chosen release target.
    auto targetForGreen = [](double gs, double ge) -> double {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.maximumHoldMs = 4000.0;
        LearningData learning;
        engine.applyConfig(config, learning);

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        engine.process(physical);
        engine.advanceTestClock(220);
        engine.process(physical);
        engine.advanceTestClock(160);  // past commit
        // Constant mid fill (no velocity/eta) so only the confirmed green window
        // drives the target; feed enough frames to confirm it.
        double target = -1.0;
        for (int i = 0; i < 6; ++i) {
            DetectionResult r = readyMeterSample(60.0);
            r.greenStartPct = gs;
            r.greenEndPct = ge;
            r.greenCenterPct = (gs + ge) * 0.5;
            r.velocityPctS = 0.0;
            r.etaToGreenMs = -1.0;
            engine.updateDetection(r);
            engine.process(physical);
            target = engine.context().targetPct;
        }
        return target;
    };

    // DEAD-TOP for ALL widths: both aim the window's TOP EDGE (the contest-invariant make-point).
    // Wide window 88-98 -> top edge 98 (was center ~93).
    const double wideTarget = targetForGreen(88.0, 98.0);
    QVERIFY2(std::abs(wideTarget - 98.0) < 1.5,
             qPrintable(QStringLiteral("dead-top: wide green should target the top edge ~98, got %1").arg(wideTarget)));

    // Miniscule window 95-98 -> top edge 98 too (no width-based split anymore).
    const double narrowTarget = targetForGreen(95.0, 98.0);
    QVERIFY2(std::abs(narrowTarget - 98.0) < 1.5,
             qPrintable(QStringLiteral("dead-top: miniscule green should target the top edge ~98, got %1").arg(narrowTarget)));
}

void AutomationEngineTests::goToWaitsForLateMeterThenTimes()
{
    // Go-To: the signature animation surfaces the meter only after a long wind-up.
    // The bot must KEEP HOLDING the stick (no release, no abort) while waiting, then
    // time the release once the meter actually appears — never dump it early.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.rightStickY = -127;
    auto output = engine.process(physical);
    engine.advanceTestClock(270);
    output = engine.process(physical);
    QCOMPARE(engine.context().mode, ShotMode::GoToStick);

    // Past the go-to commit floor with NO meter yet: still holding the stick up,
    // awaiting the meter (the old build would have dumped at ~1470ms).
    engine.advanceTestClock(900);
    output = engine.process(physical);
    QCOMPARE(output.rightStickY, -127);
    QVERIFY2(engine.context().state == HoldState::Holding, "go-to must keep holding while awaiting the meter");
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("await_meter"));

    // The meter finally surfaces, imminent -> the bot times the release.
    engine.updateDetection(readyMeterSample(94.0, 1.0));
    output = engine.process(physical);
    QVERIFY(engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown);
    QCOMPARE(output.rightStickY, 127);  // [ORION_GOTO_DOWN_FLICK] mirrored DOWN flick
    QVERIFY(engine.context().releaseReasonCode != QStringLiteral("max_hold_safety"));
}

void AutomationEngineTests::contestedNoGreenTimesMeterToTop()
{
    // Contested shot: the green window shrinks to nothing. The bot must NOT wait for
    // a green window that won't appear — it times the meter FULLY to the top
    // ("the make point") and releases predictively before it pins at 100%.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 2000.0;  // keep max-hold out of the way
    LearningData learning;
    engine.applyConfig(config, learning);

    auto noGreenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill);
        r.greenStartPct = -1.0;
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.etaToGreenMs = -1.0;  // no ETA hint — engine must derive timing itself
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);  // past commit
    engine.process(physical);

    double releaseFill = -1.0;
    QString reason, reasonCode;
    for (double fill = 40.0; fill <= 99.0; fill += 4.0) {
        engine.updateDetection(noGreenSample(fill));
        engine.process(physical);
        if (engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown) {
            releaseFill = engine.context().releaseFillPct;
            reason = engine.context().releaseReason;
            reasonCode = engine.context().releaseReasonCode;
            break;
        }
        engine.advanceTestClock(10);
    }

    QVERIFY2(releaseFill >= 0.0, "contested shot never released");
    QVERIFY2(reason.contains(QStringLiteral("meter_full")),
             qPrintable(QStringLiteral("no-green shot must target meter_full; reason=%1").arg(reason)));
    QCOMPARE(reasonCode, QStringLiteral("predictive_target"));
    QVERIFY2(releaseFill < 100.0, qPrintable(QStringLiteral("must release before pinning at 100%%, got %1").arg(releaseFill)));
    QVERIFY2(releaseFill > 45.0, qPrintable(QStringLiteral("should fill up toward the top (predictive lead releases before 100), got %1").arg(releaseFill)));
}

void AutomationEngineTests::replayedRisingTrajectoryReleasesInsideWindow()
{
    // Integration: feed a realistic RISING fill trajectory (modelled on the real
    // video's measured shot-1 curve — fill sweeps up into a green window at
    // ~94-98%) through the engine frame-by-frame and assert it releases via a
    // TIMED path BEFORE the meter pins at 100% — i.e. it actually times the shot
    // instead of dumping at max-hold. This exercises the engine's own velocity /
    // green-window math, not a hand-fed eta.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 2000.0;  // high so max-hold can't be the path that fires
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    auto risingSample = [](double fill) {
        DetectionResult r;
        r.detected = true;
        r.style = QStringLiteral("Arrow2");
        r.colorName = QStringLiteral("Purple");
        r.detectorSource = QStringLiteral("sidecar-fusion");
        r.x = 940; r.y = 420; r.width = 26; r.height = 120;
        r.fillPct = fill;
        r.confidence = 0.95;
        r.consecutiveFrames = 3;
        r.greenStartPct = 94.0;
        r.greenEndPct = 98.0;
        r.greenCenterPct = 96.0;
        r.greenConfidence = 0.9;
        r.etaToGreenMs = -1.0;         // force engine to derive timing itself
        r.frameAgeMs = 6.0;
        return r;
    };

    double releaseFill = -1.0;
    QString reason;
    // ~40% -> ~99% over a sequence of frames; release should land before the top.
    for (double fill = 40.0; fill <= 99.0; fill += 4.0) {
        engine.updateDetection(risingSample(fill));
        engine.process(physical);
        if (engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown) {
            releaseFill = engine.context().releaseFillPct;
            reason = engine.context().releaseReasonCode;
            break;
        }
        engine.advanceTestClock(10);
    }

    QVERIFY2(releaseFill >= 0.0, "engine never released across the rising trajectory");
    // A TIMED release, not the max-hold dump.
    QVERIFY2(reason == QStringLiteral("green_confirmed") || reason == QStringLiteral("predictive_target")
                 || reason == QStringLiteral("reactive_target"),
             qPrintable(QStringLiteral("unexpected reason code: %1").arg(reason)));
    QVERIFY2(reason != QStringLiteral("max_hold_safety"), "released via max-hold instead of timing the shot");
    // Released within/around the meter's green window, not pinned at 100%.
    QVERIFY2(releaseFill < 100.0, qPrintable(QStringLiteral("release fill pinned at top: %1").arg(releaseFill)));
}

void AutomationEngineTests::fastMeterCapsPredictiveReleaseNearTop()
{
    // Per-shot-type spread fix: a FAST-filling meter must NOT predictively release
    // far below the target. The reachability cap (maxPredictiveRisePct +
    // reachabilitySlackPct, ~31%) bounds how far below target a predictive release
    // may fire, so a fast meter waits until it is near the top (where it caps into
    // the green band) instead of firing ~40-57% below green and landing short.
    // This is the live "standstill releases ~57% and misses" signature.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 4000.0;  // keep max-hold out of the way
    LearningData learning;
    engine.applyConfig(config, learning);
    const RemapConfig cfg = engine.config();
    // This is a SQUARE (non-Go-To) shot, so the raised non-Go-To clamp applies.
    const double ceiling = cfg.nonGotoMaxPredictiveRisePct + cfg.reachabilitySlackPct;
    const double oldGotoCeiling = cfg.maxPredictiveRisePct + cfg.reachabilitySlackPct;  // 31

    auto noGreenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill);
        r.greenStartPct = -1.0;  // contested -> target is the meter top (100)
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.etaToGreenMs = -1.0;   // force the engine to derive timing itself
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    // FAST rise: big fill steps with short gaps -> high velocity, so velocity*lead
    // exceeds the cap and the reachability ceiling (not the velocity path) is what
    // bounds the release. Without the cap this would fire ~40-50% below the top.
    double releaseFill = -1.0;
    QString reasonCode;
    for (double fill = 30.0; fill <= 100.0; fill += 10.0) {
        engine.updateDetection(noGreenSample(fill));
        engine.process(physical);
        if (engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown) {
            releaseFill = engine.context().releaseFillPct;
            reasonCode = engine.context().releaseReasonCode;
            break;
        }
        engine.advanceTestClock(8);
    }

    QVERIFY2(releaseFill >= 0.0, "fast meter never released");
    QCOMPARE(reasonCode, QStringLiteral("predictive_target"));
    // Still BOUNDED by the (raised) non-Go-To ceiling — a fast meter must not dump wildly
    // low; it stays within ceiling (+ one fast-frame's slack) of the 100% target.
    QVERIFY2(releaseFill >= (100.0 - ceiling - 12.0),
             qPrintable(QStringLiteral("fast meter released too far below target: fill=%1, ceiling=%2")
                            .arg(releaseFill).arg(ceiling)));
    QVERIFY2(releaseFill < 100.0,
             qPrintable(QStringLiteral("must release before pinning at 100%%, got %1").arg(releaseFill)));
    // THE FIX: the raised non-Go-To clamp lets a Standstill release EARLIER than the old
    // Go-To target-31 floor (which the +80 A/B proved lands LATE). So the release fill must
    // be BELOW 100-oldGotoCeiling (i.e. it fired past where the old cap would have pinned it).
    QVERIFY2(releaseFill < (100.0 - oldGotoCeiling),
             qPrintable(QStringLiteral("raised non-Go-To cap should release earlier than the old "
                                       "target-31 floor; fill=%1 oldFloor=%2")
                            .arg(releaseFill).arg(100.0 - oldGotoCeiling)));
}

void AutomationEngineTests::nonGotoPredictiveRespectsHardFloor()
{
    // The raised non-Go-To clamp must NOT let a predictive/green release fire at absurd low
    // fill: a hard absolute floor (nonGotoMinPredictiveFillPct) blocks it regardless of how
    // small the target-gap is. Uses a LOW confirmed green (center 60) so target-gap is small
    // even at low fill — isolating the floor (the gap alone would otherwise allow release).
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    LearningData learning;
    engine.applyConfig(config, learning);
    const double floor = engine.config().nonGotoMinPredictiveFillPct;  // 42

    // Comfortably-wide green centered at 60 (start 55, end 65, width 10 >= visibleGreenWidthPct
    // 8 -> target = center 60). Caller supplies the fill.
    auto greenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill, 2.0);
        r.greenStartPct = 55.0;
        r.greenEndPct = 65.0;
        r.greenCenterPct = 60.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    // Fill 35 is BELOW the hard floor (42) but its gap to target 60 (=25) is within the
    // reachability ceiling — so ONLY the floor can block it. Confirm green + keep holding.
    for (int i = 0; i < 5; ++i) {
        engine.updateDetection(greenSample(35.0));
        engine.process(physical);
        QVERIFY2(engine.context().state == HoldState::Holding,
                 "predictive release must be blocked below the hard floor even when target-gap is small");
        engine.advanceTestClock(20);
    }
    QVERIFY2(engine.context().fillPct < floor, "test setup: fill should be below the floor");

    // Now the meter rises above the floor -> the predictive/green path is unblocked.
    engine.updateDetection(greenSample(48.0));
    engine.process(physical);
    QVERIFY2(engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown,
             "above the hard floor and within reach, the shot should release");
}

void AutomationEngineTests::holdingFramesReportHonestWaitingCode()
{
    // Telemetry honesty (TASK T1, do #4): while the engine is still HOLDING, the
    // machine-readable releaseReasonCode must describe a WAITING state, never claim
    // a release path fired. The predictive blocks set green_confirmed /
    // predictive_target / reactive_target as a SIDE EFFECT of evaluating each path —
    // even on frames where shouldRelease stayed false (e.g. the meter is within
    // reach but the velocity-extrapolated crossing is still > one lead away). The
    // code resets to "tracking" each frame, so leaving that release code in place on
    // a non-releasing frame falsely tells live telemetry a release fired while the
    // bot is merely waiting. Across a full rising trajectory, EVERY holding frame
    // must report a waiting code; only the releasing frame may report a release code.
    auto isReleaseCode = [](const QString& code) {
        return code == QStringLiteral("green_confirmed")
            || code == QStringLiteral("predictive_target")
            || code == QStringLiteral("reactive_target")
            || code == QStringLiteral("max_hold_safety")
            || code == QStringLiteral("timeout_fallback");
    };

    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;        // keep max-hold safety out of the way
    config.tempoFallbackTimeoutMs = 5000.0;  // keep the tempo timeout out of the way
    LearningData learning;
    // Unarmed hold-start clock so the meter's velocity/predictive path governs the release (the path
    // whose side-effect code this test guards); kFeedforwardDefaults=460 would otherwise fire first.
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor

    // SLOW rise (small steps, long gaps) so the meter spends several frames WITHIN
    // reach of the target before the velocity path's crossing falls inside one lead
    // and fires. ETA is disabled (-1) so the velocity path — not the imminent-ETA
    // path — governs timing; that is the path whose side-effect code we are guarding.
    bool released = false;
    bool sawHoldingFrame = false;
    QString releaseCode;
    for (double fill = 40.0; fill <= 99.0; fill += 1.0) {
        engine.updateDetection(readyMeterSample(fill, -1.0));
        engine.process(physical);
        const QString code = engine.context().releaseReasonCode;
        if (engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown) {
            released = true;
            releaseCode = code;
            break;
        }
        sawHoldingFrame = true;
        QVERIFY2(!isReleaseCode(code),
                 qPrintable(QStringLiteral("holding frame falsely reported release code '%1' at fill=%2")
                                .arg(code).arg(fill)));
        engine.advanceTestClock(30);
    }

    QVERIFY2(sawHoldingFrame, "engine never spent a frame holding the meter");
    QVERIFY2(released, "engine never released across the rising trajectory");
    QVERIFY2(isReleaseCode(releaseCode),
             qPrintable(QStringLiteral("release frame reported a non-release code: %1").arg(releaseCode)));
}

void AutomationEngineTests::holdingReportsOutOfReachWhenMeterBelowCap()
{
    // Honest waiting telemetry (TASK T1, do #4) for the reachability cap (do #2):
    // when a fresh, confident meter is still further below the target than the
    // reachability cap allows a predictive release, the bot is waiting SPECIFICALLY
    // because of that cap. The machine-readable code must say so (out_of_reach), not
    // the generic eta_not_ready — so live telemetry can confirm the cap is holding a
    // (fast) meter back near the top instead of firing early and landing short.
    // Telemetry-only: this asserts the holding frame's code, not any timing change.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;           // keep max-hold safety out of the way
    config.tempoFallbackTimeoutMs = 5000.0;  // keep the tempo timeout out of the way
    LearningData learning;
    engine.applyConfig(config, learning);

    // Fresh + confident, but stuck far below the target with ~no velocity, so the
    // expected velocity*lead rise stays tiny and the meter sits well outside the
    // reachability ceiling (target 100 - fill 40 = 60% >> cap + slack). No green ->
    // contested -> target is the meter top (100).
    auto farLowSample = []() {
        DetectionResult r = readyMeterSample(40.0);
        r.greenStartPct = -1.0;
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.velocityPctS = 0.0;
        r.etaToGreenMs = -1.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    // First sample latches meterSeen; the second keeps it fresh while velocity stays
    // ~0 (two samples at the same fill), so the meter never climbs within reach.
    engine.updateDetection(farLowSample());
    engine.process(physical);
    engine.updateDetection(farLowSample());
    engine.process(physical);

    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("out_of_reach"));
}

void AutomationEngineTests::holdingStaleSampleReportsDistinctReason()
{
    // Honest waiting telemetry (TASK T1, do #4): a meter that WAS seen this shot but
    // whose latest sample has gone stale must report a reason distinct from the
    // never-saw-a-meter await_meter path. Both keep holding, but the machine code
    // (stale_sample vs await_meter) AND the human-readable reason must differ, so
    // live telemetry can tell "meter went stale mid-shot" apart from "meter never
    // appeared". Telemetry-only: asserts the holding frame's reason/code, no timing.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;           // keep max-hold safety out of the way
    config.tempoFallbackTimeoutMs = 5000.0;  // keep the tempo timeout out of the way
    LearningData learning;
    engine.applyConfig(config, learning);

    // Far below target, no green (contested -> target 100), so the fresh frame only
    // latches meterSeen and never releases (well outside the reachability cap).
    auto farLowSample = []() {
        DetectionResult r = readyMeterSample(40.0);
        r.greenStartPct = -1.0;
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.velocityPctS = 0.0;
        r.etaToGreenMs = -1.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    // Fresh sample latches meterSeenThisShot (passing the await_meter early return).
    engine.updateDetection(farLowSample());
    engine.process(physical);
    QVERIFY(engine.context().meterDetected);

    // Let the sample age past meterFreshWindowMs (220) WITHOUT a new detection, then
    // process: meterDetected/meterSeenThisShot stay true but meterFresh is now false.
    engine.advanceTestClock(260);
    engine.process(physical);

    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("stale_sample"));
    QCOMPARE(engine.context().releaseReason, QStringLiteral("meter_sample_stale"));
    // Must NOT collide with the never-saw-a-meter await_meter path's reason text.
    QVERIFY2(engine.context().releaseReason != QStringLiteral("waiting_for_meter"),
             "stale-sample reason must differ from the await_meter waiting_for_meter text");
}

void AutomationEngineTests::greenConfirmedCrossingReportsGreenConfirmedCode()
{
    // Telemetry honesty (TASK T1, do #4): the BEST release path — a CONFIRMED green
    // window with the meter crossing the target inside one release lead — must report
    // the green_confirmed code, distinct from the velocity-only predictive_target /
    // reactive_target and the safety max_hold_safety paths. predictive_target,
    // max_hold_safety, out_of_reach, stale_sample and await_meter each already have a
    // dedicated pinning test; green_confirmed (listed FIRST in do #4's distinguish
    // list) did not. This pins it. Behavior-free: it asserts only the reported code.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;           // keep max-hold safety out of the way
    config.tempoFallbackTimeoutMs = 5000.0;  // keep the tempo timeout out of the way
    LearningData learning;
    engine.applyConfig(config, learning);

    // A comfortably-wide green window (86-98, width 12 >= visibleGreenWidthPct 8) so
    // the confirmed release target is its CENTER (92) — well-defined and below the
    // meter top. ETA disabled (-1) so the detector-ETA path can't fire; the confirmed
    // green-window crossing is the only release route. Caller supplies the fill.
    auto greenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.greenStartPct = 86.0;
        r.greenEndPct = 98.0;
        r.greenCenterPct = 92.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    // Confirm the green window with several consistent frames while the fill sits
    // BELOW the target (constant 70 -> ~zero velocity, so neither the predictive nor
    // the reactive path can fire yet). The tracker confirms after 3 consistent green
    // frames; 5 leaves margin. The bot must keep HOLDING throughout.
    for (int i = 0; i < 5; ++i) {
        engine.updateDetection(greenSample(70.0));
        engine.process(physical);
        QVERIFY2(engine.context().state == HoldState::Holding,
                 "must keep holding while the fill is below the confirmed green target");
        engine.advanceTestClock(20);
    }

    // The fill now reaches the confirmed green target. With the window confirmed and
    // the meter at/over the predicted crossing, the best path (block 1) fires and
    // labels the release green_confirmed.
    engine.updateDetection(greenSample(96.0));
    engine.process(physical);

    QVERIFY(engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("green_confirmed"));
    QVERIFY2(engine.context().releaseReasonCode != QStringLiteral("predictive_target"),
             "best-path release must be labelled green_confirmed, not the velocity-only path");
}

void AutomationEngineTests::greenConfirmsAtThreeFreshFramesAcrossDropout()
{
    // Live (2026-06-05) consistency fix: the Arrow2 Purple green window is only ~30-40 ms
    // wide, so the old 2-stable-frame gate (= 4 fresh green readings) frequently failed to
    // confirm before the fast meter forced a meter_full release — the "bot didn't time it"
    // late shots. Confirmation now reaches at 1 stable frame (3 fresh green readings), and a
    // roi_not_found dropout must NOT reset the streak (update() isn't called on a non-fresh
    // sample), so 3 readings split by a single missed frame still confirm. This pins both:
    // (a) green confirms at 3 fresh frames, not 4, and (b) a dropout in the middle is bridged.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;           // keep max-hold safety out of the way
    config.tempoFallbackTimeoutMs = 5000.0;  // keep the tempo timeout out of the way
    LearningData learning;
    engine.applyConfig(config, learning);

    // Same comfortably-wide green window (86-98, center 92) as the sibling test; ETA off.
    auto greenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.greenStartPct = 86.0;
        r.greenEndPct = 98.0;
        r.greenCenterPct = 92.0;
        return r;
    };
    // A roi_not_found dropout: detected=false -> NOT a fresh accept -> greenTracker_.update()
    // is skipped, so the streak is neither advanced nor reset by this frame.
    DetectionResult dropout;
    dropout.detected = false;
    dropout.style = QStringLiteral("Arrow2");
    dropout.profileName = QStringLiteral("Arrow2");
    dropout.colorName = QStringLiteral("Purple");
    dropout.rejectionReason = QStringLiteral("roi_not_found");
    dropout.fillPct = 0.0;
    dropout.confidence = 0.0;
    dropout.greenStartPct = -1.0;
    dropout.greenEndPct = -1.0;
    dropout.greenCenterPct = -1.0;

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    // EXACTLY three fresh green readings (fill held below the green target so no
    // predictive/reactive path can fire), with a dropout between the 2nd and 3rd. Under
    // the old 4-reading gate this never confirmed; it must confirm now.
    engine.updateDetection(greenSample(70.0));   // fresh 1
    engine.process(physical);
    engine.advanceTestClock(20);
    engine.updateDetection(greenSample(70.0));   // fresh 2
    engine.process(physical);
    engine.advanceTestClock(20);
    engine.updateDetection(dropout);             // roi_not_found — must not reset the streak
    engine.process(physical);
    QVERIFY2(engine.context().state == HoldState::Holding,
             "a single roi_not_found dropout must not release or abort the shot");
    engine.advanceTestClock(20);
    engine.updateDetection(greenSample(70.0));   // fresh 3 -> green confirms (1 stable frame)
    engine.process(physical);
    QVERIFY2(engine.context().state == HoldState::Holding,
             "fill still below the green target -> keep holding (no release yet)");

    // THE FIX: green is CONFIRMED after only 3 fresh green readings — and the 2nd and 3rd
    // were split by a roi_not_found dropout. Under the old 2-stable-frame gate this needed a
    // 4th reading and would still be unconfirmed here, so the engine would target meter_full
    // and release late (the live "didn't time it" shots). The attribution snapshot is stamped
    // every holding frame BEFORE the release blocks (AutomationEngine.cpp:1007), so it exposes
    // the tracker state directly, without coupling to the velocity/crossing release path.
    QVERIFY2(engine.context().greenConfirmedAtRelease,
             "green must confirm at 3 fresh readings, bridging a single roi_not_found dropout");
    QCOMPARE(engine.context().targetModeAtRelease, QStringLiteral("green_tip"));  // dead-top for all widths
}

void AutomationEngineTests::greenConfirmedReleaseStampsAttributionSnapshot()
{
    // DIAGNOSTIC instrumentation pin (NO behavior change): a CONFIRMED-green release must stamp the
    // path-attribution snapshot consistently with the block it took AND keep the same release code.
    // The snapshot is mode-agnostic (stamped in processHolding before the release blocks), so a
    // Square shot validates the exact fields a live Go-To logs on the "Release attribution:" line.
    // Mirrors greenConfirmedCrossingReportsGreenConfirmedCode (green 86-98, width 12 -> center).
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    auto greenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.greenStartPct = 86.0;
        r.greenEndPct = 98.0;
        r.greenCenterPct = 92.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    for (int i = 0; i < 5; ++i) {      // confirm green while fill sits below target
        engine.updateDetection(greenSample(70.0));
        engine.process(physical);
        engine.advanceTestClock(20);
    }
    engine.updateDetection(greenSample(96.0));  // cross the target -> block 1 fires
    engine.process(physical);

    const ShotContext ctx = engine.context();
    QVERIFY(ctx.state == HoldState::Releasing || ctx.state == HoldState::Cooldown);
    // Behavior unchanged: the read-only snapshot did NOT re-route the release.
    QCOMPARE(ctx.releaseReasonCode, QStringLiteral("green_confirmed"));
    // Snapshot agrees with the green block: confirmed, width-12 window -> dead-top (green_tip) target.
    QVERIFY2(ctx.greenConfirmedAtRelease,
             "green_confirmed release must stamp greenConfirmedAtRelease=true");
    QCOMPARE(ctx.targetModeAtRelease, QStringLiteral("green_tip"));  // dead-top for all widths now
    QVERIFY2(ctx.greenWidthAtReleasePct > 8.0,
             "confirmed-green width must be recorded");
    QVERIFY2(ctx.greenConfirmFillPct >= 0.0,
             "tracker confirmed this shot -> greenConfirmFillPct must be recorded, not -1");
    QVERIFY2(ctx.withinReachAtRelease, "a fired green release must record withinReach=true");
}

void AutomationEngineTests::predictiveTargetReleaseStampsMeterFullAttribution()
{
    // DIAGNOSTIC instrumentation pin (NO behavior change): a no-green velocity (predictive_target)
    // release must stamp greenConfirmed=false / targetMode=meter_full / greenConfirmFill=-1 (the
    // tracker never confirmed), record a positive engine velocity, and keep the same release code.
    // This is the seq6-style Go-To path; the snapshot is mode-agnostic, so a fast Square meter pins
    // it deterministically. Mirrors fastMeterCapsPredictiveReleaseNearTop.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 4000.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    auto noGreenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill);
        r.greenStartPct = -1.0;  // contested -> target is the meter top (meter_full)
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.etaToGreenMs = -1.0;   // force the engine to derive timing itself
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);                 // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);                 // past the standstill commit floor
    engine.process(physical);

    bool released = false;
    for (double fill = 30.0; fill <= 100.0; fill += 10.0) {
        engine.updateDetection(noGreenSample(fill));
        engine.process(physical);
        if (engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown) {
            released = true;
            break;
        }
        engine.advanceTestClock(8);
    }

    const ShotContext ctx = engine.context();
    QVERIFY2(released, "fast no-green meter never released");
    // Behavior unchanged: same predictive path, same code.
    QCOMPARE(ctx.releaseReasonCode, QStringLiteral("predictive_target"));
    // Snapshot agrees with the no-green velocity block.
    QVERIFY2(!ctx.greenConfirmedAtRelease,
             "no-green release must stamp greenConfirmedAtRelease=false");
    QCOMPARE(ctx.targetModeAtRelease, QStringLiteral("meter_full"));
    QVERIFY2(ctx.greenConfirmFillPct < 0.0,
             "tracker never confirmed -> greenConfirmFillPct must stay -1");
    QVERIFY2(ctx.releaseVelocityPctMs > 0.0,
             "predictive release must record a positive engine velocity");
    QVERIFY2(ctx.withinReachAtRelease, "a fired predictive release must record withinReach=true");
}

void AutomationEngineTests::timeoutFallbackReleasesWithDistinctReasonCode()
{
    // Telemetry honesty (TASK T1, do #4/#5): the tempo-timeout SAFETY release is its
    // own labelled path. A button shot whose meter HAS surfaced but stays stuck below
    // target (no green, no velocity, no ETA) must, after holding past
    // tempoFallbackTimeoutMs, release via timeout_fallback — distinct from the
    // post-meter max_hold_safety ceiling and from the predictive paths. Every other
    // release/waiting code (green_confirmed, predictive_target, reactive_target,
    // max_hold_safety, await_meter, stale_sample, out_of_reach, confidence_low) already
    // has a dedicated pin; the tempo timeout did not. The earlier reachability-cap +
    // meter-gating timing changes alter WHICH path a stuck shot falls through to, so
    // pinning the label guards against a regression that silently re-routes it.
    // Behavior-free: it asserts only the reported code on the release frame.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 300.0;  // tempo timeout fires well before...
    config.maximumHoldMs = 5000.0;          // ...the post-meter max-hold ceiling
    LearningData learning;
    // Unarmed hold-start clock so the tempo timeout_fallback path is reached (kFeedforwardDefaults
    // would otherwise seed Standstill=460 and preempt it with feedforward_target).
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    // Stuck ABOVE the non-Go-To min-fill floor (70) and NOT recoverable (stale_or_memory,
    // lastSampleFreshAccept=false; no green/velocity/ETA) so recoverableOrRising is false
    // and the tempo timeout may fire. A fresh stuck meter would defer to the hard cap.
    auto stuckSample = []() {
        DetectionResult r = readyMeterSample(80.0);
        r.rejectionReason = QStringLiteral("stale_or_memory");
        r.greenStartPct = -1.0;  // no green window (contested) -> target = full meter
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.velocityPctS = 0.0;   // not rising -> no velocity/predictive path
        r.etaToGreenMs = -1.0;  // no ETA path
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    auto output = engine.process(physical);
    QVERIFY(output.square());

    engine.advanceTestClock(220);  // arm -> holding
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    engine.advanceTestClock(160);  // past the 140ms standstill commit floor
    // Genuine appearance latches the meter-appear anchor (the anchor now requires a clean raw
    // accept, not a stale_or_memory echo); detection then degrades to the stuck echo fill.
    // This bucket has NO learned clock (fastTypeClockOwns=false), so the tempo timeout still
    // applies as the safety — exactly the labelled path this test pins.
    DetectionResult genuineAppear = stuckSample();
    genuineAppear.rejectionReason.clear();   // genuine accept -> latches meterSeen
    engine.updateDetection(genuineAppear);
    output = engine.process(physical);
    engine.updateDetection(stuckSample());  // now stuck (stale/echo), not recoverable
    output = engine.process(physical);
    QVERIFY2(engine.context().state == HoldState::Holding,
             "a stuck meter must keep holding until the tempo timeout (still developing)");

    // Hold past BOTH the 300ms tempo timeout AND the ~400ms peak-progress grace: the
    // stuck meter's PEAK hasn't advanced since it appeared (re-feeding fill 50 doesn't
    // raise the peak), so it is no longer "developing" and the tempo-timeout safety
    // fires — NOT max_hold_safety (its 5000ms post-meter ceiling is far off).
    engine.advanceTestClock(450);
    engine.updateDetection(stuckSample());  // keep it fresh, still stuck (peak unchanged)
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.shotsReleased(), 0);

    engine.advanceTestClock(15000); // past the 3x post-meter ownership bound
    engine.updateDetection(stuckSample());
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("detector_authority_lost_abort"));
    QVERIFY(output.square());
    QCOMPARE(engine.shotsReleased(), 0);
    QCOMPARE(engine.shotsAborted(), 1);
}

void AutomationEngineTests::timeoutDeferredWhileMeterFreshOrRising()
{
    // The 650ms tempo timeout must DEFER while the meter is still recoverable: a FRESH raw
    // accept (lastSampleFreshAccept) means the meter is still being detected and may resume
    // rising, so it must not be blind-dumped. A fresh, above-floor but stuck meter (no
    // green/velocity/ETA -> no predictive/green/reactive path) held past the tempo timeout
    // AND the peak-progress grace must STAY Holding (deferred), not dump via timeout_fallback.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 300.0;  // would fire if not deferred
    config.maximumHoldMs = 5000.0;          // keep the ceiling + hard cap far off
    LearningData learning;
    // Unarmed hold-start clock so a fresh, stuck-but-recoverable meter DEFERS (stays Holding) as this
    // test pins; kFeedforwardDefaults=460 would otherwise blind-fire feedforward_target instead.
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    auto freshStuck = []() {
        DetectionResult r = readyMeterSample(80.0);  // FRESH accept (no rejectionReason)
        r.greenStartPct = -1.0;  // no green -> no green path
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.velocityPctS = 0.0;   // re-fed at the same fill -> sampler velocity ~0
        r.etaToGreenMs = -1.0;  // no ETA path
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    auto output = engine.process(physical);
    QVERIFY(output.square());

    engine.advanceTestClock(220);  // arm -> holding
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    engine.advanceTestClock(160);  // past the standstill commit floor
    engine.updateDetection(freshStuck());  // fresh meter appears (latches meterSeen)
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // Past BOTH the 300ms tempo timeout AND the ~400ms peak-progress grace: the peak hasn't
    // advanced (still 80), so the meter is no longer "developing" — but it is STILL a fresh
    // accept, so recoverableOrRising holds and the timeout must NOT fire.
    engine.advanceTestClock(450);
    engine.updateDetection(freshStuck());  // keep it fresh (recoverable)
    output = engine.process(physical);
    QVERIFY2(engine.context().state == HoldState::Holding,
             "a freshly-detected meter must not be timeout-dumped (recoverable)");
    QVERIFY2(engine.context().releaseReasonCode != QStringLiteral("timeout_fallback"),
             "no timeout_fallback while the meter is still a fresh accept");
}

void AutomationEngineTests::timeoutDoesNotDumpBelowMinFillFloor()
{
    // Below the min-fill floor (70%), a stalled/lost meter must NOT be dumped by the tempo
    // timeout OR the max-hold ceiling — only the absolute hard cap may. A stale (non-fresh),
    // stuck 49% meter held past the timeout AND the ceiling, but before the hard cap, must
    // keep Holding. The bad live case was a Left Fade dumped at 49% via timeout_fallback.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 300.0;  // timeout (gated by the floor)
    config.maximumHoldMs = 400.0;           // ceiling (gated by the floor); hard cap = 1200ms
    LearningData learning;
    // Unarmed hold-start clock so a below-floor stuck meter stays Holding (not dumped) as this test
    // pins; kFeedforwardDefaults=460 would otherwise blind-fire feedforward_target instead.
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    auto stuckLow = []() {
        DetectionResult r = readyMeterSample(49.0);  // BELOW the 70 floor
        r.rejectionReason = QStringLiteral("stale_or_memory");  // not recoverable
        r.greenStartPct = -1.0;
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.velocityPctS = 0.0;
        r.etaToGreenMs = -1.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    auto output = engine.process(physical);
    QVERIFY(output.square());

    engine.advanceTestClock(220);  // arm -> holding
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    engine.advanceTestClock(160);  // past the commit floor
    engine.updateDetection(stuckLow());  // 49% meter appears (latches meterSeen)
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // Past the 300ms timeout, the 400ms ceiling, AND the ~400ms grace, but well before the
    // absolute hard cap (400*3 = 1200ms after the meter appeared): a below-floor stuck meter
    // must STILL be holding — neither timeout nor ceiling may dump it low.
    engine.advanceTestClock(560);
    engine.updateDetection(stuckLow());  // keep it stale + stuck at 49%
    output = engine.process(physical);
    QVERIFY2(engine.context().state == HoldState::Holding,
             "a below-floor stuck meter must not be dumped before the absolute hard cap");
}

void AutomationEngineTests::nonGotoHardCapReleasesEvenBelowFloor()
{
    // The absolute hard cap (postMeterCeiling*3) ALWAYS releases a Square/fade, even below
    // the min-fill floor — the user pressed shoot, so a possibly-mistimed shot beats none.
    // A stale, stuck 49% meter held past the hard cap releases via max_hold_safety.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 5000.0;  // keep the tempo timeout out of the way
    config.maximumHoldMs = 200.0;            // post-meter ceiling 200ms -> hard cap 600ms
    LearningData learning;
    // Unarmed hold-start clock so the absolute hard-cap max_hold_safety path is reached (kFeedforward
    // Defaults would otherwise seed Standstill=460 and preempt it with feedforward_target).
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    auto stuckLow = []() {
        DetectionResult r = readyMeterSample(49.0);  // below the floor
        r.rejectionReason = QStringLiteral("stale_or_memory");
        r.greenStartPct = -1.0;
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.velocityPctS = 0.0;
        r.etaToGreenMs = -1.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    auto output = engine.process(physical);
    QVERIFY(output.square());

    engine.advanceTestClock(220);
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    engine.advanceTestClock(160);
    // Genuine appearance latches the meter-appear anchor (now requires a clean raw accept, not a
    // stale echo); detection then degrades to the stuck below-floor echo fill.
    DetectionResult genuineAppear = stuckLow();
    genuineAppear.rejectionReason.clear();   // genuine accept -> latches meterSeen
    engine.updateDetection(genuineAppear);
    output = engine.process(physical);
    engine.updateDetection(stuckLow());  // now stuck below the floor (stale/echo)
    output = engine.process(physical);

    // Past the absolute hard cap (200*3 = 600ms after the meter appeared): even though the
    // fill is below the floor, the hard cap forces a labelled max_hold_safety release.
    engine.advanceTestClock(700);
    engine.updateDetection(stuckLow());
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("detector_authority_lost_abort"));
    QVERIFY(output.square());
    QCOMPARE(engine.shotsReleased(), 0);
    QCOMPARE(engine.shotsAborted(), 1);
}

void AutomationEngineTests::meterAnchorIgnoresStaleEchoLatchesOnGenuine()
{
    // ROOT-CAUSE GUARD (fade timing): the meter-appear anchor (firstMeterSeenMs) must latch on a
    // GENUINE fresh detection, NOT on a stale_or_memory ECHO. A cross-shot echo surfaces at
    // ~holdStart+10ms unrelated to this shot; anchoring the per-type clock to it forced the clock
    // to absorb the variable fade WIND-UP, scattering fades past the ~30-40ms green window. This
    // pins the anchor to a genuine accept so the clock measures the fixed appear->tip segment.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    // A no-green echo/genuine sample (no green/velocity/ETA -> never triggers a vision release,
    // so the only thing under test is whether the anchor latches).
    auto noGreen = [](double fill, bool genuine) {
        DetectionResult r = readyMeterSample(fill);
        r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0; r.velocityPctS = 0.0; r.etaToGreenMs = -1.0;
        if (!genuine) r.rejectionReason = QStringLiteral("stale_or_memory");
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    auto output = engine.process(physical);
    engine.advanceTestClock(220);
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // Only stale echoes arrive -> the anchor must NOT latch (and the shot keeps holding).
    for (int i = 0; i < 5; ++i) {
        engine.updateDetection(noGreen(40.0, /*genuine=*/false));
        output = engine.process(physical);
    }
    QVERIFY2(!engine.context().meterSeenThisShot,
             "a stale_or_memory echo must NOT latch the meter-appear anchor");
    QVERIFY(engine.context().firstMeterSeenMs < 0.0);

    // A genuine fresh accept latches the anchor.
    engine.updateDetection(noGreen(40.0, /*genuine=*/true));
    output = engine.process(physical);
    QVERIFY2(engine.context().meterSeenThisShot,
             "a genuine fresh accept MUST latch the meter-appear anchor");
    QVERIFY(engine.context().firstMeterSeenMs >= 0.0);
}

void AutomationEngineTests::armedFastClockBeatsHoldAnchoredTimeout()
{
    // ROOT-CAUSE GUARD (fade timing): a fast type with an ARMED meter-appear clock releases on
    // that clock (feedforward_target), NOT the hold-anchored timeout — even with the timeout set
    // very short. Live, the 650ms timeout was dumping fades late at 88.9-100% on the recede; the
    // armed clock must own the release. (An un-armed bucket still keeps the timeout, covered by
    // timeoutFallbackReleasesWithDistinctReasonCode.)
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 100.0;  // a SHORT hold-anchored timeout that must NOT win
    config.maximumHoldMs = 5000.0;          // keep the post-meter ceiling far away
    LearningData learning;
    learning.shotTypeMeterToReleaseMs[QStringLiteral("Standstill")] = 120.0;  // armed appear->tip clock
    engine.applyConfig(config, learning);

    auto noGreen = [](double fill, bool genuine) {
        DetectionResult r = readyMeterSample(fill);
        r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0; r.velocityPctS = 0.0; r.etaToGreenMs = -1.0;
        if (!genuine) r.rejectionReason = QStringLiteral("stale_or_memory");
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    auto output = engine.process(physical);
    engine.advanceTestClock(230);
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // Meter genuinely appears (latches the anchor), then detection goes stale — proving the clock
    // fires open-loop without fresh vision and is NOT preempted by the 100ms hold-anchored timeout.
    engine.updateDetection(noGreen(40.0, /*genuine=*/true));
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);  // commit floor not yet passed

    // B7 (2026-07-25) anchor hardening: a LOW first sight now needs a SECOND genuine, non-descending
    // sample before it may validate the meter-appear anchor (a one-frame décor phantom is a genuine
    // fresh accept, so a single low-fill lock used to anchor the clock on the first frame of a shot).
    // anchorValidMs still BACKDATES to the FIRST genuine sample, so the 120ms appear->release clock
    // is measured from exactly the same instant as before — the total 170ms below is unchanged.
    engine.advanceTestClock(10);
    engine.updateDetection(noGreen(41.0, /*genuine=*/true));
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    engine.advanceTestClock(160);  // clock is due, but its source-frame lease expired
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.shotsReleased(), 0);

    // A newly processed near-tip frame restores authority and can time the shot;
    // elapsed clock time alone never can.
    engine.updateDetection(readyMeterSample(94.0, 1.0));
    output = engine.process(physical);
    QVERIFY(engine.context().state == HoldState::Releasing
            || engine.context().state == HoldState::Cooldown);
    QVERIFY(engine.context().releaseReasonCode == QLatin1String("predictive_target")
            || engine.context().releaseReasonCode == QLatin1String("green_confirmed"));
}

void AutomationEngineTests::shadowModeRecordsDeadlineWithoutControlling()
{
    // PHASE B GUARD: with autonomous_vision_shadow ON the engine COMPUTES the global-velocity
    // autonomous release deadline and records it (shadowFireMs) WITHOUT controlling output — the
    // real release path still owns the shot. With the flag OFF, the shadow compute must not run.
    auto run = [](bool shadowOn) -> ShotContext {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.autonomousVisionShadow = shadowOn;
        LearningData learning;
        learning.globalRiseVelocityPctMs = 0.2;   // known vg so the shadow deadline is computable
        engine.applyConfig(config, learning);

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        engine.process(physical);
        engine.advanceTestClock(160);                          // past the commit floor
        engine.process(physical);
        // Feed a fresh, rising meter near the top so the shadow deadline comes due (fill enters
        // [target - vg*latency, target)) and a normal vision release fires over a few frames.
        for (int i = 0; i < 6; ++i) {
            engine.updateDetection(readyMeterSample(88.0 + static_cast<double>(i)));
            engine.process(physical);
            engine.advanceTestClock(20);
        }
        return engine.context();
    };

    const ShotContext on = run(true);
    const ShotContext off = run(false);

    // Shadow ON latched an autonomous fire decision (compute-only) ...
    QVERIFY2(on.shadowFireMs >= 0.0, "shadow mode should record an autonomous fire deadline");
    QVERIFY(on.shadowFireFillPct > 0.0);
    QVERIFY(on.shadowVgPctMs > 0.0);
    // ... and the real release path still owned the shot (shadow never controls output).
    QVERIFY(on.releaseReasonCode != QStringLiteral("idle"));
    // Shadow OFF: the compute must not run at all.
    QVERIFY2(off.shadowFireMs < 0.0, "shadow compute must not run when the flag is off");
}

void AutomationEngineTests::goToRsLatchHoldsUntilTrulyNeutral()
{
    // After a Go-To arms, the virtual RS stays pinned (0,0) and a Go-To cannot re-arm until
    // the PHYSICAL right stick is TRULY neutral (magnitude below the deadzone) for 3 frames.
    // A diagonal/sideways RS (!stickUp but still deflected) must NOT clear the latch — else
    // the post-shot RS leaks a dribble or re-arms a Go-To. (User rule: latch neutral until
    // the physical RS returns to neutral.)
    AutomationEngine engine;
    AppConfigData config;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState up;
    up.rightStickY = -127;
    auto output = engine.process(up);
    engine.advanceTestClock(270);
    output = engine.process(up);  // arms the Go-To (latch set)
    QCOMPARE(engine.context().mode, ShotMode::GoToStick);
    QCOMPARE(engine.shotsAttempted(), 1);

    engine.advanceTestClock(900);  // past the Go-To release floor
    engine.updateDetection(readyMeterSample(94.0, 1.0));  // fresh green meter -> release
    output = engine.process(up);
    QCOMPARE(output.rightStickY, 127);  // [ORION_GOTO_DOWN_FLICK] released: mirrored DOWN flick

    // Drive Releasing(50ms) -> completeRelease -> Go-To cooldown(650ms) -> Idle, with the
    // physical RS still held up (it never returned to neutral, so the latch must persist).
    engine.advanceTestClock(100);
    engine.process(up);            // Releasing -> Cooldown
    engine.advanceTestClock(750);
    engine.process(up);            // Cooldown elapses -> resets to Idle this frame
    output = engine.process(up);   // now Idle: latch pins neutral while RS still up
    QCOMPARE(output.rightStickY, 0);
    QCOMPARE(engine.shotsAttempted(), 1);  // did NOT re-arm

    // A DIAGONAL/SIDEWAYS RS (|Y| below the up threshold -> !stickUp, but clearly deflected)
    // must NOT clear the latch: the dribble is pinned to neutral, no re-arm.
    ControllerState sideways;
    sideways.rightStickX = 120;
    sideways.rightStickY = -30;
    output = engine.process(sideways);
    QCOMPARE(output.rightStickX, 0);
    QCOMPARE(output.rightStickY, 0);
    QCOMPARE(engine.shotsAttempted(), 1);

    // Three TRULY-neutral frames (magnitude below the deadzone) clear the latch.
    ControllerState neutral;  // (0,0)
    engine.process(neutral);
    engine.process(neutral);
    engine.process(neutral);

    // Latch cleared: a deflected RS now passes straight through again (no longer pinned).
    output = engine.process(sideways);
    QCOMPARE(output.rightStickX, 120);
    QCOMPARE(output.rightStickY, -30);
}

void AutomationEngineTests::reactiveTargetCrossingReportsReactiveTargetCode()
{
    // Telemetry honesty (TASK T1, do #4/#5): the LAST-RESORT reactive release — the
    // meter is already AT/PAST target with no confirmed green window and no usable
    // velocity/ETA prediction — must report its own distinct code `reactive_target`,
    // not be conflated with the predictive paths. Of the reachable release/waiting
    // codes, green_confirmed, predictive_target, max_hold_safety, await_meter,
    // stale_sample, out_of_reach, confidence_low, and timeout_fallback each already
    // have a dedicated pin; reactive_target was only ever ACCEPTED as one of several
    // allowed codes (contestedNoGreenTimesMeterToTop, holdingFramesReportHonestWaitingCode),
    // never pinned on its own — the same gap green_confirmed had before Round 6. The
    // reachability-cap refactor (do #2) reshaped the predictive blocks around this one,
    // so pinning the label guards against a regression that silently re-routes an
    // already-at-target shot. Behavior-free: asserts only the reported code on release.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 5000.0;  // keep the timeout/fixed/max-hold safeties...
    config.fixedHoldMs = 5000.0;             // ...far off so ONLY the reactive path (block 4)
    config.maximumHoldMs = 5000.0;           // ...can fire on the at-target frame
    LearningData learning;
    engine.applyConfig(config, learning);

    // Contested (no green window -> target = full meter), no velocity/ETA, so the
    // predictive blocks cannot pre-empt block 4: the green tracker never confirms
    // (block 1); fill >= target fails the `fill < target` guard (block 2); ETA forced
    // to -1 (block 3). Only the reactive "already at/over target" path remains.
    auto noGreenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill);
        r.greenStartPct = -1.0;   // no green window (contested) -> target = full meter
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.velocityPctS = 0.0;     // not rising -> no velocity/predictive path
        r.etaToGreenMs = -1.0;    // no ETA path
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    auto output = engine.process(physical);
    QVERIFY(output.square());

    engine.advanceTestClock(220);  // arm -> holding (no meter yet -> await_meter)
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    engine.advanceTestClock(160);  // past the 140ms standstill commit floor
    // The meter must be seen RISING into the target this shot, else the reactive path is
    // (correctly) suppressed as a phantom. Feed one fresh below-target sample first so
    // minFreshFillPct proves a real climb, then the at-target sample fires the reactive path.
    engine.updateDetection(noGreenSample(55.0));  // genuine rise from below target
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);  // below target -> still holding
    engine.updateDetection(noGreenSample(100.0));  // now at/over target -> reactive fires
    output = engine.process(physical);

    QVERIFY(engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("reactive_target"));
    QVERIFY2(engine.context().releaseReasonCode != QStringLiteral("predictive_target"),
             "an already-at-target release must be labelled reactive_target, not predictive");
}

void AutomationEngineTests::phantomAtTargetSuppressesReactiveRelease()
{
    // ROOT-CAUSE REGRESSION (live "Standstill doesn't time at all"): a Standstill armed
    // while a lingering prior-shot meter / weak false-positive sat at fill=100 (no green,
    // conf~0.50) reactive-released ~150ms into the hold, ignoring the real meter. The
    // reactive path must fire ONLY when the meter genuinely ROSE into the target THIS shot
    // (a fresh sample seen >= reactiveRiseMarginPct below target). A meter that is at/above
    // target from its FIRST sample must NOT reactive-release; the bot keeps holding for the
    // shot's own rising meter and reports the distinct phantom_target waiting code.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 5000.0;  // keep every safety far off so ONLY the
    config.fixedHoldMs = 5000.0;             // reactive path could fire on the at-target
    config.maximumHoldMs = 5000.0;           // frame — and it must be suppressed
    LearningData learning;
    engine.applyConfig(config, learning);

    auto phantomAtTarget = []() {
        DetectionResult r = readyMeterSample(100.0);  // already full from the first sample
        r.greenStartPct = -1.0;   // no green (contested) -> target = full meter
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.velocityPctS = 0.0;     // flat (not rising) -> no predictive path
        r.etaToGreenMs = -1.0;    // no ETA path
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);  // arm -> holding
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);  // past the standstill commit floor

    // Feed several at-target phantom samples — the meter was NEVER seen below target, so
    // the reactive path must stay suppressed across all of them.
    for (int i = 0; i < 5; ++i) {
        engine.updateDetection(phantomAtTarget());
        engine.process(physical);
        QVERIFY2(engine.context().state == HoldState::Holding,
                 "a phantom meter at-target from frame one must NOT reactive-release");
        engine.advanceTestClock(15);
    }
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("phantom_target"));

    // A real meter then rises from below the target -> the reactive path is unblocked and
    // the shot releases (reactive_target), proving the gate only suppresses the phantom.
    auto noGreenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill);
        r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0; r.velocityPctS = 0.0; r.etaToGreenMs = -1.0;
        return r;
    };
    engine.updateDetection(noGreenSample(50.0));   // seen below target -> meter genuinely rose
    engine.process(physical);
    engine.updateDetection(noGreenSample(100.0));  // now at target with a proven rise
    engine.process(physical);
    QVERIFY(engine.context().state == HoldState::Releasing || engine.context().state == HoldState::Cooldown);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("reactive_target"));
}

void AutomationEngineTests::syntheticMeterDetectsGreenWindow()
{
#if ORION_WITH_OPENCV
    // Realistic synthetic meter: gray frame (background) + purple fill + green window.
    // The new gray-frame-first detector finds the dark meter body first, then
    // confirms colored fill inside it.
    cv::Mat frame(720, 1280, CV_8UC3, cv::Scalar(120, 130, 125)); // court-like background

    // 1. Gray meter frame (full meter body — unfilled + filled area)
    cv::rectangle(frame, cv::Rect(620, 240, 16, 120), cv::Scalar(45, 45, 50), cv::FILLED);

    // 2. Purple fill inside the gray frame (fills from bottom up to ~60%)
    cv::Mat hsvPixel(1, 1, CV_8UC3, cv::Scalar(150, 220, 230));
    cv::Mat bgrPixel;
    cv::cvtColor(hsvPixel, bgrPixel, cv::COLOR_HSV2BGR);
    const auto purple = bgrPixel.at<cv::Vec3b>(0, 0);
    cv::rectangle(frame, cv::Rect(622, 300, 12, 58), cv::Scalar(purple[0], purple[1], purple[2]), cv::FILLED);

    // 3. Green window near the top of the fill zone
    cv::rectangle(frame, cv::Rect(622, 300, 12, 8), cv::Scalar(31, 255, 49), cv::FILLED);

    MeterDetector detector;
    AppConfigData config;
    config.meterColor = QStringLiteral("Purple");
    config.meterStyle = QStringLiteral("Sword");
    config.detectionConfidencePercent = 20;
    detector.applyConfig(config);

    auto result = detector.detect(frame);
    QVERIFY2(result.detected, "synthetic meter should be detected");
    QVERIFY(result.fillPct > 20.0);
    QVERIFY(result.fillPct < 80.0);
    QVERIFY(result.greenClusterPx > 0);
#else
    QSKIP("OpenCV not enabled");
#endif
}

