void AutomationEngineTests::deviceSelectorPrefersPhysicalSony()
{
    ControllerDeviceSelector selector;
    QVector<ControllerDeviceCandidate> candidates;
    ControllerDeviceCandidate virtualDs4;
    virtualDs4.key = QStringLiteral("raw:virtual-ds4");
    virtualDs4.source = QStringLiteral("RawInput");
    virtualDs4.label = QStringLiteral("DualShock 4");
    virtualDs4.detail = QStringLiteral("virtual ds4");
    virtualDs4.live = true;
    virtualDs4.physicalSony = true;
    virtualDs4.virtualDevice = true;
    candidates.push_back(virtualDs4);

    ControllerDeviceCandidate dualSense;
    dualSense.key = QStringLiteral("raw:dualsense");
    dualSense.source = QStringLiteral("RawInput");
    dualSense.label = QStringLiteral("DualSense");
    dualSense.detail = QStringLiteral("physical dualsense");
    dualSense.live = true;
    dualSense.physicalSony = true;
    candidates.push_back(dualSense);

    ControllerDeviceCandidate xinput;
    xinput.key = QStringLiteral("xinput:0");
    xinput.source = QStringLiteral("XInput");
    xinput.label = QStringLiteral("XInput pad");
    xinput.detail = QStringLiteral("xinput fallback");
    xinput.live = true;
    candidates.push_back(xinput);

    const auto selected = selector.select(candidates, 1000);
    QVERIFY(selected.active);
    QCOMPARE(selected.device.key, QStringLiteral("raw:dualsense"));
    QCOMPARE(selected.health, QStringLiteral("Using RawInput"));
}

