static QString testSha256File(const QString& path)
{
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
        return {};
    }
    QCryptographicHash h(QCryptographicHash::Sha256);
    h.addData(file.readAll());
    return QString::fromLatin1(h.result().toHex());
}

void AutomationEngineTests::securitySettingsSignatureRoundTrip()
{
    QTemporaryDir dir;
    QVERIFY(dir.isValid());
    QFile settings(dir.path() + QStringLiteral("/settings.json"));
    QVERIFY(settings.open(QIODevice::WriteOnly | QIODevice::Truncate));
    settings.write("{\"meter_style\":\"Arrow\"}\n");
    settings.close();

    SecurityManager security(dir.path());
    QVERIFY(!security.verifySettingsSignature());
    QVERIFY(security.writeSettingsSignature());
    QVERIFY(security.verifySettingsSignature());
}

void AutomationEngineTests::securityReleaseManifestDetectsTamper()
{
    QTemporaryDir dir;
    QVERIFY(dir.isValid());
    QFile critical(dir.path() + QStringLiteral("/critical.txt"));
    QVERIFY(critical.open(QIODevice::WriteOnly | QIODevice::Truncate));
    critical.write("known-good\n");
    critical.close();

    QJsonObject files;
    files.insert(QStringLiteral("critical.txt"), QJsonObject{{QStringLiteral("sha256"), testSha256File(critical.fileName())}});
    QJsonObject manifest;
    manifest.insert(QStringLiteral("schema"), QStringLiteral("orion.release_manifest.v1"));
    manifest.insert(QStringLiteral("files"), files);
    QFile manifestFile(dir.path() + QStringLiteral("/release_manifest.json"));
    QVERIFY(manifestFile.open(QIODevice::WriteOnly | QIODevice::Truncate));
    manifestFile.write(QJsonDocument(manifest).toJson(QJsonDocument::Compact));
    manifestFile.close();

    SecurityManager security(dir.path());
    QString detail;
#ifdef ORION_PRODUCTION_BUILD
    // Production requires the detached signature before trusting any file hash.
    // This fixture is intentionally unsigned and must fail closed.
    QVERIFY(!security.verifyReleaseIntegrity(&detail));
    QVERIFY(detail.contains(QStringLiteral("signature"), Qt::CaseInsensitive));
    return;
#else
    QVERIFY(security.verifyReleaseIntegrity(&detail));

    QVERIFY(critical.open(QIODevice::WriteOnly | QIODevice::Truncate));
    critical.write("tampered\n");
    critical.close();
    QVERIFY(!security.verifyReleaseIntegrity(&detail));
    QVERIFY(detail.contains(QStringLiteral("Hash mismatch")));
#endif
}

void AutomationEngineTests::securityReleaseManifestDetachedSignatureFailsClosed()
{
    if (!ed25519Available()) {
        QSKIP("libcrypto with Ed25519 EVP support unavailable in this test environment");
    }

    const bool hadRequired = qEnvironmentVariableIsSet("ORION_REQUIRE_RELEASE_MANIFEST");
    const bool hadOverrideId = qEnvironmentVariableIsSet("ORION_RELEASE_MANIFEST_TEST_PUBKEY_ID");
    const bool hadOverrideKey = qEnvironmentVariableIsSet("ORION_RELEASE_MANIFEST_TEST_PUBKEY_B64");
    const QByteArray savedRequired = qgetenv("ORION_REQUIRE_RELEASE_MANIFEST");
    const QByteArray savedOverrideId = qgetenv("ORION_RELEASE_MANIFEST_TEST_PUBKEY_ID");
    const QByteArray savedOverrideKey = qgetenv("ORION_RELEASE_MANIFEST_TEST_PUBKEY_B64");
    const auto restoreEnvironment = qScopeGuard([=]() {
        const auto restore = [](const char* name, bool existed, const QByteArray& value) {
            if (existed) {
                qputenv(name, value);
            } else {
                qunsetenv(name);
            }
        };
        restore("ORION_REQUIRE_RELEASE_MANIFEST", hadRequired, savedRequired);
        restore("ORION_RELEASE_MANIFEST_TEST_PUBKEY_ID", hadOverrideId, savedOverrideId);
        restore("ORION_RELEASE_MANIFEST_TEST_PUBKEY_B64", hadOverrideKey, savedOverrideKey);
    });
    Q_UNUSED(restoreEnvironment);

    QByteArray seed(32, Qt::Uninitialized);
    for (int i = 0; i < seed.size(); ++i) {
        seed[i] = static_cast<char>(i + 1);
    }
    const QByteArray publicKey = ed25519DerivePublicKey(seed);
    QCOMPARE(publicKey.size(), 32);

    qputenv("ORION_REQUIRE_RELEASE_MANIFEST", "1");
    qputenv("ORION_RELEASE_MANIFEST_TEST_PUBKEY_ID", "orion-release-test-v1");
    qputenv("ORION_RELEASE_MANIFEST_TEST_PUBKEY_B64", publicKey.toBase64());

    QTemporaryDir dir;
    QVERIFY(dir.isValid());
    QFile critical(dir.path() + QStringLiteral("/critical.txt"));
    QVERIFY(critical.open(QIODevice::WriteOnly | QIODevice::Truncate));
    critical.write("known-good\n");
    critical.close();

    QJsonObject files;
    files.insert(QStringLiteral("critical.txt"), QJsonObject{
        {QStringLiteral("sha256"), testSha256File(critical.fileName())},
        {QStringLiteral("size"), critical.size()},
    });
    QJsonObject manifest;
    manifest.insert(QStringLiteral("schema"), QStringLiteral("orion.release_manifest.v1"));
    manifest.insert(QStringLiteral("signature_required"), true);
    manifest.insert(QStringLiteral("signature_alg"), QStringLiteral("ed25519"));
    manifest.insert(QStringLiteral("public_key_id"), QStringLiteral("orion-release-test-v1"));
    manifest.insert(QStringLiteral("files"), files);
    const QByteArray manifestBytes = QJsonDocument(manifest).toJson(QJsonDocument::Indented);
    const QByteArray signature = ed25519Sign(seed, manifestBytes);
    QCOMPARE(signature.size(), 64);

    const QString manifestPath = dir.path() + QStringLiteral("/release_manifest.json");
    const QString signaturePath = dir.path() + QStringLiteral("/release_manifest.sig");
    QFile manifestFile(manifestPath);
    QVERIFY(manifestFile.open(QIODevice::WriteOnly | QIODevice::Truncate));
    QCOMPARE(manifestFile.write(manifestBytes), manifestBytes.size());
    manifestFile.close();
    const auto writeSignature = [&]() {
        QFile signatureFile(signaturePath);
        if (!signatureFile.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            return false;
        }
        const QByteArray encoded = signature.toBase64(
            QByteArray::Base64UrlEncoding | QByteArray::OmitTrailingEquals) + '\n';
        return signatureFile.write(encoded) == encoded.size();
    };
    QVERIFY(writeSignature());

    SecurityManager security(dir.path());
    QString detail;
#ifdef ORION_PRODUCTION_BUILD
    // The dev-only key override is compiled out in production. Even a valid
    // signature under that attacker-controlled key remains untrusted.
    QVERIFY(!security.verifyReleaseIntegrity(&detail));
    QVERIFY(detail.contains(QStringLiteral("not trusted"), Qt::CaseInsensitive));
    return;
#else
    QVERIFY2(security.verifyReleaseIntegrity(&detail), qPrintable(detail));

    QVERIFY(QFile::remove(signaturePath));
    QVERIFY(!security.verifyReleaseIntegrity(&detail));
    QVERIFY(detail.contains(QStringLiteral("signature missing"), Qt::CaseInsensitive));

    QVERIFY(writeSignature());
    QVERIFY(manifestFile.open(QIODevice::WriteOnly | QIODevice::Append));
    QCOMPARE(manifestFile.write(" "), 1LL); // JSON remains valid; exact signed bytes changed.
    manifestFile.close();
    QVERIFY(!security.verifyReleaseIntegrity(&detail));
    QVERIFY(detail.contains(QStringLiteral("signature verification failed"), Qt::CaseInsensitive));
#endif
}

