void AutomationEngineTests::measuredLeadFactoryPriorRequiresExactLiveRoute()
{
    auto configure = [](AutomationEngine& engine) {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        engine.applyConfig(config, LearningData{});
    };
    auto factorySample = [](int frameNumber, int n = 0) {
        DetectionResult sample = readyMeterSample(30.0, -1.0);
        sample.frameNumber = frameNumber;
        sample.stage = QStringLiteral("track");
        sample.measuredLatencyMs = 241.4;
        sample.measuredLatencySdMs = 24.0;
        sample.measuredLatencyN = n;
        sample.measuredLatencyAuthorityKind = QStringLiteral("factory");
        sample.measuredLatencyAuthorityMs = 241.4;
        sample.measuredLatencyAuthoritySdMs = 24.0;
        sample.measuredLatencyFactoryPrior = true;
        sample.measuredLatencyPriorSource = QStringLiteral(
            "venice-e2e-route-prior:capture-card-pipe");
        sample.measuredLatencyModelVersion = QStringLiteral("2026.08.02.1");
        sample.measuredLatencyAttestationGeneration = 401;
        sample.measuredLatencyDeliveryRoute = LatencyControllerRoute::Pipe;
        sample.measuredLatencyScopeEpoch = 1;
        return sample;
    };

    AutomationEngine exact;
    configure(exact);
    DetectionResult sample = factorySample(1);
    exact.updateDetection(sample);
    QVERIFY(!exact.autonomousLiveMeterReady());
    exact.setControllerDeliveryRouteAttestation(401, LatencyControllerRoute::Pipe);
    sample.frameNumber = 2;
    exact.updateDetection(sample);
    QVERIFY(exact.autonomousLiveMeterReady());
    QVERIFY(std::abs(exact.measuredLatencyValueMs() - 241.4) < 1e-6);

    // The weak prior remains a continuously refined seed only below the normal
    // six-label convergence threshold. It cannot disguise a noisy N>=6 snapshot.
    sample.frameNumber = 3;
    sample.measuredLatencyN = 5;
    exact.updateDetection(sample);
    QVERIFY(exact.autonomousLiveMeterReady());
    sample.frameNumber = 4;
    sample.measuredLatencyN = 6;
    exact.updateDetection(sample);
    QVERIFY(!exact.autonomousLiveMeterReady());

    AutomationEngine staleGeneration;
    configure(staleGeneration);
    staleGeneration.setControllerDeliveryRouteAttestation(
        402, LatencyControllerRoute::Pipe);
    staleGeneration.updateDetection(factorySample(1));
    QVERIFY(!staleGeneration.autonomousLiveMeterReady());

    AutomationEngine wrongRoute;
    configure(wrongRoute);
    wrongRoute.setControllerDeliveryRouteAttestation(
        401, LatencyControllerRoute::VigemXusb);
    wrongRoute.updateDetection(factorySample(1));
    QVERIFY(!wrongRoute.autonomousLiveMeterReady());

    AutomationEngine mismatchedSource;
    configure(mismatchedSource);
    mismatchedSource.setControllerDeliveryRouteAttestation(
        401, LatencyControllerRoute::Pipe);
    DetectionResult vigemSource = factorySample(1);
    vigemSource.measuredLatencyPriorSource = QStringLiteral(
        "venice-e2e-route-prior:capture-card-vigem");
    mismatchedSource.updateDetection(vigemSource);
    QVERIFY(!mismatchedSource.autonomousLiveMeterReady());

    AutomationEngine missingVersion;
    configure(missingVersion);
    missingVersion.setControllerDeliveryRouteAttestation(
        401, LatencyControllerRoute::Pipe);
    DetectionResult unversioned = factorySample(1);
    unversioned.measuredLatencyModelVersion.clear();
    missingVersion.updateDetection(unversioned);
    QVERIFY(!missingVersion.autonomousLiveMeterReady());
}

namespace {

// The exact telemetry shape of the benched 2026-08-06 21:52Z/22:23Z sessions: a COLD estimator
// with a valid measured snapshot but no authority the shipped gate accepts (kind="none"), on a
// healthy, attested pipe route. Every press in those sessions was refused
// `waiting_for_latency_calibration` while the fire path would have used the user's 300 anyway.
DetectionResult coldNoAuthoritySample(int frameNumber)
{
    DetectionResult sample = readyMeterSample(30.0, -1.0);
    sample.frameNumber = frameNumber;
    sample.stage = QStringLiteral("track");
    sample.measuredLatencyMs = 241.4;
    sample.measuredLatencySdMs = 24.0;
    sample.measuredLatencyN = 0;
    sample.measuredLatencyAuthorityKind = QStringLiteral("none");
    sample.measuredLatencyAuthorityMs = 0.0;
    sample.measuredLatencyAuthoritySdMs = 0.0;
    sample.measuredLatencyFactoryPrior = false;
    sample.measuredLatencyAttestationGeneration = 401;
    sample.measuredLatencyDeliveryRoute = LatencyControllerRoute::Pipe;
    sample.measuredLatencyScopeEpoch = 1;
    return sample;
}

// The probe-cache replacement seed as latency_estimator._restore_probe_prior() publishes it
// under ORION_PROBE_PRIOR_AUTHORITY: factory KIND, self-measured source, cache-versioned.
DetectionResult probeCacheSeedSample(int frameNumber, int n = 0)
{
    DetectionResult sample = readyMeterSample(30.0, -1.0);
    sample.frameNumber = frameNumber;
    sample.stage = QStringLiteral("track");
    sample.measuredLatencyMs = 230.1;
    sample.measuredLatencySdMs = 6.0;
    sample.measuredLatencyN = n;
    sample.measuredLatencyAuthorityKind = QStringLiteral("factory");
    sample.measuredLatencyAuthorityMs = 230.1;
    sample.measuredLatencyAuthoritySdMs = 6.0;
    sample.measuredLatencyFactoryPrior = true;
    sample.measuredLatencyPriorSource = QStringLiteral("probe_cache:self_measured");
    sample.measuredLatencyModelVersion = QStringLiteral("cache-v3");
    sample.measuredLatencyAttestationGeneration = 401;
    sample.measuredLatencyDeliveryRoute = LatencyControllerRoute::Pipe;
    sample.measuredLatencyScopeEpoch = 1;
    return sample;
}

AppConfigData userLeadGateConfig()
{
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    config.actuationLeadMs = 300.0;
    config.actuationLeadUserSet = true;
    // [ORION_USER_LEAD_AUTHORITY 2026-08-07] The shipped default of this flag flipped from
    // OFF to ON in AppConfig.h so packaged installs can fire under a user-typed lead. The
    // tests here still need to exercise both legs — pin OFF explicitly; the armed tests
    // override to true below.
    config.userLeadSatisfiesAuthority = false;
    return config;
}

} // namespace

void AutomationEngineTests::userLeadSatisfiesAuthorityDefaultOffPinsColdRefusal()
{
    // EXPLICIT-OFF leg: with everything else identical to the armed case below — user lead set,
    // in band, route attested, telemetry fresh — flipping this flag OFF must still refuse,
    // exactly as the benched live sessions did. Pins the fail-closed behaviour of the flag
    // itself. [ORION_USER_LEAD_AUTHORITY 2026-08-07] Shipped default is now ON (see AppConfig.h);
    // userLeadGateConfig() pins the flag OFF for this test.
    AutomationEngine engine;
    AppConfigData config = userLeadGateConfig();
    QVERIFY(!config.userLeadSatisfiesAuthority);   // pinned OFF by the helper for this leg
    engine.applyConfig(config, LearningData{});
    engine.setControllerDeliveryRouteAttestation(401, LatencyControllerRoute::Pipe);
    engine.updateDetection(coldNoAuthoritySample(1));
    QVERIFY(!engine.autonomousLiveMeterReady());
    QCOMPARE(engine.measuredLeadForActuationMs(), 0.0);
}

void AutomationEngineTests::userLeadSatisfiesAuthorityOpensGateWithChannelProofsOnly()
{
    // ARMED leg: the fresh-install case. No estimator convergence of any kind (kind="none",
    // n=0) — the user's own in-band lead plus the UNTOUCHED channel proofs open the gate, and
    // the value/sigma the scheduler sees are the user lead and the 6.0ms factory-floor sd.
    AutomationEngine engine;
    AppConfigData config = userLeadGateConfig();
    config.userLeadSatisfiesAuthority = true;
    engine.applyConfig(config, LearningData{});
    QVERIFY(!engine.autonomousLiveMeterReady());   // no telemetry yet -> shut
    engine.setControllerDeliveryRouteAttestation(401, LatencyControllerRoute::Pipe);
    QVERIFY(!engine.autonomousLiveMeterReady());   // attested but still no telemetry -> shut
    engine.updateDetection(coldNoAuthoritySample(1));
    QVERIFY(engine.autonomousLiveMeterReady());
    QCOMPARE(engine.measuredLeadForActuationMs(), 300.0);
    QCOMPARE(engine.effectiveLeadSdMs(), 6.0);

    // FAIL-CLOSED legs: each clause the flag does NOT waive still refuses independently.
    {
        // The owner never set a lead -> nothing to arm with -> shut, flag or no flag.
        AutomationEngine unset;
        AppConfigData c = userLeadGateConfig();
        c.userLeadSatisfiesAuthority = true;
        c.actuationLeadUserSet = false;
        unset.applyConfig(c, LearningData{});
        unset.setControllerDeliveryRouteAttestation(401, LatencyControllerRoute::Pipe);
        unset.updateDetection(coldNoAuthoritySample(1));
        QVERIFY(!unset.autonomousLiveMeterReady());
        QCOMPARE(unset.measuredLeadForActuationMs(), 0.0);
    }
    {
        // Out-of-band lead (the same band measuredLeadForActuationMs enforces) -> shut.
        // 900 sits above kActuationLeadMaxMs (800 since 2026-08-08; this probe was 500
        // when the ceiling was 450 — it must stay outside the band or the test inverts).
        AutomationEngine outOfBand;
        AppConfigData c = userLeadGateConfig();
        c.userLeadSatisfiesAuthority = true;
        c.actuationLeadMs = 900.0;
        outOfBand.applyConfig(c, LearningData{});
        outOfBand.setControllerDeliveryRouteAttestation(401, LatencyControllerRoute::Pipe);
        outOfBand.updateDetection(coldNoAuthoritySample(1));
        QVERIFY(!outOfBand.autonomousLiveMeterReady());
        QCOMPARE(outOfBand.measuredLeadForActuationMs(), 0.0);
    }
    {
        // No controller-route attestation echo -> the channel is unproven -> shut. The user
        // lead must not stand in for the route proof, only for the posterior.
        AutomationEngine unattested;
        AppConfigData c = userLeadGateConfig();
        c.userLeadSatisfiesAuthority = true;
        unattested.applyConfig(c, LearningData{});
        unattested.updateDetection(coldNoAuthoritySample(1));
        QVERIFY(!unattested.autonomousLiveMeterReady());
        QCOMPARE(unattested.measuredLeadForActuationMs(), 0.0);
    }
    {
        // Wrong-route echo -> shut (same clause the factory path enforces).
        AutomationEngine wrongRoute;
        AppConfigData c = userLeadGateConfig();
        c.userLeadSatisfiesAuthority = true;
        wrongRoute.applyConfig(c, LearningData{});
        wrongRoute.setControllerDeliveryRouteAttestation(
            401, LatencyControllerRoute::VigemXusb);
        wrongRoute.updateDetection(coldNoAuthoritySample(1));
        QVERIFY(!wrongRoute.autonomousLiveMeterReady());
        QCOMPARE(wrongRoute.measuredLeadForActuationMs(), 0.0);
    }
}

void AutomationEngineTests::probeCachePriorAuthorityAcceptsSelfMeasuredSeedOnlyWhenArmed()
{
    // DEFAULT-OFF leg pins the measured 2026-08-06 benching: a restored probe-cache seed
    // publishes source="probe_cache:self_measured", which the venice-e2e-route-prior: prefix
    // check refuses — no authority, every press refused. Fails on a silent default flip.
    AutomationEngine dark;
    AppConfigData config = userLeadGateConfig();
    QVERIFY(!config.probeCachePriorAuthority);     // the shipped default under test
    dark.applyConfig(config, LearningData{});
    dark.setControllerDeliveryRouteAttestation(401, LatencyControllerRoute::Pipe);
    dark.updateDetection(probeCacheSeedSample(1));
    QVERIFY(!dark.autonomousLiveMeterReady());

    // ARMED leg: the identical tuple is accepted as factory-kind authority.
    AutomationEngine armed;
    AppConfigData armedConfig = userLeadGateConfig();
    armedConfig.probeCachePriorAuthority = true;
    armed.applyConfig(armedConfig, LearningData{});
    armed.setControllerDeliveryRouteAttestation(401, LatencyControllerRoute::Pipe);
    armed.updateDetection(probeCacheSeedSample(1));
    QVERIFY(armed.autonomousLiveMeterReady());
    // The user's in-band lead still REPLACES the seed magnitude on the fire path.
    QCOMPARE(armed.measuredLeadForActuationMs(), 300.0);

    // FAIL-CLOSED legs: the flag admits exactly ONE source string, and every other factory
    // envelope clause survives.
    {
        AutomationEngine otherSource;
        otherSource.applyConfig(armedConfig, LearningData{});
        otherSource.setControllerDeliveryRouteAttestation(
            401, LatencyControllerRoute::Pipe);
        DetectionResult sample = probeCacheSeedSample(1);
        sample.measuredLatencyPriorSource = QStringLiteral("probe_cache:evil_other");
        otherSource.updateDetection(sample);
        QVERIFY(!otherSource.autonomousLiveMeterReady());
    }
    {
        // N >= 6 leaves the factory envelope exactly as before — the seed cannot disguise a
        // converged-count posterior that failed validation.
        AutomationEngine converged;
        converged.applyConfig(armedConfig, LearningData{});
        converged.setControllerDeliveryRouteAttestation(
            401, LatencyControllerRoute::Pipe);
        converged.updateDetection(probeCacheSeedSample(1, 6));
        QVERIFY(!converged.autonomousLiveMeterReady());
    }
    {
        // No attestation echo -> shut, exactly like the packaged prior.
        AutomationEngine unattested;
        unattested.applyConfig(armedConfig, LearningData{});
        unattested.updateDetection(probeCacheSeedSample(1));
        QVERIFY(!unattested.autonomousLiveMeterReady());
    }
}

void AutomationEngineTests::factoryPriorExactPipeRouteOwnsFirstShotEveryCoreGesture()
{
    struct ShotCase {
        const char* name;
        ControllerState physical;
        ShotMode mode;
        QString shotType;
    };

    QVector<ShotCase> cases;
    ControllerState standstill;
    standstill.buttons |= XINPUT_GAMEPAD_X;
    cases.push_back({"first standstill Square", standstill,
                     ShotMode::ButtonShot, QStringLiteral("Standstill")});
    ControllerState leftFade = standstill;
    leftFade.leftStickX = -20000;
    cases.push_back({"left-fade Square", leftFade,
                     ShotMode::ButtonShot, QStringLiteral("Left Fade")});
    ControllerState rightFade = standstill;
    rightFade.leftStickX = 20000;
    cases.push_back({"right-fade Square", rightFade,
                     ShotMode::ButtonShot, QStringLiteral("Right Fade")});
    ControllerState goTo;
    goTo.rightStickY = -127;
    cases.push_back({"Go-To RS-up", goTo,
                     ShotMode::GoToStick, QStringLiteral("Go-To")});

    quint64 shotEpoch = 61'000;
    for (int caseIndex = 0; caseIndex < cases.size(); ++caseIndex, ++shotEpoch) {
        const ShotCase& shotCase = cases.at(caseIndex);
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        engine.applyConfig(config, LearningData{});
        engine.setControllerRouteBindingRequired(true);

        quint64 routeGeneration = 71'000
            + static_cast<quint64>(caseIndex);
        engine.setControllerDeliveryRouteAttestation(
            routeGeneration, LatencyControllerRoute::Pipe);

        int frame = 1;
        quint64 scopeEpoch = 1;
        const auto factorySample = [&](double fillPct, bool currentShotProof) {
            DetectionResult sample = strictLiveMeterSample(
                fillPct, frame++, shotEpoch, 241.4, 24.0, 0);
            sample.measuredLatencyAuthorityKind = QStringLiteral("factory");
            sample.measuredLatencyAuthorityMs = 241.4;
            sample.measuredLatencyAuthoritySdMs = 24.0;
            sample.measuredLatencyFactoryPrior = true;
            sample.measuredLatencyPriorSource = QStringLiteral(
                "venice-e2e-route-prior:capture-card-pipe");
            sample.measuredLatencyModelVersion = QStringLiteral("2026.08.02.1");
            sample.measuredLatencyAttestationGeneration = routeGeneration;
            sample.measuredLatencyDeliveryRoute = LatencyControllerRoute::Pipe;
            sample.measuredLatencyScopeEpoch = scopeEpoch;
            if (!currentShotProof) {
                sample.detected = false;
                sample.fillPct = 0.0;
                sample.confidence = 0.0;
                sample.consecutiveFrames = 0;
                sample.stage = QStringLiteral("no_meter");
                sample.gameplayStructureVerified = false;
                sample.gameplayStructureEpoch = 0;
                sample.greenStartPct = -1.0;
                sample.greenEndPct = -1.0;
                sample.greenCenterPct = -1.0;
            }
            return sample;
        };

        // This is the production startup order: the controller proves the live
        // Pipe generation, then a sidecar frame echoes the same scoped factory
        // prior before the first user gesture. No learned six-shot warmup exists.
        engine.updateDetection(factorySample(0.0, false));
        QVERIFY2(engine.autonomousLiveMeterReady(), shotCase.name);
        QCOMPARE(engine.controllerDeliveryRouteAttestationSnapshot().generation,
                 routeGeneration);
        QCOMPARE(engine.controllerDeliveryRouteAttestationSnapshot().route,
                 LatencyControllerRoute::Pipe);

        // The card/decoder may replace its estimator in place while the native
        // route remains Pipe and frame numbering continues. Epoch 2 must revoke
        // generation 1; a fresh neutral proof then restores first-shot authority.
        ++scopeEpoch;
        DetectionResult rekeyedCold = factorySample(0.0, false);
        rekeyedCold.measuredLatencyMs = 0.0;
        rekeyedCold.measuredLatencySdMs = 0.0;
        rekeyedCold.measuredLatencyAttestationGeneration = 0;
        rekeyedCold.measuredLatencyDeliveryRoute = LatencyControllerRoute::None;
        engine.updateDetection(rekeyedCold);
        QVERIFY2(!engine.autonomousLiveMeterReady(), shotCase.name);
        QVERIFY2(!engine.controllerDeliveryRouteAttestationExpected(
                     routeGeneration, LatencyControllerRoute::Pipe),
                 shotCase.name);

        routeGeneration += 10'000;
        engine.setControllerDeliveryRouteAttestation(
            routeGeneration, LatencyControllerRoute::Pipe);
        engine.updateDetection(factorySample(0.0, false));
        QVERIFY2(engine.autonomousLiveMeterReady(), shotCase.name);

        QSignalSpy marker(&engine, &AutomationEngine::releaseMarker);
        QSignalSpy issued(&engine, &AutomationEngine::releaseIssued);
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        engine.setPhysicalShotEpoch(shotEpoch);
        ControllerState output = engine.process(shotCase.physical);

        if (shotCase.mode == ShotMode::GoToStick) {
            // Raw stick gestures have a deliberate dwell. Keep the scoped lead
            // lease fresh without manufacturing meter/gameplay proof while it
            // expires, exactly as idle sidecar telemetry does in production.
            for (const double deltaMs : {130.0, 130.0}) {
                engine.advanceTestClock(deltaMs);
                engine.updateDetection(factorySample(0.0, false));
                output = engine.process(shotCase.physical);
            }
        }

        // Ownership remains current-shot and vision-derived: the startup prior
        // supplies only transport lead, never the meter proof itself.
        for (const double fillPct : {5.0, 9.0, 13.0}) {
            engine.advanceTestClock(20.0);
            engine.updateDetection(factorySample(fillPct, true));
            output = engine.process(shotCase.physical);
        }

        QVERIFY2(engine.autonomousLiveMeterReady(), shotCase.name);
        QCOMPARE(engine.context().state, HoldState::Holding);
        QCOMPARE(engine.context().mode, shotCase.mode);
        QCOMPARE(engine.context().shotType, shotCase.shotType);
        QVERIFY2(engine.context().gameplayStructureVerified, shotCase.name);
        QCOMPARE(engine.context().gameplayStructureEpoch, shotEpoch);
        QVERIFY2(std::isfinite(engine.context().releaseCrossingEtaMs)
                     && engine.context().releaseCrossingEtaMs > 0.0,
                 qPrintable(QStringLiteral(
                     "%1 gained ownership without a real crossing ETA: eta=%2 command_eta=%3")
                                .arg(QString::fromLatin1(shotCase.name))
                                .arg(engine.context().releaseCrossingEtaMs)
                                .arg(engine.context().releaseEtaMs)));
        // The HUD intentionally exposes the frame-derived target crossing ETA,
        // not a guessed command deadline. releaseEtaMs may remain unavailable
        // until the fit's uncertainty is strong enough to authorize actuation.

        bool sawEtaWhileOwned = true;
        for (double fillPct = 17.0;
             fillPct < 100.0 && engine.context().state == HoldState::Holding;
             fillPct += 4.0) {
            engine.advanceTestClock(20.0);
            engine.updateDetection(factorySample(fillPct, true));
            engine.reevaluateScheduleOnFreshSample();
            output = engine.process(shotCase.physical);
            if (engine.context().state == HoldState::Holding) {
                sawEtaWhileOwned = sawEtaWhileOwned
                    && std::isfinite(engine.context().releaseCrossingEtaMs)
                    && engine.context().releaseCrossingEtaMs > 0.0;
            }
            if (engine.scheduledFireDeadlineMs() >= 0.0) {
                const double deadline = engine.scheduledFireDeadlineMs();
                const quint64 token = engine.scheduledFireToken();
                QCOMPARE(engine.scheduledFireRouteGeneration(), routeGeneration);
                QCOMPARE(engine.scheduledFireRoute(), LatencyControllerRoute::Pipe);
                if (deadline > engine.engineNowMs()) {
                    engine.advanceTestClock(deadline - engine.engineNowMs());
                }
                engine.confirmScheduledFire(token, deadline);
                output = engine.process(shotCase.physical);
            }
        }

        QVERIFY2(sawEtaWhileOwned, shotCase.name);
        QVERIFY2(engine.context().state == HoldState::Releasing,
                 qPrintable(QStringLiteral(
                     "%1 did not release from the exact-route live tip: state=%2 reason=%3")
                                .arg(QString::fromLatin1(shotCase.name))
                                .arg(static_cast<int>(engine.context().state))
                                .arg(engine.context().releaseReasonCode)));
        QCOMPARE(engine.context().releaseReasonCode,
                 QStringLiteral("live_meter_tip"));
        QCOMPARE(engine.context().releaseScheduleRouteGeneration,
                 routeGeneration);
        QCOMPARE(engine.context().releaseScheduleRoute,
                 LatencyControllerRoute::Pipe);
        QCOMPARE(marker.count(), 1);
        QCOMPARE(issued.count(), 1);
        QCOMPARE(aborted.count(), 0);
        const ShotContext issuedContext =
            issued.at(0).at(0).value<ShotContext>();
        QCOMPARE(issuedContext.releaseScheduleRouteGeneration,
                 routeGeneration);
        QCOMPARE(issuedContext.releaseScheduleRoute,
                 LatencyControllerRoute::Pipe);
        QVERIFY2(!output.square(), shotCase.name);
    }
}

