static DetectionResult authoritativeLiveMeterSample(double fillPct, int frameNumber,
                                                     double latencyMs = 70.0,
                                                     double latencySdMs = 2.0,
                                                     int latencyN = 6,
                                                     bool provisional = false)
{
    DetectionResult sample = readyMeterSample(fillPct, -1.0);
    sample.frameNumber = frameNumber;
    sample.captureTsMs = 100'000.0 + static_cast<double>(frameNumber) * 20.0;
    sample.measurementCaptureTsMs = sample.captureTsMs;
    sample.stage = QStringLiteral("track");
    sample.measuredLatencyMs = latencyMs;
    sample.measuredLatencyN = latencyN;
    sample.measuredLatencySdMs = latencySdMs;
    sample.measuredLatencyControlledAnchor = provisional;
    sample.measuredLatencyProvisional = provisional;
    if (std::isfinite(latencyMs) && latencyMs > 0.0
        && std::isfinite(latencySdMs) && latencySdMs > 0.0
        && (latencyN >= 6 || provisional)) {
        sample.measuredLatencyAuthorityKind = QStringLiteral("validated");
        sample.measuredLatencyAuthorityMs = latencyMs;
        sample.measuredLatencyAuthoritySdMs = latencySdMs;
    }
    sample.measuredLatencyScopeEpoch = 1;
    return sample;
}

