void AutomationEngineTests::measuredLeadRestoredRequiresVideoAndNeutralRouteAttestation()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    DetectionResult restored = authoritativeLiveMeterSample(
        30.0, 1, 72.0, 4.0, 2, true);
    restored.measuredLatencyRestored = true;
    restored.measuredLatencyVideoRouteAttested = true;
    restored.measuredLatencyAttestationGeneration = 101;
    restored.measuredLatencyDeliveryRoute = LatencyControllerRoute::Pipe;
    engine.updateDetection(restored);
    QVERIFY(engine.restoredLatencyAwaitingControllerAttestation());
    QVERIFY(!engine.autonomousLiveMeterReady());

    engine.setControllerDeliveryRouteAttestation(101, LatencyControllerRoute::Pipe);
    restored.frameNumber = 2;
    restored.captureTsMs = 100'000.0 + 2.0 * 20.0;
    engine.updateDetection(restored);
    QVERIFY(!engine.restoredLatencyAwaitingControllerAttestation());
    QVERIFY(engine.autonomousLiveMeterReady());

    engine.setControllerDeliveryRouteAttestation(0, LatencyControllerRoute::None);
    QVERIFY(!engine.autonomousLiveMeterReady());
    QVERIFY(engine.restoredLatencyAwaitingControllerAttestation());

    // An old-route frame can arrive after native has proved a replacement route. Its stale
    // generation must not combine with the new local ACK to authorize the old cached posterior.
    engine.setControllerDeliveryRouteAttestation(102, LatencyControllerRoute::VigemDs4);
    restored.frameNumber = 3;
    restored.captureTsMs = 100'000.0 + 3.0 * 20.0;
    engine.updateDetection(restored);
    QVERIFY(!engine.autonomousLiveMeterReady());
    QVERIFY(engine.restoredLatencyAwaitingControllerAttestation());

    restored.frameNumber = 4;
    restored.captureTsMs = 100'000.0 + 4.0 * 20.0;
    restored.measuredLatencyAttestationGeneration = 102;
    // Matching generation alone is insufficient: old Pipe telemetry cannot authorize ViGEm.
    engine.updateDetection(restored);
    QVERIFY(!engine.autonomousLiveMeterReady());
    restored.measuredLatencyDeliveryRoute = LatencyControllerRoute::VigemDs4;
    restored.frameNumber = 5;
    restored.captureTsMs = 100'000.0 + 5.0 * 20.0;
    engine.updateDetection(restored);
    QVERIFY(engine.autonomousLiveMeterReady());

    restored.frameNumber = 6;
    restored.captureTsMs = 100'000.0 + 6.0 * 20.0;
    restored.measuredLatencyVideoRouteAttested = false;
    engine.updateDetection(restored);
    QVERIFY(!engine.autonomousLiveMeterReady());

    restored.frameNumber = 7;
    restored.captureTsMs = 100'000.0 + 7.0 * 20.0;
    restored.measuredLatencyVideoRouteAttested = true;
    restored.measuredLatencyAttestationGeneration = 103;
    restored.measuredLatencyDeliveryRoute = LatencyControllerRoute::VigemXusb;
    engine.setControllerDeliveryRouteAttestation(
        103, LatencyControllerRoute::VigemXusb);
    engine.updateDetection(restored);
    QVERIFY(engine.autonomousLiveMeterReady());
    engine.setArmed(false);
    QVERIFY(!engine.autonomousLiveMeterReady());
}

