void AutomationEngineTests::measuredLeadAttestationEchoSurvivesExactRouteRekey()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    DetectionResult pipe = authoritativeLiveMeterSample(
        30.0, 1, 72.0, 2.0, 6, false);
    pipe.measuredLatencyRestored = true;
    pipe.measuredLatencyVideoRouteAttested = true;
    pipe.measuredLatencyAttestationGeneration = 201;
    pipe.measuredLatencyDeliveryRoute = LatencyControllerRoute::Pipe;
    pipe.captureTsMs = 1000.0;
    engine.setControllerDeliveryRouteAttestation(201, LatencyControllerRoute::Pipe);
    engine.updateDetection(pipe);
    QVERIFY(engine.autonomousLiveMeterReady());

    // Route re-key loads a different cached estimator, so N may regress on the same detector
    // sequence. The exact new generation+route echo survives; a generic source/sequence reset does
    // not use this exception and still revokes the expected token.
    DetectionResult xusb = authoritativeLiveMeterSample(
        30.0, 2, 75.0, 4.0, 2, true);
    xusb.measuredLatencyRestored = true;
    xusb.measuredLatencyVideoRouteAttested = true;
    xusb.measuredLatencyAttestationGeneration = 202;
    xusb.measuredLatencyDeliveryRoute = LatencyControllerRoute::VigemXusb;
    xusb.captureTsMs = 1010.0;
    engine.setControllerDeliveryRouteAttestation(
        202, LatencyControllerRoute::VigemXusb);
    engine.updateDetection(xusb);
    QVERIFY(engine.controllerDeliveryRouteAttestationExpected(
        202, LatencyControllerRoute::VigemXusb));
    QVERIFY(engine.restoredLatencyAttestationEchoMatches(
        202, LatencyControllerRoute::VigemXusb, 1));
    QVERIFY(!engine.restoredLatencyAwaitingControllerAttestation());

    xusb.frameNumber = 3;
    xusb.measuredLatencyN = 3;
    xusb.captureTsMs = 1020.0;
    engine.updateDetection(xusb);
    QVERIFY(engine.autonomousLiveMeterReady());

    DetectionResult staleSourceEcho = xusb;
    staleSourceEcho.frameNumber = 1;
    staleSourceEcho.captureTsMs = 1030.0;
    staleSourceEcho.measuredLatencyN = 1;
    staleSourceEcho.measuredLatencyAttestationGeneration = 203;
    engine.setControllerDeliveryRouteAttestation(
        203, LatencyControllerRoute::VigemXusb);
    engine.updateDetection(staleSourceEcho);
    QVERIFY(!engine.controllerDeliveryRouteAttestationExpected(
        203, LatencyControllerRoute::VigemXusb));
    QVERIFY(!engine.autonomousLiveMeterReady());
}

