void AutomationEngineTests::calibrationDropoutAfterProofUsesBoundedRelockGrace()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});
    engine.setAutomaticLatencyCalibrationMode(true);

    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy abortedSpy(&engine, &AutomationEngine::shotAborted);
    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;
    ControllerState neutral;
    constexpr quint64 shotEpoch = 779;
    engine.setPhysicalShotEpoch(shotEpoch);
    engine.process(square);

    int frame = 1;
    for (const double fill : {10.0, 14.0, 18.0}) {
        engine.advanceTestClock(20.0);
        DetectionResult sample = calibrationOwnershipSample(fill, frame++, shotEpoch);
        sample.greenStartPct = 80.0;
        sample.greenEndPct = 100.0;
        sample.greenCenterPct = 90.0;
        engine.updateDetection(sample);
        engine.process(square);
    }
    QCOMPARE(engine.context().state, HoldState::Holding);
    QVERIFY(engine.context().latencyCalibrationProbe);
    QVERIFY(engine.context().gameplayStructureVerified);
    QVERIFY(engine.context().sawFreshMeterThisShot);
    QCOMPARE(markerSpy.count(), 0);

    // A physical UP arriving on the first missing detector frame is ambiguous after
    // current-epoch proof. Keep the bot-owned DOWN edge for the bounded re-lock window.
    engine.advanceTestClock(5.0);
    DetectionResult missing = calibrationOwnershipSample(0.0, frame++, shotEpoch);
    missing.detected = false;
    missing.confidence = 0.0;
    missing.stage = QStringLiteral("no_meter");
    missing.rejectionReason = QStringLiteral("roi_not_found");
    engine.updateDetection(missing);
    ControllerState out = engine.process(neutral);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("waiting_for_meter_relock"));
    QVERIFY2(out.square(), "a one-frame post-proof dropout must not leak Square-UP");
    QCOMPARE(abortedSpy.count(), 0);

    // With no relock, fail closed after the existing freshness budget. The abort
    // itself still cannot trust that one raw UP poll: bridge the held output until
    // three post-abort UP samples agree, with no marker or fabricated release.
    engine.advanceTestClock(engine.config().meterFreshWindowMs + 1.0);
    out = engine.process(neutral);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("detector_authority_lost_abort"));
    QVERIFY(out.square());
    QCOMPARE(markerSpy.count(), 0);
    QCOMPARE(engine.shotsReleased(), 0);
    QCOMPARE(abortedSpy.count(), 1);
    out = engine.process(neutral);
    QVERIFY(out.square());
    out = engine.process(neutral);
    QVERIFY(!out.square());
}

void AutomationEngineTests::latencyValidationAbortRequiresNewPhysicalPress()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});
    engine.setAutomaticLatencyCalibrationMode(true);
    QSignalSpy abortedSpy(&engine, &AutomationEngine::shotAborted);

    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;
    ControllerState neutral;
    int frame = 1;
    auto feed = [&](double fill, quint64 epoch) {
        engine.advanceTestClock(20.0);
        DetectionResult sample = calibrationOwnershipSample(fill, frame++, epoch);
        sample.greenStartPct = 96.0;
        sample.greenEndPct = 100.0;
        sample.greenCenterPct = 98.0;
        sample.measuredLatencyMs = 220.0;
        sample.measuredLatencyN = 1;
        sample.measuredLatencySdMs = 5.5;
        sample.measuredLatencyControlledAnchor = true;
        sample.measuredLatencyProvisional = false;
        engine.updateDetection(sample);
        return engine.process(square);
    };

    constexpr quint64 firstEpoch = 781;
    engine.setPhysicalShotEpoch(firstEpoch);
    engine.process(square);
    ControllerState out;
    // Begin below the strict ownership anchor ceiling, then rise quickly enough
    // that the 220ms controlled lead cannot reach even the latest reliable
    // validation stop. This exercises the abort/rearm fence without asking the
    // production engine to claim a high-fill carry-over episode.
    for (const double fill : {10.0, 18.0, 26.0}) {
        out = feed(fill, firstEpoch);
    }
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("latency_validation_deadline_missed"));
    QCOMPARE(abortedSpy.count(), 1);
    QVERIFY(out.square());

    // More convincing frames during the SAME held press cannot create another ownership
    // episode. The live batch previously emitted 5-9 validation aborts from one real shot.
    for (const double fill : {10.0, 14.0, 18.0, 22.0, 26.0}) {
        out = feed(fill, firstEpoch);
        QCOMPARE(engine.context().state, HoldState::Idle);
        QVERIFY(out.square());
    }
    QCOMPARE(abortedSpy.count(), 1);

    // Only a debounced physical UP followed by a new epoch can arm another attempt.
    for (int i = 0; i < 3; ++i) {
        engine.advanceTestClock(4.0);
        out = engine.process(neutral);
    }
    QVERIFY(!out.square());
    constexpr quint64 secondEpoch = firstEpoch + 1;
    engine.setPhysicalShotEpoch(secondEpoch);
    engine.process(square);
    for (const double fill : {10.0, 18.0, 26.0}) {
        out = feed(fill, secondEpoch);
    }
    QCOMPARE(abortedSpy.count(), 2);
}

void AutomationEngineTests::automaticLatencyCalibrationPromotesOnlyGenuineRise()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    config.tempoRemapEnabled = true; // auto setup must still begin as physical Button/Square
    engine.applyConfig(config, LearningData{});
    engine.setAutomaticLatencyCalibrationMode(true);
    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);

    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;
    constexpr quint64 shotEpoch = 41;
    engine.setPhysicalShotEpoch(shotEpoch);
    ControllerState out = engine.process(square);
    engine.advanceTestClock(2'000.0); // deliberately beyond squareHoldArmMs
    out = engine.process(square);
    QVERIFY(out.square());
    QCOMPARE(engine.context().state, HoldState::Idle);

    int frame = 1;
    auto feed = [&](double fill, const QString& stage = QStringLiteral("track"),
                    bool identified = true, int x = 940, int y = 420,
                     int width = 26, int height = 120,
                     bool structureVerified = false, bool staleGreenUi = false,
                     quint64 structureEpoch = 0) {
        engine.advanceTestClock(20.0);
        DetectionResult sample = readyMeterSample(fill, -1.0);
        sample.frameNumber = identified ? frame++ : -1;
        if (sample.frameNumber >= 0) {
            sample.captureTsMs = 100'000.0
                + static_cast<double>(sample.frameNumber) * 20.0;
            sample.measurementCaptureTsMs = sample.captureTsMs;
        }
        sample.x = x;
        sample.y = y;
        sample.width = width;
        sample.height = height;
        sample.stage = stage;
        sample.gameplayStructureVerified = structureVerified;
        sample.gameplayStructureEpoch = structureEpoch;
        if (staleGreenUi) {
            // The QML/sidecar green display can be hysteretic.  Convincing display fields are
            // deliberately not independent current-shot provenance.
            sample.greenStartPct = 93.0;
            sample.greenEndPct = 100.0;
            sample.greenCenterPct = 96.0;
            sample.greenConfidence = 1.0;
        }
        sample.measuredLatencyMs = 0.0;
        sample.measuredLatencyN = 0;
        sample.measuredLatencySdMs = 0.0;
        engine.updateDetection(sample);
        return engine.process(square);
    };

    // Static menu-like detections and a non-authoritative coast can never promote ownership.
    out = feed(10.0);
    out = feed(10.0);
    out = feed(14.0, QStringLiteral("coast"));
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());
    QCOMPARE(markerSpy.count(), 0);

    // A visually plausible rise without an advancing decoder/capture identity is not live proof.
    out = feed(10.0, QStringLiteral("track"), false);
    out = feed(14.0, QStringLiteral("track"), false);
    out = feed(18.0, QStringLiteral("track"), false);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());

    // Candidate switching cannot combine one box's low fill with another box's later rise.
    out = feed(10.0, QStringLiteral("track"), true, 940);
    out = feed(14.0, QStringLiteral("track"), true, 100);
    out = feed(18.0, QStringLiteral("track"), true, 100);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());

    // Same-center boxes may still be different menu/capture candidates.  Neither a 10x
    // horizontal nor vertical stretch can contribute samples to automatic ownership proof.
    out = feed(10.0);
    out = feed(14.0, QStringLiteral("track"), true, 823, 420, 260, 120);
    out = feed(18.0);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());
    out = feed(10.0);
    out = feed(14.0, QStringLiteral("track"), true, 940, -120, 26, 1200);
    out = feed(18.0);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());
    out = feed(5.0, QStringLiteral("coast")); // isolate the final genuine episode

    // Synthetic menu/loading bars can be unique, geometry-continuous, monotonically rising,
    // and moving. Even convincing stale/hysteretic green UI fields cannot substitute for the
    // reader-origin connected-structure proof. This horizontal animation passed the old gate.
    out = feed(10.0, QStringLiteral("track"), true, 940, 420, 26, 120, false, true);
    out = feed(14.0, QStringLiteral("track"), true, 943, 420, 26, 120, false, true);
    out = feed(18.0, QStringLiteral("track"), true, 946, 420, 26, 120, false, true);
    out = feed(22.0, QStringLiteral("track"), true, 949, 420, 26, 120, false, true);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());
    QCOMPARE(markerSpy.count(), 0);

    // Same adversary moving vertically, as a loading animation or menu selection transition.
    out = feed(10.0, QStringLiteral("track"), true, 600, 400, 26, 120, false, true);
    out = feed(14.0, QStringLiteral("track"), true, 600, 403, 26, 120, false, true);
    out = feed(18.0, QStringLiteral("track"), true, 600, 406, 26, 120, false, true);
    out = feed(22.0, QStringLiteral("track"), true, 600, 409, 26, 120, false, true);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());
    QCOMPARE(markerSpy.count(), 0);

    // Three unique, geometry-continuous, strict-age, captured-after-press rising frames validate
    // the first real, structure-proven shot episode even though the physical hold is long past
    // the ordinary debounce window.
    out = feed(10.0, QStringLiteral("track"), true, 940, 420, 26, 120,
               true, false, shotEpoch);
    out = feed(14.0, QStringLiteral("track"), true, 940, 420, 26, 120,
               true, false, shotEpoch);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());
    out = feed(18.0, QStringLiteral("track"), true, 940, 420, 26, 120,
               true, false, shotEpoch);
    QCOMPARE(engine.context().state, HoldState::Releasing);
    QCOMPARE(engine.context().mode, ShotMode::ButtonShot);
    QVERIFY(engine.context().latencyCalibrationProbe);
    QCOMPARE(engine.shotsAttempted(), 0);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("latency_calibration_probe"));
    QCOMPARE(markerSpy.count(), 1);
    QCOMPARE(markerSpy.at(0).at(2).toBool(), true);
    QVERIFY(!out.square());
}

void AutomationEngineTests::automaticLatencyCalibrationRejectsDelayedPriorShotEpoch()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});
    engine.setAutomaticLatencyCalibrationMode(true);
    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);

    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;
    ControllerState neutral;

    // Shot 1 opens epoch 100, then the player releases before any meter proof returns.
    engine.setPhysicalShotEpoch(100);
    engine.process(square);
    for (int i = 0; i < 3; ++i) {
        engine.advanceTestClock(4.0);
        engine.process(neutral);
    }

    // A quick next Square edge supersedes it synchronously, before process().
    engine.setPhysicalShotEpoch(101);
    ControllerState out = engine.process(square);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());

    int frame = 1;
    auto feed = [&](double fill, quint64 proofEpoch) {
        engine.advanceTestClock(20.0);
        DetectionResult sample = readyMeterSample(fill, -1.0);
        sample.frameNumber = frame++;
        sample.captureTsMs = 100'000.0
            + static_cast<double>(sample.frameNumber) * 20.0;
        sample.measurementCaptureTsMs = sample.captureTsMs;
        sample.x = 940;
        sample.y = 420;
        sample.width = 26;
        sample.height = 120;
        sample.stage = QStringLiteral("track");
        sample.gameplayStructureVerified = true;
        sample.gameplayStructureEpoch = proofEpoch;
        sample.measuredLatencyMs = 0.0;
        sample.measuredLatencyN = 0;
        sample.measuredLatencySdMs = 0.0;
        engine.updateDetection(sample);
        return engine.process(square);
    };

    // A local/legacy arm can prove pixels but carries epoch zero: never authority.
    for (double fill : {10.0, 14.0, 18.0, 22.0}) {
        out = feed(fill, 0);
    }
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());
    QCOMPARE(markerSpy.count(), 0);

    // The delayed structure proof from shot 1 is equally non-authoritative even though
    // its frames are unique, current-age, geometry-stable, and monotonically rising.
    for (double fill : {10.0, 14.0, 18.0, 22.0}) {
        out = feed(fill, 100);
    }
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(out.square());
    QCOMPARE(markerSpy.count(), 0);

    // Only shot 2's exact epoch can promote ownership and emit its one calibration marker.
    out = feed(10.0, 101);
    out = feed(14.0, 101);
    QCOMPARE(engine.context().state, HoldState::Idle);
    out = feed(18.0, 101);
    QCOMPARE(engine.context().state, HoldState::Releasing);
    QCOMPARE(engine.context().physicalShotEpoch, quint64(101));
    QCOMPARE(engine.context().gameplayStructureEpoch, quint64(101));
    QCOMPARE(markerSpy.count(), 1);
    QCOMPARE(markerSpy.at(0).at(2).toBool(), true);
    QVERIFY(!out.square());
}

void AutomationEngineTests::tickLockAlignsFireDeadlineMidTick()
{
    // [ORION_TICK_LOCK] Pure phase-alignment math: nudge an absolute fire deadline so the release ARRIVES
    // mid-tick on the 60Hz console grid (maximally far from the ±T/2 quantization edges).
    const double T = 1000.0 / 60.0;   // ~16.667ms
    const double now = 1000.0;
    const double eta = 4.0;           // next console tick edge 4ms out
    const double edge0 = now + eta;   // tick grid: edge0, edge0+T, edge0+2T, ...
    auto phaseFromEdge = [&](double t) {
        const double rel = t - edge0;
        return rel - std::floor(rel / T) * T;   // [0, T)
    };
    // Worst case: a deadline sitting exactly ON a tick edge (±T/2 quantization). Tick-lock must push it
    // to mid-tick (phase == T/2).
    const double onEdge = edge0 + 3.0 * T;
    const double aligned = AutomationEngine::tickAlignedFireDeadlineMs(onEdge, now, eta, T);
    QVERIFY2(std::abs(phaseFromEdge(aligned) - T / 2.0) < 1e-6,
             qPrintable(QStringLiteral("aligned deadline must land mid-tick; phase=%1 want %2")
                            .arg(phaseFromEdge(aligned)).arg(T / 2.0)));
    QVERIFY2(std::abs(aligned - onEdge) <= T / 2.0 + 1e-6,
             "the nudge must be bounded to half a tick (a committed fire never slips more than T/2)");
    // A deadline already mid-tick must not move.
    const double midTick = edge0 + 2.0 * T + T / 2.0;
    QVERIFY2(std::abs(AutomationEngine::tickAlignedFireDeadlineMs(midTick, now, eta, T) - midTick) < 1e-6,
             "a mid-tick deadline must be left unchanged");
    // Telemetry-not-ready (eta <= 0) returns the deadline unchanged (byte-identical to today).
    QCOMPARE(AutomationEngine::tickAlignedFireDeadlineMs(onEdge, now, 0.0, T), onEdge);
}

void AutomationEngineTests::regFusionUsesRegistrationAtFarHorizon()
{
    // [ORION_REG_FUSION] At the FAR horizon (low fill / commit >~200ms out) the quadratic sampler blows
    // up; the sidecar's registration time-to-TIP (reg_tip_ms) is flat/accurate there. With the flag ON
    // and adequate reg confidence, the release crossing must follow reg_tip_ms; OFF it follows the
    // sampler (a very different value at this horizon).
    auto crossingEta = [](bool regFusion) -> double {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.maximumHoldMs = 5000.0;
        config.tempoFallbackTimeoutMs = 5000.0;
        config.regFusionEnabled = regFusion;
        LearningData learning;
        engine.applyConfig(config, learning);
        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        engine.process(physical);
        engine.advanceTestClock(220);
        engine.process(physical);                    // -> Holding
        auto farSample = [](double fill) {
            DetectionResult r = readyMeterSample(fill, -1.0);
            r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0; r.greenConfidence = 0.0;
            r.velocityPctS = 40.0;                   // slow rise -> sampler crossing is FAR / absent
            r.regTipMs = 300.0;                      // registration: tip 300ms out (>= far horizon)
            r.regConf = 0.9;
            return r;
        };
        double fill = 30.0;
        for (int i = 0; i < 12; ++i) {               // low fill -> far horizon, no predictive release;
            engine.updateDetection(farSample(fill));  // ~360ms total drives past the 140ms commit floor
            engine.process(physical);
            engine.advanceTestClock(30);
            fill += 0.8;                              // stays < the 42% predictive floor throughout
        }
        return engine.context().releaseCrossingEtaMs;
    };
    const double on = crossingEta(true);
    const double off = crossingEta(false);
    QVERIFY2(std::abs(on - 300.0) < 40.0,
             qPrintable(QStringLiteral("far horizon: crossing must follow reg_tip_ms(300); got %1").arg(on)));
    QVERIFY2(std::abs(on - off) > 40.0,
             qPrintable(QStringLiteral("reg fusion must change the far-horizon crossing; on=%1 off=%2")
                            .arg(on).arg(off)));
}

void AutomationEngineTests::adaptiveAutonomousSchedulerTracksSourceCadence()
{
    AutomationEngine engine;
    AppConfigData config;
    config.autonomousVision = true;
    engine.applyConfig(config, LearningData{});

    engine.genuineFrameGapEmaMs_ = 1000.0 / 60.0;
    engine.genuineFrameGapHighWaterMs_ = 1000.0 / 60.0;
    const double sixtyFpsGapMs = 1000.0 / 60.0;
    // [ORION_ARMING_HORIZON] 2*gap+6 -> 4*gap+6 -> 7*gap+6. The window has to be wider than the
    // distance the command deadline MOVES between frames, or the deadline steps over it and is
    // discovered already overdue. 4*gap+6 is 72.7 ms at 60 FPS, against a measured p90
    // per-refinement collapse of 105.8 ms and p95 of 122.7 ms in the 2026-08-04 post-fix batch --
    // still about half the step it existed to cover, and three shots aborted stepping over it.
    // Seven gaps covers the p95. See armingHorizonCoversMeasuredInterFrameStepOver() for the
    // behavioural gate and the per-shot evidence.
    QVERIFY(std::abs(engine.adaptiveAutonomousSchedulerHorizonMs()
                     - (7.0 * sixtyFpsGapMs + 6.0)) < 1e-6);

    // A deadline just over one frame away used to miss the gap+6 handoff window.
    // The vision-only worker now owns it one frame earlier, still inside the
    // immutable genuine-frame authority lease.
    engine.setArmed(true);
    const double now = engine.engineNowMs();
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.lastFreshAcceptMs = now;
    engine.shot_.frameAgeMs = 0.0;
    engine.shot_.fillPct = 50.0;
    engine.shot_.confidence = 1.0;
    engine.shot_.physicalShotEpoch = 91;
    engine.shot_.armToken = 92;
    engine.shot_.visionEpoch = 93;
    engine.measuredLeadLastUpdateMs_ = now;
    QVERIFY(engine.scheduleFire(
        now + 30.0, now, -1.0,
        AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision));
    QCOMPARE(engine.scheduledFireDeadlineMs(), now + 30.0);
    engine.invalidateUnconfirmedVisionSchedule();

    // A slower source still tracks LINEARLY below the ceiling: max(ema, high-water) = 18
    // (~55 FPS) -> 7*18 + 6 = 132, which is under the 135 ms cap so the linear term is what is
    // actually being observed here rather than the clamp.
    engine.genuineFrameGapEmaMs_ = 16.0;
    engine.genuineFrameGapHighWaterMs_ = 18.0;
    QVERIFY(std::abs(engine.adaptiveAutonomousSchedulerHorizonMs() - 132.0) < 1e-6);

    // Stall-sized high-water spikes are still clamped to the 29 ms clean gap, and the outer
    // clamp caps the window at 135 ms however slow the source claims to be (7*29 + 6 = 209).
    // The window must stay BOUNDED: an unbounded horizon would let a shot commit a deadline
    // before its trajectory carries any information.
    engine.genuineFrameGapHighWaterMs_ = 80.0;
    QCOMPARE(engine.adaptiveAutonomousSchedulerHorizonMs(), 135.0);

    engine.genuineFrameGapEmaMs_ = 0.0;
    engine.genuineFrameGapHighWaterMs_ = 0.0;
    QVERIFY(std::abs(engine.adaptiveAutonomousSchedulerHorizonMs()
                     - (7.0 * sixtyFpsGapMs + 6.0)) < 1e-6);
}

void AutomationEngineTests::autonomousTipPastDeadlineAlwaysFailsClosed()
{
    struct Result {
        HoldState state = HoldState::Idle;
        QString reason;
        QString diagnostic;
        int markers = 0;
        int aborts = 0;
        bool squareOut = false;
    };

    const auto run = [](double latenessMs) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        engine.applyConfig(config, LearningData{});

        const double now = engine.engineNowMs();
        constexpr double leadMs = 70.0;
        engine.measuredLatencyMs_ = leadMs;
        engine.measuredLatencySdMs_ = 2.0;
        engine.measuredLatencyN_ = 6;
        engine.measuredLatencyAuthorityKind_ = QStringLiteral("validated");
        engine.measuredLatencyAuthorityMs_ = leadMs;
        engine.measuredLatencyAuthoritySdMs_ = 2.0;
        engine.measuredLeadTelemetryPresent_ = true;
        engine.measuredLeadEverValid_ = true;
        engine.measuredLeadEpochReady_ = true;
        engine.measuredLeadLastUpdateMs_ = now;

        engine.shot_.state = HoldState::Holding;
        engine.shot_.mode = ShotMode::ButtonShot;
        engine.shot_.shotType = QStringLiteral("Standstill");
        engine.shot_.holdStartMs = now - 10.0;
        engine.shot_.physicalShotEpoch = 9'201;
        engine.shot_.armToken = 9'202;
        engine.shot_.visionEpoch = 7;
        engine.shot_.meterDetected = true;
        engine.shot_.lastSampleGenuineAccept = true;
        engine.shot_.lastFreshAcceptMs = now;
        engine.shot_.firstFreshAcceptMs = now;
        engine.shot_.anchorValidMs = now;
        engine.shot_.sawFreshMeterThisShot = true;
        engine.shot_.meterSeenThisShot = true;
        engine.shot_.frameAgeMs = 0.0;
        engine.shot_.fillPct = 50.0;
        engine.shot_.confidence = 1.0;

        // Registration supplies a valid future TIP while the derived command
        // deadline is intentionally just behind the decision clock.
        engine.shot_.regTipMs = leadMs - latenessMs;
        engine.shot_.regTipAbsMs = now + engine.shot_.regTipMs;
        engine.shot_.regConf = 1.0;
        engine.shot_.regSigmaMs = 2.0;
        engine.shot_.regN = 16;
        engine.shot_.regModelId = QStringLiteral("timing-audit-model");
        engine.shot_.regModelVersion = QStringLiteral("1");

        engine.lastPhysical_.buttons |= XINPUT_GAMEPAD_X;
        ControllerState output = engine.lastPhysical_;
        QSignalSpy markers(&engine, &AutomationEngine::releaseMarker);
        QSignalSpy aborts(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diagnostics(&engine, &AutomationEngine::engineDiagnostic);
        engine.processAutonomousLiveMeterHolding(output, now);

        Result result;
        result.state = engine.context().state;
        result.reason = engine.context().releaseReasonCode;
        result.markers = markers.count();
        result.aborts = aborts.count();
        result.squareOut = output.square();
        for (const QList<QVariant>& row : diagnostics) {
            const QString line = row.at(0).toString();
            if (line.startsWith(QStringLiteral("TIP DEADLINE DECISION:"))) {
                result.diagnostic = line;
            }
        }
        return result;
    };

    // Even a one-millisecond miss is already too late for a new command. None
    // may emit an UP edge or masquerade as a successful live-tip release.
    for (const double latenessMs : {1.0, 4.0, 12.0, 20.0, 47.0}) {
        const Result missed = run(latenessMs);
        QCOMPARE(missed.state, HoldState::Idle);
        QCOMPARE(missed.reason, QStringLiteral("live_tip_deadline_missed"));
        QCOMPARE(missed.markers, 0);
        QCOMPARE(missed.aborts, 1);
        QVERIFY(missed.squareOut); // physical DOWN restored; no synthetic UP edge
        QVERIFY(missed.diagnostic.contains(QStringLiteral("disposition=rejected_missed")));
        QVERIFY(!missed.diagnostic.contains(QStringLiteral("cadence_recovery_release")));
    }
}

namespace {

struct ReservationRun {
    QStringList diagnostics;
    int markers = 0;
    int aborts = 0;
    HoldState finalState = HoldState::Idle;
    QString finalReason;
    bool squareOut = false;
    bool everHeld = false;      // the harness actually reached the owned autonomous path
    bool leadEverReady = false; // ...with live lead authority, so the path was not short-circuited
    QString createdLine;
    QString promotedLine;
    QString abortLine;
    int createdCount = 0;
    int updatedCount = 0;
    int promotedCount = 0;
    int canceledCount = 0;
};

// Pull a "key=value" number out of one of the engine's structured diagnostic lines.
static double diagField(const QString& line, const QString& key, bool* ok = nullptr)
{
    if (ok) {
        *ok = false;
    }
    const int at = line.indexOf(key + QLatin1Char('='));
    if (at < 0) {
        return 0.0;
    }
    const int from = at + key.size() + 1;
    int to = from;
    while (to < line.size() && !line.at(to).isSpace()) {
        ++to;
    }
    return line.mid(from, to - from).toDouble(ok);
}

// Drives a genuine 60 FPS rising meter through a strictly-owned autonomous Square shot. Stands in
// for OrionPreciseFireThread exactly the way the closed-loop timing tests do: when the engine arms
// a deadline, advance to it and confirm the token.
//
// This reproduces the 2026-08-03 live session shape: ownership lands around 13% fill, the meter
// rises at ~0.18 %/ms, and the canonical decision is far too uncertain to be valid for most of the
// climb. `epochSwapAtFrame` >= 0 injects a physical-epoch change mid-flight.
static ReservationRun driveAutonomousRise(double leadMs, double leadSdMs,
                                          double velocityPctPerMs, int maxFrames,
                                          int epochSwapAtFrame = -1)
{
    constexpr quint64 kEpoch = 4'411;
    constexpr double kFrameMs = 1000.0 / 60.0;

    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;

    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy abortSpy(&engine, &AutomationEngine::shotAborted);
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

    int frame = 1;
    quint64 epoch = kEpoch;
    ControllerState output = promoteStrictAutonomousSquare(
        engine, square, frame, epoch, leadMs, leadSdMs, 6, 6.0);

    ReservationRun run;
    double fill = 13.0;
    for (int i = 0; i < maxFrames; ++i) {
        engine.advanceTestClock(kFrameMs);
        fill = std::min(99.5, fill + velocityPctPerMs * kFrameMs);
        if (i == epochSwapAtFrame) {
            epoch = kEpoch + 1;
            engine.setPhysicalShotEpoch(epoch);
        }
        DetectionResult sample = strictLiveMeterSample(
            fill, frame++, epoch, leadMs, leadSdMs, 6);
        sample.frameAgeMs = 6.0;
        engine.updateDetection(sample);
        output = engine.process(square);
        if (engine.context().state == HoldState::Holding) {
            run.everHeld = true;
        }
        if (engine.autonomousLiveMeterReady()) {
            run.leadEverReady = true;
        }

        if (engine.scheduledFireDeadlineMs() >= 0.0) {
            const double deadline = engine.scheduledFireDeadlineMs();
            const quint64 token = engine.scheduledFireToken();
            const double untilMs = deadline - engine.engineNowMs();
            if (untilMs > 0.0) {
                engine.advanceTestClock(untilMs);
            }
            engine.confirmScheduledFire(token, deadline);
            output = engine.process(square);
        }
        if (markerSpy.count() > 0 || abortSpy.count() > 0) {
            break;
        }
    }

    run.markers = markerSpy.count();
    run.aborts = abortSpy.count();
    run.finalState = engine.context().state;
    run.finalReason = engine.context().releaseReasonCode;
    run.squareOut = output.square();
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        run.diagnostics << line;
        if (line.startsWith(QStringLiteral("TIP RESERVATION:"))) {
            if (line.contains(QStringLiteral("disposition=reservation_created"))) {
                ++run.createdCount;
                if (run.createdLine.isEmpty()) {
                    run.createdLine = line;
                }
            } else if (line.contains(QStringLiteral("disposition=reservation_updated"))) {
                ++run.updatedCount;
            } else if (line.contains(QStringLiteral("disposition=reservation_promoted"))) {
                ++run.promotedCount;
                run.promotedLine = line;
            } else if (line.contains(QStringLiteral("disposition=reservation_canceled"))) {
                ++run.canceledCount;
            }
        } else if (line.startsWith(QStringLiteral("TIP DEADLINE DECISION:"))
                   && line.contains(QStringLiteral("disposition=rejected_missed"))) {
            run.abortLine = line;
        }
    }
    return run;
}

}  // namespace

void AutomationEngineTests::tipReservationIsCreatedCausallyBeforeTheCommandDeadline()
{
    // THE 2026-08-03 REGRESSION. On that session the engine tracked nothing between ownership
    // (~13-25% fill) and the instant the canonical decision first became valid (~47-58% fill), so
    // it discovered its own command deadline only once that deadline was already in the past --
    // 8 of 10 owned shots aborted with command_eta_ms between -0.464 and -129.081 ms.
    //
    // The reservation must exist BEFORE that point and must describe a deadline in the FUTURE.
    // That is the whole causality claim: at ownership there was always time; the old code simply
    // was not looking.
    const ReservationRun run = driveAutonomousRise(
        /*leadMs=*/196.0, /*leadSdMs=*/2.0, /*velocityPctPerMs=*/0.18, /*maxFrames=*/60);

    QVERIFY2(run.everHeld, "harness never reached the owned autonomous holding path");
    QVERIFY2(run.leadEverReady, "harness never established live lead authority");
    QVERIFY2(run.createdCount >= 1, "no reservation was ever created during an owned rising shot");
    QCOMPARE(run.createdCount, 1);   // exactly one plan per shot, not one per frame

    bool ok = false;
    const double commandEtaMs = diagField(run.createdLine, QStringLiteral("command_eta_ms"), &ok);
    QVERIFY2(ok, qPrintable(QStringLiteral("no command_eta_ms in: %1").arg(run.createdLine)));
    QVERIFY2(commandEtaMs > 0.0,
             qPrintable(QStringLiteral("reservation was born already late: command_eta_ms=%1")
                            .arg(commandEtaMs)));

    // It must be a genuinely EARLY plan: created while the decision is still too uncertain to
    // authorise a release. A reservation that only appears once the decision is already valid
    // would buy nothing over the old behaviour.
    const double createdFill = diagField(run.createdLine, QStringLiteral("fill_pct"));
    QVERIFY2(createdFill < 47.0,
             qPrintable(QStringLiteral("reservation created too late, at fill %1%")
                            .arg(createdFill)));

    // Fresh frames refine the same plan rather than starting new ones.
    QVERIFY(run.updatedCount >= 1);
}

void AutomationEngineTests::tipReservationPromotesExactlyOnceWithMatchingIdentity()
{
    const ReservationRun run = driveAutonomousRise(
        /*leadMs=*/196.0, /*leadSdMs=*/2.0, /*velocityPctPerMs=*/0.18, /*maxFrames=*/60);

    QVERIFY2(run.everHeld, "harness never reached the owned autonomous holding path");
    QVERIFY2(run.leadEverReady, "harness never established live lead authority");
    // Exactly one physical release, one marker, no duplicate submission from the repeated
    // per-frame refinement.
    QCOMPARE(run.markers, 1);
    QCOMPARE(run.aborts, 0);
    QCOMPARE(run.promotedCount, 1);
    QVERIFY(!run.promotedLine.isEmpty());

    // The promotion must carry the same identity the delivery will assert.
    bool ok = false;
    const double epoch = diagField(run.promotedLine, QStringLiteral("physical_epoch"), &ok);
    QVERIFY(ok);
    QCOMPARE(static_cast<quint64>(epoch), static_cast<quint64>(4'411));
    const double token = diagField(run.promotedLine, QStringLiteral("schedule_token"), &ok);
    QVERIFY(ok);
    QVERIFY2(token > 0.0, "promoted reservation carries no schedule token");
    const double attempt = diagField(run.promotedLine, QStringLiteral("shot_attempt"), &ok);
    QVERIFY(ok);
    QVERIFY(attempt > 0.0);

    // The command must be submitted ahead of the tip, never behind it.
    const double commandEtaMs = diagField(run.promotedLine, QStringLiteral("command_eta_ms"), &ok);
    QVERIFY(ok);
    QVERIFY2(commandEtaMs > 0.0,
             qPrintable(QStringLiteral("promoted a deadline already in the past: %1")
                            .arg(commandEtaMs)));
}

namespace {

// Pull a "key=value" STRING token out of a structured diagnostic line ("" = absent).
static QString diagToken(const QString& line, const QString& key)
{
    const int at = line.indexOf(key + QLatin1Char('='));
    if (at < 0) {
        return QString();
    }
    const int from = at + key.size() + 1;
    int to = from;
    while (to < line.size() && !line.at(to).isSpace()) {
        ++to;
    }
    return line.mid(from, to - from);
}

}  // namespace

void AutomationEngineTests::outcomeIdentityCarriesThePromotingDecisionsSourceAndSigma()
{
    // [ORION_ARMED_SOURCE] The per-shot "Outcome identity:" line must carry the values of the
    // decision that ACTUALLY armed the fired token -- captured at the arm instant and carried
    // token -> release -> outcome -- never a default and never a re-derivation at emit time
    // (shot_ has been reset long before the outcome arrives ~1.2s later).
    //
    // REVERT-TRACE. With the schedFireArmed*/armedPredictor*/lastReleaseArmed* plumbing
    // reverted this fails on armed_source=none. With any field HARDCODED it fails on the
    // cross-run check at the bottom: the two trajectories promote at different command ETAs /
    // fills, and each outcome must equal ITS OWN promotion line, so no constant satisfies both.
    struct OutcomeRun {
        QString promotedLine;
        QString outcomeLine;
        int markers = 0;
    };
    auto drive = [](quint64 epoch, double velocityPctPerMs) -> OutcomeRun {
        constexpr double kFrameMs = 1000.0 / 60.0;
        constexpr double kLeadMs = 196.0;

        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        engine.applyConfig(config, LearningData{});

        ControllerState square;
        square.buttons |= XINPUT_GAMEPAD_X;

        QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

        int frame = 1;
        ControllerState output = promoteStrictAutonomousSquare(
            engine, square, frame, epoch, kLeadMs, 2.0, 6, 6.0);

        double fill = 13.0;
        for (int i = 0; i < 60 && markerSpy.count() == 0; ++i) {
            engine.advanceTestClock(kFrameMs);
            fill = std::min(99.5, fill + velocityPctPerMs * kFrameMs);
            DetectionResult sample = strictLiveMeterSample(
                fill, frame++, epoch, kLeadMs, 2.0, 6);
            sample.frameAgeMs = 6.0;
            engine.updateDetection(sample);
            output = engine.process(square);
            if (engine.scheduledFireDeadlineMs() >= 0.0) {
                const double deadline = engine.scheduledFireDeadlineMs();
                const quint64 token = engine.scheduledFireToken();
                const double untilMs = deadline - engine.engineNowMs();
                if (untilMs > 0.0) {
                    engine.advanceTestClock(untilMs);
                }
                engine.confirmScheduledFire(token, deadline);
                output = engine.process(square);
            }
        }
        Q_UNUSED(output);

        OutcomeRun run;
        run.markers = markerSpy.count();
        // The HUD verdict arrives ~1.2s post-release; updateShotOutcome enforces that window.
        engine.advanceTestClock(900.0);
        engine.updateShotOutcome(QStringLiteral("EXCELLENT"), 0.0, 1.0);
        for (const QList<QVariant>& row : diagSpy) {
            const QString line = row.at(0).toString();
            if (line.contains(QStringLiteral("disposition=reservation_promoted"))) {
                run.promotedLine = line;
            } else if (line.startsWith(QStringLiteral("Outcome identity:"))) {
                run.outcomeLine = line;
            }
        }
        return run;
    };

    const OutcomeRun a = drive(5'517, 0.18);
    const OutcomeRun b = drive(5'518, 0.24);

    for (const OutcomeRun* run : {&a, &b}) {
        QCOMPARE(run->markers, 1);
        QVERIFY2(!run->promotedLine.isEmpty(), "shot never promoted a reservation");
        QVERIFY2(!run->outcomeLine.isEmpty(), "no Outcome identity line was emitted");

        // The outcome's attribution must equal the PROMOTION line's, field for field.
        const QString promotedSource =
            diagToken(run->promotedLine, QStringLiteral("source"));
        const QString armedSource =
            diagToken(run->outcomeLine, QStringLiteral("armed_source"));
        QVERIFY2(!promotedSource.isEmpty(), "promotion line carries no source");
        QVERIFY2(armedSource != QStringLiteral("none"),
                 qPrintable(QStringLiteral("outcome lost its attribution: %1")
                                .arg(run->outcomeLine)));
        QCOMPARE(armedSource, promotedSource);

        bool ok = false;
        const double promotedSigma =
            diagField(run->promotedLine, QStringLiteral("predictor_sigma_ms"), &ok);
        QVERIFY(ok);
        const double armedSigma =
            diagField(run->outcomeLine, QStringLiteral("armed_sigma_ms"), &ok);
        QVERIFY(ok);
        QVERIFY2(std::abs(armedSigma - promotedSigma) < 0.0015,
                 qPrintable(QStringLiteral("sigma not carried: outcome %1 vs promoted %2")
                                .arg(armedSigma).arg(promotedSigma)));

        const double promotedFill =
            diagField(run->promotedLine, QStringLiteral("fill_pct"), &ok);
        QVERIFY(ok);
        const double armedFill =
            diagField(run->outcomeLine, QStringLiteral("armed_fill_pct"), &ok);
        QVERIFY(ok);
        QVERIFY2(std::abs(armedFill - promotedFill) < 0.015,
                 qPrintable(QStringLiteral("fill not carried: outcome %1 vs promoted %2")
                                .arg(armedFill).arg(promotedFill)));

        const double promotedEta =
            diagField(run->promotedLine, QStringLiteral("command_eta_ms"), &ok);
        QVERIFY(ok);
        const double armedEta =
            diagField(run->outcomeLine, QStringLiteral("command_eta_ms"), &ok);
        QVERIFY(ok);
        QVERIFY2(std::abs(armedEta - promotedEta) < 0.0015,
                 qPrintable(QStringLiteral("command eta not carried: outcome %1 vs promoted %2")
                                .arg(armedEta).arg(promotedEta)));

        const double promotedToken =
            diagField(run->promotedLine, QStringLiteral("schedule_token"), &ok);
        QVERIFY(ok);
        const double armedToken =
            diagField(run->outcomeLine, QStringLiteral("armed_schedule_token"), &ok);
        QVERIFY(ok);
        QVERIFY2(promotedToken > 0.0, "promotion carries no schedule token");
        QCOMPARE(armedToken, promotedToken);
    }

    // Anti-hardcode: the two runs promote at different command ETAs (different velocities),
    // so the per-run equalities above cannot be satisfied by any constant.
    bool ok = false;
    const double etaA = diagField(a.promotedLine, QStringLiteral("command_eta_ms"), &ok);
    QVERIFY(ok);
    const double etaB = diagField(b.promotedLine, QStringLiteral("command_eta_ms"), &ok);
    QVERIFY(ok);
    QVERIFY2(std::abs(etaA - etaB) > 0.01,
             "harness degenerated: both runs promoted identical decisions, the "
             "hardcoding guard is void");
}

void AutomationEngineTests::outcomeIdentityRendersUnattributedReleaseAsNone()
{
    // [ORION_ARMED_SOURCE] A release that did not fire from an attributed autonomous vision
    // token must render as armed_source=none with -1/-1/-1/0 sentinels -- absent, never a
    // stale or invented attribution.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    engine.applyConfig(config, LearningData{});

    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    engine.lastReleaseSeq_ = 7;
    engine.lastReleasePhysicalShotEpoch_ = 91;
    engine.lastReleaseShotAttempt_ = 3;
    engine.emitShotOutcome(7, QStringLiteral("Standstill"), QStringLiteral("Standstill"),
                           QStringLiteral("LATE"), 12.0);

    QString outcomeLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("Outcome identity:"))) {
            outcomeLine = line;
        }
    }
    QVERIFY2(!outcomeLine.isEmpty(), "no Outcome identity line was emitted");
    QCOMPARE(diagToken(outcomeLine, QStringLiteral("armed_source")), QStringLiteral("none"));
    bool ok = false;
    QCOMPARE(diagField(outcomeLine, QStringLiteral("armed_sigma_ms"), &ok), -1.0);
    QVERIFY(ok);
    QCOMPARE(diagField(outcomeLine, QStringLiteral("armed_schedule_token"), &ok), 0.0);
    QVERIFY(ok);
    // The five original fields keep their exact names and order.
    QVERIFY(outcomeLine.startsWith(QStringLiteral(
        "Outcome identity: physical_epoch=91 shot_attempt=3 release_seq=7 verdict=LATE ")));
}

void AutomationEngineTests::tipReservationCancelsOnIdentityChangeWithoutReleasing()
{
    // A plan is bound to one physical shot. A new physical epoch mid-flight must retire it; a
    // stale plan surviving into a new epoch is exactly how an old deadline could fire a new shot.
    const ReservationRun run = driveAutonomousRise(
        /*leadMs=*/196.0, /*leadSdMs=*/2.0, /*velocityPctPerMs=*/0.18, /*maxFrames=*/60,
        /*epochSwapAtFrame=*/3);

    QVERIFY2(run.everHeld, "harness never reached the owned autonomous holding path");
    QVERIFY2(run.canceledCount >= 1, "physical epoch changed but no reservation was cancelled");
    QCOMPARE(run.markers, 0);
    QVERIFY2(run.squareOut, "physical DOWN must be restored; no synthetic UP edge on cancellation");
}

void AutomationEngineTests::tipReservationAttributesAMissedDeadlineHonestly()
{
    // With the inflated 241.4 ms lead the live session actuated on, a shot must still FAIL CLOSED
    // -- and must now say WHICH failure happened rather than reporting an undifferentiated miss.
    //
    // Deliberately NOT driven through driveAutonomousRise: whether a given synthetic trajectory
    // happens to beat a given lead is incidental, and a test that branches on it silently stops
    // covering the abort path the day the trajectory changes. Hand-stuff a shot whose command
    // deadline is ALREADY behind the clock the first time it can be computed, which is precisely
    // the live signature (epoch 8: tip_eta 226.348 vs a 241.4 lead -> command_eta -15.052).
    // first time it can be computed, which is precisely the live signature. No branching on
    // whether the trajectory happened to make it -- this case must always abort.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    const double now = engine.engineNowMs();
    constexpr double leadMs = 241.4;
    engine.measuredLatencyMs_ = leadMs;
    engine.measuredLatencySdMs_ = 2.0;
    engine.measuredLatencyN_ = 6;
    engine.measuredLatencyAuthorityKind_ = QStringLiteral("validated");
    engine.measuredLatencyAuthorityMs_ = leadMs;
    engine.measuredLatencyAuthoritySdMs_ = 2.0;
    engine.measuredLeadTelemetryPresent_ = true;
    engine.measuredLeadEverValid_ = true;
    engine.measuredLeadEpochReady_ = true;
    engine.measuredLeadLastUpdateMs_ = now;

    engine.shot_.state = HoldState::Holding;
    engine.shot_.mode = ShotMode::ButtonShot;
    engine.shot_.shotType = QStringLiteral("Standstill");
    engine.shot_.holdStartMs = now - 10.0;
    engine.shot_.physicalShotEpoch = 9'301;
    engine.shot_.armToken = 9'302;
    engine.shot_.visionEpoch = 7;
    engine.shot_.meterDetected = true;
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.lastFreshAcceptMs = now;
    engine.shot_.firstFreshAcceptMs = now;
    engine.shot_.anchorValidMs = now;
    engine.shot_.sawFreshMeterThisShot = true;
    engine.shot_.meterSeenThisShot = true;
    engine.shot_.frameAgeMs = 0.0;
    engine.shot_.fillPct = 52.7;      // the live fill at the moment of decision
    engine.shot_.confidence = 1.0;

    // Live epoch 8: tip_eta 226.348 against a 241.4 lead -> command_eta -15.052.
    engine.shot_.regTipMs = 226.348;
    engine.shot_.regTipAbsMs = now + engine.shot_.regTipMs;
    engine.shot_.regConf = 1.0;
    engine.shot_.regSigmaMs = 2.0;
    engine.shot_.regN = 16;
    engine.shot_.regModelId = QStringLiteral("timing-audit-model");
    engine.shot_.regModelVersion = QStringLiteral("1");

    engine.lastPhysical_.buttons |= XINPUT_GAMEPAD_X;
    ControllerState output = engine.lastPhysical_;
    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy abortSpy(&engine, &AutomationEngine::shotAborted);
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    engine.processAutonomousLiveMeterHolding(output, now);

    QString abortLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("TIP DEADLINE DECISION:"))) {
            abortLine = line;
        }
    }

    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("live_tip_deadline_missed"));
    QCOMPARE(markerSpy.count(), 0);
    QCOMPARE(abortSpy.count(), 1);
    QVERIFY2(output.square(), "physical DOWN restored; no synthetic UP edge on a missed deadline");
    QVERIFY(!abortLine.isEmpty());
    QVERIFY(abortLine.contains(QStringLiteral("disposition=rejected_missed")));
    // The whole point of the attribution: this is a LEAD problem, not a predictor problem, and the
    // log must say so rather than reporting an undifferentiated miss.
    QVERIFY2(abortLine.contains(QStringLiteral("reservation_disposition=unschedulable_lead")),
             qPrintable(QStringLiteral("wrong attribution in: %1").arg(abortLine)));
    QVERIFY(!abortLine.contains(QStringLiteral("cadence_recovery_release")));

    bool ok = false;
    const double commandEta = diagField(abortLine, QStringLiteral("command_eta_ms"), &ok);
    QVERIFY(ok);
    QVERIFY(commandEta < 0.0);
}

void AutomationEngineTests::tipReservationSeparatesLateValidityFromAuthorityLoss()
{
    // THE 2026-08-03 SIGNATURE, and the one an earlier version of this attribution could never
    // report. On that session the command deadline WAS comfortably in the future at ownership
    // (fireAt ~ +147ms) and the canonical decision simply did not become authoritative until the
    // deadline had already passed. That is a PREDICTOR failure (sigma grows 0.20ms per ms of
    // horizon against a 65ms cap), not an authority loss, and the log must say so -- otherwise the
    // operator is sent to investigate routes and leases while the real fault is the sigma gate.
    //
    // Two ticks are required, because the distinction is inherently temporal:
    //   tick 1  deadline in the FUTURE, decision INVALID (sigma over the cap)
    //   tick 2  deadline in the PAST,   decision VALID
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    const double t0 = engine.engineNowMs();
    constexpr double leadMs = 241.4;
    engine.measuredLatencyMs_ = leadMs;
    engine.measuredLatencySdMs_ = 2.0;
    engine.measuredLatencyN_ = 6;
    engine.measuredLatencyAuthorityKind_ = QStringLiteral("validated");
    engine.measuredLatencyAuthorityMs_ = leadMs;
    engine.measuredLatencyAuthoritySdMs_ = 2.0;
    engine.measuredLeadTelemetryPresent_ = true;
    engine.measuredLeadEverValid_ = true;
    engine.measuredLeadEpochReady_ = true;
    engine.measuredLeadLastUpdateMs_ = t0;

    engine.shot_.state = HoldState::Holding;
    engine.shot_.mode = ShotMode::ButtonShot;
    engine.shot_.shotType = QStringLiteral("Standstill");
    engine.shot_.holdStartMs = t0 - 10.0;
    engine.shot_.physicalShotEpoch = 9'401;
    engine.shot_.armToken = 9'402;
    engine.shot_.visionEpoch = 11;
    engine.shot_.meterDetected = true;
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.firstFreshAcceptMs = t0;
    engine.shot_.anchorValidMs = t0;
    engine.shot_.sawFreshMeterThisShot = true;
    engine.shot_.meterSeenThisShot = true;
    engine.shot_.frameAgeMs = 0.0;
    engine.shot_.confidence = 1.0;
    engine.shot_.regModelId = QStringLiteral("timing-audit-model");
    engine.shot_.regModelVersion = QStringLiteral("1");
    engine.shot_.regConf = 1.0;
    engine.shot_.regN = 16;

    engine.lastPhysical_.buttons |= XINPUT_GAMEPAD_X;
    ControllerState output = engine.lastPhysical_;
    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy abortSpy(&engine, &AutomationEngine::shotAborted);
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

    // --- tick 1: ownership-era. Tip far out, so the command deadline is genuinely ahead of us,
    // but the prediction is far too uncertain to authorise anything (combined sigma ~80 > 65 cap).
    engine.shot_.fillPct = 18.0;
    engine.shot_.lastFreshAcceptMs = t0;
    engine.shot_.regTipMs = 500.0;
    engine.shot_.regTipAbsMs = t0 + 500.0;
    engine.shot_.regSigmaMs = 80.0;
    engine.processAutonomousLiveMeterHolding(output, t0);

    QCOMPARE(markerSpy.count(), 0);
    QCOMPARE(abortSpy.count(), 0);           // still tracking; nothing decided yet
    QVERIFY2(engine.tipReservationView().active,
             "a future-deadline plan must exist before the decision is ever valid");

    // --- tick 2: the deadline has passed, and only NOW does the fit tighten enough to be valid.
    const double t1 = t0 + 300.0;
    engine.advanceTestClock(300.0);
    // The lead snapshot carries its own freshness lease; without renewing it the 300ms advance
    // revokes lead authority and the engine never reaches the deadline test at all.
    engine.measuredLeadLastUpdateMs_ = t1;
    engine.shot_.fillPct = 52.7;
    engine.shot_.lastFreshAcceptMs = t1;
    engine.shot_.anchorValidMs = t1;
    engine.shot_.regTipMs = 226.348;
    engine.shot_.regTipAbsMs = t1 + 226.348;   // -> fireAt = t1 - 15.05, already behind us
    engine.shot_.regSigmaMs = 2.0;
    engine.processAutonomousLiveMeterHolding(output, t1);

    QString abortLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("TIP DEADLINE DECISION:"))) {
            abortLine = line;
        }
    }

    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("live_tip_deadline_missed"));
    QCOMPARE(markerSpy.count(), 0);
    QCOMPARE(abortSpy.count(), 1);
    QVERIFY2(output.square(), "physical DOWN restored; no synthetic UP edge on a missed deadline");
    QVERIFY(!abortLine.isEmpty());
    QVERIFY(abortLine.contains(QStringLiteral("disposition=rejected_missed")));

    // The whole point. Not authority_lost_before_submit -- there was never a valid, still-future
    // moment to lose. Not unschedulable_lead -- the deadline genuinely was ahead of us at t0.
    QVERIFY2(abortLine.contains(
                 QStringLiteral("reservation_disposition=deadline_missed_before_validity")),
             qPrintable(QStringLiteral("wrong attribution in: %1").arg(abortLine)));
    QVERIFY(!abortLine.contains(QStringLiteral("authority_lost_before_submit")));
    QVERIFY(!abortLine.contains(QStringLiteral("unschedulable_lead")));
}

void AutomationEngineTests::primeRollingLeaseEngine(AutomationEngine& engine, double now,
                                                    double frameAgeMs)
{
    engine.setArmed(true);
    engine.shot_.state = HoldState::Holding;
    engine.shot_.mode = ShotMode::ButtonShot;
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.lastFreshAcceptMs = now;
    engine.shot_.frameAgeMs = frameAgeMs;
    engine.shot_.fillPct = 40.0;
    engine.shot_.confidence = 1.0;
    engine.shot_.meterDetected = true;
    engine.shot_.lastDetectionMs = now;
    engine.shot_.physicalShotEpoch = 8'101;
    engine.shot_.armToken = 8'102;
    engine.shot_.visionEpoch = 21;
    engine.shot_.holdStartMs = now - 200.0;
    engine.measuredLeadLastUpdateMs_ = now;
    engine.genuineFrameGapEmaMs_ = 1000.0 / 60.0;
    engine.genuineFrameGapHighWaterMs_ = 1000.0 / 60.0;
}

void AutomationEngineTests::rollingLeaseArmsDeadlineBeyondOneFrameOfAuthority()
{
    // [ORION_ROLLING_LEASE] THE 2026-08-04 SIGNATURE.
    //
    // meterAuthorityExpiryMs() is `capture_time + age_limit`. Requiring the DEADLINE to sit under
    // it at ARM time means "the frame in hand must, by itself, authorise a fire up to a horizon
    // away" -- which the frame stream can never do, because the fire is authorised by the frame
    // that will exist AT the fire. The arithmetic result was an effective arming window of
    // `50 - frame_age` ms: across 268 live promotions the largest command_eta ever armed was
    // 40.41 ms, and widening the scheduler horizon to 64/100/150/250 ms recovered EXACTLY ZERO
    // aborts because this check, not the horizon, was binding.
    AutomationEngine engine;
    AppConfigData config;
    config.autonomousVision = true;
    engine.applyConfig(config, LearningData{});

    const double now = engine.engineNowMs();
    constexpr double frameAgeMs = 12.0;
    primeRollingLeaseEngine(engine, now, frameAgeMs);

    // Authority from THIS frame alone expires at capture + 50 = now + 38.
    const double authorityEtaMs = engine.meterAuthorityExpiryMs() - now;
    QVERIFY2(std::abs(authorityEtaMs - 38.0) < 1e-6,
             qPrintable(QStringLiteral("expected a 38ms single-frame lease, got %1")
                            .arg(authorityEtaMs)));

    // A deadline 60ms out is inside the horizon (4*16.67+6 = 72.7) but well BEYOND that lease.
    // This is exactly the arm the old code refused and the live batch needed.
    const double deadlineMs = now + 60.0;
    QVERIFY(deadlineMs - now > authorityEtaMs);
    QVERIFY(deadlineMs - now <= engine.adaptiveAutonomousSchedulerHorizonMs());
    QVERIFY2(engine.scheduleFire(
                 deadlineMs, now, -1.0,
                 AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision),
             "a deadline inside the horizon must arm even when this frame's own lease is shorter");
    QCOMPARE(engine.scheduledFireDeadlineMs(), deadlineMs);
    QVERIFY2(!engine.scheduledFireAuthorityCoversDeadline(),
             "the arming frame is deliberately NOT expected to cover the deadline yet");

    // The worker must not be handed a bound that silently drops the token it was just given.
    QVERIFY2(engine.scheduledFireAuthorityExpiryMs() >= deadlineMs - 1e-6,
             "worker snapshot must cover the committed deadline or it drops the fire");

    // A later genuine frame in the same vision epoch rolls the lease forward and COVERS it.
    engine.advanceTestClock(16.0);
    const double t1 = engine.engineNowMs();
    engine.shot_.lastFreshAcceptMs = t1;
    engine.shot_.frameAgeMs = 8.0;             // capture + 50 = t1 + 42 = now + 58 -> still short
    engine.measuredLeadLastUpdateMs_ = t1;
    engine.refreshScheduledFireAuthorityLease();
    QVERIFY(!engine.scheduledFireAuthorityCoversDeadline());

    engine.advanceTestClock(16.0);
    const double t2 = engine.engineNowMs();
    engine.shot_.lastFreshAcceptMs = t2;
    engine.shot_.frameAgeMs = 8.0;             // capture + 50 = now + 74 -> covers the 60ms deadline
    engine.measuredLeadLastUpdateMs_ = t2;
    engine.refreshScheduledFireAuthorityLease();
    QVERIFY2(engine.scheduledFireAuthorityCoversDeadline(),
             "the evidence stream must be able to authorise a deadline the arming frame could not");
}

void AutomationEngineTests::rollingLeaseExtendsOnlyForwardAndOnlyInSameVisionEpoch()
{
    // The lease may be extended by the evidence stream, but it is not a free-for-all: a memory
    // echo is not evidence, a different trajectory epoch is a different shot, and nothing may
    // ever SHORTEN a lease a token already holds (that is the fences' job, under their own
    // fail-closed rules).
    AutomationEngine engine;
    AppConfigData config;
    config.autonomousVision = true;
    engine.applyConfig(config, LearningData{});

    const double now = engine.engineNowMs();
    primeRollingLeaseEngine(engine, now, 12.0);
    QVERIFY(engine.scheduleFire(
        now + 60.0, now, -1.0,
        AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision));
    const double armedExpiry = engine.schedFireAuthorityExpiryMs_;

    // A memory echo (not a genuine accept) may not extend anything.
    engine.advanceTestClock(16.0);
    const double t1 = engine.engineNowMs();
    engine.shot_.lastSampleGenuineAccept = false;
    engine.shot_.lastFreshAcceptMs = t1;
    engine.measuredLeadLastUpdateMs_ = t1;
    engine.refreshScheduledFireAuthorityLease();
    QCOMPARE(engine.schedFireAuthorityExpiryMs_, armedExpiry);

    // A genuine frame from a DIFFERENT vision epoch may not extend it either.
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.visionEpoch = 22;                  // token was armed on epoch 21
    engine.refreshScheduledFireAuthorityLease();
    QCOMPARE(engine.schedFireAuthorityExpiryMs_, armedExpiry);

    // Back on epoch, a genuine frame extends it forward.
    engine.shot_.visionEpoch = 21;
    engine.shot_.frameAgeMs = 8.0;
    engine.refreshScheduledFireAuthorityLease();
    QVERIFY2(engine.schedFireAuthorityExpiryMs_ > armedExpiry,
             "a genuine same-epoch frame must roll the lease forward");
    const double extended = engine.schedFireAuthorityExpiryMs_;

    // An OLDER frame (larger age) must never pull the lease back.
    engine.shot_.frameAgeMs = 45.0;
    engine.refreshScheduledFireAuthorityLease();
    QCOMPARE(engine.schedFireAuthorityExpiryMs_, extended);
}

void AutomationEngineTests::rollingLeaseFailsClosedWhenEvidenceStops()
{
    // The contract the rolling lease must not weaken: if the evidence stream stops, an early-armed
    // token is RETIRED, never fired on stale evidence. Two independent fail-closed paths, both
    // exercised here:
    //   (a) `now` passes the rolling lease            -> hold_authority_expired
    //   (b) the deadline is still uncovered with less
    //       than one source cadence left to run       -> hold_authority_uncovered
    AppConfigData config;
    config.autonomousVision = true;

    {   // (a) authority expires outright while the deadline is still ahead.
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        const double now = engine.engineNowMs();
        primeRollingLeaseEngine(engine, now, 12.0);
        QVERIFY(engine.scheduleFire(
            now + 60.0, now, -1.0,
            AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision));
        QVERIFY(engine.scheduledFireDeadlineMs() >= 0.0);

        // No further frames. Step past the 38ms lease but stay INSIDE one source cadence of the
        // 60ms deadline (until_armed = 15ms < 16.7ms gap) -- precisely the imminent-token window
        // that the transient-blink guard protects. An expired AUTHORITY must not get that
        // protection: the blink guard exists for a detector hiccup, not for evidence that is
        // genuinely too old to authorise the release.
        engine.advanceTestClock(45.0);
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
        QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
        ControllerState output = engine.lastPhysical_;
        engine.processHolding(output, engine.engineNowMs());
        QVERIFY2(engine.scheduledFireDeadlineMs() < 0.0,
                 "an expired lease must retire the token BEFORE its deadline arrives");
        QStringList kills;
        for (const QList<QVariant>& row : diagSpy) {
            const QString line = row.at(0).toString();
            if (line.startsWith(QStringLiteral("TIP TOKEN KILL:"))) {
                kills << line;
            }
        }
        // Several independent fences can claim this one (authority, dropout, epoch) -- that is
        // defence in depth and deliberately not pinned to a single site. What must hold is the
        // property below: the deadline passes and NOTHING is ever released.
        QVERIFY2(!kills.isEmpty(),
                 "the token must be retired by a named fence, not silently forgotten");

        // Run past the original deadline. A rolling lease that failed to expire would still be
        // holding this token here and would fire it on evidence that is now 80ms stale.
        for (int i = 0; i < 10; ++i) {
            engine.advanceTestClock(4.0);
            ControllerState tickOut = engine.lastPhysical_;
            engine.processHolding(tickOut, engine.engineNowMs());
        }
        QCOMPARE(markerSpy.count(), 0);
        QVERIFY2(engine.scheduledFireDeadlineMs() < 0.0,
                 "no token may survive its own lease into a release");
    }

    {   // (b) evidence keeps arriving but never catches up to the deadline.
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        const double now = engine.engineNowMs();
        primeRollingLeaseEngine(engine, now, 12.0);
        QVERIFY(engine.scheduleFire(
            now + 60.0, now, -1.0,
            AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision));

        // Advance to inside one source cadence of the deadline, refreshing the lease with frames
        // that are too OLD to ever cover it (age 45 -> capture + 50 is only 5ms ahead of arrival).
        engine.advanceTestClock(50.0);
        const double t1 = engine.engineNowMs();
        engine.shot_.lastFreshAcceptMs = t1;
        engine.shot_.lastDetectionMs = t1;
        engine.shot_.frameAgeMs = 45.0;         // lease = t1 + 5; deadline = t1 + 10 -> uncovered
        engine.measuredLeadLastUpdateMs_ = t1;
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
        ControllerState output = engine.lastPhysical_;
        engine.processHolding(output, t1);
        QVERIFY2(engine.scheduledFireDeadlineMs() < 0.0,
                 "an uncovered deadline inside the commit cadence must abort, never fire");
        QStringList kills;
        for (const QList<QVariant>& row : diagSpy) {
            const QString line = row.at(0).toString();
            if (line.startsWith(QStringLiteral("TIP TOKEN KILL:"))) {
                kills << line;
            }
        }
        // The authority has NOT expired here (now < lease) and the epoch is unchanged -- the only
        // thing wrong is that the lease will never reach the deadline. That is its own fence.
        QVERIFY2(!kills.filter(QStringLiteral("site=tick_authority_uncovered")).isEmpty(),
                 qPrintable(QStringLiteral("uncovered deadline must retire via its OWN fence; "
                                           "saw: %1").arg(kills.join(QStringLiteral(" | ")))));
    }
}

void AutomationEngineTests::wifiAuthorityDegradesGracefullyInsteadOfCliffing()
{
    // [ORION_WIFI_CLIFF] wifiFreshnessFactor (0.5) tightened the source-age limit to 25ms -- BELOW
    // the age at which frames physically arrive (live p90 29.8ms). Every such frame then returned
    // -1 from meterAuthorityExpiryMs(), so nothing could be armed and the fire rate went to zero
    // rather than degrading. Customer links are worse than the dev rig, so this was a shipped
    // cliff. The bar may tighten; it may not drop below what the observed cadence can deliver.
    AutomationEngine engine;
    AppConfigData config;
    config.autonomousVision = true;
    engine.applyConfig(config, LearningData{});

    const double now = engine.engineNowMs();
    primeRollingLeaseEngine(engine, now, 29.8);       // the live p90 arrival age
    QCOMPARE(engine.config().strictReleaseMaxSourceAgeMs, 50.0);
    QCOMPARE(engine.config().wifiFreshnessFactor, 0.5);

    const double wiredExpiry = engine.meterAuthorityExpiryMs();
    QVERIFY(wiredExpiry >= 0.0);

    engine.wifiMode_ = true;
    const double wifiExpiry = engine.meterAuthorityExpiryMs();
    QVERIFY2(wifiExpiry >= 0.0,
             "a p90-age frame on a jittery link must still grant authority, not -1");
    QVERIFY2(wifiExpiry > now,
             "the granted lease must be strictly positive, not a zero-length grant");
    // Floor is two clean source gaps (2 * 16.67 = 33.3ms), so the limit degrades 50 -> 33.3
    // instead of collapsing to 25 and rejecting the frame outright.
    QVERIFY2(std::abs((wifiExpiry - now) - (2.0 * (1000.0 / 60.0) - 29.8)) < 1e-6,
             qPrintable(QStringLiteral("expected a cadence-floored lease, got eta %1")
                            .arg(wifiExpiry - now)));
    QVERIFY2(wifiExpiry < wiredExpiry,
             "wifi must still be STRICTER than wired -- graceful, not disabled");

    // And the whole point: a token can still be armed on that degraded link.
    QVERIFY2(engine.scheduleFire(
                 now + 30.0, now, -1.0,
                 AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision),
             "a degraded link must still be able to fire");
}

void AutomationEngineTests::armGateRejectionNamesTheGateThatRefused()
{
    // [ORION_ARM_GATE_TRACE] scheduleFire() had five silent `return false` paths. The live logs
    // therefore showed a valid, still-future deadline being refused thousands of times with no
    // record of WHICH gate refused it -- three investigation rounds went into rediscovering that
    // by hand. Every refusal now names itself, exactly once per reason per shot attempt.
    AutomationEngine engine;
    AppConfigData config;
    config.autonomousVision = true;
    engine.applyConfig(config, LearningData{});
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

    const double now = engine.engineNowMs();
    primeRollingLeaseEngine(engine, now, 12.0);

    auto gatesSeen = [&diagSpy]() {
        QStringList out;
        for (const QList<QVariant>& row : diagSpy) {
            const QString line = row.at(0).toString();
            if (line.startsWith(QStringLiteral("SCHEDULE FIRE REJECT:"))) {
                out << line;
            }
        }
        return out;
    };

    // Far beyond the horizon.
    QVERIFY(!engine.scheduleFire(
        now + 5'000.0, now, -1.0,
        AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision));
    QVERIFY2(!gatesSeen().filter(QStringLiteral("gate=outside_horizon")).isEmpty(),
             "an out-of-horizon refusal must name itself");

    // Already in the past.
    QVERIFY(!engine.scheduleFire(
        now - 5.0, now, -1.0,
        AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision));
    QVERIFY(!gatesSeen().filter(QStringLiteral("gate=deadline_past")).isEmpty());

    // No usable evidence at all.
    engine.shot_.confidence = 0.0;
    QVERIFY(!engine.scheduleFire(
        now + 30.0, now, -1.0,
        AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision));
    QVERIFY(!gatesSeen().filter(QStringLiteral("gate=no_authority")).isEmpty());

    // Bounded: the same gate must not re-log on every 4ms tick within one shot attempt.
    const int afterFirst = gatesSeen().filter(QStringLiteral("gate=no_authority")).size();
    for (int i = 0; i < 50; ++i) {
        engine.scheduleFire(now + 30.0, now, -1.0,
                            AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision);
    }
    QCOMPARE(gatesSeen().filter(QStringLiteral("gate=no_authority")).size(), afterFirst);

    // A new shot attempt re-arms the trace.
    engine.shot_.armToken = 8'103;
    QVERIFY(!engine.scheduleFire(
        now + 30.0, now, -1.0,
        AutomationEngine::ScheduledFireAuthority::AutonomousMeterVision));
    QVERIFY2(gatesSeen().filter(QStringLiteral("gate=no_authority")).size() > afterFirst,
             "a fresh shot attempt must be traceable again");
}

void AutomationEngineTests::tipReservationReportsNeverInsideArmingWindow()
{
    // FIX 6. `everValidAndFuture` is true of essentially every shot -- a command deadline is valid
    // and in the future for its entire approach -- so it labelled 106 of 115 live aborts
    // "authority_lost_before_submit" while 32 of 42 had in fact never armed a token at all. That
    // label sends the operator to investigate routes and leases for a shot that never once had an
    // armable moment. everArmable narrows it to the honest question: was there ever a tick on
    // which scheduleFire() could have said yes?
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    const double t0 = engine.engineNowMs();
    constexpr double leadMs = 300.0;
    engine.measuredLatencyMs_ = leadMs;
    engine.measuredLatencySdMs_ = 2.0;
    engine.measuredLatencyN_ = 6;
    engine.measuredLatencyAuthorityKind_ = QStringLiteral("validated");
    engine.measuredLatencyAuthorityMs_ = leadMs;
    engine.measuredLatencyAuthoritySdMs_ = 2.0;
    engine.measuredLeadTelemetryPresent_ = true;
    engine.measuredLeadEverValid_ = true;
    engine.measuredLeadEpochReady_ = true;
    engine.measuredLeadLastUpdateMs_ = t0;

    engine.shot_.state = HoldState::Holding;
    engine.shot_.mode = ShotMode::ButtonShot;
    engine.shot_.shotType = QStringLiteral("Standstill");
    engine.shot_.holdStartMs = t0 - 10.0;
    engine.shot_.physicalShotEpoch = 9'501;
    engine.shot_.armToken = 9'502;
    engine.shot_.visionEpoch = 31;
    engine.shot_.meterDetected = true;
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.firstFreshAcceptMs = t0;
    engine.shot_.anchorValidMs = t0;
    engine.shot_.sawFreshMeterThisShot = true;
    engine.shot_.meterSeenThisShot = true;
    engine.shot_.frameAgeMs = 0.0;
    engine.shot_.confidence = 1.0;
    engine.shot_.regModelId = QStringLiteral("timing-audit-model");
    engine.shot_.regModelVersion = QStringLiteral("1");
    engine.shot_.regConf = 1.0;
    engine.shot_.regN = 16;

    engine.lastPhysical_.buttons |= XINPUT_GAMEPAD_X;
    ControllerState output = engine.lastPhysical_;
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

    // tick 1: VALID and comfortably in the future -- fireAt = t0 + 150, far outside any horizon.
    engine.shot_.fillPct = 20.0;
    engine.shot_.lastFreshAcceptMs = t0;
    engine.shot_.regTipMs = 450.0;
    engine.shot_.regTipAbsMs = t0 + 450.0;
    engine.shot_.regSigmaMs = 2.0;
    engine.processAutonomousLiveMeterHolding(output, t0);
    QVERIFY(engine.tipReservationView().active);
    QVERIFY2(engine.tipReservation_.everValidAndFuture,
             "test setup: the deadline must be valid and future here");
    QVERIFY2(!engine.tipReservation_.everArmable,
             "a deadline 150ms out is valid and future but was never ARMABLE");

    // tick 2: the estimate snaps earlier, stepping straight over the arming window into the past.
    const double t1 = t0 + 200.0;
    engine.advanceTestClock(200.0);
    engine.measuredLeadLastUpdateMs_ = t1;
    engine.shot_.fillPct = 42.0;
    engine.shot_.lastFreshAcceptMs = t1;
    engine.shot_.anchorValidMs = t1;
    engine.shot_.regTipMs = 280.0;
    engine.shot_.regTipAbsMs = t1 + 280.0;      // fireAt = t1 - 20, already behind us
    engine.shot_.regSigmaMs = 2.0;
    engine.processAutonomousLiveMeterHolding(output, t1);

    QString abortLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("TIP DEADLINE DECISION:"))) {
            abortLine = line;
        }
    }
    QVERIFY(!abortLine.isEmpty());
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("live_tip_deadline_missed"));
    QVERIFY2(abortLine.contains(
                 QStringLiteral("reservation_disposition=never_inside_arming_window")),
             qPrintable(QStringLiteral("wrong attribution in: %1").arg(abortLine)));
    QVERIFY2(!abortLine.contains(QStringLiteral("authority_lost_before_submit")),
             "must NOT claim we had it and lost it -- there was never an armable moment");
    QVERIFY2(abortLine.contains(QStringLiteral("reservation_ever_armable=0")),
             "the new field must be present for live-batch triage");
    QVERIFY(abortLine.contains(QStringLiteral("arming_horizon_ms=")));
}

void AutomationEngineTests::fusedEstimatorConvergesAndGatesOutliers()
{
    // [ORION_FUSED_FIRE] Pure posterior math: anchor, sequential fusion, correlation control,
    // chi^2 outlier gate, and the vision-pair override that lets two agreeing live sources
    // beat a wrong clock prior.
    FusedTipEstimator est;
    QVERIFY(!est.anchored());
    est.anchor(1000.0, 45.0);
    QVERIFY(est.anchored());
    QCOMPARE(est.muTipMs(), 1000.0);

    const FusedTipEstimator::SourceMeas none;
    for (int i = 0; i < 6; ++i) {
        FusedTipEstimator::SourceMeas samp;
        samp.tipAbsMs = 950.0;
        samp.sigmaMs = 10.0;
        est.update(true, none, samp, false, 5.0, 15.0);
    }
    QVERIFY2(std::abs(est.muTipMs() - 950.0) < 15.0,
             qPrintable(QStringLiteral("mu must converge onto the consistent source; got %1")
                            .arg(est.muTipMs())));
    QVERIFY2(est.sigmaMs() < 12.0,
             qPrintable(QStringLiteral("sigma must contract below the source sigma+q floor; got %1")
                            .arg(est.sigmaMs())));
    QCOMPARE(est.infoUpdates(), 6);

    // chi^2 gate: one wild single source must not move the posterior at all.
    const double muBefore = est.muTipMs();
    FusedTipEstimator::SourceMeas wild;
    wild.tipAbsMs = 1500.0;
    wild.sigmaMs = 10.0;
    est.update(true, wild, none, false, 5.0, 15.0);
    QVERIFY2(std::abs(est.muTipMs() - muBefore) < 1e-9,
             "a chi^2-gated outlier must not move mu");

    // Correlation control: a no-new-information sample only GROWS sigma (process noise),
    // never contracts it — 60fps duplicates of one game frame cannot fake convergence.
    const double sigBefore = est.sigmaMs();
    FusedTipEstimator::SourceMeas samp;
    samp.tipAbsMs = 950.0;
    samp.sigmaMs = 10.0;
    est.update(false, none, samp, false, 5.0, 15.0);
    QVERIFY2(est.sigmaMs() > sigBefore, "newInfo=false must only grow sigma");

    // Vision-pair override: an estimator anchored WRONG must yield to two agreeing live
    // sources, and record that the prior lost the argument.
    FusedTipEstimator est2;
    est2.anchor(1400.0, 25.0);
    for (int i = 0; i < 4; ++i) {
        FusedTipEstimator::SourceMeas r2;
        r2.tipAbsMs = 948.0;
        r2.sigmaMs = 20.0;
        FusedTipEstimator::SourceMeas s2;
        s2.tipAbsMs = 952.0;
        s2.sigmaMs = 12.0;
        est2.update(true, r2, s2, false, 5.0, 15.0);
    }
    QVERIFY(est2.pairOverrideFired());
    QVERIFY2(std::abs(est2.muTipMs() - 950.0) < 40.0,
             qPrintable(QStringLiteral("pair override must pull mu onto the agreeing sources; got %1")
                            .arg(est2.muTipMs())));
}




void AutomationEngineTests::latencyProbesInjectPressesAndCancelOnUserInput()
{
    // [ORION_PROBE] A probe run injects virtual Square presses (probePressMs hold, probeGapMs
    // apart) while the engine stays Idle, emitting probeMarker (seq + epoch + spawn offset)
    // per press. A physical Square press cancels the remainder of the run instantly.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    // PIN the probe timings rather than inheriting the shipped defaults. This test is about the
    // MECHANISM (presses injected, markers emitted, physical input cancels), not about whatever
    // hold/gap the rig currently wants. Left unpinned it silently re-broke when the live defaults
    // moved 150/2500 -> 900/6000 (+2000ms call-for-ball) on 2026-08-05: two probes no longer fit
    // the tick budget below, so the run was still active at the loop's end and the failure read as
    // "probes never finished" rather than "the test's clock is too short".
    config.probePressMs = 150.0;
    config.probeGapMs = 2650.0;   // >= callLead + press + 500, the engine's own floor
    LearningData learning;
    learning.probeSpawnOffsetMs = 38.0;
    engine.applyConfig(config, learning);
    QSignalSpy markerSpy(&engine, &AutomationEngine::probeMarker);

    ControllerState physical;                     // neutral controller throughout
    engine.advanceTestClock(1);
    engine.process(physical);
    QVERIFY(!engine.latencyProbesActive());

    engine.startLatencyProbes(2);
    QVERIFY(engine.latencyProbesActive());

    int pressEpisodes = 0;
    int pressTicks = 0;
    bool prevX = false;
    // 4ms x 8000 = 32s cap. Generous on purpose: the run's length is now dominated by the
    // call-for-ball lead ahead of each press, and a cap sized to the old 150/2500 timings is what
    // turned a timing change into a mystery failure.
    for (int i = 0; i < 8000 && engine.latencyProbesActive(); ++i) {
        engine.advanceTestClock(4);
        const ControllerState out = engine.process(physical);
        const bool x = (out.buttons & XINPUT_GAMEPAD_X) != 0;
        if (x) {
            ++pressTicks;
        }
        if (x && !prevX) {
            ++pressEpisodes;
        }
        prevX = x;
        QCOMPARE(engine.context().state, HoldState::Idle);   // probes never arm a shot
    }
    QVERIFY(!engine.latencyProbesActive());
    QCOMPARE(pressEpisodes, 2);
    QCOMPARE(markerSpy.count(), 2);
    QCOMPARE(markerSpy.at(0).at(0).toInt(), 1);
    QCOMPARE(markerSpy.at(1).at(0).toInt(), 2);
    QVERIFY2(markerSpy.at(0).at(1).toDouble() > 0.0, "probe press must carry a real epoch stamp");
    QCOMPARE(markerSpy.at(0).at(2).toDouble(), 38.0);
    // Each press holds ~probePressMs (150ms / 4ms ticks ~= 37-38 ticks; x2 presses).
    QVERIFY2(pressTicks >= 70 && pressTicks <= 82,
             qPrintable(QStringLiteral("presses must hold ~150ms each; total X ticks=%1")
                            .arg(pressTicks)));

    // A physical Square press cancels a fresh run immediately.
    engine.startLatencyProbes(4);
    QVERIFY(engine.latencyProbesActive());
    ControllerState pressing;
    pressing.buttons |= XINPUT_GAMEPAD_X;
    engine.advanceTestClock(60);                  // past the 50ms first-probe delay
    engine.process(pressing);
    QVERIFY2(!engine.latencyProbesActive(), "a physical Square press must cancel the probe run");
}


void AutomationEngineTests::inTickFeedforwardReleaseClearsSquareSameTick()
{
    // P3.1: an in-tick feedforward-clock release (AutomationEngine.cpp :1855) must drop the virtual
    // Square the SAME tick it fires — mirroring the scheduled-confirm path — not one tick later. The
    // sub-tick scheduler horizon is 6ms, so a 250ms-future clock can never be pre-scheduled; once the
    // clock is overdue the release fires strictly in-tick, isolating the fixed path.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);  // armed hold-start clock
    engine.applyConfig(config, learning);

    ControllerState out;
    QVERIFY(driveAuthorizedFeedforwardRelease(engine, 250.0, 60.0,
                                               94.0, 98.0, 96.0, &out));

    QVERIFY(engine.context().releaseReasonCode == QLatin1String("feedforward_target")
            || engine.context().releaseReasonCode == QLatin1String("predictive_target"));
    QVERIFY2(!out.square(),
             "the in-tick feedforward release must clear the virtual Square the SAME tick it fires");
}

void AutomationEngineTests::productionRejectsPoseOnlyReleaseAuthority()
{
    // P3.1: a no-meter pose feedforward-clock release (AutomationEngine.cpp :1924) must clear Square the
    // SAME tick it fires, like the meter path. A large negative base offset drives the pose feedforward
    // fireTime into the past so the release fires strictly in-tick, isolating the fixed pose site.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.noMeterEnabled = true;
    config.noMeterBaseOffsetMs = -2000.0;   // pose feedforward fireTime = holdStart + clock - 2007.5 -> past
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 300.0);  // armed pose ff clock
    engine.applyConfig(config, learning);
    QVERIFY(!engine.config().noMeterEnabled);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);                 // -> Holding, holdStart set (commit_wait)
    engine.advanceTestClock(160);
    const ControllerState held = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QVERIFY(held.square());
    QCOMPARE(engine.shotsReleased(), 0);
    engine.advanceTestClock(3000);
    const ControllerState aborted = engine.process(physical);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("no_meter_abort"));
    QVERIFY(aborted.square());
    QCOMPARE(engine.shotsReleased(), 0);
}

void AutomationEngineTests::modeAwareReleaseEdgePreservesUnownedControls()
{
    ControllerState seed;
    seed.buttons = XINPUT_GAMEPAD_X | XINPUT_GAMEPAD_A | XINPUT_GAMEPAD_Y
        | XINPUT_GAMEPAD_RIGHT_SHOULDER;
    seed.dpad = 3;
    seed.leftStickX = -73;
    seed.leftStickY = 41;
    seed.rightStickX = 52;
    seed.rightStickY = 127;
    seed.l2 = 91;
    seed.r2 = 203;
    seed.touchpad = true;

    const auto verifyUnowned = [&](const ControllerState& out) {
        QCOMPARE(out.dpad, seed.dpad);
        QCOMPARE(out.leftStickX, seed.leftStickX);
        QCOMPARE(out.leftStickY, seed.leftStickY);
        QCOMPARE(out.l2, seed.l2);
        QCOMPARE(out.r2, seed.r2);
        QCOMPARE(out.touchpad, seed.touchpad);
        QVERIFY(out.cross());
        QVERIFY(out.triangle());
        QVERIFY(out.r1());
    };

    ControllerState button = seed;
    applyShotReleaseEdge(button, ShotMode::ButtonShot, QStringLiteral("Standstill"));
    verifyUnowned(button);
    QVERIFY(!button.square());
    QCOMPARE(button.rightStickX, seed.rightStickX);
    QCOMPARE(button.rightStickY, seed.rightStickY);
    QVERIFY(isValidShotReleaseOutput(button, ShotMode::ButtonShot));

    ControllerState goTo = seed;
    applyShotReleaseEdge(goTo, ShotMode::GoToStick, QStringLiteral("Go-To"));
    verifyUnowned(goTo);
    QVERIFY(goTo.square());
    QCOMPARE(goTo.rightStickX, 0);
    // [ORION_GOTO_DOWN_FLICK] Go-To gathers RS-up (-127), so it releases with the mirrored
    // DOWN flick, exactly like a fade. It used to release at neutral, which is a return to
    // rest rather than the direction-change edge the game reads as a release.
    QCOMPARE(goTo.rightStickY, 127);
    QVERIFY(isValidShotReleaseOutput(goTo, ShotMode::GoToStick));

    ControllerState tempoStick = seed;
    applyShotReleaseEdge(
        tempoStick, ShotMode::TempoStick, QStringLiteral("Standstill"));
    verifyUnowned(tempoStick);
    QVERIFY(tempoStick.square());
    QCOMPARE(tempoStick.rightStickX, 0);
    QCOMPARE(tempoStick.rightStickY, -127);
    QVERIFY(isValidShotReleaseOutput(tempoStick, ShotMode::TempoStick));

    ControllerState tempoSquare = seed;
    applyShotReleaseEdge(
        tempoSquare, ShotMode::TempoSquare, QStringLiteral("Standstill"));
    verifyUnowned(tempoSquare);
    QVERIFY(!tempoSquare.square());
    QCOMPARE(tempoSquare.rightStickX, 0);
    QCOMPARE(tempoSquare.rightStickY, -127);
    QVERIFY(isValidShotReleaseOutput(tempoSquare, ShotMode::TempoSquare));

    ControllerState tempoFade = seed;
    applyShotReleaseEdge(
        tempoFade, ShotMode::TempoSquare, QStringLiteral("Right Fade"));
    verifyUnowned(tempoFade);
    QVERIFY(!tempoFade.square());
    QCOMPARE(tempoFade.rightStickX, 0);
    QCOMPARE(tempoFade.rightStickY, -127);
    QVERIFY(isValidShotReleaseOutput(tempoFade, ShotMode::TempoSquare));
}

void AutomationEngineTests::preciseFireMailboxRejectsModeMismatchedReleaseOutput()
{
    // Exact live failure shape from Button release seq=2: the mailbox still
    // carried held Square even though the worker reported a successful route
    // write. Neutral RS cannot make that a valid Button release.
    ControllerState malformedButtonSeq2;
    malformedButtonSeq2.buttons = XINPUT_GAMEPAD_X;
    malformedButtonSeq2.rightStickX = 0;
    malformedButtonSeq2.rightStickY = 0;
    QVERIFY(!isValidShotReleaseOutput(
        malformedButtonSeq2, ShotMode::ButtonShot));

    // Button owns only Square. A cleared Square is valid even while unrelated
    // stick input is active; a Tempo-shaped flick never excuses held Square.
    ControllerState button;
    button.rightStickX = 61;
    button.rightStickY = -127;
    QVERIFY(isValidShotReleaseOutput(button, ShotMode::ButtonShot));
    malformedButtonSeq2.rightStickY = -127;
    QVERIFY(!isValidShotReleaseOutput(
        malformedButtonSeq2, ShotMode::ButtonShot));

    ControllerState goTo;
    goTo.buttons = XINPUT_GAMEPAD_X; // unowned in raw Go-To mode
    // [ORION_GOTO_DOWN_FLICK] A NEUTRAL packet is no longer a valid Go-To release. This case
    // previously asserted the opposite: the old fence accepted rest state, so a blank or stale
    // payload cleared Go-To's final submit check while every other mode demanded a full-scale
    // flick. That hole is now closed.
    QVERIFY(!isValidShotReleaseOutput(goTo, ShotMode::GoToStick));
    goTo.rightStickY = 127; // the mirrored down flick — the only valid Go-To release
    QVERIFY(isValidShotReleaseOutput(goTo, ShotMode::GoToStick));
    goTo.rightStickY = -127; // the GATHER direction is not a release
    QVERIFY(!isValidShotReleaseOutput(goTo, ShotMode::GoToStick));
    goTo.rightStickY = 126; // partial deflection never passes
    QVERIFY(!isValidShotReleaseOutput(goTo, ShotMode::GoToStick));
    goTo.rightStickY = -1;
    QVERIFY(!isValidShotReleaseOutput(goTo, ShotMode::GoToStick));
    goTo.rightStickY = 127;
    goTo.rightStickX = 1; // X must be exactly centred
    QVERIFY(!isValidShotReleaseOutput(goTo, ShotMode::GoToStick));

    ControllerState tempoStick;
    tempoStick.buttons = XINPUT_GAMEPAD_X; // not owned by raw TempoStick
    tempoStick.rightStickX = 0;
    tempoStick.rightStickY = -127;
    QVERIFY(isValidShotReleaseOutput(tempoStick, ShotMode::TempoStick));
    tempoStick.rightStickY = -126;
    QVERIFY(!isValidShotReleaseOutput(tempoStick, ShotMode::TempoStick));
    tempoStick.rightStickY = -127;
    tempoStick.rightStickX = 1;
    QVERIFY(!isValidShotReleaseOutput(tempoStick, ShotMode::TempoStick));
    tempoStick.rightStickX = 0;
    tempoStick.rightStickY = 0;
    QVERIFY(!isValidShotReleaseOutput(tempoStick, ShotMode::TempoStick));

    ControllerState tempoSquare;
    tempoSquare.rightStickX = 0;
    tempoSquare.rightStickY = -127;
    QVERIFY(isValidShotReleaseOutput(tempoSquare, ShotMode::TempoSquare));
    tempoSquare.buttons = XINPUT_GAMEPAD_X;
    QVERIFY(!isValidShotReleaseOutput(tempoSquare, ShotMode::TempoSquare));
    tempoSquare.buttons = 0;
    tempoSquare.rightStickY = 0;
    QVERIFY(!isValidShotReleaseOutput(tempoSquare, ShotMode::TempoSquare));
    tempoSquare.rightStickY = -127;
    tempoSquare.rightStickX = -1;
    QVERIFY(!isValidShotReleaseOutput(tempoSquare, ShotMode::TempoSquare));
}

void AutomationEngineTests::autonomousTipTargetIsMeterTipNotGreen()
{
    // Item 2: under autonomous tip-vision the release TARGET is the meter TIP (fill=100%)
    // UNCONDITIONALLY — a confirmed green window is telemetry-only and no longer moves the aim (the
    // self-measured global lead absorbs the constant offset to the true make-point). Contrast with
    // greenTrackerAdaptiveTargetByWidth (per-type: aims the green TOP EDGE).
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    int frame = 1;
    constexpr quint64 shotEpoch = 781;
    auto strictSample = [&](double fill) {
        return strictLiveMeterSample(
            fill, frame++, shotEpoch, 70.0, 2.0, 6);
    };
    promoteStrictAutonomousSquare(
        engine, physical, frame, shotEpoch, 70.0, 2.0, 6);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // Confirm a green window whose TOP EDGE (94) sits well below the tip; constant mid fill so the
    // (now telemetry-only) green window is the only thing that could otherwise pull the target down.
    double target = -1.0;
    for (int i = 0; i < 6; ++i) {
        DetectionResult r = strictSample(60.0);
        r.greenStartPct = 86.0; r.greenEndPct = 94.0; r.greenCenterPct = 90.0;
        r.velocityPctS = 0.0; r.etaToGreenMs = -1.0;
        engine.updateDetection(r);
        engine.process(physical);
        target = engine.context().targetPct;
        engine.advanceTestClock(16.0);
    }
    QVERIFY2(std::abs(target - 100.0) < 1.0,
             qPrintable(QStringLiteral("autonomous target must be the tip (~100), not the green top (94); got %1").arg(target)));
    QVERIFY2(target > 96.0,
             "a confirmed green window must NOT pull the autonomous target down off the tip");
}


// ---- C1: the tip-fire floor must not cap the expressible lead -------------------------------

// Shared rig for the C1/A3 floor tests: a Square shot under autonomous tip-vision, fed a
// perfectly linear rise at a caller-chosen rate, with the green window stripped (target = tip)
// and frameAge zeroed so effectiveLatency == learnedLatencyMs EXACTLY (the arithmetic below is
// then checkable by hand).
namespace {
struct TipFloorRun {
    double releaseFillPct = -1.0;
    double releaseCommandEquivalentFillPct = -1.0;
    QString releaseReasonCode;
    HoldState finalState = HoldState::Idle;
    double lastFillPct = 0.0;
};

TipFloorRun runLinearRise(double leadMs, double startFill, double stepPct, double stepMs,
                          int maxSamples, bool autonomous = true)
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 8000.0;          // keep every safety dump far away
    config.tempoFallbackTimeoutMs = 8000.0;
    config.autonomousVision = autonomous;
    config.measuredLeadEnabled = autonomous;
    LearningData learning;
    learning.learnedLatencyMs = leadMs;     // ignored by strict mode; retained for legacy runs
    engine.applyConfig(config, learning);

    int frame = 1;
    constexpr quint64 shotEpoch = 791;
    auto sample = [](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.etaToGreenMs = -1.0;
        r.frameAgeMs = 0.0;                 // isolates the selected lead source exactly
        return r;
    };
    auto strictSample = [&](double fill) {
        DetectionResult r = sample(fill);
        r.frameNumber = frame++;
        r.captureTsMs = 100'000.0 + static_cast<double>(r.frameNumber) * stepMs;
        r.measurementCaptureTsMs = r.captureTsMs;
        r.stage = QStringLiteral("track");
        r.measuredLatencyMs = leadMs;
        r.measuredLatencyN = 6;
        r.measuredLatencySdMs = 2.0;
        r.measuredLatencyAuthorityKind = QStringLiteral("validated");
        r.measuredLatencyAuthorityMs = leadMs;
        r.measuredLatencyAuthoritySdMs = 2.0;
        r.gameplayStructureVerified = true;
        r.gameplayStructureEpoch = shotEpoch;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    if (autonomous) {
        // Keep ownership proof on the same physical linear trajectory being
        // tested; a fixed low-fill helper would inject an artificial
        // acceleration and bias the weighted fit before the asserted release.
        // The pre-press sample establishes lead authority only. Keep the first
        // post-press proof sample at the production low-fill anchor ceiling,
        // while preserving one continuous linear trajectory into startFill.
        engine.updateDetection(strictSample(
            std::max(1.0, startFill - 5.0 * stepPct)));
        engine.setPhysicalShotEpoch(shotEpoch);
        engine.process(physical);
        for (double fill : {startFill - 4.0 * stepPct,
                            startFill - 3.0 * stepPct,
                            startFill - 2.0 * stepPct,
                            startFill - stepPct}) {
            engine.advanceTestClock(stepMs);
            engine.updateDetection(strictSample(fill));
            engine.process(physical);
        }
        engine.advanceTestClock(stepMs);
    } else {
        engine.process(physical);
        engine.advanceTestClock(220);       // arm -> holding
        engine.process(physical);
        engine.advanceTestClock(160);       // past the standstill commit floor
        engine.process(physical);
    }

    TipFloorRun out;
    const double trajectoryStartMs = engine.engineNowMs();
    const double velocityPctPerMs = stepMs > 0.0 ? stepPct / stepMs : 0.0;
    double fill = startFill;
    for (int i = 0; i < maxSamples; ++i, fill += stepPct) {
        engine.updateDetection(autonomous
                                   ? strictSample(std::min(fill, 100.0))
                                   : sample(std::min(fill, 100.0)));
        engine.process(physical);
        if (autonomous && engine.context().state == HoldState::Holding
            && engine.scheduledFireDeadlineMs() >= engine.engineNowMs()) {
            const double deadline = engine.scheduledFireDeadlineMs();
            const quint64 token = engine.scheduledFireToken();
            engine.advanceTestClock(deadline - engine.engineNowMs());
            engine.confirmScheduledFire(token, deadline);
            engine.process(physical);
        }
        out.lastFillPct = engine.context().fillPct;
        out.finalState = engine.context().state;
        out.releaseReasonCode = engine.context().releaseReasonCode;
        if (out.finalState != HoldState::Holding) {
            out.releaseFillPct = engine.context().releaseFillPct;
            out.releaseCommandEquivalentFillPct = startFill
                + velocityPctPerMs
                    * (engine.context().releaseTriggerMs - trajectoryStartMs);
            break;
        }
        engine.advanceTestClock(stepMs);
    }
    return out;
}
}  // namespace

void AutomationEngineTests::tipFireFloorTracksLeadAtHighVelocity()
{
    // C1 — THE LEAD CAP. Expressing a lead L at rise rate v REQUIRES firing at `target - v*L`.
    // The old FIXED tipFireMinFillPct=88 therefore forbade any lead longer than (target-88)/v:
    // live (target ~99.6, v ~0.25 %/ms) that capped the lead at ~46ms while learned_latency_ms
    // was 75, so the bot was structurally ~29ms LATE on EVERY vision shot and the release fills
    // piled up against the floor (88.9/90.1/90.7/91.3/91.9) instead of spreading.
    //
    // With the lead-aware floor, a 75ms lead at v = 0.25 %/ms must fire near
    //     target - v*L = 100 - 0.25*75 = 81.25  (floor itself = 81.25 - slack = 79.25)
    // i.e. BELOW the old 88 cap. If the floor ever goes back to a fixed 88 this test fails,
    // because 88 is not reachable-from-below at a 75ms lead.
    const double leadMs = 75.0;
    const double velocity = 0.25;                       // %/ms
    const double expectedFireFill = 100.0 - velocity * leadMs;   // 81.25

    // 2.5pp every 10ms == 0.25 %/ms, from well below the old floor.
    const TipFloorRun run = runLinearRise(leadMs, /*startFill=*/50.0, /*stepPct=*/2.5,
                                          /*stepMs=*/10.0, /*maxSamples=*/40);

    QVERIFY2(run.releaseFillPct >= 0.0, "engine never released across the rising trajectory");
    QCOMPARE(run.releaseReasonCode, QStringLiteral("live_meter_tip"));
    QVERIFY2(run.releaseFillPct < 88.0,
             qPrintable(QStringLiteral("THE C1 BUG: release still pinned at/above the old fixed 88 "
                                       "floor (%1) — a 75ms lead is not expressible there")
                            .arg(run.releaseFillPct)));
    // A precise timer may be armed several frames before it fires, so the last
    // detector fill is the decision fill, not the meter fill at command time.
    // Project the known linear fixture to releaseTriggerMs and check the actual
    // command instant against target-v*lead.
    QVERIFY2(std::abs(run.releaseCommandEquivalentFillPct - expectedFireFill) <= 5.0,
             qPrintable(QStringLiteral(
                 "release command must land near target - v*lead (%1); got %2 (decision fill %3)")
                            .arg(expectedFireFill)
                            .arg(run.releaseCommandEquivalentFillPct)
                            .arg(run.releaseFillPct)));
}

void AutomationEngineTests::tipFireFloorIgnoresNonsenseVelocity()
{
    // C1 GUARD. The lead-aware floor is `target - v*effectiveLatency - slack`, which a garbage
    // velocity drives wildly negative (v = 10 %/ms, L = 75ms -> -652). Without the absolute
    // sanity floor (tipFireAbsMinFillPct) that would open the predictive rung at ANY fill, and
    // block 2 would fire instantly because msUntilTarget = 75/10 = 7.5ms is inside the lead.
    // A torn frame / detector blip must never dump the shot at a quarter-full meter.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 8000.0;
    config.tempoFallbackTimeoutMs = 8000.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    LearningData learning;
    learning.learnedLatencyMs = 75.0;
    engine.applyConfig(config, learning);
    const double absFloor = engine.config().tipFireAbsMinFillPct;
    QVERIFY2(absFloor > 20.0, "the absolute sanity floor must actually block an absurd early fire");

    int frame = 1;
    constexpr quint64 shotEpoch = 801;
    auto sample = [&](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.etaToGreenMs = -1.0;
        r.frameAgeMs = 0.0;
        r.frameNumber = frame++;
        // The promotion helper's last sample is frame 4 at 100080ms. Continue
        // that canonical capture clock at 1ms intervals for this burst.
        r.captureTsMs = 100'076.0 + static_cast<double>(r.frameNumber);
        r.measurementCaptureTsMs = r.captureTsMs;
        r.stage = QStringLiteral("track");
        r.measuredLatencyMs = 75.0;
        r.measuredLatencyN = 6;
        r.measuredLatencySdMs = 2.0;
        r.measuredLatencyAuthorityKind = QStringLiteral("validated");
        r.measuredLatencyAuthorityMs = 75.0;
        r.measuredLatencyAuthoritySdMs = 2.0;
        r.gameplayStructureVerified = true;
        r.gameplayStructureEpoch = shotEpoch;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    promoteStrictAutonomousSquare(
        engine, physical, frame, shotEpoch, 75.0, 2.0, 6, 0.0);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // NONSENSE velocity: 5 -> 15 -> 25 in 1ms steps == 10 %/ms, ~40x a real meter, while the
    // fill itself stays a quarter of the way up.
    for (double fill : {5.0, 15.0, 25.0}) {
        engine.updateDetection(sample(fill));
        engine.process(physical);
        engine.advanceTestClock(1);
    }

    QVERIFY2(engine.context().fillPct < absFloor,
             "test setup: the burst remains below the legacy sanity floor");
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("owned_square_trajectory_unresolved"));
    QCOMPARE(engine.shotsReleased(), 0);
    QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);

    // Even after the evidence span becomes long enough, an impossible jump is
    // rejected by the independent slope-plausibility ceiling.
    engine.advanceTestClock(10.0);
    engine.updateDetection(sample(95.0));
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.shotsReleased(), 0);
    QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
}

void AutomationEngineTests::reachabilityHorizonTracksFarButValidCrossing()
{
    // A3 — REACHABILITY HORIZON. The reach test asked "is the tip within ONE LEAD's worth of
    // rise?", which abandons a shot that demonstrably WILL reach the tip, just not that soon:
    // live seq 9/12/19 had healthy velocity and a valid forward crossing (crossingEta
    // 210/355/143ms) yet reported withinReach=0, so every vision rung was closed and the blind
    // feedforward clock owned the release.
    // Per-type path (autonomous OFF) so the hard 42 floor — not the tip floor — is what could
    // otherwise be confused with the gap test: at fill 45, target 100, the gap is 55pp while
    // clamp(v*lead, 0, 39) + 6 = 45 at most, so PRE-A3 this frame reported out_of_reach even
    // though the meter is rising steadily straight at the tip.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 8000.0;
    config.tempoFallbackTimeoutMs = 8000.0;
    LearningData learning;
    // Unarmed clocks so nothing preempts: this test is about the reach GATE, not the clock.
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    auto sample = [](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.etaToGreenMs = -1.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    engine.advanceTestClock(160);   // past the commit floor
    engine.process(physical);

    // Steady 0.25 %/ms (2.5pp per 10ms) through the low-40s. The crossing to the tip is ~220ms
    // out — far beyond one lead, but real and forward.
    double fill = 37.5;
    for (int i = 0; i < 4; ++i, fill += 2.5) {
        engine.updateDetection(sample(fill));
        engine.process(physical);
        engine.advanceTestClock(10);
    }

    QCOMPARE(engine.context().state, HoldState::Holding);
    QVERIFY2(engine.context().fillPct > 42.0 && engine.context().fillPct < 55.0,
             qPrintable(QStringLiteral("test setup: fill must sit above the 42 hard floor but far "
                                       "below the tip; got %1").arg(engine.context().fillPct)));
    // THE FIX: the shot is TRACKED (a live vision plan waiting on its crossing), not ABANDONED.
    QVERIFY2(engine.context().releaseReasonCode != QStringLiteral("out_of_reach"),
             "a rising meter with a valid forward crossing must not be reported out_of_reach");
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("eta_not_ready"));
    // ...and widening reach must NOT make it fire early: the release still waits for the
    // crossing-minus-lead deadline, which is ~150ms away here.
    QCOMPARE(engine.context().state, HoldState::Holding);
}

void AutomationEngineTests::heldSquareStillReleasesAfterRaisedNoMeterCap()
{
    // A1 — the button no-meter cap was 1500ms, but the live meter-acquire distribution straddles
    // it (Go-To shots on the same rig acquired at firstMeterMs = 1424/1535/1445), so a ButtonShot
    // whose meter was a few tens of ms late got blind-fired instead of timed. The cap is now
    // 2800ms. GUARANTEED RELEASE IS SACRED: this pins BOTH halves — the shot must still be
    // holding at 2000ms (past the old cap, waiting for its meter) AND must still be released by
    // the raised cap, never left stuck on a dead button.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 360.0;
    config.tempoFallbackTimeoutMs = 20.0;
    LearningData learning;
    // Unarmed hold clock, so the no-meter net (not the feedforward clock) is what fires.
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);
    QVERIFY2(engine.config().buttonNoMeterAbortMs > 2000.0,
             "the button no-meter cap must cover the measured meter-acquire distribution");

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // 2000ms of hold with NO meter: past the OLD 1500ms cap, still waiting for the meter.
    engine.advanceTestClock(1800);
    engine.process(physical);
    QVERIFY2(engine.context().state == HoldState::Holding,
             "a held Square must keep waiting for its meter past the old 1500ms cap");
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("await_meter"));

    // ...but the guaranteed-release net still fires by the raised cap. Never a dead button.
    for (int i = 0; i < 40 && engine.context().state == HoldState::Holding; ++i) {
        engine.advanceTestClock(50);
        engine.process(physical);
    }
    QVERIFY2(engine.context().state != HoldState::Holding,
             "GUARANTEED RELEASE: the no-meter net must still fire by the raised cap");
}

void AutomationEngineTests::beginShotArmsReaderInMeterMode()
{
    // The single shotArmed signal drives both the meter reader's physical gate and
    // the lab pose arm. Meter mode must still emit it, exactly once per beginShot.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);
    QVERIFY2(!engine.config().noMeterEnabled, "test setup: this is METER mode (the live config)");

    QSignalSpy armedSpy(&engine, &AutomationEngine::shotArmed);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);

    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(armedSpy.count(), 1);
    // The payload identifies the shot that just armed.
    QCOMPARE(armedSpy.at(0).at(0).value<orion::ShotMode>(), ShotMode::ButtonShot);
    QCOMPARE(armedSpy.at(0).at(1).toString(), engine.context().shotType);
    const quint64 firstToken = armedSpy.at(0).at(2).toULongLong();
    QVERIFY(firstToken != 0);
    QCOMPARE(firstToken, engine.context().armToken);

    engine.reset();
    ControllerState neutral;
    engine.process(neutral);
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    QCOMPARE(armedSpy.count(), 2);
    const quint64 secondToken = armedSpy.at(1).at(2).toULongLong();
    QVERIFY(secondToken != 0);
    QVERIFY(secondToken != firstToken);
    QCOMPARE(secondToken, engine.context().armToken);
}

void AutomationEngineTests::rightStickDownArmsReaderAndAutomationWhenBothInputsEnabled()
{
    // Production input contract: a sustained RS-down shot uses the same reader
    // arm signal and meter-authority engine as Square. The old hidden `square`
    // default made this path completely silent.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 20.0;
    config.tempoFlickHoldMs = 66.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    QSignalSpy armedSpy(&engine, &AutomationEngine::shotArmed);
    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy issuedSpy(&engine, &AutomationEngine::releaseIssued);
    ControllerState stickShot;
    stickShot.rightStickY = 127;

    auto output = engine.process(stickShot);
    QCOMPARE(engine.shotsAttempted(), 0);
    QCOMPARE(output.rightStickY, 0); // LS-only ordered commit precedes the gather

    for (const double dwellMs : {60.0, 60.0}) {
        engine.advanceTestClock(dwellMs);
        output = engine.process(stickShot);
        QCOMPARE(engine.shotsAttempted(), 0);
        QCOMPARE(output.rightStickY, 127);
    }
    engine.advanceTestClock(40.0);
    output = engine.process(stickShot);
    QCOMPARE(engine.shotsAttempted(), 1);
    QCOMPARE(engine.context().mode, ShotMode::TempoStick);
    QCOMPARE(armedSpy.count(), 1);
    QCOMPARE(armedSpy.at(0).at(0).value<orion::ShotMode>(), ShotMode::TempoStick);
    QVERIFY(armedSpy.at(0).at(2).toULongLong() != 0);
    QCOMPARE(output.rightStickX, 0);
    QCOMPARE(output.rightStickY, 127); // Orion now owns the gather until timed release

    engine.advanceTestClock(engine.config().tempoFallbackTimeoutMs + 1.0);
    output = engine.process(stickShot);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(output.rightStickY, 127);

    // Cross the normal commit floor, then feed a valid meter. Every packet
    // before the decision remains DOWN; the first release packet is directly
    // UP, proving there was no neutral/re-press hidden in the legacy lane.
    engine.advanceTestClock(180.0);
    bool released = false;
    for (int frame = 1; frame <= 40 && !released; ++frame) {
        DetectionResult sample = readyMeterSample(96.0, 1.0);
        sample.frameNumber = frame;
        engine.updateDetection(sample);
        output = engine.process(stickShot);
        if (engine.context().state == HoldState::Releasing) {
            released = true;
            QCOMPARE(output.rightStickX, 0);
            QCOMPARE(output.rightStickY, -127);
        } else {
            QCOMPARE(output.rightStickY, 127);
        }
        engine.advanceTestClock(16.0);
    }
    QVERIFY2(released, "legacy TempoStick must reach one meter-authorized UP flick");
    QCOMPARE(markerSpy.count(), 1);
    QCOMPARE(issuedSpy.count(), 1);
    QCOMPARE(markerSpy.at(0).at(0).toInt(), engine.context().releaseSeq);
    const ShotContext issued = issuedSpy.at(0).at(0).value<ShotContext>();
    QCOMPARE(issued.mode, ShotMode::TempoStick);
    QCOMPARE(issued.releaseSeq, engine.context().releaseSeq);
}

void AutomationEngineTests::shotIntentEdgesWakeReaderBeforeOwnershipDebounce()
{
    ControllerState neutral;

    ControllerState square = neutral;
    square.buttons |= XINPUT_GAMEPAD_X;
    auto edge = shotIntentEdges(square, neutral, 50.0, 50.0);
    QVERIFY(edge.square);
    QVERIFY(!edge.stickUp);
    QVERIFY(!edge.stickDown);
    QVERIFY(!shotIntentEdges(square, square, 50.0, 50.0).any());

    ControllerState diagonalUp;
    diagonalUp.rightStickX = 100;
    diagonalUp.rightStickY = -100;
    QVERIFY2(!shotIntentEdges(diagonalUp, neutral, 50.0, 50.0).any(),
             "diagonal dribble must not wake the shot reader");

    ControllerState verticalUp;
    verticalUp.rightStickX = 10;
    verticalUp.rightStickY = -100;
    edge = shotIntentEdges(verticalUp, neutral, 50.0, 50.0);
    QVERIFY(edge.stickUp);

    ControllerState crossUp = verticalUp;
    crossUp.buttons |= XINPUT_GAMEPAD_A;
    edge = shotIntentEdges(crossUp, neutral, 50.0, 50.0);
    QVERIFY2(!edge.stickUp,
             "Cross + RS-up is call-for-ball context and must not wake the shot reader");

    ControllerState verticalDown;
    verticalDown.rightStickX = -12;
    verticalDown.rightStickY = 110;
    edge = shotIntentEdges(verticalDown, neutral, 50.0, 50.0);
    QVERIFY(edge.stickDown);
}

void AutomationEngineTests::shotIntentEdgeTrackerDebouncesPollDropoutsAndPreservesGestureEdges()
{
    ControllerState neutral;
    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;

    ShotIntentEdgeTracker tracker;
    ShotIntentEdges edge = tracker.update(square, 50.0, 50.0);
    QVERIFY(edge.square);
    QVERIFY(!tracker.update(square, 50.0, 50.0).any());

    // A one- or two-poll observed UP must not make the still-held Square a new
    // physical-shot epoch when the physical report returns DOWN.
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    QVERIFY(!tracker.update(square, 50.0, 50.0).any());
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    QVERIFY(!tracker.update(square, 50.0, 50.0).any());

    // Three consecutive selected-device neutral samples are the real-release
    // boundary. The next DOWN is a genuine new shot edge.
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    edge = tracker.update(square, 50.0, 50.0);
    QVERIFY(edge.square);

    // The same lifetime applies to a same-direction RS gesture, while direct
    // Up <-> Down changes remain immediate new gestures as before.
    tracker.reset();
    ControllerState up;
    up.rightStickY = -100;
    ControllerState down;
    down.rightStickY = 100;
    edge = tracker.update(up, 50.0, 50.0);
    QVERIFY(edge.stickUp);
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    QVERIFY(!tracker.update(up, 50.0, 50.0).any());
    edge = tracker.update(down, 50.0, 50.0);
    QVERIFY(edge.stickDown);
    edge = tracker.update(up, 50.0, 50.0);
    QVERIFY(edge.stickUp);

    // A diagonal dribble remains non-shot input and cannot wake the reader.
    tracker.reset();
    ControllerState diagonal;
    diagonal.rightStickX = 100;
    diagonal.rightStickY = -100;
    QVERIFY(!tracker.update(diagonal, 50.0, 50.0).any());

    // A Cross/RS-up overlap stays blocked when Cross is released while RS is
    // still held. Only a physical neutral boundary may create a later edge.
    tracker.reset();
    ControllerState crossUp = up;
    crossUp.buttons |= XINPUT_GAMEPAD_A;
    QVERIFY(!tracker.update(crossUp, 50.0, 50.0).any());
    QVERIFY(!tracker.update(up, 50.0, 50.0).any());
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    edge = tracker.update(up, 50.0, 50.0);
    QVERIFY(edge.stickUp);
}

void AutomationEngineTests::shotIntentTransportRecoveryRequiresObservedNeutral()
{
    ControllerState neutral;
    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;
    ControllerState stickUp;
    stickUp.rightStickY = -100;
    ControllerState stickDown;
    stickDown.rightStickY = 100;

    struct ReconnectCase {
        const char* name;
        ControllerState held;
        bool expectSquare;
        bool expectStickUp;
        bool expectStickDown;
    };
    const ReconnectCase cases[] = {
        {"Button", square, true, false, false},
        {"TempoSquare", square, true, false, false},
        {"GoToStick", stickUp, false, true, false},
        {"TempoStick", stickDown, false, false, true},
    };

    for (const ReconnectCase& testCase : cases) {
        ShotIntentEdgeTracker tracker;
        ShotIntentEdges edge = tracker.update(testCase.held, 50.0, 50.0);
        QVERIFY2(edge.square == testCase.expectSquare
                     && edge.stickUp == testCase.expectStickUp
                     && edge.stickDown == testCase.expectStickDown,
                 testCase.name);

        tracker.beginTransportRecovery();
        QVERIFY2(tracker.transportRecoveryActive(), testCase.name);

        // Any duration of report loss, followed by the same held control, must
        // neither create a reader-wake epoch nor clear the recovery fence.
        for (int i = 0; i < 5; ++i) {
            QVERIFY2(!tracker.update(testCase.held, 50.0, 50.0).any(),
                     testCase.name);
            QVERIFY2(tracker.transportRecoveryActive(), testCase.name);
        }

        // Two real neutral reports are insufficient, and a held report resets
        // their count. Only three consecutive selected-device neutral reports
        // clear the fence; that third report itself is never a shot edge.
        QVERIFY2(!tracker.update(neutral, 50.0, 50.0).any(), testCase.name);
        QVERIFY2(!tracker.update(neutral, 50.0, 50.0).any(), testCase.name);
        QVERIFY2(tracker.transportRecoveryActive(), testCase.name);
        QVERIFY2(!tracker.update(testCase.held, 50.0, 50.0).any(),
                 testCase.name);
        QVERIFY2(tracker.transportRecoveryActive(), testCase.name);
        for (int i = 0; i < ShotIntentEdgeTracker::kReleaseSamples; ++i) {
            QVERIFY2(!tracker.update(neutral, 50.0, 50.0).any(), testCase.name);
        }
        QVERIFY2(!tracker.transportRecoveryActive(), testCase.name);

        edge = tracker.update(testCase.held, 50.0, 50.0);
        QVERIFY2(edge.square == testCase.expectSquare
                     && edge.stickUp == testCase.expectStickUp
                     && edge.stickDown == testCase.expectStickDown,
                 testCase.name);
    }

    // Cross may change while reports are unavailable, but an unchanged RS-up
    // remains fenced until the stick itself is physically centered.
    ShotIntentEdgeTracker tracker;
    QVERIFY(tracker.update(stickUp, 50.0, 50.0).stickUp);
    tracker.beginTransportRecovery();
    ControllerState crossUp = stickUp;
    crossUp.buttons |= XINPUT_GAMEPAD_A;
    QVERIFY(!tracker.update(crossUp, 50.0, 50.0).any());
    QVERIFY(!tracker.update(stickUp, 50.0, 50.0).any());
    QVERIFY(tracker.transportRecoveryActive());
    for (int i = 0; i < ShotIntentEdgeTracker::kReleaseSamples; ++i) {
        QVERIFY(!tracker.update(neutral, 50.0, 50.0).any());
    }
    QVERIFY(!tracker.transportRecoveryActive());
    QVERIFY(tracker.update(stickUp, 50.0, 50.0).stickUp);
}

void AutomationEngineTests::shotIntentThresholdMatchesAutomationOwnershipThreshold()
{
    // The configured value is a percentage; ControllerState uses [-127, 127].
    // A 50% threshold therefore crosses between raw 63 and 64. The early
    // reader wake and AutomationEngine must agree exactly at that boundary or
    // a partial stick can open a long hardware gate that never becomes a shot.
    QCOMPARE(rawStickThreshold(50.0), 63.5);

    ControllerState neutral;
    ControllerState downBelow;
    downBelow.rightStickY = 63;
    ControllerState downAt;
    downAt.rightStickY = 64;
    ControllerState upBelow;
    upBelow.rightStickY = -63;
    ControllerState upAt;
    upAt.rightStickY = -64;

    QVERIFY(!shotIntentEdges(downBelow, neutral, 50.0, 50.0).any());
    QVERIFY(!shotIntentEdges(upBelow, neutral, 50.0, 50.0).any());
    const ShotIntentEdges downEdge = shotIntentEdges(
        downAt, neutral, 50.0, 50.0);
    const ShotIntentEdges upEdge = shotIntentEdges(
        upAt, neutral, 50.0, 50.0);
    QVERIFY(downEdge.stickDown);
    QVERIFY(!downEdge.stickUp);
    QVERIFY(upEdge.stickUp);
    QVERIFY(!upEdge.stickDown);
    QVERIFY(!shotIntentEdges(downAt, downAt, 50.0, 50.0).any());
    QVERIFY(!shotIntentEdges(upAt, upAt, 50.0, 50.0).any());

    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.minimumHoldMs = 0.0;
    LearningData learning;

    AutomationEngine downBelowEngine;
    downBelowEngine.applyConfig(config, learning);
    downBelowEngine.process(downBelow);
    downBelowEngine.advanceTestClock(160);
    downBelowEngine.process(downBelow);
    QCOMPARE(downBelowEngine.shotsAttempted(), 0);

    AutomationEngine downAtEngine;
    downAtEngine.applyConfig(config, learning);
    downAtEngine.process(downAt);
    downAtEngine.advanceTestClock(160);
    downAtEngine.process(downAt);
    QCOMPARE(downAtEngine.shotsAttempted(), 1);
    QCOMPARE(downAtEngine.context().mode, ShotMode::TempoStick);

    AutomationEngine upBelowEngine;
    upBelowEngine.applyConfig(config, learning);
    upBelowEngine.process(upBelow);
    upBelowEngine.advanceTestClock(260);
    upBelowEngine.process(upBelow);
    QCOMPARE(upBelowEngine.shotsAttempted(), 0);

    AutomationEngine upAtEngine;
    upAtEngine.applyConfig(config, learning);
    upAtEngine.process(upAt);
    upAtEngine.advanceTestClock(260);
    upAtEngine.process(upAt);
    QCOMPARE(upAtEngine.shotsAttempted(), 1);
    QCOMPARE(upAtEngine.context().mode, ShotMode::GoToStick);
}

void AutomationEngineTests::shotIntentLateralBoundaryMatchesAutomationOwnership()
{
    // Production uses the same 0.5 vertical-dominance ratio for the early
    // reader edge and the hold-to-own state machine. At |Y|=100, |X|=50 is a
    // legitimate vertical shot and |X|=51 is a diagonal dribble. Test both
    // directions and the diagonal->vertical transition that must wake the
    // reader when the user straightens the stick without returning to neutral.
    constexpr double lateralRatio = 0.5;
    ControllerState neutral;

    ControllerState downAt;
    downAt.rightStickX = 50;
    downAt.rightStickY = 100;
    ControllerState downOutside = downAt;
    downOutside.rightStickX = 51;
    ControllerState upAt;
    upAt.rightStickX = -50;
    upAt.rightStickY = -100;
    ControllerState upOutside = upAt;
    upOutside.rightStickX = -51;

    QVERIFY(verticalStickShotIntent(downAt, false, 50.0, lateralRatio));
    QVERIFY(!verticalStickShotIntent(downOutside, false, 50.0, lateralRatio));
    QVERIFY(verticalStickShotIntent(upAt, true, 50.0, lateralRatio));
    QVERIFY(!verticalStickShotIntent(upOutside, true, 50.0, lateralRatio));

    QVERIFY(shotIntentEdges(downAt, neutral, 50.0, 50.0, lateralRatio).stickDown);
    QVERIFY(!shotIntentEdges(downOutside, neutral, 50.0, 50.0, lateralRatio).any());
    QVERIFY(shotIntentEdges(upAt, neutral, 50.0, 50.0, lateralRatio).stickUp);
    QVERIFY(!shotIntentEdges(upOutside, neutral, 50.0, 50.0, lateralRatio).any());
    QVERIFY(shotIntentEdges(downAt, downOutside, 50.0, 50.0, lateralRatio).stickDown);
    QVERIFY(shotIntentEdges(upAt, upOutside, 50.0, 50.0, lateralRatio).stickUp);

    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.minimumHoldMs = 0.0;
    LearningData learning;

    const auto runDown = [&](const ControllerState& state) {
        AutomationEngine engine;
        engine.applyConfig(config, learning);
        engine.process(state);
        engine.advanceTestClock(160);
        engine.process(state);
        return engine.shotsAttempted();
    };
    const auto runUp = [&](const ControllerState& state) {
        AutomationEngine engine;
        engine.applyConfig(config, learning);
        engine.process(state);
        engine.advanceTestClock(260);
        engine.process(state);
        return engine.shotsAttempted();
    };

    QCOMPARE(runDown(downAt), 1);
    QCOMPARE(runDown(downOutside), 0);
    QCOMPARE(runUp(upAt), 1);
    QCOMPARE(runUp(upOutside), 0);
}

void AutomationEngineTests::poseArmTokenProtocolIsCanonicalAndShotScoped()
{
    const quint64 token = std::numeric_limits<quint64>::max();
    const QString encoded = encodePoseArmToken(token);
    QCOMPARE(encoded, QStringLiteral("18446744073709551615"));

    quint64 decoded = 0;
    QVERIFY(decodePoseArmToken(QJsonValue(encoded), &decoded));
    QCOMPARE(decoded, token);
    QVERIFY(poseArmTokenMatches(token, decoded));
    QVERIFY(!poseArmTokenMatches(token, token - 1));
    QVERIFY(!poseArmTokenMatches(0, 0));

    // Numeric JSON is rejected to avoid IEEE-754 rounding; non-canonical strings
    // cannot alias another shot token either.
    QVERIFY(!decodePoseArmToken(QJsonValue(42.0), &decoded));
    QVERIFY(!decodePoseArmToken(QJsonValue(QStringLiteral("0")), &decoded));
    QVERIFY(!decodePoseArmToken(QJsonValue(QStringLiteral("042")), &decoded));
    QVERIFY(!decodePoseArmToken(QJsonValue(QStringLiteral("42.0")), &decoded));
    QVERIFY(!decodePoseArmToken(QJsonValue(QStringLiteral("18446744073709551616")), &decoded));
}

void AutomationEngineTests::cooldownClearsSquareLatchOnReleasedButton()
{
    // B2c/C5 — LATCH + HISTORY LEAK. processCooldown reset ShotContext (wiping the 3-frame
    // PHYSICAL button history that processIdle's release detector needs) but left
    // squareLatchedUntilRelease_ set. A user who let go of Square DURING the cooldown had that
    // release thrown away, so the latch survived and processIdle suppressed their NEXT press
    // ("waiting_for_button_release") until they released for 3 fresh clean ticks.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 300.0;          // dump promptly; this test is about the cooldown exit
    config.tempoFallbackTimeoutMs = 300.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState held;
    held.buttons |= XINPUT_GAMEPAD_X;
    ControllerState idle;                  // button up

    engine.process(held);
    engine.advanceTestClock(220);
    engine.process(held);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // Let the shot run to a release however it likes (meter never appears -> the no-meter net).
    for (int i = 0; i < 200 && engine.context().state != HoldState::Cooldown
                    && engine.context().state != HoldState::Idle; ++i) {
        engine.advanceTestClock(50);
        engine.process(held);
    }
    QVERIFY2(engine.context().state == HoldState::Cooldown || engine.context().state == HoldState::Idle,
             "test setup: the shot must have released/aborted into cooldown or idle");

    // The user lets go DURING the cooldown, then the cooldown expires.
    for (int i = 0; i < 10 && engine.context().state != HoldState::Idle; ++i) {
        engine.advanceTestClock(100);
        engine.process(idle);
    }
    QCOMPARE(engine.context().state, HoldState::Idle);
    // A detector abort reaches Idle immediately, so explicitly deliver the
    // stable physical release that clears the separate rearm block.
    for (int i = 0; i < 3; ++i) engine.process(idle);

    // A fresh press must be able to arm IMMEDIATELY — not be swallowed by a stale latch.
    engine.process(held);
    QVERIFY2(engine.context().releaseReason != QStringLiteral("waiting_for_button_release"),
             "C5 LEAK: the completed shot's Square latch survived cooldown and swallowed the "
             "next press");
    engine.advanceTestClock(220);
    engine.process(held);
    QCOMPARE(engine.context().state, HoldState::Holding);
}

void AutomationEngineTests::anchorNeedsTwoGenuineSamplesOnLowFill()
{
    // B7 — ANCHOR HARDENING. A décor phantom is a GENUINE fresh accept (genuine-vs-echo cannot
    // reject it) and is low-fill almost by definition, so the low-fill branch used to validate
    // anchorValidMs on the FIRST frame of a new episode — handing the meter-appear CLOCK an
    // anchor that never belonged to a meter. Both branches now require >= 2 genuine samples, and
    // anchorValidMs still BACKDATES to the first one, so validity costs zero timing accuracy.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    auto genuine = [](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        r.etaToGreenMs = -1.0;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    // ONE low-fill genuine accept — the phantom shape. It must NOT validate the anchor.
    engine.updateDetection(genuine(12.0));
    engine.process(physical);
    QVERIFY2(engine.context().anchorValidMs < 0.0,
             "a single low-fill genuine accept must not validate the meter-appear anchor");
    const double firstSampleClockMs = engine.context().anchorCandFirstMs;
    QVERIFY(firstSampleClockMs >= 0.0);

    // The confirm frame (non-descending) arrives -> the episode is a real meter -> validated,
    // and BACKDATED to the first sample so the appear->tip clock loses no accuracy.
    engine.advanceTestClock(16);
    engine.updateDetection(genuine(14.0));
    engine.process(physical);
    QVERIFY2(engine.context().anchorValidMs >= 0.0,
             "a confirmed low-fill episode must validate the anchor on the second genuine sample");
    QVERIFY2(std::abs(engine.context().anchorValidMs - firstSampleClockMs) < 0.001,
             "anchorValidMs must BACKDATE to the episode's first genuine sample");
}


void AutomationEngineTests::reevaluateOnFreshSampleMovesDeadlineEarlier()
{
    // Item 7: a fresh meter sample re-runs ONLY predictCrossingMs + the fire SCHEDULE (no 4ms tick), so it
    // can move an already-armed sub-tick fire deadline EARLIER without advancing the tracking-history /
    // tempo cadence. Deterministic lever: a fresher sample that is staler-at-capture (higher frameAgeMs)
    // means the real meter rose further since capture, so the lead grows and the fire moves earlier — the
    // trajectory is held steady so the move is attributable to the reschedule, not to a velocity swing.
    // Per-type mode keeps the crossing well BELOW the meter-top decel knee (88) so msUntilTarget is clean
    // (above the knee the deceleration correction pulls the fire in-tick instead of scheduling it). The
    // reschedule path is mode-agnostic — autonomous tip-vision uses the identical scheduleFire mechanism.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    LearningData learning;
    engine.applyConfig(config, learning);   // per-type lead = controllerChain(45) + pipeline(55) = 100

    auto rising = [](double fill, double frameAge) {
        DetectionResult r = readyMeterSample(fill, -1.0);   // no eta; the velocity crossing drives the fire
        r.greenStartPct = -1.0; r.greenEndPct = -1.0; r.greenCenterPct = -1.0; r.greenConfidence = 0.0;
        r.frameAgeMs = frameAge;
        return r;
    };

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);                 // -> Holding
    engine.advanceTestClock(160);             // past commit
    engine.process(physical);

    // Steady rise (~0.379%/ms) toward a contested tip (target 100), ending at fill 60 — below the decel
    // knee. crossing ~105ms out, lead 100 -> the fire deadline (crossing - lead) lands ~5ms out, inside
    // the 6ms scheduler horizon, so the tick ARMS it.
    engine.updateDetection(rising(52.42, 0.0)); engine.process(physical); engine.advanceTestClock(10);
    engine.updateDetection(rising(56.21, 0.0)); engine.process(physical); engine.advanceTestClock(10);
    engine.updateDetection(rising(60.00, 0.0)); engine.process(physical);

    const double d0 = engine.scheduledFireDeadlineMs();
    QVERIFY2(d0 >= 0.0,
             qPrintable(QStringLiteral("a fresh in-horizon crossing must arm the sub-tick scheduler; d0=%1").arg(d0)));
    const int holdFramesBefore = engine.context().holdFrames;

    // A fresher sample, steady trajectory but STALER at capture (frameAge 3) -> lead grows to ~103 -> the
    // fire deadline must move EARLIER. Advance a hair so the sample carries a distinct timestamp.
    engine.advanceTestClock(0.5);
    engine.updateDetection(rising(60.19, 3.0));
    engine.reevaluateScheduleOnFreshSample();
    const double d1 = engine.scheduledFireDeadlineMs();

    QVERIFY2(d1 >= 0.0, "the deadline must stay armed after the fresh-sample reschedule");
    QVERIFY2(d1 < d0 - 1e-6,
             qPrintable(QStringLiteral("a fresh sample must move the scheduled fire EARLIER: d0=%1 d1=%2").arg(d0).arg(d1)));
    // No 4ms tick ran across the reschedule, so the tracking-history / tempo advance must NOT have happened.
    QCOMPARE(engine.context().holdFrames, holdFramesBefore);
}

void AutomationEngineTests::rttEstimatorSeedsAndSmoothsSteadyRtt()
{
    orion::RttEstimator e;
    QVERIFY(e.update(50.0));            // first sample seeds
    QCOMPARE(e.rttMs, 50.0);
    for (int i = 0; i < 20; ++i) QVERIFY(e.update(50.0));
    QVERIFY2(std::abs(e.rttMs - 50.0) < 0.5, qPrintable(QString::number(e.rttMs)));
    QVERIFY2(std::abs(e.offsetMs - 25.0) < 0.5, qPrintable(QString::number(e.offsetMs)));   // one-way = rtt/2
    QVERIFY(e.syncAdjustMs >= e.offsetMs);   // offset + a (here ~0) jitter margin
}

void AutomationEngineTests::rttEstimatorRejectsTransientSpike()
{
    orion::RttEstimator e;
    for (int i = 0; i < 8; ++i) e.update(50.0);
    const double before = e.rttMs;
    QVERIFY2(!e.update(400.0), "a lone 400ms spike must be held out");
    QVERIFY2(std::abs(e.rttMs - before) < 1e-6, "the spike must not move the RTT estimate");
    QVERIFY(e.update(50.0));            // steady resumes, accepted again
}

void AutomationEngineTests::rttEstimatorAdoptsSustainedShift()
{
    orion::RttEstimator e;
    for (int i = 0; i < 8; ++i) e.update(50.0);
    bool adopted = false;
    for (int i = 0; i < e.outlierAdoptAfter + 2; ++i) {
        if (e.update(120.0)) adopted = true;   // a persistent new level, not a spike
    }
    QVERIFY2(adopted, "a sustained 120ms level must eventually be adopted as a real shift");
    QVERIFY2(e.rttMs > 90.0, qPrintable(QStringLiteral("RTT must track the new level, got %1").arg(e.rttMs)));
}

void AutomationEngineTests::rttEstimatorDropsImplausibleSamples()
{
    orion::RttEstimator e;
    e.update(50.0);
    const double before = e.rttMs;
    QVERIFY2(!e.update(0.0), "0ms (torn match) must be dropped");
    QVERIFY2(!e.update(2000.0), "2000ms (implausible) must be dropped");
    QCOMPARE(e.rttMs, before);
}

void AutomationEngineTests::feedforwardDoesNotFireWhenFillFarBelowTarget()
{
    // (do #1) Reachability cap on the OPEN-LOOP feedforward fire — the chief live early-fire fix. A
    // short-drifted learned clock used to fire "no matter how low the fill is". Mirror
    // feedforwardTimesFastVisibleMeterFromHoldStart (which FIRES at fill 60) but at fill 25: the clock
    // elapses, yet a trustworthy fresh fill far below target must HOLD the fire (not blind early-fire).
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 5000.0;   // keep the tempo timeout safety out of the way
    config.maximumHoldMs = 5000.0;            // keep the max-hold ceiling out of the way
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);  // short, ARMED clock
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);                 // -> Holding (holdStart set)
    QCOMPARE(engine.context().state, HoldState::Holding);

    DetectionResult r = readyMeterSample(25.0, -1.0);  // fresh accept, visible, FAR below target
    r.velocityPctS = 0.0;                               // no vision crossing -> only the clock could fire
    engine.updateDetection(r);
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    engine.advanceTestClock(300);                        // PAST the 250ms clock (an UNGUARDED clock fires here)
    r = readyMeterSample(25.0, -1.0);
    r.velocityPctS = 0.0;
    engine.updateDetection(r);
    engine.process(physical);

    const ShotContext ctx = engine.context();
    QVERIFY2(ctx.state == HoldState::Holding,
             "the reachability cap must keep the shot holding, not feedforward-fire at fill 25");
    QVERIFY2(ctx.releaseReasonCode != QStringLiteral("feedforward_target"),
             "feedforward must not fire when a trustworthy fresh fill is far below target");
    QCOMPARE(ctx.releaseReasonCode, QStringLiteral("out_of_reach"));
}

void AutomationEngineTests::tempoNotOpenLoopEarly()
{
    // (do #3) Tempo like the button: tempoOpenLoopPrimary is DEMOTED (default OFF) and the open-loop
    // feedforward is reachability-capped (#1), so a TempoSquare can no longer fire EARLY on a short
    // clock at a low fill. Seed a short clock, drive a TempoSquare, feed a fresh meter FAR below
    // target: the clock elapses but the fire is held back for the whole window (no early tempo release).
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.tempoRemapEnabled = true;          // a held Square becomes a TempoSquare
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    config.maximumHoldMs = 5000.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);  // short armed clock
    engine.applyConfig(config, learning);

    QCOMPARE(engine.config().tempoOpenLoopPrimary, false);   // demoted by default

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;      // user holds Square -> tempo gesture
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    QCOMPARE(engine.context().mode, ShotMode::TempoSquare);

    // Feed a fresh, static, far-below-target meter for ~640ms (well past the 250ms clock). The tempo
    // shot must never open-loop fire early on it (the cap holds), nor vision-fire (no crossing).
    bool releasedEarly = false;
    for (int i = 0; i < 40; ++i) {
        DetectionResult r = readyMeterSample(25.0, -1.0);
        r.velocityPctS = 0.0;
        engine.updateDetection(r);
        engine.process(physical);
        const HoldState st = engine.context().state;
        if (st == HoldState::Releasing || st == HoldState::Cooldown) {
            releasedEarly = engine.context().releaseReasonCode == QStringLiteral("feedforward_target");
            break;
        }
        engine.advanceTestClock(16);
    }
    QVERIFY2(!releasedEarly, "tempo must not open-loop feedforward-fire early at a low fill");
}

void AutomationEngineTests::tempoLegacyClockFlagCannotForkButtonAuthority()
{
    // The retired ORION_TEMPO_OWN_CLOCK environment flag must be inert: two
    // otherwise identical Tempo fades use the same Button timing authority,
    // release on the same frame, and never create a `|tempo` namespace.
    const QByteArray saved = qgetenv("ORION_TEMPO_OWN_CLOCK");

    struct Run {
        ShotContext ctx;
        bool forkedTempoBucketPresent = false;
    };
    auto runShot = [](bool ownOnly) {
        if (ownOnly) {
            qputenv("ORION_TEMPO_OWN_CLOCK", "1");
        } else {
            qunsetenv("ORION_TEMPO_OWN_CLOCK");
        }
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.tempoRemapEnabled = true;
        config.minimumHoldMs = 0.0;
        config.maximumHoldMs = 5000.0;              // keep the blind safeties out of the way
        config.tempoFallbackTimeoutMs = 5000.0;
        // Isolate the learned-clock rung; detector freshness still remains its
        // release authority and is supplied on every meter frame below.
        config.tipGateEnabled = false;
        LearningData learning;
        // Only the canonical Left Fade timing keys exist.
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Left Fade"), 700.0);
        learning.shotTypeMeterToReleaseMs.insert(QStringLiteral("Left Fade"), 380.0);
        engine.applyConfig(config, learning);

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;       // user HOLDS Square...
        physical.leftStickX = -90;                  // ...with a Left Fade lean
        engine.process(physical);
        engine.advanceTestClock(220);               // shared Square ownership gate
        engine.process(physical);

        // A deterministic rising fade trace with current detector authority.
        for (int i = 0; i < 140; ++i) {
            DetectionResult r = readyMeterSample(std::min(20.0 + 0.8 * i, 99.0), -1.0);
            r.velocityPctS = 80.0;
            engine.updateDetection(r);
            engine.process(physical);
            const HoldState st = engine.context().state;
            if (st == HoldState::Releasing || st == HoldState::Cooldown) {
                break;
            }
            engine.advanceTestClock(10);
        }
        Run run;
        run.ctx = engine.context();
        run.forkedTempoBucketPresent =
            engine.config().shotTypeFeedforwardMs.contains(QStringLiteral("Left Fade|tempo"));
        return run;
    };

    const Run borrowed = runShot(false);
    QCOMPARE(borrowed.ctx.mode, ShotMode::TempoSquare);
    QCOMPARE(borrowed.ctx.shotType, QStringLiteral("Left Fade"));
    QVERIFY2(borrowed.ctx.state == HoldState::Releasing || borrowed.ctx.state == HoldState::Cooldown,
             "baseline tempo fade must have released");
    QCOMPARE(borrowed.ctx.releaseReasonCode, QStringLiteral("feedforward_target"));
    QVERIFY2(borrowed.ctx.releaseFillPct < 75.0,
             qPrintable(QStringLiteral("baseline clock trace unexpectedly changed, "
                                       "got fill=%1").arg(borrowed.ctx.releaseFillPct)));
    QVERIFY(!borrowed.forkedTempoBucketPresent);

    const Run own = runShot(true);
    QCOMPARE(own.ctx.mode, ShotMode::TempoSquare);
    QCOMPARE(own.ctx.shotType, QStringLiteral("Left Fade"));
    QVERIFY2(own.ctx.state == HoldState::Releasing || own.ctx.state == HoldState::Cooldown,
             "own-clock tempo fade must still release (vision-timed)");
    QCOMPARE(own.ctx.releaseReasonCode, borrowed.ctx.releaseReasonCode);
    QCOMPARE(own.ctx.releaseFillPct, borrowed.ctx.releaseFillPct);
    QVERIFY2(!own.forkedTempoBucketPresent,
             "the legacy flag must not recreate a separate |tempo namespace");

    if (saved.isEmpty()) {
        qunsetenv("ORION_TEMPO_OWN_CLOCK");
    } else {
        qputenv("ORION_TEMPO_OWN_CLOCK", saved);
    }
}

void AutomationEngineTests::tempoToggleDoesNotEnableRawStickInput()
{
    // (do #4) Stick-tempo (RS-DOWN) must arm even when inputMode is the default square_only, as long as
    // the user selected the stick tempo remap — previously stickInputAllowed()==false SILENTLY killed
    // the gesture. Then it runs the shared engine (TempoStick) like any other shot.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");   // inputMode square_only -> stickInputAllowed()==false
    config.tempoRemapEnabled = true;
    config.tempoRemapType = QStringLiteral("stick");           // user picked the RS-down tempo
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.rightStickY = 127;     // RS held DOWN (the stick-tempo gesture; down = +Y)
    engine.process(physical);       // start the stick hold timer
    engine.advanceTestClock(160);   // past stickHoldArmMs (135ms)
    engine.process(physical);       // arms TempoStick

    QCOMPARE(engine.shotsAttempted(), 0);
    QCOMPARE(engine.context().state, HoldState::Idle);

    // Raw RS-down remains available through the explicit stick input source.
    AutomationEngine stickEngine;
    config.remotePlayInputSource = QStringLiteral("both");
    stickEngine.applyConfig(config, learning);
    stickEngine.process(physical);
    stickEngine.advanceTestClock(160);
    stickEngine.process(physical);
    QCOMPARE(stickEngine.shotsAttempted(), 1);
    QCOMPARE(stickEngine.context().mode, ShotMode::TempoStick);
}

void AutomationEngineTests::stickLatchClearsOnCrossDirectionForTempo()
{
    // (do #4) TempoStick<->Go-To latch conflict: after a Go-To latches the RS-up neutral latch, a
    // STRAIGHT RS-up -> RS-down transition (never passing through center) used to keep the stick pinned
    // to (0,0) — the neutral-only clear never fired — stranding a follow-up RS-down tempo. An RS pushed
    // CLEARLY in the opposite (down) direction is an unambiguous new gesture and must clear the stale
    // up-latch so the down input is no longer pinned. Mirrors goToRsLatchHoldsUntilTrulyNeutral's setup.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState up;
    up.rightStickY = -127;
    engine.process(up);
    engine.advanceTestClock(270);
    engine.process(up);                                   // arms the Go-To (up-latch set)
    QCOMPARE(engine.context().mode, ShotMode::GoToStick);

    engine.advanceTestClock(900);                         // past the Go-To release floor
    engine.updateDetection(readyMeterSample(94.0, 1.0));  // fresh green meter -> release
    engine.process(up);
    engine.advanceTestClock(100);
    engine.process(up);                                   // Releasing -> Cooldown
    engine.advanceTestClock(750);
    engine.process(up);                                   // Cooldown elapses -> Idle
    auto output = engine.process(up);                     // Idle: latch pins the still-up RS to neutral
    QCOMPARE(output.rightStickY, 0);                      // still latched (RS never returned to neutral)

    // The user now pushes the RS straight DOWN (the opposite-direction tempo gesture) without passing
    // through center. The stale up-latch must clear so the down input is NOT pinned — it passes through.
    ControllerState down;
    down.rightStickY = 127;
    output = engine.process(down);
    QCOMPARE(output.rightStickY, 127);
}

void AutomationEngineTests::tempoStickSquareOverlapCannotRetrigger()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.tempoRemapEnabled = true;
    config.tempoRemapType = QStringLiteral("stick");
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 20.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.rightStickY = 127;
    engine.process(physical);
    engine.advanceTestClock(160.0);
    engine.process(physical); // TempoStick Armed
    engine.advanceTestClock(engine.config().tempoFallbackTimeoutMs + 1.0);
    engine.process(physical); // Holding
    QCOMPARE(engine.context().mode, ShotMode::TempoStick);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.shotsAttempted(), 1);

    // Live seq12 shape: Square arrives while TempoStick already owns RS-down.
    // It is suppressed now and must be remembered through cooldown.
    physical.buttons |= XINPUT_GAMEPAD_X;
    ControllerState output = engine.process(physical);
    QVERIFY(!output.square());
    engine.advanceTestClock(180.0); // past Standstill commit floor

    bool sawReleaseEdge = false;
    for (int i = 0; i < 40 && !sawReleaseEdge; ++i) {
        engine.updateDetection(readyMeterSample(96.0, 1.0));
        output = engine.process(physical);
        if (engine.context().state == HoldState::Releasing) {
            sawReleaseEdge = true;
            QCOMPARE(output.rightStickX, 0);
            QCOMPARE(output.rightStickY, -127); // exact TempoStick release edge
            QVERIFY(!output.square());          // overlapped Square remains suppressed
        }
        engine.advanceTestClock(16.0);
    }
    QVERIFY2(sawReleaseEdge, "TempoStick setup must produce a meter-authorized release");

    while (engine.context().state == HoldState::Releasing) {
        output = engine.process(physical);
        engine.advanceTestClock(16.0);
    }
    QVERIFY(engine.context().state == HoldState::Cooldown);
    engine.advanceTestClock(engine.config().cooldownMs + 10.0);
    output = engine.process(physical); // finish cooldown
    QCOMPARE(engine.context().state, HoldState::Idle);

    const int attempts = engine.shotsAttempted();
    for (int i = 0; i < 8; ++i) {
        engine.advanceTestClock(50.0); // far beyond Square's arm window in aggregate
        output = engine.process(physical);
        QVERIFY(!output.square());
        QCOMPARE(engine.shotsAttempted(), attempts);
        QCOMPARE(engine.context().state, HoldState::Idle);
    }
}

void AutomationEngineTests::tempoSquareStickOverlapCannotRetrigger()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.tempoRemapEnabled = true;
    config.tempoRemapType = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220.0);
    engine.process(physical);
    QCOMPARE(engine.context().mode, ShotMode::TempoSquare);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.shotsAttempted(), 1);

    // A physical RS-down gesture is hidden beneath TempoSquare's generated
    // gather. It must not surface as TempoStick after Square is released.
    physical.rightStickY = 127;
    ControllerState output = engine.process(physical);
    QVERIFY(!output.square());
    QCOMPARE(output.rightStickY, 127);
    engine.advanceTestClock(180.0);

    bool sawReleaseEdge = false;
    for (int i = 0; i < 40 && !sawReleaseEdge; ++i) {
        engine.updateDetection(readyMeterSample(96.0, 1.0));
        output = engine.process(physical);
        if (engine.context().state == HoldState::Releasing) {
            sawReleaseEdge = true;
            QVERIFY(!output.square());
            QCOMPARE(output.rightStickX, 0);
            QCOMPARE(output.rightStickY, -127); // non-fade TempoSquare initial flick
        }
        engine.advanceTestClock(16.0);
    }
    QVERIFY2(sawReleaseEdge, "TempoSquare setup must produce a meter-authorized release");

    // Release the owning Square, but keep the overlapped physical RS-down held.
    physical.buttons &= ~XINPUT_GAMEPAD_X;
    while (engine.context().state == HoldState::Releasing) {
        output = engine.process(physical);
        engine.advanceTestClock(16.0);
    }
    QVERIFY(engine.context().state == HoldState::Cooldown);
    engine.advanceTestClock(engine.config().cooldownMs + 10.0);
    output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Idle);

    const int attempts = engine.shotsAttempted();
    for (int i = 0; i < 8; ++i) {
        engine.advanceTestClock(50.0);
        output = engine.process(physical);
        QCOMPARE(output.rightStickX, 0);
        QCOMPARE(output.rightStickY, 0);
        QCOMPARE(engine.shotsAttempted(), attempts);
        QCOMPARE(engine.context().state, HoldState::Idle);
    }
}

// Drives a plain ButtonShot from a physical hold through to Cooldown.
static void driveButtonShotToCooldown(AutomationEngine& engine,
                                       const ControllerState& held)
{
    engine.process(held);
    engine.advanceTestClock(engine.config().squareHoldArmMs + 30.0);
    engine.process(held);
    QCOMPARE(engine.context().mode, ShotMode::ButtonShot);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.shotsAttempted(), 1);

    bool released = false;
    for (int i = 0; i < 60 && !released; ++i) {
        engine.updateDetection(readyMeterSample(96.0, 1.0));
        engine.process(held);
        released = engine.context().state == HoldState::Releasing
            || engine.context().state == HoldState::Cooldown;
        engine.advanceTestClock(16.0);
    }
    QVERIFY2(released, "Button setup must produce a meter-authorized release");
    while (engine.context().state == HoldState::Releasing) {
        engine.process(held);
        engine.advanceTestClock(16.0);
    }
    QCOMPARE(engine.context().state, HoldState::Cooldown);
}

void AutomationEngineTests::squareRepressInsideCooldownReachesTheConsole()
{
    // A1 regression (2026-08-04). releasePulseMs + cooldownMs is only ~250ms, so a player
    // shooting quickly releases Square the moment the bot fires and presses again for the
    // next shot with BOTH edges inside that window. The cooldown-end latch reset sampled
    // lastPhysical_ once, saw the button down again, kept squareLatchedUntilRelease_, and
    // processIdle then STRIPPED Square out of the virtual pad for the whole of the new
    // press: the console never saw the button at all.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.minimumHoldMs = 0.0;
    engine.applyConfig(config, LearningData{});

    ControllerState held;
    held.buttons |= XINPUT_GAMEPAD_X;
    driveButtonShotToCooldown(engine, held);

    // Fully debounced physical release, then an immediate re-press -- still in cooldown.
    ControllerState up;
    for (int i = 0; i < 4; ++i) {
        engine.process(up);
        engine.advanceTestClock(4.0);
    }
    engine.process(held);

    engine.advanceTestClock(engine.config().cooldownMs + 10.0);
    engine.process(held); // cooldown-end tick
    QCOMPARE(engine.context().state, HoldState::Idle);

    const ControllerState output = engine.process(held);
    QVERIFY2(output.square(),
             "a re-press made inside cooldown must reach the console, not be masked");
    QVERIFY2(engine.context().releaseReason
                 != QStringLiteral("waiting_for_button_release"),
             "the new press must not be sitting behind the ownership latch");

    // ...and it is a real gesture again: it can arm the next shot on its own merits.
    engine.advanceTestClock(engine.config().squareHoldArmMs + 30.0);
    engine.process(held);
    QCOMPARE(engine.shotsAttempted(), 2);
}

void AutomationEngineTests::squareHeldThroughCooldownStaysSuppressed()
{
    // The other half of the same contract, and the one the latch exists for: a
    // CONTINUOUSLY held Square is not a new shot. It must stay suppressed and must never
    // auto-repeat, exactly as before the A1 fix.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.minimumHoldMs = 0.0;
    engine.applyConfig(config, LearningData{});

    ControllerState held;
    held.buttons |= XINPUT_GAMEPAD_X;
    driveButtonShotToCooldown(engine, held);

    engine.advanceTestClock(engine.config().cooldownMs + 10.0);
    engine.process(held);
    QCOMPARE(engine.context().state, HoldState::Idle);

    const int attempts = engine.shotsAttempted();
    for (int i = 0; i < 10; ++i) {
        engine.advanceTestClock(50.0); // far past squareHoldArmMs in aggregate
        const ControllerState output = engine.process(held);
        QVERIFY2(!output.square(),
                 "a never-released Square must remain suppressed after cooldown");
        QCOMPARE(engine.shotsAttempted(), attempts);
        QCOMPARE(engine.context().state, HoldState::Idle);
    }

    // Only a genuine three-poll release returns the button to the player.
    ControllerState up;
    for (int i = 0; i < 4; ++i) {
        engine.process(up);
        engine.advanceTestClock(4.0);
    }
    QVERIFY(!engine.squareLatchedUntilRelease_);
}

void AutomationEngineTests::ownedOutputDrainHonoursProvenReleaseAcrossRepress()
{
    // FIX 2 regression. ownedOutputDrainEndFrames_ is zeroed by ANY re-assertion of the
    // primary control, and abort() wipes ShotContext (and xButtonHistory) before latching
    // the drain. A drain latched over an ALREADY released button therefore demanded three
    // fresh UP polls, and a re-press inside those three polls stranded it -- under
    // ReleasedUntilPhysicalEnd applyReleased() then masked the player's new press for as
    // long as they held it, with processIdle short-circuited so it could never re-arm.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    engine.applyConfig(config, LearningData{});

    ControllerState held;
    held.buttons |= XINPUT_GAMEPAD_X;
    ControllerState up;

    engine.setPhysicalShotEpoch(1);
    engine.lastPhysical_ = held;
    engine.beginShot(ShotMode::ButtonShot, engine.engineNowMs(),
                     QStringLiteral("Standstill"));

    // The player's release is fully proven BEFORE any drain exists.
    for (int i = 0; i < 3; ++i) {
        engine.process(up);
        engine.advanceTestClock(4.0);
    }
    QVERIFY(engine.physicalSquareUpPolls_ >= 3);

    engine.latchOwnedOutputDrain(
        AutomationEngine::OwnedOutputDrain::ReleasedUntilPhysicalEnd,
        ShotMode::ButtonShot, QStringLiteral("Standstill"));
    QVERIFY2(engine.ownedOutputDrainEndObserved_,
             "a drain latched over an already-proven release is born complete");

    // Immediate re-press. This used to zero the counter and strand the drain.
    engine.shot_.state = HoldState::Idle;
    engine.process(held);
    QCOMPARE(engine.ownedOutputDrain_, AutomationEngine::OwnedOutputDrain::None);
    const ControllerState output = engine.process(held);
    QVERIFY2(output.square(),
             "the re-press must not stay masked behind a completed drain");
}

void AutomationEngineTests::staleCarryOverMeterEndsPendingWaitEarly()
{
    // B1 regression. When a press lands while the PREVIOUS shot's meter is still rendered
    // (or frozen), every structure-verified frame of the new epoch sits above the
    // first-sight bound, so no ownership episode can ever open. The player used to stand
    // there holding the ball for the whole buttonNoMeterAbortMs waiting for a proof that
    // provably cannot arrive.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    config.autonomousVision = true;
    config.minimumHoldMs = 0.0;
    engine.applyConfig(config, LearningData{});

    int frame = 1;
    const quint64 epoch = 7;
    DetectionResult lead = strictLiveMeterSample(1.0, frame++, 0);
    engine.updateDetection(lead);

    QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);

    ControllerState held;
    held.buttons |= XINPUT_GAMEPAD_X;
    engine.setPhysicalShotEpoch(epoch);
    engine.process(held);

    // A frozen carry-over meter: well above anchorMaxFirstFillPct and numerically static.
    for (int i = 0; i < 20 && aborted.isEmpty(); ++i) {
        engine.advanceTestClock(70.0);
        engine.updateDetection(strictLiveMeterSample(67.4, frame++, epoch));
        engine.process(held);
    }

    QCOMPARE(aborted.count(), 1);
    QCOMPARE(aborted.at(0).at(0).toString(),
             QStringLiteral("ownership_blocked_stale_meter"));
    // Ended EARLY -- the whole point is not paying buttonNoMeterAbortMs for it.
    QVERIFY(engine.engineNowMs() < engine.config().buttonNoMeterAbortMs);
    // Fail-closed is unchanged: nothing was owned and nothing was released.
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.shotsReleased(), 0);
}

void AutomationEngineTests::risingMeterNeverTripsStaleCarryOverCensus()
{
    // The census must be unreachable for anything the game actually draws. A meter that is
    // high but MOVING fails the static test, and a meter that starts low disarms the census
    // permanently by reaching the first-sight bound.
    for (const bool startLow : {false, true}) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.minimumHoldMs = 0.0;
        engine.applyConfig(config, LearningData{});

        int frame = 1;
        const quint64 epoch = 11;
        engine.updateDetection(strictLiveMeterSample(1.0, frame++, 0));

        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);

        ControllerState held;
        held.buttons |= XINPUT_GAMEPAD_X;
        engine.setPhysicalShotEpoch(epoch);
        engine.process(held);

        // startLow  : an ordinary meter, empty -> filling.
        // !startLow : acquired late and already high, but genuinely rising.
        double fill = startLow ? 5.0 : 45.0;
        for (int i = 0; i < 20; ++i) {
            engine.advanceTestClock(70.0);
            engine.updateDetection(strictLiveMeterSample(
                std::min(fill, 99.0), frame++, epoch));
            engine.process(held);
            fill += 4.0;
        }

        for (const QList<QVariant>& call : aborted) {
            QVERIFY2(call.at(0).toString()
                         != QStringLiteral("ownership_blocked_stale_meter"),
                     "a moving meter must never be censused as stale carry-over");
        }
    }
}

void AutomationEngineTests::tempoStickPostReleaseLatchRequiresDebouncedNeutral()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("both");
    engine.applyConfig(config, LearningData{});

    // Seed the exact post-cooldown state: the bot has already flicked UP and
    // neutralized, while the user's original physical gather remains DOWN.
    engine.stickDownLatchedUntilNeutral_ = true;
    ControllerState down;
    down.rightStickY = 127;
    ControllerState neutral;

    ControllerState output = engine.process(down);
    QCOMPARE(output.rightStickY, 0);
    QVERIFY(engine.stickDownLatchedUntilNeutral_);

    // One/two neutral polls and a DOWN bounce are jitter, not a new gesture.
    output = engine.process(neutral);
    QCOMPARE(output.rightStickY, 0);
    QVERIFY(engine.stickDownLatchedUntilNeutral_);
    output = engine.process(neutral);
    QCOMPARE(output.rightStickY, 0);
    QVERIFY(engine.stickDownLatchedUntilNeutral_);
    output = engine.process(down);
    QCOMPARE(output.rightStickY, 0);
    QVERIFY(engine.stickDownLatchedUntilNeutral_);

    for (int i = 0; i < 3; ++i) {
        output = engine.process(neutral);
    }
    QVERIFY(!engine.stickDownLatchedUntilNeutral_);
    QCOMPARE(output.rightStickY, 0);

    // Only a fresh DOWN after the debounced neutral edge may start a new
    // trigger-neutral movement transaction.
    output = engine.process(down);
    QCOMPARE(output.rightStickY, 0);
    QCOMPARE(engine.shotsAttempted(), 0);
}

void AutomationEngineTests::autonomousVisionScheduleLeaseIsModeNeutral()
{
    for (const ShotMode mode : {ShotMode::ButtonShot, ShotMode::GoToStick,
                                ShotMode::TempoSquare, ShotMode::TempoStick}) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        engine.applyConfig(config, LearningData{});
        engine.shot_.state = HoldState::Holding;
        engine.shot_.mode = mode;
        engine.shot_.visionEpoch = 73;
        engine.schedFireDeadlineMs_ = engine.engineNowMs() + 4.0;
        engine.schedFireToken_ = 73 + static_cast<quint64>(mode);
        engine.schedFireRequiresGenuineFrame_ = true;
        engine.schedFireVisionEpoch_ = engine.shot_.visionEpoch;
        engine.schedFireAuthorityExpiryMs_ = engine.engineNowMs() + 10.0;

        QVERIFY2(engine.autonomousVisionScheduleLeaseCurrent(engine.engineNowMs() + 1.0),
                 qPrintable(QStringLiteral("mode=%1 lost a valid immutable meter lease")
                                .arg(static_cast<int>(mode))));
        const quint64 token = engine.scheduledFireToken();
        engine.invalidateVisionScheduleForDropout(engine.engineNowMs() + 1.0);
        QCOMPARE(engine.scheduledFireToken(), token);
        QVERIFY(engine.scheduledFireDeadlineMs() >= 0.0);

        engine.invalidateVisionScheduleForDropout(engine.engineNowMs() + 11.0);
        QCOMPARE(engine.scheduledFireDeadlineMs(), -1.0);
    }
}

void AutomationEngineTests::duplicateTelemetryFillsDoNotDepressVelocity()
{
    // T1 sampler dedupe: the ~60Hz telemetry thread re-serves each CV fill 2-3x at
    // different timestamps. Those identical-fill duplicates (~17ms apart) must NOT feed
    // the velocity fit — before the 20ms identical-fill dedupe they flattened the fitted
    // slope well below the true rise, depressing every predictive path.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);                 // -> Holding
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.advanceTestClock(160);             // past the 140ms standstill commit floor
    engine.process(physical);

    // A true 0.25%/ms rise delivered as CV frames every 40ms (+10%/frame).
    auto noGreen = [](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.velocityPctS = 0.0;
        r.greenStartPct = -1.0;
        r.greenEndPct = -1.0;
        r.greenCenterPct = -1.0;
        r.greenConfidence = 0.0;
        return r;
    };
    engine.updateDetection(noGreen(20.0));
    engine.process(physical);
    engine.advanceTestClock(40);
    engine.updateDetection(noGreen(30.0));
    engine.process(physical);
    engine.advanceTestClock(40);
    engine.updateDetection(noGreen(40.0));
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);   // out of reach -> still holding
    const double honest = engine.context().releaseVelocityPctMs;
    QVERIFY2(honest >= 0.20 && honest <= 0.30,
             qPrintable(QString("clean fit %1 must read the true ~0.25%/ms rise").arg(honest)));

    // The 60Hz telemetry re-serve: the SAME 40-fill again 17ms later (dt < 20ms,
    // identical fill). It must be DEDUPED — the recency-weighted fit would otherwise
    // read the flat duplicate tail and depress the velocity every predictive path
    // consumes (fails before the 5ms->20ms identical-fill dedupe widen).
    engine.advanceTestClock(17);
    engine.updateDetection(noGreen(40.0));   // duplicate telemetry re-serve
    engine.process(physical);
    const double afterDup = engine.context().releaseVelocityPctMs;
    QCOMPARE(afterDup, honest);              // sampler state unchanged -> identical fit
}

// Drive a fresh Square hold to the Holding state (shot 1). On shot 1 no clock is armed, so
// nothing fires on its own — the caller can feed samples and inspect ShotContext safely.
static void driveToHolding(AutomationEngine& engine, ControllerState& physical)
{
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
}

// A genuine-fresh detection with NO green window and a controllable velocity, so a fed series
// exercises the anchor/tip logic without a green-window release confounding the assertion.
static DetectionResult plainSample(double fillPct, double velocityPctS)
{
    DetectionResult r = readyMeterSample(fillPct, -1.0);
    r.velocityPctS = velocityPctS;
    r.greenStartPct = -1.0;
    r.greenEndPct = -1.0;
    r.greenCenterPct = -1.0;
    r.greenConfidence = 0.0;
    return r;
}

void AutomationEngineTests::feedforwardRequiresPositiveConfidentCurrentFill()
{
    // Establish a valid two-sample anchor, then let the learned clock mature on
    // either a zero-fill or below-threshold current frame. Both payloads are
    // unique/detected and used to pass the clock's "genuine frame" check.
    auto run = [](double dueFill, double dueConfidence) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.tempoFallbackTimeoutMs = 5000.0;
        config.maximumHoldMs = 5000.0;
        LearningData learning;
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
        engine.applyConfig(config, learning);

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        engine.process(physical);
        engine.advanceTestClock(220.0);
        engine.process(physical);

        DetectionResult anchor = readyMeterSample(30.0, -1.0);
        anchor.velocityPctS = 0.0;
        engine.updateDetection(anchor);
        engine.process(physical);
        engine.advanceTestClock(10.0);
        engine.updateDetection(anchor); // validates this shot's low-first anchor
        engine.process(physical);

        engine.advanceTestClock(300.0); // clock is now due
        DetectionResult due = readyMeterSample(dueFill, -1.0);
        due.velocityPctS = 0.0;
        due.confidence = dueConfidence;
        engine.updateDetection(due);
        engine.process(physical);
        return engine.context();
    };

    const ShotContext zero = run(0.0, 0.95);
    QCOMPARE(zero.releaseSeq, 0);
    QVERIFY2(zero.releaseReasonCode != QStringLiteral("feedforward_target"),
             "a detected zero-fill frame must not authorize a learned-clock release");

    const ShotContext lowConfidence = run(60.0, 0.05);
    QCOMPARE(lowConfidence.releaseSeq, 0);
    QVERIFY2(lowConfidence.releaseReasonCode != QStringLiteral("feedforward_target"),
             "a below-threshold candidate must not authorize any meter release");
}

void AutomationEngineTests::preciseFireAuthorityLeaseFailsClosed()
{
    const PreciseFireArmWindow live = PreciseFirePolicy::evaluate(110.0, 120.0, 100.0);
    QVERIFY(live.allowed);
    QVERIFY(live.finiteAuthority);
    QCOMPARE(live.delayMs, 10.0);
    QCOMPARE(live.authorityRemainingMs, 20.0);

    QVERIFY(!PreciseFirePolicy::evaluate(110.0, 100.0, 100.0).allowed);
    QVERIFY(!PreciseFirePolicy::evaluate(110.0, 99.0, 100.0).allowed);
    QVERIFY2(!PreciseFirePolicy::evaluate(121.0, 120.0, 100.0).allowed,
             "a tick nudge may not move the fire past its evidence lease");
    QVERIFY(!PreciseFirePolicy::evaluate(
        110.0, std::numeric_limits<double>::quiet_NaN(), 100.0).allowed);

    const PreciseFireArmWindow explicitUnbounded =
        PreciseFirePolicy::evaluate(110.0, -1.0, 100.0);
    QVERIFY(explicitUnbounded.allowed);
    QVERIFY(!explicitUnbounded.finiteAuthority);
}

void AutomationEngineTests::preciseFireAuthorityRefreshOnlyEverExtends()
{
    // [ORION_ROLLING_LEASE] arm() copied the meter-authority lease once and nothing updated it
    // again, so an armed token ran to its deadline on a lease frozen at arm time while the
    // engine's own copy kept rolling forward with each genuine frame. One dropped frame near the
    // deadline expired the stale copy and the worker silently declined to submit. This is the
    // decision that hands the rolling lease across; every property below is load-bearing.
    using P = PreciseFirePolicy;

    // The whole point: engine lease now runs to 160 while the token holds only 20ms more.
    const PreciseFireAuthorityRefresh grow =
        P::evaluateAuthorityRefresh(160.0, 100.0, 20.0, true, true);
    QVERIFY2(grow.extend, "a longer engine lease must reach an armed token");
    QCOMPARE(grow.remainingMs, 60.0);

    // MONOTONIC: a SHORTER engine lease must never shorten the token's. If this regressed, the
    // refresh could retire a token early -- i.e. manufacture the very abort it exists to prevent.
    QVERIFY2(!P::evaluateAuthorityRefresh(160.0, 100.0, 90.0, true, true).extend,
             "a shorter engine lease must never shorten an armed token's lease");
    QVERIFY2(!P::evaluateAuthorityRefresh(160.0, 100.0, 60.0, true, true).extend,
             "an equal lease is not an extension");

    // NEVER REVIVES: an already-expired engine lease is refused, not propagated. Otherwise stale
    // evidence could authorize a submit, which is exactly what the lease exists to forbid.
    QVERIFY2(!P::evaluateAuthorityRefresh(100.0, 100.0, 5.0, true, true).extend,
             "an engine lease expiring exactly now must not extend anything");
    QVERIFY2(!P::evaluateAuthorityRefresh(90.0, 100.0, 5.0, true, true).extend,
             "an expired engine lease must never resurrect a token's authority");

    // NEVER UNBOUNDS: the negative sentinel means "no finite authority". An armed token must not
    // be promoted onto unbounded evidence by a later tick.
    QVERIFY2(!P::evaluateAuthorityRefresh(-1.0, 100.0, 5.0, true, true).extend,
             "the unbounded sentinel must not launder an armed token's finite lease");
    // ...and a token already unbounded (+inf) can never be shortened onto a finite one.
    QVERIFY2(!P::evaluateAuthorityRefresh(
                 160.0, 100.0, std::numeric_limits<double>::infinity(), true, true).extend,
             "an unbounded token lease must never be reduced to a finite one");

    // TOKEN-SCOPED and ARM-SCOPED: a lease may never leak onto a different or unarmed token.
    QVERIFY2(!P::evaluateAuthorityRefresh(160.0, 100.0, 20.0, true, false).extend,
             "a lease must never leak across tokens");
    QVERIFY2(!P::evaluateAuthorityRefresh(160.0, 100.0, 20.0, false, true).extend,
             "an unarmed token must never be granted authority");

    // Non-finite inputs fail safe rather than propagating a garbage lease.
    const double nan = std::numeric_limits<double>::quiet_NaN();
    QVERIFY(!P::evaluateAuthorityRefresh(nan, 100.0, 20.0, true, true).extend);
    QVERIFY(!P::evaluateAuthorityRefresh(160.0, nan, 20.0, true, true).extend);
    QVERIFY2(!P::evaluateAuthorityRefresh(160.0, 100.0, nan, true, true).extend,
             "an unreadable current lease must not be overwritten");
}

void AutomationEngineTests::preciseFireDeliveryRequiresAcceptedAuthorizedRoute()
{
    using Write = InputRouteWriteResult;

    // Only exact local UDP acceptance owns the PS5 route and may confirm the deadline.
    // This is still not a console/game acknowledgement.
    // The desktop target is neutral in this mode, so its result is irrelevant.
    PreciseFireDeliveryDecision delivery =
        PreciseFirePolicy::evaluateDelivery(Write::LocalUdpAccepted, true, false);
    QVERIFY(delivery.pipeAccepted);
    QVERIFY(!delivery.virtualFallbackAccepted);
    QVERIFY(delivery.confirmScheduledFire);
    QVERIFY(!delivery.controllerFault);
    QCOMPARE(delivery.stage, PreciseFireDeliveryStage::LocalUdpAccepted);

    delivery = PreciseFirePolicy::evaluateDelivery(Write::LocalUdpAccepted, true, true);
    QVERIFY(delivery.pipeAccepted);
    QVERIFY(!delivery.virtualFallbackAccepted);
    QVERIFY(delivery.confirmScheduledFire);
    QCOMPARE(delivery.stage, PreciseFireDeliveryStage::LocalUdpAccepted);

    delivery = PreciseFirePolicy::evaluateDelivery(Write::Written, true, true);
    QVERIFY(!delivery.pipeAccepted);
    QVERIFY(!delivery.virtualFallbackAccepted);
    QVERIFY(!delivery.confirmScheduledFire);
    QCOMPARE(delivery.stage, PreciseFireDeliveryStage::None);

    // Once bytes may have reached Chiaki, a missing ACK is ambiguous. ViGEm must remain
    // suppressed while the direct session is terminated; racing both routes is unsafe.
    delivery = PreciseFirePolicy::evaluateDelivery(Write::WrittenUnconfirmed, true, true);
    QVERIFY(!delivery.pipeAccepted);
    QVERIFY(!delivery.virtualFallbackAccepted);
    QVERIFY(!delivery.confirmScheduledFire);
    QVERIFY(delivery.controllerFault);
    QCOMPARE(delivery.stage, PreciseFireDeliveryStage::None);

    // An already-latched release state is not evidence that this fire token
    // produced its hold->release edge at the scheduled deadline. Likewise, a
    // successful neutral ViGEm submit cannot rescue the active direct route.
    delivery = PreciseFirePolicy::evaluateDelivery(Write::Unchanged, true, true);
    QVERIFY(!delivery.pipeAccepted);
    QVERIFY(!delivery.virtualFallbackAccepted);
    QVERIFY(!delivery.confirmScheduledFire);
    QVERIFY(delivery.controllerFault);

    delivery = PreciseFirePolicy::evaluateDelivery(Write::Failed, true, true);
    QVERIFY(!delivery.pipeAccepted);
    QVERIFY(!delivery.virtualFallbackAccepted);
    QVERIFY(!delivery.confirmScheduledFire);
    QVERIFY(delivery.controllerFault);

    // When the direct route does not own input, releaseOutput is carried by
    // ViGEm instead. Only an accepted active-fallback submit may confirm it.
    delivery = PreciseFirePolicy::evaluateDelivery(Write::Failed, false, true);
    QVERIFY(!delivery.pipeAccepted);
    QVERIFY(delivery.virtualFallbackAccepted);
    QVERIFY(delivery.confirmScheduledFire);
    QVERIFY(!delivery.controllerFault);
    QCOMPARE(delivery.stage, PreciseFireDeliveryStage::ActiveVigemSubmit);

    delivery = PreciseFirePolicy::evaluateDelivery(Write::Failed, false, false);
    QVERIFY(!delivery.pipeAccepted);
    QVERIFY(!delivery.virtualFallbackAccepted);
    QVERIFY(!delivery.confirmScheduledFire);
    QVERIFY(delivery.controllerFault);

    // Recovery needs both a proved active route and three physically neutral
    // polls. A connected handle, a held shot gesture, or two neutral polls must
    // not reset the engine and re-arm the same physical hold.
    QVERIFY(PreciseFirePolicy::routeRecoveryReady(true, true, 3));
    QVERIFY(PreciseFirePolicy::routeRecoveryReady(true, true, 4));
    QVERIFY(!PreciseFirePolicy::routeRecoveryReady(false, true, 3));
    QVERIFY(!PreciseFirePolicy::routeRecoveryReady(true, false, 3));
    QVERIFY(!PreciseFirePolicy::routeRecoveryReady(true, true, 2));
    QVERIFY(!PreciseFirePolicy::routeRecoveryReady(true, true, 3, 0));

    ControllerState neutral;
    QVERIFY(PreciseFirePolicy::controllerStateFullyNeutral(neutral));
    QVERIFY(PreciseFirePolicy::latencyRouteAttestationEligible(
        true, true, true, true, neutral, neutral));
    for (int field = 0; field < 6; ++field) {
        ControllerState active;
        switch (field) {
        case 0: active.buttons = XINPUT_GAMEPAD_A; break;
        case 1: active.dpad = 0; break;
        case 2: active.leftStickX = 1; break;
        case 3: active.rightStickY = -1; break;
        case 4: active.l2 = 1; break;
        case 5: active.touchpad = true; break;
        }
        QVERIFY(!PreciseFirePolicy::controllerStateFullyNeutral(active));
        QVERIFY(!PreciseFirePolicy::latencyRouteAttestationEligible(
            true, true, true, true, active, neutral));
    }
    QVERIFY(!PreciseFirePolicy::latencyRouteAttestationEligible(
        false, true, true, true, neutral, neutral));
    QVERIFY(!PreciseFirePolicy::latencyRouteAttestationEligible(
        true, true, true, false, neutral, neutral));
}

void AutomationEngineTests::preciseFireRouteBindingRejectsBothRouteTransitions()
{
    using Route = LatencyControllerRoute;
    using Write = InputRouteWriteResult;

    QCOMPARE(PreciseFirePolicy::liveControllerRoute(
                 true, true, true, true, false), Route::Pipe);
    QCOMPARE(PreciseFirePolicy::liveControllerRoute(
                 true, true, false, true, false), Route::VigemXusb);
    QCOMPARE(PreciseFirePolicy::liveControllerRoute(
                 true, false, false, true, true), Route::VigemDs4);
    QCOMPARE(PreciseFirePolicy::liveControllerRoute(
                 false, true, true, true, false), Route::None);

    const PreciseFireRouteBinding pipe{701, Route::Pipe};
    QVERIFY(PreciseFirePolicy::routeBindingMatches(
        pipe, Route::Pipe, 701, Route::Pipe));
    QVERIFY2(!PreciseFirePolicy::routeBindingMatches(
                 pipe, Route::VigemXusb, 701, Route::Pipe),
             "Pipe -> ViGEm must revoke the token");
    QVERIFY(!PreciseFirePolicy::routeBindingMatches(
        pipe, Route::Pipe, 702, Route::Pipe));

    const PreciseFireRouteBinding vigem{801, Route::VigemXusb};
    QVERIFY(PreciseFirePolicy::routeBindingMatches(
        vigem, Route::VigemXusb, 801, Route::VigemXusb));
    QVERIFY2(!PreciseFirePolicy::routeBindingMatches(
                 vigem, Route::Pipe, 801, Route::VigemXusb),
             "ViGEm -> Pipe must revoke the token");

    // A successful alternate route can never rescue a bound token.
    auto delivery = PreciseFirePolicy::evaluateBoundDelivery(
        Write::Failed, true, Route::Pipe);
    QVERIFY(!delivery.confirmScheduledFire);
    QCOMPARE(delivery.stage, PreciseFireDeliveryStage::None);
    delivery = PreciseFirePolicy::evaluateBoundDelivery(
        Write::LocalUdpAccepted, false, Route::VigemXusb);
    QVERIFY(!delivery.confirmScheduledFire);
    QCOMPARE(delivery.stage, PreciseFireDeliveryStage::None);

    const auto verifyEngineTransition = [](Route from, Route to, quint64 generation) {
        AutomationEngine engine;
        engine.config_.subTickScheduler = true;
        engine.config_.noMeterEnabled = true;
        engine.config_.noMeterPushReleaseWindowMs = 200.0;
        engine.shot_.armToken = generation + 10;
        engine.shot_.physicalShotEpoch = generation + 20;
        const double now = engine.engineNowMs();
        engine.pose_.lastLandmarkFreshAccept = true;
        engine.pose_.lastLandmarkArrivalMs = now;
        engine.pose_.acceptedArmToken = engine.shot_.armToken;
        engine.pose_.authorityEpoch = 1;
        engine.setControllerDeliveryRouteAttestation(generation, from);
        QVERIFY(engine.scheduleFire(
            now + 5.0, now, 20.0,
            AutomationEngine::ScheduledFireAuthority::Pose));
        QCOMPARE(engine.scheduledFireRouteGeneration(), generation);
        QCOMPARE(engine.scheduledFireRoute(), from);

        QSignalSpy invalidated(&engine, &AutomationEngine::visionScheduleInvalidating);
        engine.setControllerDeliveryRouteAttestation(generation + 1, to);
        QCOMPARE(invalidated.count(), 1);
        QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
        QCOMPARE(engine.scheduledFireRouteGeneration(), quint64{0});
        QCOMPARE(engine.scheduledFireRoute(), Route::None);
    };
    verifyEngineTransition(Route::Pipe, Route::VigemXusb, 901);
    verifyEngineTransition(Route::VigemXusb, Route::Pipe, 1001);

    const auto verifyImmediateTransition = [](Route from, Route to,
                                               quint64 generation) {
        AutomationEngine engine;
        engine.config_.autonomousVision = true;
        engine.config_.noMeterEnabled = false;
        engine.setControllerRouteBindingRequired(true);
        engine.config_.confidenceGate = 0.5;
        engine.config_.strictReleaseMaxSourceAgeMs = 50.0;
        const double now = engine.engineNowMs();
        engine.shot_.state = HoldState::Holding;
        engine.shot_.lastSampleGenuineAccept = true;
        engine.shot_.lastFreshAcceptMs = now;
        engine.shot_.frameAgeMs = 0.0;
        engine.shot_.fillPct = 92.0;
        engine.shot_.confidence = 1.0;
        engine.shot_.releaseReasonCode = QStringLiteral("predictive_target");
        engine.setControllerDeliveryRouteAttestation(generation, from);

        QVERIFY(engine.triggerRelease(now));
        QCOMPARE(engine.context().releaseScheduleToken, quint64{0});
        QCOMPARE(engine.context().releaseScheduleRouteGeneration, generation);
        QCOMPARE(engine.context().releaseScheduleRoute, from);

        const PreciseFireRouteBinding binding{
            engine.context().releaseScheduleRouteGeneration,
            engine.context().releaseScheduleRoute};
        engine.setControllerDeliveryRouteAttestation(generation + 1, to);
        QVERIFY(!engine.controllerDeliveryRouteAttestationExpected(
            binding.generation, binding.route));
        QVERIFY(!PreciseFirePolicy::routeBindingMatches(
            binding, to, generation + 1, to));
    };
    verifyImmediateTransition(Route::Pipe, Route::VigemXusb, 1201);
    verifyImmediateTransition(Route::VigemXusb, Route::Pipe, 1301);

    // Autonomous timing may not emit an unbound immediate release. Without an
    // exact controller route there is no trustworthy delivery delay to subtract.
    {
        AutomationEngine unattested;
        unattested.config_.autonomousVision = true;
        unattested.config_.noMeterEnabled = false;
        unattested.setControllerRouteBindingRequired(true);
        unattested.config_.confidenceGate = 0.5;
        unattested.config_.strictReleaseMaxSourceAgeMs = 50.0;
        const double now = unattested.engineNowMs();
        unattested.shot_.state = HoldState::Holding;
        unattested.shot_.lastSampleGenuineAccept = true;
        unattested.shot_.lastFreshAcceptMs = now;
        unattested.shot_.frameAgeMs = 0.0;
        unattested.shot_.fillPct = 92.0;
        unattested.shot_.confidence = 1.0;
        unattested.shot_.releaseReasonCode = QStringLiteral("predictive_target");
        QVERIFY(!unattested.triggerRelease(now));
        QCOMPARE(unattested.context().releaseReasonCode,
                 QStringLiteral("controller_route_unattested_abort"));
        QCOMPARE(unattested.context().releaseSeq, 0);
    }

    // Exercise the publication race directly. A reader may fail closed while a
    // writer owns the seqlock, but it may never observe generation from one
    // attestation combined with the route from the other.
    AutomationEngine concurrent;
    concurrent.setControllerDeliveryRouteAttestation(1101, Route::Pipe);
    std::atomic<bool> start{false};
    std::atomic<bool> done{false};
    std::thread writer([&] {
        while (!start.load(std::memory_order_acquire)) {
            std::this_thread::yield();
        }
        for (int i = 0; i < 100'000; ++i) {
            if ((i & 1) == 0) {
                concurrent.setControllerDeliveryRouteAttestation(
                    1102, Route::VigemXusb);
            } else {
                concurrent.setControllerDeliveryRouteAttestation(
                    1101, Route::Pipe);
            }
        }
        done.store(true, std::memory_order_release);
    });
    start.store(true, std::memory_order_release);
    bool torn = false;
    int observations = 0;
    while (!done.load(std::memory_order_acquire) || observations < 10'000) {
        const auto snapshot =
            concurrent.controllerDeliveryRouteAttestationSnapshot();
        const bool empty = snapshot.generation == 0 && snapshot.route == Route::None;
        const bool pipePair = snapshot.generation == 1101
            && snapshot.route == Route::Pipe;
        const bool vigemPair = snapshot.generation == 1102
            && snapshot.route == Route::VigemXusb;
        if (!empty && !pipePair && !vigemPair) {
            torn = true;
            break;
        }
        ++observations;
    }
    writer.join();
    QVERIFY2(!torn, "controller route attestation publication must be atomic as a pair");
    QVERIFY(observations > 0);
}

void AutomationEngineTests::ownedAutomationDisarmDrainsEveryModeWithoutDuplicateRearm()
{
    quint64 epoch = 12'700;
    for (const ShotMode mode : {ShotMode::ButtonShot, ShotMode::TempoSquare,
                                ShotMode::GoToStick, ShotMode::TempoStick}) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.minimumHoldMs = 0.0;
        config.tempoRemapEnabled = mode == ShotMode::TempoSquare;
        engine.applyConfig(config, LearningData{});

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_A;
        physical.dpad = 0x04;
        if (mode == ShotMode::ButtonShot || mode == ShotMode::TempoSquare) {
            physical.buttons |= XINPUT_GAMEPAD_X;
        } else {
            physical.rightStickY = mode == ShotMode::GoToStick ? -127 : 127;
        }
        engine.setPhysicalShotEpoch(epoch++);
        engine.lastPhysical_ = physical;
        engine.beginShot(mode, engine.engineNowMs(),
                         mode == ShotMode::GoToStick
                             ? QStringLiteral("Go-To")
                             : QStringLiteral("Standstill"));
        const int attempts = engine.shotsAttempted();
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy marker(&engine, &AutomationEngine::releaseMarker);

        // Model a short route flap entirely between controller polls. The
        // revocation generation must still consume the old ownership even though
        // the route appears armed again by the time process() runs.
        engine.setArmed(false);
        engine.setArmed(true);
        ControllerState out = engine.process(physical);
        QCOMPARE(engine.context().state, HoldState::Idle);
        QCOMPARE(engine.context().releaseReasonCode,
                 QStringLiteral("automation_disarmed_abort"));
        QCOMPARE(engine.ownedOutputDrain_,
                 AutomationEngine::OwnedOutputDrain::HoldUntilPhysicalEnd);
        QCOMPARE(aborted.count(), 1);
        QCOMPARE(marker.count(), 0);
        QCOMPARE(engine.shotsAttempted(), attempts);
        QVERIFY((out.buttons & XINPUT_GAMEPAD_A) != 0);
        QCOMPARE(out.dpad, 0x04);
        switch (mode) {
        case ShotMode::ButtonShot:
            QVERIFY(out.square());
            QCOMPARE(out.rightStickY, 0);
            break;
        case ShotMode::GoToStick:
            QVERIFY(!out.square());
            QCOMPARE(out.rightStickY, -127);
            break;
        case ShotMode::TempoSquare:
            QVERIFY(!out.square());
            QCOMPARE(out.rightStickY, 127);
            break;
        case ShotMode::TempoStick:
            QVERIFY(!out.square());
            QCOMPARE(out.rightStickY, 127);
            break;
        }

        // Re-arming while the same gesture is still held cannot create another
        // attempt or release edge. Only three physical end samples close it.
        for (int held = 0; held < 3; ++held) {
            out = engine.process(physical);
            QCOMPARE(engine.shotsAttempted(), attempts);
            QCOMPARE(aborted.count(), 1);
            QCOMPARE(marker.count(), 0);
        }
        ControllerState ended;
        ended.buttons |= XINPUT_GAMEPAD_A;
        ended.dpad = 0x04;
        for (int sample = 0; sample < 3; ++sample) {
            out = engine.process(ended);
            QCOMPARE(engine.shotsAttempted(), attempts);
            QCOMPARE(marker.count(), 0);
            if (sample < 2) {
                if (mode == ShotMode::ButtonShot) {
                    QVERIFY(out.square());
                } else {
                    QCOMPARE(out.rightStickY,
                             mode == ShotMode::GoToStick ? -127 : 127);
                }
            }
        }
        QCOMPARE(engine.ownedOutputDrain_, AutomationEngine::OwnedOutputDrain::None);
        QVERIFY(!out.square());
        QCOMPARE(out.rightStickY, mode == ShotMode::TempoSquare ? -127 : 0);
        QCOMPARE(aborted.count(), 1);
    }
}

void AutomationEngineTests::preciseFireDeliveryFailureDrainsEveryModeWithoutFabricatedRelease()
{
    quint64 epoch = 12'800;
    for (const ShotMode mode : {ShotMode::ButtonShot, ShotMode::TempoSquare,
                                ShotMode::GoToStick, ShotMode::TempoStick}) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.minimumHoldMs = 0.0;
        config.tempoRemapEnabled = mode == ShotMode::TempoSquare;
        engine.applyConfig(config, LearningData{});

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_A;
        physical.dpad = 0x04;
        if (mode == ShotMode::ButtonShot || mode == ShotMode::TempoSquare) {
            physical.buttons |= XINPUT_GAMEPAD_X;
        } else {
            physical.rightStickY = mode == ShotMode::GoToStick ? -127 : 127;
        }
        engine.setPhysicalShotEpoch(epoch++);
        engine.lastPhysical_ = physical;
        engine.beginShot(mode, engine.engineNowMs(),
                         mode == ShotMode::GoToStick
                             ? QStringLiteral("Go-To")
                             : QStringLiteral("Standstill"));
        engine.schedFireDeadlineMs_ = engine.engineNowMs() + 1.0;
        engine.schedFireToken_ = 700 + static_cast<quint64>(mode);
        engine.schedFirePlan_ = QStringLiteral("Live meter tip");
        engine.schedFireReason_ = QStringLiteral("live_meter_tip");
        engine.schedFireCode_ = QStringLiteral("live_meter_tip");
        engine.schedFirePhysicalShotEpoch_ = engine.context().physicalShotEpoch;
        engine.schedFireShotAttempt_ = engine.context().armToken;
        const quint64 token = engine.scheduledFireToken();
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy marker(&engine, &AutomationEngine::releaseMarker);
        connect(&engine, &AutomationEngine::scheduledFireFallbackInvalidating,
                &engine, [&engine, token](quint64 fencedToken) {
                    if (fencedToken == token) {
                        // The worker may have written bytes but could not prove
                        // exact local acceptance. Mirror the controller fault gate.
                        engine.rejectScheduledFire(token);
                        engine.setArmed(false);
                    }
                }, Qt::DirectConnection);

        ControllerState out = physical;
        QVERIFY(engine.consumeDueScheduledFire(
            out, engine.scheduledFireDeadlineMs()
                     + engine.config().schedulerGraceMs + 1.0));
        QCOMPARE(engine.context().state, HoldState::Idle);
        QCOMPARE(engine.context().releaseReasonCode,
                 QStringLiteral("precise_fire_delivery_failed"));
        QCOMPARE(engine.ownedOutputDrain_,
                 AutomationEngine::OwnedOutputDrain::ReleasedUntilPhysicalEnd);
        QCOMPARE(aborted.count(), 1);
        QCOMPARE(marker.count(), 0);
        QCOMPARE(engine.context().releaseSeq, 0);
        QVERIFY(!out.square());
        QCOMPARE(out.rightStickX, 0);
        QCOMPARE(out.rightStickY, 0);
        QVERIFY((out.buttons & XINPUT_GAMEPAD_A) != 0);
        QCOMPARE(out.dpad, 0x04);

        // A replacement route may become healthy before the user lets go. The
        // ambiguous old transaction still wins fail-closed and cannot be raced
        // by a held packet or a fabricated release marker.
        engine.setArmed(true);
        for (int held = 0; held < 3; ++held) {
            out = engine.process(physical);
            QVERIFY(!out.square());
            QCOMPARE(out.rightStickY, 0);
            QCOMPARE(aborted.count(), 1);
            QCOMPARE(marker.count(), 0);
        }
        ControllerState ended;
        ended.buttons |= XINPUT_GAMEPAD_A;
        ended.dpad = 0x04;
        for (int sample = 0; sample < 3; ++sample) {
            out = engine.process(ended);
            QVERIFY(!out.square());
            QCOMPARE(out.rightStickY, 0);
        }
        QCOMPARE(engine.ownedOutputDrain_, AutomationEngine::OwnedOutputDrain::None);
        QCOMPARE(aborted.count(), 1);
        QCOMPARE(marker.count(), 0);
    }
}

void AutomationEngineTests::routeRecoveryRequiresTruePhysicalEndForEveryMode()
{
    constexpr double upThreshold = 72.0;
    constexpr double downThreshold = 72.0;
    auto neutral = [&](const ControllerState& state) {
        return routeRecoveryShotInputsNeutral(
            state, upThreshold, downThreshold);
    };

    ControllerState centered;
    QVERIFY(neutral(centered));
    ControllerState restingDrift;
    restingDrift.rightStickX = 20;
    restingDrift.rightStickY = -20;
    QVERIFY(neutral(restingDrift));

    // This was the production hole: RS-Y looked neutral while the stick was
    // fully sideways. It must not contribute a recovery sample.
    ControllerState sideways;
    sideways.rightStickX = 127;
    QVERIFY(!neutral(sideways));

    auto activeFor = [](ShotMode mode) {
        ControllerState state;
        if (mode == ShotMode::ButtonShot || mode == ShotMode::TempoSquare) {
            state.buttons |= XINPUT_GAMEPAD_X;
        } else {
            state.rightStickY = mode == ShotMode::GoToStick ? -127 : 127;
        }
        return state;
    };
    for (const ShotMode mode : {ShotMode::ButtonShot, ShotMode::TempoSquare,
                                ShotMode::GoToStick, ShotMode::TempoStick}) {
        const ControllerState active = activeFor(mode);
        QVERIFY(!neutral(active));
        int neutralFrames = 0;
        auto observe = [&](const ControllerState& state) {
            const bool isNeutral = neutral(state);
            neutralFrames = isNeutral ? std::min(3, neutralFrames + 1) : 0;
            return PreciseFirePolicy::routeRecoveryReady(
                true, isNeutral, neutralFrames);
        };
        QVERIFY(!observe(active));
        QVERIFY(!observe(centered));
        QVERIFY(!observe(centered));
        QVERIFY(!observe(sideways));
        QCOMPARE(neutralFrames, 0);
        QVERIFY(!observe(centered));
        QVERIFY(!observe(centered));
        QVERIFY(observe(centered));
        QVERIFY(!PreciseFirePolicy::routeRecoveryReady(
            false, true, neutralFrames));
    }
}

void AutomationEngineTests::disarmedReleaseDrainConsumesPhysicalEndDuringPulse()
{
    quint64 epoch = 13'100;
    for (const ShotMode mode : {ShotMode::ButtonShot, ShotMode::TempoSquare,
                                ShotMode::GoToStick, ShotMode::TempoStick}) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = false;
        config.tempoRemapEnabled = mode == ShotMode::TempoSquare;
        engine.applyConfig(config, LearningData{});

        ControllerState active;
        if (mode == ShotMode::ButtonShot || mode == ShotMode::TempoSquare) {
            active.buttons |= XINPUT_GAMEPAD_X;
        } else {
            active.rightStickY = mode == ShotMode::GoToStick ? -127 : 127;
        }
        engine.setPhysicalShotEpoch(epoch++);
        engine.lastPhysical_ = active;
        engine.beginShot(mode, engine.engineNowMs(),
                         mode == ShotMode::GoToStick
                             ? QStringLiteral("Go-To")
                             : QStringLiteral("Standstill"));
        const int attemptsBeforeRecovery = engine.shotsAttempted();
        engine.shot_.state = HoldState::Releasing;
        engine.shot_.releaseTriggerMs = engine.engineNowMs();

        engine.setArmed(false);
        ControllerState ended;
        for (int sample = 0; sample < 3; ++sample) {
            engine.process(ended);
        }
        QCOMPARE(engine.context().state, HoldState::Releasing);
        QCOMPARE(engine.ownedOutputDrain_, AutomationEngine::OwnedOutputDrain::None);

        // A fourth disabled poll used to re-latch ReleasedUntilPhysicalEnd
        // immediately after the third poll cleared it.
        engine.process(ended);
        QCOMPARE(engine.ownedOutputDrain_, AutomationEngine::OwnedOutputDrain::None);

        engine.advanceTestClock(std::max(engine.config().tempoFlickHoldMs,
                                         engine.config().releasePulseMs) + 1.0);
        engine.process(ended);
        QCOMPARE(engine.context().state, HoldState::Cooldown);
        QCOMPARE(engine.ownedOutputDrain_, AutomationEngine::OwnedOutputDrain::None);
        engine.advanceTestClock(std::max(engine.config().gotoCooldownMs,
                                         engine.config().cooldownMs) + 1.0);
        engine.process(ended);
        QCOMPARE(engine.context().state, HoldState::Idle);
        QCOMPARE(engine.ownedOutputDrain_, AutomationEngine::OwnedOutputDrain::None);
        QVERIFY(!engine.squareRearmBlockedUntilRelease_);
        QVERIFY(!engine.stickRearmBlockedUntilNeutral_);

        // Recovery must not sacrifice the first fresh gesture. Use the public
        // idle gate (not beginShot directly) so stale hold timers/latches are
        // covered for all four input representations.
        engine.setArmed(true);
        engine.setPhysicalShotEpoch(epoch++);
        ControllerState out = engine.process(active);
        const RemapConfig recovered = engine.config();
        if (mode == ShotMode::ButtonShot || mode == ShotMode::TempoSquare) {
            engine.advanceTestClock(recovered.squareHoldArmMs + 1.0);
        } else if (mode == ShotMode::GoToStick) {
            engine.advanceTestClock(recovered.gotoHoldArmMs + 1.0);
        } else {
            engine.advanceTestClock(
                std::max(recovered.stickHoldArmMs,
                         recovered.tempoMinStickHoldMs) + 1.0);
        }
        out = engine.process(active);
        QCOMPARE(engine.context().mode, mode);
        QVERIFY(engine.context().state == HoldState::Holding
                || engine.context().state == HoldState::Armed);
        QCOMPARE(engine.shotsAttempted(), attemptsBeforeRecovery + 1);
        if (mode == ShotMode::ButtonShot) {
            QVERIFY(out.square());
        } else {
            QVERIFY(!out.square());
            QCOMPARE(out.rightStickY,
                     mode == ShotMode::GoToStick ? -127 : 127);
        }
    }
}

void AutomationEngineTests::routeDisableAfterConfirmedFireNeverReassertsHeldOutput()
{
    for (const ShotMode mode : {ShotMode::ButtonShot, ShotMode::TempoSquare,
                                ShotMode::GoToStick, ShotMode::TempoStick}) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.minimumHoldMs = 0.0;
        config.tempoRemapEnabled = mode == ShotMode::TempoSquare;
        engine.applyConfig(config, LearningData{});

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_A;
        if (mode == ShotMode::ButtonShot || mode == ShotMode::TempoSquare) {
            physical.buttons |= XINPUT_GAMEPAD_X;
        } else {
            physical.rightStickY = mode == ShotMode::GoToStick ? -127 : 127;
        }
        physical.dpad = 0x04;
        engine.setPhysicalShotEpoch(13'000 + static_cast<quint64>(mode));
        engine.lastPhysical_ = physical;
        engine.beginShot(mode, engine.engineNowMs(),
                         mode == ShotMode::GoToStick
                             ? QStringLiteral("Go-To")
                             : QStringLiteral("Standstill"));
        engine.schedFireDeadlineMs_ = engine.engineNowMs() + 4.0;
        engine.schedFireToken_ = 501 + static_cast<quint64>(mode);
        engine.schedFirePlan_ = QStringLiteral("Live meter tip");
        engine.schedFireReason_ = QStringLiteral("live_meter_tip");
        engine.schedFireCode_ = QStringLiteral("live_meter_tip");
        engine.schedFirePhysicalShotEpoch_ = engine.context().physicalShotEpoch;
        engine.schedFireShotAttempt_ = engine.context().armToken;
        const quint64 token = engine.scheduledFireToken();
        QSignalSpy marker(&engine, &AutomationEngine::releaseMarker);
        connect(&engine, &AutomationEngine::visionScheduleInvalidating,
                &engine, [&engine, token](quint64 fencedToken) {
                    if (fencedToken == token) {
                        engine.confirmScheduledFire(token, engine.engineNowMs());
                    }
                }, Qt::DirectConnection);

        AppConfigData disabled = config;
        disabled.remotePlayInputSource = QStringLiteral("off");
        engine.applyConfig(disabled, LearningData{});
        QCOMPARE(marker.count(), 1);
        QCOMPARE(engine.context().state, HoldState::Releasing);
        QCOMPARE(engine.ownedOutputDrain_,
                 AutomationEngine::OwnedOutputDrain::ReleasedUntilPhysicalEnd);

        ControllerState out = engine.process(physical);
        QVERIFY(!out.square());
        // [ORION_GOTO_DOWN_FLICK] Each mode holds ITS OWN release edge after the route is
        // disabled — tempo the up flick, Go-To the mirrored down flick, ButtonShot neutral.
        // The property under test is unchanged: the GATHER must never be re-asserted.
        QCOMPARE(out.rightStickY,
                 mode == ShotMode::TempoSquare || mode == ShotMode::TempoStick ? -127
                     : mode == ShotMode::GoToStick                             ? 127
                                                                               : 0);
        QVERIFY((out.buttons & XINPUT_GAMEPAD_A) != 0);
        QCOMPARE(out.dpad, 0x04);

        engine.advanceTestClock(std::max(engine.config().tempoFlickHoldMs,
                                         engine.config().releasePulseMs) + 1.0);
        out = engine.process(physical);
        QVERIFY(!out.square());
        QCOMPARE(out.rightStickY, 0);
        engine.advanceTestClock(std::max(engine.config().cooldownMs,
                                         engine.config().gotoCooldownMs) + 1.0);
        out = engine.process(physical);
        QVERIFY(!out.square());
        out = engine.process(physical);
        // Once ShotContext resets to Idle, the independent release drain must
        // not reassert any of the four held physical shot representations.
        QVERIFY(!out.square());
        QCOMPARE(out.rightStickY, 0);
        QCOMPARE(marker.count(), 1);

        ControllerState ended;
        ended.buttons |= XINPUT_GAMEPAD_A;
        ended.dpad = 0x04;
        for (int sample = 0; sample < 3; ++sample) {
            out = engine.process(ended);
            QVERIFY(!out.square());
            QCOMPARE(out.rightStickY, 0);
        }
        QCOMPARE(engine.ownedOutputDrain_, AutomationEngine::OwnedOutputDrain::None);
        QCOMPARE(marker.count(), 1);
    }
}

void AutomationEngineTests::productionConfigRepairsNoMeterAuthority()
{
#ifdef ORION_PRODUCTION_BUILD
    // This test drives AppConfig through a QTemporaryDir root. In a production build
    // AppConfig::settingsPath() resolves through orionDataDir(), which returns the per-user
    // %LOCALAPPDATA% data dir and IGNORES rootDir (OrionPaths.h) — deliberately, because a
    // production install lives in Program Files where a normal user cannot write. So the
    // temp settings.json is never read, load() returns false, and the test is asserting a
    // dev-build path contract. Skipping is correct; pointing it at the real data dir would
    // make the suite write to the user's live configuration.
    QSKIP("settings path redirects to the per-user data dir in production builds");
#endif
    QTemporaryDir dir;
    QVERIFY(dir.isValid());
    QFile settings(dir.path() + QStringLiteral("/settings.json"));
    QVERIFY(settings.open(QIODevice::WriteOnly));
    const QJsonObject legacy{
        {QStringLiteral("meter_enabled"), true},
        {QStringLiteral("no_meter_enabled"), true},
        {QStringLiteral("no_meter"), QJsonObject{{QStringLiteral("enabled"), true}}}
    };
    settings.write(QJsonDocument(legacy).toJson());
    settings.close();

    AppConfig cfg(dir.path());
    QVERIFY(cfg.load());
    QVERIFY(cfg.data().meterEnabled);
    QVERIFY(!cfg.data().noMeterEnabled);

    // Public save is also a trusted boundary: even a contradictory caller is
    // serialized and retained in memory as meter-only production policy.
    AppConfigData contradictory = cfg.data();
    contradictory.meterEnabled = false;
    contradictory.noMeterEnabled = true;
    QVERIFY(cfg.save(contradictory));
    QVERIFY(cfg.data().meterEnabled);
    QVERIFY(!cfg.data().noMeterEnabled);
    QFile saved(dir.path() + QStringLiteral("/settings.json"));
    QVERIFY(saved.open(QIODevice::ReadOnly));
    const QJsonObject persisted = QJsonDocument::fromJson(saved.readAll()).object();
    QCOMPARE(persisted.value(QStringLiteral("meter_enabled")).toBool(false), true);
    QCOMPARE(persisted.value(QStringLiteral("no_meter_enabled")).toBool(true), false);
    QCOMPARE(persisted.value(QStringLiteral("no_meter")).toObject()
                 .value(QStringLiteral("enabled")).toBool(true), false);

    AutomationEngine engine;
    engine.applyConfig(contradictory, LearningData{});
    QVERIFY(!engine.config().noMeterEnabled);
}

void AutomationEngineTests::productionConfigPreservesExplicitInputSourceModes()
{
#ifdef ORION_PRODUCTION_BUILD
    // This test drives AppConfig through a QTemporaryDir root. In a production build
    // AppConfig::settingsPath() resolves through orionDataDir(), which returns the per-user
    // %LOCALAPPDATA% data dir and IGNORES rootDir (OrionPaths.h) — deliberately, because a
    // production install lives in Program Files where a normal user cannot write. So the
    // temp settings.json is never read, load() returns false, and the test is asserting a
    // dev-build path contract. Skipping is correct; pointing it at the real data dir would
    // make the suite write to the user's live configuration.
    QSKIP("settings path redirects to the per-user data dir in production builds");
#endif
    AppConfigData defaults;
    QCOMPARE(defaults.remotePlayInputSource, QStringLiteral("square"));
    QCOMPARE(normalizedRemotePlayInputSource(QStringLiteral("button")),
             QStringLiteral("square"));
    QCOMPARE(normalizedRemotePlayInputSource(QStringLiteral("right stick")),
             QStringLiteral("stick"));
    QCOMPARE(normalizedRemotePlayInputSource(QStringLiteral("auto")),
             QStringLiteral("both"));
    QCOMPARE(normalizedRemotePlayInputSource(QStringLiteral("invalid")),
             QStringLiteral("square"));
    QCOMPARE(normalizedRemotePlayInputSource(QStringLiteral("invalid"),
                                             QStringLiteral("stick_only")),
             QStringLiteral("stick"));
    QCOMPARE(normalizedRemotePlayInputSource(QStringLiteral("invalid"),
                                             QStringLiteral("also_invalid")),
             QStringLiteral("square"));

    QTemporaryDir dir;
    QVERIFY(dir.isValid());
    QFile settings(dir.path() + QStringLiteral("/settings.json"));
    QVERIFY(settings.open(QIODevice::WriteOnly));
    const QJsonObject conflictingAliases{
        {QStringLiteral("remote_play_input_source"), QStringLiteral("both")},
        {QStringLiteral("hold_square_input_source"), QStringLiteral("square")},
        {QStringLiteral("tempo_input_mode"), QStringLiteral("stick")},
        {QStringLiteral("tempo"), QJsonObject{
            {QStringLiteral("input_source"), QStringLiteral("square")},
            {QStringLiteral("input_mode"), QStringLiteral("stick")}}}
    };
    settings.write(QJsonDocument(conflictingAliases).toJson());
    settings.close();

    AppConfig cfg(dir.path());
    QVERIFY(cfg.load());
    // The canonical shipping key wins over stale compatibility aliases left by
    // an older build, so an explicit `both` cannot silently collapse to one lane.
    QCOMPARE(cfg.data().remotePlayInputSource, QStringLiteral("both"));

    // The explicit `both` route reaches AutomationEngine as both input families:
    // Square remains available for Button/TempoSquare, while raw RS-down can own
    // TempoStick and the existing qualified RS-up path can own Go-To.
    AutomationEngine engine;
    engine.applyConfig(cfg.data(), LearningData{});
    QCOMPARE(engine.config().inputMode, QStringLiteral("both"));
    ControllerState physical;
    physical.rightStickY = 127;
    auto output = engine.process(physical);
    QCOMPARE(output.rightStickY, 0); // ordered movement pre-roll
    engine.advanceTestClock(500.0);
    output = engine.process(physical);
    QCOMPARE(output.rightStickY, physical.rightStickY);
    QCOMPARE(engine.shotsAttempted(), 1);
    QCOMPARE(engine.context().mode, ShotMode::TempoStick);

    // Save is also a trusted boundary: valid explicit modes survive and are
    // serialized consistently through every compatibility alias.
    AppConfigData requested = cfg.data();
    requested.remotePlayInputSource = QStringLiteral("right_stick");
    QVERIFY(cfg.save(requested));
    QCOMPARE(cfg.data().remotePlayInputSource, QStringLiteral("stick"));

    requested = cfg.data();
    requested.remotePlayInputSource = QStringLiteral("both");
    QVERIFY(cfg.save(requested));
    QCOMPARE(cfg.data().remotePlayInputSource, QStringLiteral("both"));

    QFile saved(dir.path() + QStringLiteral("/settings.json"));
    QVERIFY(saved.open(QIODevice::ReadOnly));
    const QJsonObject persisted = QJsonDocument::fromJson(saved.readAll()).object();
    QCOMPARE(persisted.value(QStringLiteral("remote_play_input_source")).toString(),
             QStringLiteral("both"));
    QCOMPARE(persisted.value(QStringLiteral("hold_square_input_source")).toString(),
             QStringLiteral("both"));
    QCOMPARE(persisted.value(QStringLiteral("tempo_input_mode")).toString(),
             QStringLiteral("both"));
    const QJsonObject tempo = persisted.value(QStringLiteral("tempo")).toObject();
    QCOMPARE(tempo.value(QStringLiteral("input_source")).toString(), QStringLiteral("both"));
    QCOMPARE(tempo.value(QStringLiteral("input_mode")).toString(), QStringLiteral("both"));
    saved.close();

    // Unknown values cannot create a fourth hidden ownership mode.
    requested = cfg.data();
    requested.remotePlayInputSource = QStringLiteral("unexpected");
    QVERIFY(cfg.save(requested));
    QCOMPARE(cfg.data().remotePlayInputSource, QStringLiteral("square"));
}

static DetectionResult identifiedPlainSample(double fillPct, int frameNumber,
                                              double captureTsMs,
                                              const QString& stage = QStringLiteral("track"))
{
    DetectionResult r = plainSample(fillPct, 0.0);
    r.frameNumber = frameNumber;
    r.captureTsMs = captureTsMs;
    r.frameAgeMs = 0.0;
    r.stage = stage;
    return r;
}

void AutomationEngineTests::duplicateAndMemoryFramesCannotOwnScheduledRelease()
{
    // Build a real, future predictive deadline, then replay its source frame. The
    // replay must revoke release authority and cancel the unconfirmed deadline;
    // a trusted memory echo may keep display continuity but still cannot re-arm it.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    config.memoryTrustEnabled = true;
    config.memoryTrustMaxAgeMs = 50.0;
    config.memoryTrustMaxFillPct = 85.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    learning.shotTypeMeterToReleaseMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    engine.advanceTestClock(160.0); // past the Standstill commit floor
    engine.process(physical);

    DetectionResult f1 = identifiedPlainSample(52.42, 100, 1000.0,
                                                QStringLiteral("acquire"));
    engine.updateDetection(f1);
    engine.process(physical);
    engine.advanceTestClock(10.0);
    DetectionResult f2 = identifiedPlainSample(56.21, 101, 1010.0);
    engine.updateDetection(f2);
    engine.process(physical);
    engine.advanceTestClock(10.0);
    DetectionResult f3 = identifiedPlainSample(60.0, 102, 1020.0);
    engine.updateDetection(f3);
    engine.process(physical);

    QVERIFY2(engine.scheduledFireDeadlineMs() >= 0.0,
             "test setup: the unique rising frames must arm a future vision deadline");
    QVERIFY(engine.context().lastSampleGenuineAccept);
    const quint64 armedToken = engine.scheduledFireToken();
    QSignalSpy invalidatingSpy(&engine, &AutomationEngine::visionScheduleInvalidating);

    engine.updateDetection(f3); // exact same decoded game frame, re-served
    QCOMPARE(engine.context().detectionPresence, QStringLiteral("duplicate"));
    QVERIFY(!engine.context().lastSampleFreshAccept);
    QVERIFY(!engine.context().lastSampleGenuineAccept);
    QCOMPARE(engine.context().detDuplicateFrameDrop, 1);
    QVERIFY2(engine.scheduledFireDeadlineMs() < 0.0,
             "updateDetection must revoke the copied deadline immediately, before the next tick");
    QCOMPARE(invalidatingSpy.count(), 1);
    QCOMPARE(invalidatingSpy.at(0).at(0).toULongLong(), armedToken);
    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseSeq, 0);

    engine.advanceTestClock(1.0);
    DetectionResult memory = identifiedPlainSample(60.0, 103, 1021.0,
                                                    QStringLiteral("coast"));
    memory.rejectionReason = QStringLiteral("stale_or_memory");
    engine.updateDetection(memory);
    QVERIFY(engine.context().lastSampleFreshAccept); // display-only trust bridge
    QVERIFY(!engine.context().lastSampleGenuineAccept);
    engine.process(physical);
    QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseSeq, 0);
}

void AutomationEngineTests::duplicateNoMeterClearsPresenceWithoutRefreshingTiming()
{
    // A frozen decoder cannot advance frame identity, but the sidecar still emits
    // meter_present=false when its content-stall watchdog declares the feed lost.
    // That negative must clear engine presence and revoke a copied deadline without
    // pretending the repeated pixels are a new timing sample.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    learning.shotTypeMeterToReleaseMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    engine.advanceTestClock(160.0);
    engine.process(physical);
    for (int i = 0; i < 3; ++i) {
        DetectionResult sample = identifiedPlainSample(
            52.42 + 3.79 * i, 500 + i, 5000.0 + 10.0 * i,
            i == 0 ? QStringLiteral("acquire") : QStringLiteral("track"));
        engine.updateDetection(sample);
        engine.process(physical);
        if (i != 2) {
            engine.advanceTestClock(10.0);
        }
    }
    QVERIFY(engine.context().meterDetected);
    QVERIFY(engine.context().lastSampleGenuineAccept);
    QVERIFY(engine.scheduledFireDeadlineMs() >= 0.0);
    const double lastDetectionMs = engine.context().lastDetectionMs;
    const quint64 armedToken = engine.scheduledFireToken();
    QSignalSpy invalidatingSpy(&engine, &AutomationEngine::visionScheduleInvalidating);

    DetectionResult lost = identifiedPlainSample(0.0, 502, 5020.0,
                                                  QStringLiteral("no_meter"));
    lost.detected = false;
    lost.confidence = 0.0;
    lost.consecutiveFrames = 0;
    lost.rejectionReason = QStringLiteral("no_meter");
    engine.updateDetection(lost); // same decoder identity, newer health-negative

    QCOMPARE(engine.context().detectionPresence, QStringLiteral("duplicate"));
    QVERIFY(!engine.context().meterDetected);
    QVERIFY(!engine.context().lastSampleFreshAccept);
    QVERIFY(!engine.context().lastSampleGenuineAccept);
    QCOMPARE(engine.context().fillPct, 0.0);
    QCOMPARE(engine.context().lastDetectionMs, lastDetectionMs);
    QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
    QCOMPARE(invalidatingSpy.count(), 1);
    QCOMPARE(invalidatingSpy.at(0).at(0).toULongLong(), armedToken);

    engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseSeq, 0);
}

void AutomationEngineTests::outOfOrderFramesCannotOwnScheduledRelease()
{
    auto configure = [](AutomationEngine& engine) {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.maximumHoldMs = 5000.0;
        config.tempoFallbackTimeoutMs = 5000.0;
        LearningData learning;
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
        learning.shotTypeMeterToReleaseMs.insert(QStringLiteral("Standstill"), 0.0);
        engine.applyConfig(config, learning);
    };
    auto armFromRise = [](AutomationEngine& engine, ControllerState& physical,
                          bool useCaptureTimestamp) {
        driveToHolding(engine, physical);
        engine.advanceTestClock(160.0);
        engine.process(physical);
        for (int i = 0; i < 3; ++i) {
            DetectionResult r = identifiedPlainSample(
                52.42 + 3.79 * i, 400 + i, 4000.0 + 10.0 * i,
                i == 0 ? QStringLiteral("acquire") : QStringLiteral("track"));
            if (!useCaptureTimestamp) {
                r.captureTsMs = -1.0;
            }
            engine.updateDetection(r);
            engine.process(physical);
            if (i != 2) {
                engine.advanceTestClock(10.0);
            }
        }
    };

    // Capture timestamps are the preferred decoder identity. A late callback
    // carrying an older timestamp must revoke—not rewind—the trajectory.
    {
        AutomationEngine engine;
        configure(engine);
        ControllerState physical;
        armFromRise(engine, physical, true);
        QVERIFY(engine.scheduledFireDeadlineMs() >= 0.0);
        QSignalSpy invalidatingSpy(&engine, &AutomationEngine::visionScheduleInvalidating);

        DetectionResult old = identifiedPlainSample(58.0, 399, 4005.0);
        engine.updateDetection(old);
        QCOMPARE(engine.context().detectionPresence, QStringLiteral("stale"));
        QCOMPARE(engine.context().detStaleFrameDrop, 1);
        QVERIFY(!engine.context().lastSampleGenuineAccept);
        QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
        QCOMPARE(invalidatingSpy.count(), 1);
        engine.process(physical);
        QCOMPARE(engine.context().state, HoldState::Holding);
        QCOMPARE(engine.context().releaseSeq, 0);
    }

    // Older sidecars may omit capture timestamps. The frame-number fallback is
    // monotonic too; a lower number is stale, not fresh authority.
    {
        AutomationEngine engine;
        configure(engine);
        ControllerState physical;
        armFromRise(engine, physical, false);
        QVERIFY(engine.scheduledFireDeadlineMs() >= 0.0);
        QSignalSpy invalidatingSpy(&engine, &AutomationEngine::visionScheduleInvalidating);

        DetectionResult old = identifiedPlainSample(58.0, 399, -1.0);
        engine.updateDetection(old);
        QCOMPARE(engine.context().detectionPresence, QStringLiteral("stale"));
        QCOMPARE(engine.context().detStaleFrameDrop, 1);
        QVERIFY(!engine.context().lastSampleGenuineAccept);
        QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
        QCOMPARE(invalidatingSpy.count(), 1);
        engine.process(physical);
        QCOMPARE(engine.context().state, HoldState::Holding);
        QCOMPARE(engine.context().releaseSeq, 0);
    }
}

void AutomationEngineTests::relockJumpStartsNewTrajectoryEpoch()
{
    // A silent capture gap followed by a high-fill re-lock must not splice that
    // point onto the pre-gap rise. The first re-lock frame starts a new sampler,
    // invalidates the old anchor, and cannot release by itself.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
    learning.shotTypeMeterToReleaseMs.insert(QStringLiteral("Standstill"), 0.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    engine.advanceTestClock(160.0);
    engine.process(physical);

    engine.updateDetection(identifiedPlainSample(20.0, 200, 2000.0,
                                                 QStringLiteral("acquire")));
    engine.process(physical);
    engine.advanceTestClock(20.0);
    engine.updateDetection(identifiedPlainSample(30.0, 201, 2020.0));
    engine.process(physical);
    engine.advanceTestClock(20.0);
    engine.updateDetection(identifiedPlainSample(40.0, 202, 2040.0));
    engine.process(physical);
    QVERIFY(engine.context().anchorValidMs >= 0.0);
    QVERIFY(engine.context().releaseVelocityPctMs > 0.1);

    engine.advanceTestClock(60.0); // silent gap: no coast/no_meter payload arrives
    engine.updateDetection(identifiedPlainSample(85.0, 203, 2100.0));
    engine.process(physical);

    QCOMPARE(engine.context().detRelockResets, 1);
    QCOMPARE(engine.context().visionEpoch, 1);
    QVERIFY2(engine.context().anchorValidMs < 0.0,
             "the first frame of a re-lock cannot inherit the old meter anchor");
    QVERIFY2(std::abs(engine.context().releaseVelocityPctMs) < 1e-9,
             "the re-lock fill jump must not become synthetic release velocity");
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseSeq, 0);
}

void AutomationEngineTests::learnedClockRequiresValidatedMeterAndHardCapStillReleases()
{
    // A due learned hold clock is not a substitute for detector evidence. It stays
    // inert with no frame and with only a one-frame phantom; after a two-frame
    // anchor and a current in-reach frame, it may time the release.
    {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.maximumHoldMs = 5000.0;
        config.tempoFallbackTimeoutMs = 5000.0;
        LearningData learning;
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
        engine.applyConfig(config, learning);

        ControllerState physical;
        driveToHolding(engine, physical);
        engine.advanceTestClock(280.0); // learned clock is long past due
        auto output = engine.process(physical);
        QCOMPARE(engine.context().state, HoldState::Holding);
        QCOMPARE(engine.context().releaseSeq, 0);
        QVERIFY(output.square());

        engine.updateDetection(identifiedPlainSample(20.0, 300, 3000.0,
                                                     QStringLiteral("acquire")));
        output = engine.process(physical);
        QVERIFY(engine.context().anchorValidMs < 0.0);
        QCOMPARE(engine.context().state, HoldState::Holding);
        QCOMPARE(engine.context().releaseSeq, 0);

        engine.advanceTestClock(16.0);
        engine.updateDetection(identifiedPlainSample(20.0, 301, 3016.0));
        output = engine.process(physical);
        QVERIFY(engine.context().anchorValidMs >= 0.0);
        QCOMPARE(engine.context().state, HoldState::Holding); // valid, but still out of reach

        engine.advanceTestClock(1.0);
        engine.updateDetection(identifiedPlainSample(50.0, 302, 3017.0));
        output = engine.process(physical);
        QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("feedforward_target"));
        QVERIFY(engine.context().state == HoldState::Releasing
                || engine.context().state == HoldState::Cooldown);
        QVERIFY(!output.square());
    }

    // Detector starvation must still never strand the user's physical shoot input:
    // the one explicitly-labelled hard-cap class drops it on the same tick.
    {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.maximumHoldMs = 360.0;
        config.tempoFallbackTimeoutMs = 20.0;
        LearningData learning;
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
        engine.applyConfig(config, learning);

        ControllerState physical;
        driveToHolding(engine, physical);
        engine.advanceTestClock(engine.config().buttonNoMeterAbortMs + 10.0);
        const ControllerState output = engine.process(physical);
        QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("no_meter_abort"));
        QCOMPARE(engine.context().state, HoldState::Idle);
        QVERIFY(output.square());
        QCOMPARE(engine.shotsReleased(), 0);
        QCOMPARE(engine.shotsAborted(), 1);
    }
}

void AutomationEngineTests::carryoverHighFillNeverValidatesAnchor()
{
    // T2: a lingering PREVIOUS-shot meter (high fill, flat/deflating, panning) is a REAL raw
    // detection, so genuine-vs-echo cannot reject it. It must NOT validate the meter-appear
    // anchor — that leak fired seq6 at 175ms (premature) in batch #2. Shot 1 arms no clock and
    // these samples yield no crossing, so the shot just holds while we inspect anchorValidMs.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    for (double f : {90.0, 90.0, 88.0, 87.0, 86.0}) {
        engine.updateDetection(plainSample(f, 0.0));
        engine.process(physical);
        engine.advanceTestClock(40);
    }
    QCOMPARE(engine.context().state, HoldState::Holding);   // nothing fired (no clock, no crossing)
    QVERIFY2(engine.context().anchorValidMs < 0.0,
             "a high-fill lingering carryover meter must never validate the meter-appear anchor");
}

void AutomationEngineTests::carryoverThenRealRiseRelatchesAnchor()
{
    // T2: after the invalid carryover, a genuine LOW rise (a new shot's meter appearing) must
    // RELATCH the anchor to the rise's first sight — the episode breaks on the >180ms gap and
    // the low-first-confirmed rule validates. Proves the fix restores the meter-appear anchor
    // for the real meter without being poisoned by the carryover.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);

    for (double f : {90.0, 90.0, 88.0}) {
        engine.updateDetection(plainSample(f, 0.0));
        engine.process(physical);
        engine.advanceTestClock(40);
    }
    QVERIFY2(engine.context().anchorValidMs < 0.0, "carryover alone must not validate");

    engine.advanceTestClock(220);   // > 180ms genuine-sample gap -> the episode restarts
    for (double f : {20.0, 30.0, 40.0}) {
        engine.updateDetection(plainSample(f, 200.0));   // genuine low rise
        engine.process(physical);
        engine.advanceTestClock(40);
    }
    QVERIFY2(engine.context().anchorValidMs >= 0.0,
             "a genuine low rise after a carryover must relatch the meter-appear anchor");
}

void AutomationEngineTests::remapConfigDefaultAutonomousOff()
{
    // T3: a default-constructed engine config must NOT silently run the experimental global
    // (autonomous) clock — the live value is settings-driven; the default is the safe path.
    RemapConfig rc;
    QVERIFY2(!rc.autonomousVision,
             "a default RemapConfig must default autonomousVision OFF (settings.json drives the live value)");
}

void AutomationEngineTests::tipGateDefersClockToPredictedCrossing()
{
    // T4: the SAME armed-clock fast-meter scenario as feedforwardTimesFastVisibleMeterFromHoldStart,
    // but the meter is genuinely RISING with a real forward crossing within cap. When the 250ms
    // clock comes DUE the tip gate must DEFER it (tipGateDeferMs>0, shot still Holding) so the
    // predictive vision path can release AT the tip instead of the clock firing at ~mid fill.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tipGateEnabled = true;
    config.tipGateCapMs = 400.0;   // generous cap: the crossing is unambiguously within it
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().shotType, QStringLiteral("Standstill"));

    // Rising, fresh, below-green series spanning PAST the 250ms clock (>=3 accepts in 150ms).
    double fill = 55.0;
    for (int i = 0; i < 8; ++i) {
        engine.updateDetection(plainSample(fill, 220.0));
        engine.process(physical);
        engine.advanceTestClock(40);
        fill += 4.0;                 // 55..83, all below the (readyMeterSample) target 96
    }
    const ShotContext ctx = engine.context();
    QVERIFY2(ctx.tipGateDeferMs > 0.0,
             "a healthy rising meter with a crossing within cap must DEFER the due clock");
    QVERIFY2(ctx.state == HoldState::Holding,
             "the deferred shot must still be open (the raw clock did not fire)");
}

void AutomationEngineTests::tipGateCapFiresClockWhenCrossingRecedes()
{
    // T4 bound: with a tiny rolling cap the latency-compensated vision press is not
    // credible within now+cap, so the gate must NOT defer and the raw backstop may fire.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tipGateEnabled = true;
    config.tipGateCapMs = 1.0;      // vision fire ETA is not within 1ms of now -> no defer
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    double fill = 50.0;
    for (int i = 0; i < 8; ++i) {
        engine.updateDetection(plainSample(fill, 120.0));   // rise stays below green
        engine.process(physical);
        engine.advanceTestClock(40);
        fill += 3.0;                 // 50..71, below green 94 through the clock deadline
    }
    const ShotContext ctx = engine.context();
    QVERIFY2(ctx.tipGateDeferMs == 0.0, "a beyond-cap crossing must not defer the clock");
    // releaseReasonCode is set synchronously in triggerRelease, so it is a robust signal that
    // the clock fired on schedule (unlike the transient HoldState).
    QCOMPARE(ctx.releaseReasonCode, QStringLiteral("feedforward_target"));
}

void AutomationEngineTests::tipGateNeverBlocksNoMeterContract()
{
    // T4 safety: with NO meter there are no genuine fresh accepts, so the tip gate's health
    // check fails and it never engages -> the no-meter blind-fire contract is untouched. This
    // is the invariant that the tip gate (default ON) cannot hang a held Square when the meter
    // is invisible.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.tipGateEnabled = true;   // the gate is ON
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    QCOMPARE(engine.context().state, HoldState::Holding);

    engine.advanceTestClock(3000);
    const ControllerState output = engine.process(physical);
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("no_meter_abort"));
    QVERIFY(output.square());
    QCOMPARE(engine.shotsReleased(), 0);
    QCOMPARE(engine.shotsAborted(), 1);
}

// ---------------------------------------------------------------------------------------------
// Track W — watchdog cascade hardening. A transient capture freeze trips the frame-stall
// watchdog, which restarts the sidecar; in capture-card mode the Elgato's DirectShow handle has
// not released, so a too-fast restart hits "no live device (index 0)" and the contended device
// stalls GUI-thread enumeration into SAFE MODE. These tests pin the two fixes: (1) capture-card
// restart pacing, (2) the bounded, non-blocking video-device enumeration.
// ---------------------------------------------------------------------------------------------

void AutomationEngineTests::forwardCrossingBlocksSubTickFeedforwardSchedule()
{
    // A raw hold clock is 10ms away (inside the scheduler horizon), but three
    // current frames describe a healthy forward crossing. The clock must not
    // copy a precise-fire token while vision still owns the trajectory.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    config.tipGateEnabled = true;
    config.tipGateCapMs = 300.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    engine.advanceTestClock(225.0);
    engine.updateDetection(identifiedPlainSample(50.0, 600, 6000.0,
                                                 QStringLiteral("acquire")));
    engine.process(physical);
    engine.advanceTestClock(10.0);
    engine.updateDetection(identifiedPlainSample(52.0, 601, 6010.0));
    engine.process(physical);
    engine.advanceTestClock(10.0);
    engine.updateDetection(identifiedPlainSample(54.0, 602, 6020.0));
    engine.process(physical); // hold-clock deadline is now +5ms (default 6ms horizon)

    QVERIFY2(engine.context().lastSampleGenuineAccept,
             "test setup requires current detector authority");
    QVERIFY2(engine.context().releaseVelocityPctMs > 0.02,
             "test setup requires a healthy forward trajectory");
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseSeq, 0);
    QVERIFY2(engine.scheduledFireDeadlineMs() < 0.0,
             "a healthy future crossing must block the sub-tick raw-clock token");
}

void AutomationEngineTests::lateForwardCrossingPreemptsOverdueFeedforward()
{
    // The crossing itself is future, but its latency-compensated release time is
    // already past when detector lock becomes healthy. That is still vision
    // authority: the predictive ladder fires now instead of misattributing the
    // same edge to an overdue feedforward clock.
    QVERIFY(healthyForwardCrossingOwnsTiming(
        true, 3, 0.25, 70.0, 100.0,
        /*crossingMs=*/1080.0, /*nowMs=*/1000.0,
        /*effectiveLatencyMs=*/100.0, /*capMs=*/300.0));
    QVERIFY2(!healthyForwardCrossingOwnsTiming(
                 true, 3, 0.25, 70.0, 100.0,
                 /*crossingMs=*/1350.0, /*nowMs=*/1000.0,
                 /*effectiveLatencyMs=*/0.0, /*capMs=*/300.0),
             "the rolling cap applies to crossing-latency relative to now");

    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    config.tipGateEnabled = true;
    config.tipGateCapMs = 300.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    engine.advanceTestClock(300.0); // raw hold clock is already overdue
    engine.updateDetection(identifiedPlainSample(20.0, 610, 6100.0,
                                                 QStringLiteral("acquire")));
    engine.process(physical);
    engine.advanceTestClock(10.0);
    engine.updateDetection(identifiedPlainSample(35.0, 611, 6110.0));
    engine.process(physical); // anchor valid, but still below clock reach floor
    engine.advanceTestClock(10.0);
    engine.updateDetection(identifiedPlainSample(55.0, 612, 6120.0));
    const ControllerState output = engine.process(physical);

    QVERIFY2(engine.context().releaseSeq > 0,
             "late acquisition with a due vision press must release immediately");
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("predictive_target"));
    QVERIFY2(engine.context().releaseReasonCode != QStringLiteral("feedforward_target"),
             "an overdue raw clock may not steal a healthy crossing");
    QVERIFY(!output.square());
}

void AutomationEngineTests::flatFreshSampleAllowsFeedforwardBackstop()
{
    // Vision first validates this shot's meter, then the local trajectory goes
    // flat. With no credible forward crossing left, a current genuine in-reach
    // frame is exactly where the learned clock is allowed to act as a backstop.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    config.tipGateEnabled = true;
    config.tipGateCapMs = 300.0;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    driveToHolding(engine, physical);
    engine.advanceTestClock(160.0);
    engine.updateDetection(identifiedPlainSample(20.0, 620, 6200.0,
                                                 QStringLiteral("acquire")));
    engine.process(physical);
    engine.advanceTestClock(20.0);
    engine.updateDetection(identifiedPlainSample(21.0, 621, 6220.0));
    engine.process(physical); // validated low-first anchor

    // 45ms clears the velocity sampler without tripping the >50ms relock
    // trajectory reset, so the validated anchor remains shot-local authority.
    engine.advanceTestClock(45.0);
    engine.updateDetection(identifiedPlainSample(55.0, 622, 6265.0));
    engine.process(physical);
    engine.advanceTestClock(15.0);
    engine.updateDetection(identifiedPlainSample(55.1, 623, 6285.0));
    engine.process(physical);
    engine.advanceTestClock(20.0); // hold clock is now due
    engine.updateDetection(identifiedPlainSample(55.2, 624, 6305.0));
    const ControllerState output = engine.process(physical);

    QVERIFY2(engine.context().releaseVelocityPctMs <= 0.02,
             "test setup requires a flat/no-crossing current trajectory");
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("feedforward_target"));
    QVERIFY(engine.context().releaseSeq > 0);
    QVERIFY(!output.square());
}

void AutomationEngineTests::staleAndDuplicateFramesCannotOpenFeedforwardBackstop()
{
    auto run = [](bool duplicate) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.maximumHoldMs = 5000.0;
        config.tempoFallbackTimeoutMs = 5000.0;
        config.tipGateEnabled = true;
        LearningData learning;
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
        engine.applyConfig(config, learning);

        ControllerState physical;
        driveToHolding(engine, physical);
        engine.advanceTestClock(160.0);
        engine.updateDetection(identifiedPlainSample(20.0, 630, 6300.0,
                                                     QStringLiteral("acquire")));
        engine.process(physical);
        engine.advanceTestClock(20.0);
        engine.updateDetection(identifiedPlainSample(21.0, 631, 6320.0));
        engine.process(physical);
        engine.advanceTestClock(20.0);
        DetectionResult last = identifiedPlainSample(22.0, 632, 6340.0);
        engine.updateDetection(last);
        engine.process(physical);

        engine.advanceTestClock(70.0); // learned clock is now due
        DetectionResult untrusted = identifiedPlainSample(60.0,
            duplicate ? 632 : 633, duplicate ? 6340.0 : 6410.0,
            duplicate ? QStringLiteral("track") : QStringLiteral("coast"));
        if (!duplicate) {
            untrusted.rejectionReason = QStringLiteral("stale_or_memory");
            untrusted.staleFrame = true;
        }
        engine.updateDetection(untrusted);
        const ControllerState output = engine.process(physical);

        QCOMPARE(engine.context().state, HoldState::Holding);
        QCOMPARE(engine.context().releaseSeq, 0);
        QVERIFY(engine.context().releaseReasonCode != QStringLiteral("feedforward_target"));
        QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
        QVERIFY(output.square());
        QVERIFY(!engine.context().lastSampleGenuineAccept);
        if (duplicate) {
            QCOMPARE(engine.context().detectionPresence, QStringLiteral("duplicate"));
        }
    };

    run(true);
    run(false);
}

void AutomationEngineTests::watchdogCaptureCardUsesLongRestartDelay()
{
    // Fix 1: in capture-card mode the watchdog must wait long enough for the Elgato's DirectShow
    // handle to release before respawning the sidecar, or the restart hits "no live device
    // (index 0)" and the contended device stalls enumeration into SAFE MODE.
    AppConfigData cfg;
    cfg.videoSource = QStringLiteral("capture_card");
    QVERIFY(isCaptureCardSource(cfg));
    QCOMPARE(sidecarRestartDelayMs(isCaptureCardSource(cfg)), kSidecarRestartDelayMsCaptureCard);
    // The long delay must sit in the 2500-4000ms Elgato release window observed live, and be
    // meaningfully longer than the decoder-pipe fast beat.
    QVERIFY(kSidecarRestartDelayMsCaptureCard >= 2500 && kSidecarRestartDelayMsCaptureCard <= 4000);
    QVERIFY(kSidecarRestartDelayMsCaptureCard > kSidecarRestartDelayMs);
    // Case-insensitive, matching the sidecar-env gate (QString::compare CaseInsensitive) so the
    // restart pacing and the ORION_CAPTURE_CARD env decision can never disagree.
    AppConfigData mixed;
    mixed.videoSource = QStringLiteral("Capture_Card");
    QVERIFY(isCaptureCardSource(mixed));
    QCOMPARE(sidecarRestartDelayMs(isCaptureCardSource(mixed)), kSidecarRestartDelayMsCaptureCard);
}

void AutomationEngineTests::watchdogDecoderModeUsesFastRestartDelay()
{
    // Decoder-pipe mode has no DirectShow device to release, so it keeps the historical fast
    // restart beat — the long capture-card delay must NOT apply here.
    AppConfigData cfg;
    cfg.videoSource = QStringLiteral("decoder");
    QVERIFY(!isCaptureCardSource(cfg));
    QCOMPARE(sidecarRestartDelayMs(isCaptureCardSource(cfg)), kSidecarRestartDelayMs);
    QCOMPARE(kSidecarRestartDelayMs, 600);
}

void AutomationEngineTests::controllerRoutingQuarantinesRetiredVirtualSlot()
{
    // Exact unplug race from the live log: ViGEm identity was cleared, but its
    // XInput slot remained readable for another poll and was selected as the
    // physical pad. The retired slot must stay virtual throughout PnP removal.
    QCOMPARE(kRetiredVirtualSlotQuarantineMs, qint64(3000));
    QVERIFY(isVirtualXinputCandidate(/*slot=*/1, /*active=*/-1, /*retired=*/1,
                                     /*now=*/10'500, /*retiredUntil=*/13'000,
                                     /*noNavigationCapability=*/false));
    QVERIFY(!isVirtualXinputCandidate(2, -1, 1, 10'500, 13'000, false));
    QVERIFY(!isVirtualXinputCandidate(1, -1, 1, 13'001, 13'000, false));
    QVERIFY(isVirtualXinputCandidate(3, 3, -1, 20'000, 0, false));
    QVERIFY(isVirtualXinputCandidate(0, -1, -1, 20'000, 0, true));
}

void AutomationEngineTests::directPipeNeutralizesDesktopVirtualPad()
{
    QVERIFY(shouldNeutralizeDesktopVirtualPad(true, true, true));
    QVERIFY(!shouldNeutralizeDesktopVirtualPad(false, true, true));
    QVERIFY(!shouldNeutralizeDesktopVirtualPad(true, false, true));
    // A dropped pipe must restore the real ViGEm state on the same tick.
    QVERIFY(!shouldNeutralizeDesktopVirtualPad(true, true, false));

    // Pipe creation precedes Chiaki streaminfo. A pre-ready ownership packet
    // would correctly fail closed as Uninitialized, so Connecting is never
    // sufficient direct-input authority.
    QVERIFY(!directInputWriteAllowed(RemotePlayState::Disconnected));
    QVERIFY(!directInputWriteAllowed(RemotePlayState::Connecting));
    QVERIFY(directInputWriteAllowed(RemotePlayState::Running));
    QVERIFY(!directInputWriteAllowed(RemotePlayState::Error));

    QVERIFY(!directInputRouteCurrentlyOwned(false, false, false));
    QVERIFY(!directInputRouteCurrentlyOwned(true, false, false));
    QVERIFY(!directInputRouteCurrentlyOwned(true, true, false));
    QVERIFY(!directInputRouteCurrentlyOwned(false, true, true));
    QVERIFY(directInputRouteCurrentlyOwned(true, true, true));

    QVERIFY(rawInputRemovalMatchesActivePhysical(true, false, false, false));
    QVERIFY(rawInputRemovalMatchesActivePhysical(false, true, true, true));
    QVERIFY(!rawInputRemovalMatchesActivePhysical(false, false, true, false));
    QVERIFY(!rawInputRemovalMatchesActivePhysical(false, true, false, false));
    QVERIFY(!rawInputRemovalMatchesActivePhysical(false, true, true, false));
}

void AutomationEngineTests::padConnectGateWakesEnumeratedSilentPadInsteadOfRefusing()
{
    // [ORION_PAD_LIVE_INPUT_GATE 2026-08-08] SHIP-BLOCKER regression (live
    // sessions orion_native.log 2026-08-08 03:14 and 05:36): with the pad
    // physically attached, Connect refused repeatedly. The gate decision must
    // never map "enumerated but silent" straight to a refusal — a Sony pad
    // streams reports continuously while enumerated, so that state is a
    // suspended/idle transport (wakeable within the same click), not an idle
    // user. Exact scenario under test: pad enumerated, ONE report at T0, then
    // T0+5 s with no further reports -> the gate must attempt the wake+recheck
    // (pre-fix code refused outright on !live && !recentReport).
    const qint64 t0 = 1'000'000;
    const qint64 nowMs = t0 + 5'000;
    const bool hasRecent = (nowMs - t0) < 3000; // hasRecentRawInput() window
    QVERIFY(!hasRecent);
    QCOMPARE(padConnectGateAction(/*physicalPadLive=*/false, hasRecent,
                                  /*rawInputEnumerated=*/true),
             PadConnectGateAction::WakeProbeThenRecheck);

    // The wake itself never admits. Connect proceeds only once the post-wake
    // re-evaluation sees a REAL fresh report — the same predicate the
    // 2026-08-07 tightening introduced.
    const qint64 postWakeReportMs = nowMs + 40;
    const qint64 recheckMs = nowMs + 60;
    const bool freshAfterWake = (recheckMs - postWakeReportMs) < 3000;
    QVERIFY(freshAfterWake);
    QCOMPARE(padConnectGateAction(false, freshAfterWake, true),
             PadConnectGateAction::Proceed);

    // A live selector route (report age <= 750 ms) passes outright, with or
    // without the enumeration sweep having run yet.
    QCOMPARE(padConnectGateAction(true, false, true), PadConnectGateAction::Proceed);
    QCOMPARE(padConnectGateAction(true, false, false), PadConnectGateAction::Proceed);
    QCOMPARE(padConnectGateAction(false, true, false), PadConnectGateAction::Proceed);
}

void AutomationEngineTests::padConnectGateStillRefusesDeadAndAbsentPads()
{
    // Absent pad (never reported AND not enumerated): refuse — there is no
    // wake target. This is the live 2026-08-08 failure state: the pad had
    // dropped off USB after system idle and was invisible to RawInput and
    // WinMM alike until a physical re-plug re-arrived it. No gate predicate
    // can admit a device Windows cannot see.
    QCOMPARE(padConnectGateAction(/*physicalPadLive=*/false,
                                  /*hasRecentRawReport=*/false,
                                  /*rawInputEnumerated=*/false),
             PadConnectGateAction::RefuseNoController);

    // Dead-but-enumerated pad that stays silent THROUGH the wake: every
    // re-evaluation keeps yielding WakeProbeThenRecheck (never Proceed), and
    // the runtime maps an unconfirmed wake to the same refusal as before. The
    // hole the 2026-08-07 gate closed (dead pad slipping into a hung
    // "connected but no inputs" session) stays closed.
    QVERIFY(padConnectGateAction(false, false, true)
            != PadConnectGateAction::Proceed);
    QCOMPARE(padConnectGateAction(false, false, true),
             PadConnectGateAction::WakeProbeThenRecheck);
}

void AutomationEngineTests::absentPadAdviceKeysOffRegistryHistoryNotGuesswork()
{
    // [ORION_PAD_LIVE_INPUT_GATE 2026-08-08] The absent-pad refusal message
    // must distinguish "no pad has ever been on this PC" from "the pad was
    // here and dropped off USB" (rig-verified EnhancedPowerManagementEnabled
    // wedge; recovery = re-plug), and must offer the consented one-time fix
    // ONLY when a known Sony pad entry still carries the risky setting.
    // Pre-fix behaviour collapsed all three into one generic "No controller
    // detected" message.
    QCOMPARE(absentPadAdvice(/*historyKnown=*/false, /*fixApplicable=*/false),
             AbsentPadAdvice::NeverSeen);
    // No history means the fix flag cannot be trusted either — never claim a
    // pad "was here" without registry evidence.
    QCOMPARE(absentPadAdvice(false, true), AbsentPadAdvice::NeverSeen);
    QCOMPARE(absentPadAdvice(true, false), AbsentPadAdvice::DroppedOffBus);
    QCOMPARE(absentPadAdvice(true, true),
             AbsentPadAdvice::DroppedOffBusFixAvailable);
}

void AutomationEngineTests::silentAutoApplyGetsOneAttemptPerVersion()
{
    // [ORION_UPDATE_NO_LOCKOUT 2026-08-08] Live loop (deployed orion_native.log
    // 2026-08-07 05:11:34->05:13:24Z, 18 relaunches): the startup gate refused
    // to re-attempt the failed 1.0.1 update, but the silent idle-session path
    // re-ran the doomed OrionUpdater handoff on every relaunch because it
    // never consulted the per-version already-attempted latch. The exact
    // regression scenario: update available, updater present, idle session,
    // version ALREADY attempted -> the automatic path must NOT apply again.
    QVERIFY(!silentAutoApplyAllowed(/*updateAvailable=*/true, /*devBuild=*/false,
                                    /*updaterPresent=*/true, /*streamingActive=*/false,
                                    /*alreadyAttemptedThisVersion=*/true));

    // A genuinely NEW version (latch is keyed by version, so it reads false)
    // must still auto-apply on an idle session.
    QVERIFY(silentAutoApplyAllowed(true, false, true, false, false));

    // The pre-existing refusals are unchanged: nothing to apply, dev build,
    // missing updater, or a live stream (deferred, not skipped).
    QVERIFY(!silentAutoApplyAllowed(false, false, true, false, false));
    QVERIFY(!silentAutoApplyAllowed(true, true, true, false, false));
    QVERIFY(!silentAutoApplyAllowed(true, false, false, false, false));
    QVERIFY(!silentAutoApplyAllowed(true, false, true, true, false));
}

void AutomationEngineTests::rawInputDeviceIdentityIsResolvedOncePerHandle()
{
    RawInputDeviceIdentityCache cache;
    int pathCalls = 0;
    int classifyCalls = 0;
    const auto resolve = [&](quintptr handle, qint64 nowMs, bool pathAvailable) {
        return cache.resolve(
            handle,
            nowMs,
            [&] {
                ++pathCalls;
                return pathAvailable ? QStringLiteral("HID#VID_054C&PID_0CE6") : QString{};
            },
            [&](const QString&) {
                ++classifyCalls;
                return QStringLiteral("DualSense");
            });
    };

    const auto first = resolve(7, 100, true);
    QCOMPARE(first.kind, QStringLiteral("DualSense"));
    QCOMPARE(cache.cachedPath(7), QStringLiteral("HID#VID_054C&PID_0CE6"));
    QCOMPARE(resolve(7, 9999, true).path, first.path);
    QCOMPARE(pathCalls, 1);
    QCOMPARE(classifyCalls, 1);

    // A transient lookup failure is bounded to one query per second, then can
    // recover without waiting for a device-change notification.
    QVERIFY(resolve(8, 200, false).path.isEmpty());
    QVERIFY(resolve(8, 1199, true).path.isEmpty());
    QCOMPARE(pathCalls, 2);
    QCOMPARE(resolve(8, 1200, true).kind, QStringLiteral("DualSense"));
    QCOMPARE(pathCalls, 3);
    QCOMPARE(classifyCalls, 2);

    cache.clear();
    QCOMPARE(cache.size(), 0);
    (void)resolve(7, 2000, true);
    QCOMPARE(pathCalls, 4);
}

void AutomationEngineTests::automationRouteAuthorityTransitionsFailClosed()
{
    // Preview, Connecting, and a dropped virtual target all lack release authority. The policy's
    // sessionRunning input intentionally means the exact RemotePlayState::Running verdict; callers
    // must never substitute remoteRunning_, which is also true while Connecting.
    QVERIFY(!automationRouteReady(/*sessionRunning=*/false,
                                  /*virtualControllerConnected=*/false)); // capture preview
    QVERIFY(!automationRouteReady(/*sessionRunning=*/false,
                                  /*virtualControllerConnected=*/true));  // Connecting
    QVERIFY(!automationRouteReady(/*sessionRunning=*/true,
                                  /*virtualControllerConnected=*/false)); // route dropped
    QVERIFY(automationRouteReady(/*sessionRunning=*/true,
                                 /*virtualControllerConnected=*/true));   // usable route
    QVERIFY(!automationRouteReady(/*sessionRunning=*/false,
                                  /*virtualControllerConnected=*/true));  // leave Running
}

void AutomationEngineTests::meterDelayRampDisarmPreservesRouteAttestation()
{
    // [ORION_METER_DELAY_ROUTE_AUTHORITY 2026-08-08] Live regression, owner rig
    // 22:32Z: with the intercept Locked (target_delay_ms=250, applied_ms=250),
    // the user raised the target to 300 ms. The 0.45 s re-ramp published
    // settled=false, readyForArm() correctly refused, and syncEngineArmed()'s
    // blanket disarm ALSO revoked the controller-route attestation -- benching
    // every press for 72 s as waiting_for_latency_calibration until a neutral
    // controller window happened to re-issue a route proof. The inbound video
    // delay cannot change the outbound controller route, so the attestation must
    // survive a delay-gate-only disarm.

    // The regression case: route authority fully intact, delay gate refusing
    // (mid-ramp between two applied targets > 0). Disarm yes; revoke NO.
    {
        const EngineArmDecision d = engineArmDecision(
            /*routeAuthorityOk=*/true, /*meterDelayGateOk=*/false);
        QVERIFY(!d.arm);
        QVERIFY2(!d.revokeRouteAttestation,
                 "a meter-delay ramp revoked the controller-route attestation; "
                 "the engine will bench on waiting_for_latency_calibration until "
                 "the next neutral-delivery route proof (72 s live 2026-08-08)");
    }

    // Fail-closed is untouched for every route/security cause, including a real
    // route fault that lands DURING a delay ramp.
    {
        const EngineArmDecision d = engineArmDecision(false, true);
        QVERIFY(!d.arm);
        QVERIFY(d.revokeRouteAttestation);
    }
    {
        const EngineArmDecision d = engineArmDecision(false, false);
        QVERIFY(!d.arm);
        QVERIFY2(d.revokeRouteAttestation,
                 "a route fault during a delay ramp must still revoke");
    }

    // Healthy steady state: armed, nothing revoked.
    {
        const EngineArmDecision d = engineArmDecision(true, true);
        QVERIFY(d.arm);
        QVERIFY(!d.revokeRouteAttestation);
    }
}

void AutomationEngineTests::sidecarStartedRequiresExplicitConsoleSessionReadiness()
{
    // Preview-only capture/detection stays usable without Chiaki input.
    QVERIFY(sidecarStartedHasInputAuthority(/*previewMode=*/true,
                                            /*hasExplicitInputReady=*/false,
                                            /*inputReady=*/false));

    // A real stream never inherits authority from a legacy/missing field, an
    // explicit false verdict, or a stale process/pipe liveness assumption.
    QVERIFY(!sidecarStartedHasInputAuthority(false, false, false));
    QVERIFY(!sidecarStartedHasInputAuthority(false, false, true));
    QVERIFY(!sidecarStartedHasInputAuthority(false, true, false));
    QVERIFY(sidecarStartedHasInputAuthority(false, true, true));

    // Recovery uses the same contract: it cannot re-enter Running until the
    // freshly launched child publishes explicit current-session readiness.
    QVERIFY(!sidecarStartedHasInputAuthority(false, true, false));
    QVERIFY(sidecarStartedHasInputAuthority(false, true, true));
}

void AutomationEngineTests::previewRouteCannotGeneratePhantomRelease()
{
    AutomationEngine engine;
    AppConfigData config;
    LearningData learning;
    engine.applyConfig(config, learning);

    ControllerState held;
    held.buttons |= XINPUT_GAMEPAD_X;

    // The historical regression ran this exact shape after disconnect: fresh meter telemetry and
    // a held physical shot input were still processed while capture preview had no Chiaki/ViGEm
    // route, producing "Release issued" followed by NOT_SUBMITTED. A disarmed preview must remain
    // pure pass-through even if authoritative-looking meter samples keep arriving.
    engine.setArmed(automationRouteReady(/*sessionRunning=*/false,
                                         /*virtualControllerConnected=*/false));
    ControllerState output;
    for (int frame = 0; frame < 20; ++frame) {
        auto meter = readyMeterSample(96.0, 1.0);
        meter.frameNumber = frame;
        meter.captureTsMs = 1'000.0 + frame * 16.0;
        engine.updateDetection(meter);
        output = engine.process(held);
        engine.advanceTestClock(16.0);
    }
    QVERIFY(output.square());
    QCOMPARE(engine.context().state, HoldState::Idle);
    QCOMPARE(engine.shotsAttempted(), 0);
    QCOMPARE(engine.shotsReleased(), 0);

    // Once Running + virtual-connected is true the same input may arm. Losing either half of the
    // route mid-hold disarms and resets on the next process tick; later meter frames cannot fire.
    engine.setArmed(automationRouteReady(true, true));
    engine.process(held);
    engine.advanceTestClock(220.0);
    engine.process(held);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.shotsAttempted(), 1);

    engine.setArmed(automationRouteReady(/*sessionRunning=*/false,
                                         /*virtualControllerConnected=*/true));
    // setArmed(false) alone does not mutate ShotContext. This is the simultaneous route-loss /
    // physical-pad-loss regression: with no next physical poll, Holding would remain resident and
    // could be revived by a later setArmed(true). The GUI-thread route callbacks therefore reset it
    // immediately after revoking the worker deadline.
    QCOMPARE(engine.context().state, HoldState::Holding);
    engine.reset();
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
    output = engine.process(held);
    QVERIFY(output.square());
    QCOMPARE(engine.context().state, HoldState::Idle);
    for (int frame = 20; frame < 40; ++frame) {
        auto meter = readyMeterSample(98.0, 0.5);
        meter.frameNumber = frame;
        meter.captureTsMs = 1'000.0 + frame * 16.0;
        engine.updateDetection(meter);
        output = engine.process(held);
        engine.advanceTestClock(16.0);
    }
    QVERIFY(output.square());
    QCOMPARE(engine.shotsReleased(), 0);

    // Reconnection can grant authority again, but only to a clean Idle context; no old release
    // sequence or copied deadline crosses the route boundary.
    engine.setArmed(automationRouteReady(true, true));
    QCOMPARE(engine.context().state, HoldState::Idle);
    QVERIFY(engine.scheduledFireDeadlineMs() < 0.0);
    QCOMPARE(engine.shotsReleased(), 0);
}

