void AutomationEngineTests::applicationShutdownStateMachineIsOneShot()
{
    ApplicationShutdownPhase phase = ApplicationShutdownPhase::Running;
    QVERIFY(!applicationShutdownActive(phase));
    QVERIFY(shouldResumeRuntimeAfterDisconnect(phase));

    QVERIFY(markApplicationShutdownRequested(phase));
    QVERIFY(applicationShutdownActive(phase));
    QVERIFY(!markApplicationShutdownRequested(phase));
    QVERIFY(!shouldResumeRuntimeAfterDisconnect(phase));

    QVERIFY(beginApplicationShutdownTeardown(phase));
    QVERIFY(!beginApplicationShutdownTeardown(phase));
    completeApplicationShutdownTeardown(phase);
    QVERIFY(phase == ApplicationShutdownPhase::Complete);
    QVERIFY(!beginApplicationShutdownTeardown(phase));

    // Minimize keeps the root visible and must not exit; a real hide/close is
    // the fallback trigger when a transient window keeps Qt's loop alive.
    QVERIFY(!shouldRequestShutdownForRootVisibility(true));
    QVERIFY(shouldRequestShutdownForRootVisibility(false));
}

