    // A later restart must extend, never shorten, the existing deadline.
    const qint64 second = extendStreamWindowContainmentGrace(first, 2'000);
    QCOMPARE(second, 2'000 + kStreamWindowRestartContainmentGraceMs);
    QCOMPARE(extendStreamWindowContainmentGrace(second, 0), second);
