    // static/loading screen must not restart while raw delivery stays current.
    QVERIFY(!streamTransportNeedsRestart(0.0, false));
    QVERIFY(!streamTransportNeedsRestart(kStreamTransportRestartAgeMs, false));
    QVERIFY(streamTransportNeedsRestart(kStreamTransportRestartAgeMs + 0.1, false));
    QVERIFY(streamTransportNeedsRestart(0.0, true));
    QVERIFY(!streamTransportNeedsRestart(-1.0, false));
    QVERIFY(!streamTransportNeedsRestart(
        std::numeric_limits<double>::quiet_NaN(), false));
