void AutomationEngineTests::inputLinkRecoveryEscalatesOnceAfterFinalGrace()
{
    using Action = InputLinkRecoveryAction;

    QCOMPARE(kInputHookDownRecoverHeartbeats, 5);
    QCOMPARE(kInputHookRecoveryRetryHeartbeats, 15);
    QCOMPARE(kInputHookRecoveryMaxAttempts, 3);
    QCOMPARE(kInputHookFullRestartHeartbeat, 50);

    // Three capture-preserving child recoveries at ~5s, 20s, and 35s.
    QVERIFY(inputLinkRecoveryAction(4, 0, false) == Action::None);
    QVERIFY(inputLinkRecoveryAction(5, 0, false) == Action::RecoverInputOnly);
    QVERIFY(inputLinkRecoveryAction(19, 1, false) == Action::None);
    QVERIFY(inputLinkRecoveryAction(20, 1, false) == Action::RecoverInputOnly);
    QVERIFY(inputLinkRecoveryAction(34, 2, false) == Action::None);
    QVERIFY(inputLinkRecoveryAction(35, 2, false) == Action::RecoverInputOnly);

    // One final 15s grace after attempt three, then exactly one contained full
    // restart. Before this fix, attempts==3 made the watchdog silent forever.
    QVERIFY(inputLinkRecoveryAction(49, 3, false) == Action::None);
    QVERIFY(inputLinkRecoveryAction(50, 3, false)
            == Action::RestartSidecarContained);

    // The caller sets the latch before restarting. A transient non-Running
    // state resets the down-heartbeat counter to zero, but must not reopen the
    // retry/restart lane; automation stays fail-closed until verified reconnect.
    QVERIFY(inputLinkRecoveryAction(0, 3, true) == Action::HoldFailClosed);
    QVERIFY(inputLinkRecoveryAction(50, 3, true) == Action::HoldFailClosed);
    QVERIFY(inputLinkRecoveryAction(10'000, 3, true) == Action::HoldFailClosed);
}

void AutomationEngineTests::inputRecoveryVerdictIsBoundedAndAttemptScoped()
{
    // Recovery is a warm child/session repair, not a cold 40-second launch. The native state has
    // its own bound so a blocked sidecar call cannot leave controller authority in limbo forever.
    QVERIFY(kInputSessionRecoveryDeadlineMs >= 10'000);
    QVERIFY(kInputSessionRecoveryDeadlineMs <= 20'000);

    QVERIFY(shouldAcceptInputRecoveryReady(
        /*pending=*/true, /*rejectLate=*/false, /*connecting=*/true,
        /*hasExplicitInputReady=*/true, /*inputReady=*/true));
    QVERIFY(!shouldAcceptInputRecoveryReady(true, false, true, false, true));
    QVERIFY(!shouldAcceptInputRecoveryReady(true, false, true, true, false));
    QVERIFY(!shouldAcceptInputRecoveryReady(false, false, true, true, true));
    QVERIFY(!shouldAcceptInputRecoveryReady(true, true, true, true, true));
    QVERIFY(!shouldAcceptInputRecoveryReady(true, false, false, true, true));

    constexpr quint64 current = 12;
    QVERIFY(inputRecoveryDeadlineApplies(current, current, true, true));
    QVERIFY(!inputRecoveryDeadlineApplies(current - 1, current, true, true));
    QVERIFY(!inputRecoveryDeadlineApplies(current, current, false, true));
    QVERIFY(!inputRecoveryDeadlineApplies(current, current, true, false));
}

void AutomationEngineTests::failedWarmPromotionRestoresOnlyLiveCapturePreview()
{
    // The exact live failure still had a healthy 60-fps capture-card sidecar. Only that narrow
    // case may restore preview ownership; decoder mode, a dead process, or a cold connect must not
    // claim there is a preview to preserve.
    QVERIFY(shouldRestoreWarmPreviewAfterPromotionFailure(
        /*promotedWarmPreview=*/true, /*sidecarRunning=*/true,
        /*captureCardSource=*/true));
    QVERIFY(!shouldRestoreWarmPreviewAfterPromotionFailure(false, true, true));
    QVERIFY(!shouldRestoreWarmPreviewAfterPromotionFailure(true, false, true));
    QVERIFY(!shouldRestoreWarmPreviewAfterPromotionFailure(true, true, false));
}

void AutomationEngineTests::stallMeterLostEmissionBypassesFrameCountGate()
{
    // RC-2b (live-path bug #2): during a pixel-age STALL the sidecar synthesizes a
    // meter_present:false emission while frame_count is FROZEN (a stall is exactly "no new
    // unique frame"). The detection emit gate dedupes on frame_count, so it silently dropped
    // every stall emission -> the meter-lost reset chain (the 293s-HOLD-bug fix) never fired
    // until the next unique frame. A meter_present:false emission must bypass the dedupe: it
    // carries no fill/velocity that could double-feed timing (the engine only resets off it).
    const int frozen = 4711;
    // The synthesized stall emission (frozen frame_count, no meter) must be ACCEPTED so the
    // meter-lost path (detected=false, rejectionReason "no_meter") fires promptly...
    QVERIFY2(shouldAcceptSidecarDetectionEmission(/*hasDetectionSignal=*/false,
                                                  /*meterPresent=*/false, frozen, frozen),
             "a frozen-frame_count meter_present:false stall emission must NOT be dropped");
    // ...and must stay accepted on every repeated stall heartbeat while the freeze persists.
    QVERIFY(shouldAcceptSidecarDetectionEmission(false, false, frozen, frozen));
    // A normal meter-lost emission (frame_count advanced) is accepted as before.
    QVERIFY(shouldAcceptSidecarDetectionEmission(false, false, frozen + 1, frozen));
    // Meter PRESENT: the frame_count dedupe still guards against double-feeding the engine
    // with a re-published consensus for the same frame.
    QVERIFY(!shouldAcceptSidecarDetectionEmission(true, true, frozen, frozen));
    QVERIFY(shouldAcceptSidecarDetectionEmission(true, true, frozen + 1, frozen));
    // Meter present but zero-signal (fill<=0 && conf<=0) stays rejected — unchanged contract.
    QVERIFY(!shouldAcceptSidecarDetectionEmission(false, true, frozen + 1, frozen));
}

void AutomationEngineTests::sidecarFrameAgeIncludesStdoutTransit()
{
    QCOMPARE(effectiveSidecarFrameAgeMs(6.0, 1'000.0, 1'018.0), 18.0);
    QCOMPARE(effectiveSidecarFrameAgeMs(25.0, 1'000.0, 1'018.0), 25.0);
    QCOMPARE(effectiveSidecarFrameAgeMs(6.0, 0.0, 1'018.0), 6.0); // legacy payload
    QVERIFY(!std::isfinite(effectiveSidecarFrameAgeMs(6.0, 1'020.0, 1'018.0)));
    QVERIFY(!std::isfinite(effectiveSidecarFrameAgeMs(-1.0, 1'000.0, 1'018.0)));
    // A payload that waited behind stdout preview traffic consumes the strict
    // 50ms lease even though its sidecar-reported pre-transit age was only 6ms.
    QVERIFY(effectiveSidecarFrameAgeMs(6.0, 1'000.0, 1'080.0) > 50.0);
}

void AutomationEngineTests::capturePreviewSkipsChiakiLaunch()
{
    // Live capture-card preview (shown BEFORE Connect) MUST open the card WITHOUT launching Chiaki —
    // that is the whole point of a live HDMI feed with no Remote Play session yet. buildSidecarConfig
    // drives the sidecar's auto_launch_client straight from this policy, so lock the contract here:
    // a regression that launched Chiaki in preview would break "no Chiaki before Connect".
    QCOMPARE(sidecarShouldAutoLaunchClient(/*previewMode=*/true), false);   // preview: card only, no Chiaki
    QCOMPARE(sidecarShouldAutoLaunchClient(/*previewMode=*/false), true);   // full session: launch Chiaki

    // The preview -> full hand-off reuses the capture-card release beat so the single-open Elgato is
    // never opened twice: Connect tears the preview sidecar down, then starts the full one only after
    // this delay. In capture-card mode that must be the long release beat, never the fast decoder beat.
    AppConfigData cc;
    cc.videoSource = QStringLiteral("capture_card");
    QVERIFY(isCaptureCardSource(cc));
    QCOMPARE(sidecarRestartDelayMs(isCaptureCardSource(cc)), kSidecarRestartDelayMsCaptureCard);
}

void AutomationEngineTests::connectReusesWarmPreviewWhenSourceMatches()
{
    // The slow Connect tore down the warm preview sidecar (capture card + detector already live) and
    // cold-rebuilt a new one after the ~3s Elgato-release beat, all before Chiaki's cold start. When
    // the warm source == the connect source (both capture-card, where Chiaki is input-only and the
    // card is the video), the warm sidecar must be REUSED in place (start_stream cmd) — never rebuilt.

    // Warm capture-card preview + capture-card connect => reuse (the fast-path).
    QVERIFY(shouldReuseWarmSidecarForConnect(/*warmPreviewRunning=*/true,
                                             /*warmSourceIsCaptureCard=*/true,
                                             /*connectSourceIsCaptureCard=*/true));

    // No warm preview running => nothing to reuse; a fresh sidecar is correct.
    QVERIFY(!shouldReuseWarmSidecarForConnect(false, false, false));
    QVERIFY(!shouldReuseWarmSidecarForConnect(false, true, true));

    // Source CHANGED away from the capture card between preview and Connect => the feed genuinely
    // differs, so a full rebuild (not a reuse) is required for correctness.
    QVERIFY(!shouldReuseWarmSidecarForConnect(/*warmPreviewRunning=*/true,
                                              /*warmSourceIsCaptureCard=*/true,
                                              /*connectSourceIsCaptureCard=*/false));

    // Drive the decision through the real AppConfig source predicate to lock the wiring: a
    // capture-card config connecting over a warm preview reuses; a decoder config does not.
    AppConfigData cc;
    cc.videoSource = QStringLiteral("capture_card");
    QVERIFY(shouldReuseWarmSidecarForConnect(true, true, isCaptureCardSource(cc)));
    AppConfigData decoder;
    decoder.videoSource = QStringLiteral("decoder");
    QVERIFY(!shouldReuseWarmSidecarForConnect(true, true, isCaptureCardSource(decoder)));
}

void AutomationEngineTests::boundedEnumerationReturnsFreshNamesWhenFast()
{
    // Fix 2: when the DirectShow enumeration returns promptly (the normal, uncontended case) the
    // fresh names are used verbatim — existing behavior preserved.
    const QStringList fallback{ QStringLiteral("CACHED") };
    const QStringList fresh = runBoundedEnumeration(
        1000, fallback,
        []() { return QStringList{ QStringLiteral("Elgato HD60 X"), QStringLiteral("Integrated Webcam") }; });
    QCOMPARE(fresh.size(), 2);
    QCOMPARE(fresh.first(), QStringLiteral("Elgato HD60 X"));
    QVERIFY(fresh != fallback);
}

void AutomationEngineTests::boundedEnumerationFallsBackWithoutBlockingWhenSlow()
{
    // Fix 2, the core anti-SAFE-MODE guarantee: a wedged (contended-Elgato) enumeration must NOT
    // block the caller past the deadline — it returns the cached fallback promptly instead of
    // freezing the GUI thread for the full (10-15s live) stall.
    const QStringList fallback{ QStringLiteral("Elgato HD60 X (cached)") };
    QElapsedTimer timer;
    timer.start();
    const QStringList names = runBoundedEnumeration(
        100, fallback,
        []() {
            std::this_thread::sleep_for(std::chrono::milliseconds(600));  // simulate a wedged device
            return QStringList{ QStringLiteral("SHOULD-NOT-APPEAR") };
        });
    const qint64 elapsed = timer.elapsed();
    QCOMPARE(names, fallback);  // reused the cached names, not the wedged result
    QVERIFY2(elapsed < 450,     // returned near the 100ms deadline, not after the 600ms stall
             qPrintable(QStringLiteral("bounded enumeration blocked %1 ms (must be < 450)").arg(elapsed)));
}

void AutomationEngineTests::videoInputStableIdsAreOpaqueAndDeterministic()
{
    const QString rawMoniker = QStringLiteral(
        R"(@device:pnp:\\?\usb#vid_0fd9&pid_0080#SERIAL-DO-NOT-EXPORT#{camera-guid}\global)");
    const QString id = stableVideoInputDeviceId(rawMoniker);

    QVERIFY(id.startsWith(QStringLiteral("dshow-moniker-sha256-v1:")));
    QCOMPARE(id.size(), QStringLiteral("dshow-moniker-sha256-v1:").size() + 64);
    QVERIFY(!id.contains(QStringLiteral("SERIAL-DO-NOT-EXPORT"), Qt::CaseInsensitive));
    QCOMPARE(id, stableVideoInputDeviceId(
                     QStringLiteral("  %1  ").arg(rawMoniker.toUpper())));
    QVERIFY(id != stableVideoInputDeviceId(
                      QStringLiteral(R"(@device:pnp:\\?\usb#vid_0fd9&pid_0080#OTHER)")));
    QVERIFY(stableVideoInputDeviceId(QString()).isEmpty());
}

void AutomationEngineTests::videoInputInventoryPreservesEveryDeviceIndex()
{
    VideoInputDeviceInventory inventory;
    appendVideoInputDevice(
        inventory, QStringLiteral("Elgato HD60 X"),
        QStringLiteral(R"(@device:pnp:\\?\usb#vid_0fd9&pid_0080#card-a)"));
    // Simulate BindToStorage/GetDisplayName failure. DirectShow still consumed
    // index 1, so Orion must retain an explicit placeholder at that index.
    appendVideoInputDevice(inventory, QString(), QString());
    appendVideoInputDevice(
        inventory, QStringLiteral("Integrated Camera"),
        QStringLiteral(R"(@device:pnp:\\?\usb#vid_1234&pid_abcd#camera-b)"));

    QVERIFY(inventory.isAligned());
    QCOMPARE(inventory.friendlyNames.size(), 3);
    QCOMPARE(inventory.stableIds.size(), 3);
    QCOMPARE(inventory.friendlyNames.at(1), QStringLiteral("Unknown device"));
    QVERIFY(inventory.stableIds.at(1).isEmpty());
    QVERIFY(!inventory.stableIds.at(0).isEmpty());
    QVERIFY(inventory.stableIds.at(0) != inventory.stableIds.at(2));

    // The child environment uses `|` with KeepEmptyParts semantics. A failed
    // identity never shifts the later webcam into the selected card's index.
    const QString wire = inventory.stableIds.join(QLatin1Char('|'));
    QCOMPARE(wire.split(QLatin1Char('|'), Qt::KeepEmptyParts), inventory.stableIds);

    QProcessEnvironment environment;
    environment.insert(QStringLiteral("ORION_VIDEO_DEVICE_NAMES"),
                       QStringLiteral("caller-poisoned-name"));
    environment.insert(QStringLiteral("ORION_VIDEO_DEVICE_IDS"),
                       QStringLiteral("caller-poisoned-id"));
    QVERIFY(insertVideoInputDeviceEnvironment(environment, inventory));
    QCOMPARE(environment.value(QStringLiteral("ORION_VIDEO_DEVICE_NAMES")),
             inventory.friendlyNames.join(QLatin1Char('|')));
    QCOMPARE(environment.value(QStringLiteral("ORION_VIDEO_DEVICE_IDS")), wire);

    VideoInputDeviceInventory malformed = inventory;
    malformed.stableIds.removeLast();
    QVERIFY(!insertVideoInputDeviceEnvironment(environment, malformed));
    QVERIFY(!environment.contains(QStringLiteral("ORION_VIDEO_DEVICE_NAMES")));
    QVERIFY(!environment.contains(QStringLiteral("ORION_VIDEO_DEVICE_IDS")));
}

void AutomationEngineTests::boundedEnumerationTimeoutAfterSwapStripsStableIdentity()
{
    VideoInputDeviceInventory cachedCardA;
    appendVideoInputDevice(
        cachedCardA, QStringLiteral("Same Model Capture Card"),
        QStringLiteral(R"(@device:pnp:\\?\usb#vid_0001&pid_0001#physical-card-a)"));
    const QString cardAId = cachedCardA.stableIds.first();

    const VideoInputDeviceInventory result = runBoundedEnumeration(
        30, cachedCardA.namesOnlyFallback(),
        []() {
            // Card A was unplugged and same-model card B now owns index 0, but
            // its enumeration is contended past the launch deadline.
            std::this_thread::sleep_for(std::chrono::milliseconds(250));
            VideoInputDeviceInventory physicalCardB;
            appendVideoInputDevice(
                physicalCardB, QStringLiteral("Same Model Capture Card"),
                QStringLiteral(R"(@device:pnp:\\?\usb#vid_0001&pid_0001#physical-card-b)"));
            return physicalCardB;
        });

    QCOMPARE(result.friendlyNames, cachedCardA.friendlyNames);
    QVERIFY(result.isAligned());
    QVERIFY(!result.hasAnyStableId());
    QVERIFY(!result.stableIds.contains(cardAId));

    QProcessEnvironment environment;
    environment.insert(QStringLiteral("ORION_VIDEO_DEVICE_IDS"), cardAId);
    QVERIFY(insertVideoInputDeviceEnvironment(environment, result));
    QCOMPARE(environment.value(QStringLiteral("ORION_VIDEO_DEVICE_NAMES")),
             QStringLiteral("Same Model Capture Card"));
    QVERIFY(!environment.contains(QStringLiteral("ORION_VIDEO_DEVICE_IDS")));
}

void AutomationEngineTests::winMmSonyButtonMappingAndPov()
{
    // WinMM fallback route: the generic PC-joystick driver surfaces DualSense/DualShock
    // buttons in HID usage order (btn1=Square btn2=Cross btn3=Circle btn4=Triangle ...).
    // Regression guard: these were once mapped in XBOX A/B/X/Y order, which scrambled the
    // face buttons whenever WinMM carried a live session (2026-07: Circle acted as Square,
    // Square as Cross, Cross as Circle — and the phantom Square armed the autogreen hold).
    const auto sampleFor = [](uint32_t dwButtons, uint32_t dwPov) {
        ControllerState s;
        applyWinMmButtonsToSample(dwButtons, dwPov, s);
        return s;
    };
    constexpr uint32_t kPovCentered = 0xFFFFu;

    // Face buttons, one bit at a time, in Sony HID order.
    QVERIFY(sampleFor(0x0001u, kPovCentered).square());    // btn1 -> Square
    QVERIFY(sampleFor(0x0002u, kPovCentered).cross());     // btn2 -> Cross
    QVERIFY(sampleFor(0x0004u, kPovCentered).circle());    // btn3 -> Circle
    QVERIFY(sampleFor(0x0008u, kPovCentered).triangle());  // btn4 -> Triangle
    QCOMPARE(int(sampleFor(0x0001u, kPovCentered).buttons), int(XINPUT_GAMEPAD_X));
    QCOMPARE(int(sampleFor(0x0002u, kPovCentered).buttons), int(XINPUT_GAMEPAD_A));
    QCOMPARE(int(sampleFor(0x0004u, kPovCentered).buttons), int(XINPUT_GAMEPAD_B));
    QCOMPARE(int(sampleFor(0x0008u, kPovCentered).buttons), int(XINPUT_GAMEPAD_Y));
    // The exact live regression: Circle/Cross must never read as Square, Square not as Cross.
    QVERIFY(!sampleFor(0x0004u, kPovCentered).square());
    QVERIFY(!sampleFor(0x0002u, kPovCentered).square());
    QVERIFY(!sampleFor(0x0001u, kPovCentered).cross());

    // Shoulders / triggers / meta / stick clicks / PS / touchpad in Sony HID order.
    QVERIFY(sampleFor(0x0010u, kPovCentered).l1());                  // btn5  L1
    QVERIFY(sampleFor(0x0020u, kPovCentered).r1());                  // btn6  R1
    QCOMPARE(int(sampleFor(0x0040u, kPovCentered).l2), 255);         // btn7  L2
    QCOMPARE(int(sampleFor(0x0080u, kPovCentered).r2), 255);         // btn8  R2
    QVERIFY(sampleFor(0x0100u, kPovCentered).create());              // btn9  Create/Share
    QVERIFY(sampleFor(0x0200u, kPovCentered).options());             // btn10 Options
    QVERIFY((sampleFor(0x0400u, kPovCentered).buttons & XINPUT_GAMEPAD_LEFT_THUMB) != 0);   // btn11 L3
    QVERIFY((sampleFor(0x0800u, kPovCentered).buttons & XINPUT_GAMEPAD_RIGHT_THUMB) != 0);  // btn12 R3
    QVERIFY(sampleFor(0x1000u, kPovCentered).ps());                  // btn13 PS
    QVERIFY(sampleFor(0x2000u, kPovCentered).touchpad);              // btn14 Touchpad

    // POV hat -> dpad nibble + XINPUT dpad bits. dwPOV is hundredths of a degree from up.
    QCOMPARE(sampleFor(0u, kPovCentered).dpad, 8);   // centered (WORD form)
    QCOMPARE(sampleFor(0u, 0xFFFFFFFFu).dpad, 8);    // centered (drivers that return DWORD -1)
    QCOMPARE(int(sampleFor(0u, 0xFFFFFFFFu).buttons), 0);
    QCOMPARE(sampleFor(0u, 0u).dpad, 0);             // up
    QVERIFY((sampleFor(0u, 0u).buttons & XINPUT_GAMEPAD_DPAD_UP) != 0);
    QCOMPARE(sampleFor(0u, 4500u).dpad, 1);          // up-right
    QCOMPARE(sampleFor(0u, 9000u).dpad, 2);          // right
    QVERIFY((sampleFor(0u, 9000u).buttons & XINPUT_GAMEPAD_DPAD_RIGHT) != 0);
    QCOMPARE(sampleFor(0u, 18000u).dpad, 4);         // down
    QVERIFY((sampleFor(0u, 18000u).buttons & XINPUT_GAMEPAD_DPAD_DOWN) != 0);
    QCOMPARE(sampleFor(0u, 27000u).dpad, 6);         // left
    QVERIFY((sampleFor(0u, 27000u).buttons & XINPUT_GAMEPAD_DPAD_LEFT) != 0);
    QCOMPARE(sampleFor(0u, 35900u).dpad, 0);         // wraps back to up
}

