void AutomationEngineTests::releaseMarkerEmittedWithEpochOnRelease()
{
    // RC-3: every release must push a release_marker (seq + wall-clock EPOCH ms) so the sidecar's
    // frozen-meter latency oracle can close. The oracle never measured before because this timestamp
    // was never emitted from the native side (which owns the controller live).
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    LearningData learning;
    engine.applyConfig(config, learning);
    QSignalSpy spy(&engine, &AutomationEngine::releaseMarker);
    const int seq = driveStandstillToRelease(engine);
    QVERIFY2(seq > 0, "the shot must release so a marker can be pushed");
    QCOMPARE(spy.count(), 1);
    const QList<QVariant> args = spy.takeFirst();
    QCOMPARE(args.at(0).toInt(), seq);                          // seq pairs the marker to the release
    QVERIFY2(args.at(1).toDouble() > 1.0e12,
             "wall_ms must be a real epoch-ms timestamp (same clock as the sidecar fill samples)");
    QCOMPARE(args.at(2).toBool(), false);
}



void AutomationEngineTests::blindFireSuppressedOnRejectedFrameWhenEnabled()
{
    // RC-3/C3: a feedforward CLOCK fire that lands on a rejected/no-fill frame (the live seq=18: presence
    // rejected, conf 0, fill 0, no meter ever seen) is a drifted clock on a dead frame. With the flag ON
    // it is suppressed (no release this tick); with it OFF the current blind fire still happens.
    auto releaseSeqBlindClock = [](bool suppress) -> int {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.blindFireSuppressEnabled = suppress;
        LearningData learning;
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);   // armed hold clock
        engine.applyConfig(config, learning);
        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        engine.process(physical);
        engine.advanceTestClock(220);
        engine.process(physical);            // -> Holding, holdStart set
        DetectionResult rejected;            // detected=false, fill 0, conf 0 -> presence "rejected"
        rejected.detected = false;
        rejected.fillPct = 0.0;
        rejected.confidence = 0.0;
        rejected.frameAgeMs = 6.0;
        for (int i = 0; i < 80 && engine.context().releaseSeq == 0
                        && engine.context().state == HoldState::Holding; ++i) {
            engine.advanceTestClock(10);     // stays well under the 1500ms no-meter cap
            engine.updateDetection(rejected);
            engine.process(physical);
        }
        return engine.context().releaseSeq;
    };
    QCOMPARE(releaseSeqBlindClock(false), 0);
    QCOMPARE(releaseSeqBlindClock(true), 0);

    // Suppression must NOT block a normal fresh-vision release (fresh-then-fires).
    AutomationEngine live;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.blindFireSuppressEnabled = true;
    LearningData learning;
    live.applyConfig(config, learning);
    QVERIFY2(driveStandstillToRelease(live) > 0,
             "suppression must not block a normal fresh-vision release");
}

void AutomationEngineTests::priorPosteriorBlendDegradesToClockAndConvergesToVision()
{
    // C2: the inverse-variance fuse of the clock PRIOR and the vision POSTERIOR must (a) equal the pure
    // clock when vision is unusable / zero-confidence (never degrade below pure clock), (b) sit between
    // the clock and the vision crossing at mid confidence, and (c) converge to the vision crossing as the
    // vision noise -> 0.
    const double clockDue = 1000.0;
    const double visionFireAt = 1080.0;      // confident vision says fire 80ms later than the clock
    const double priorSd = 45.0, base = 20.0, maxSd = 400.0;
    // (a) no usable vision -> EXACTLY the pure clock.
    QCOMPARE(AutomationEngine::blendedFireDeadlineMs(clockDue, visionFireAt, false, 1.0, priorSd, base, maxSd),
             clockDue);
    // zero confidence -> vision variance maxed -> ~pure clock.
    const double lowConf = AutomationEngine::blendedFireDeadlineMs(
        clockDue, visionFireAt, true, 0.0, priorSd, base, maxSd);
    QVERIFY2(std::abs(lowConf - clockDue) < 2.0,
             qPrintable(QStringLiteral("confidence 0 must fuse to ~the pure clock; got %1").arg(lowConf)));
    // (b) mid confidence -> the fuse lies between the clock and the vision crossing.
    const double mid = AutomationEngine::blendedFireDeadlineMs(
        clockDue, visionFireAt, true, 0.6, priorSd, base, maxSd);
    QVERIFY2(mid >= clockDue && mid <= visionFireAt,
             qPrintable(QStringLiteral("the fused deadline must lie between clock and vision; got %1").arg(mid)));
    // (c) vision noise -> 0 (tiny base SD, full confidence) -> converge to the vision crossing.
    const double converged = AutomationEngine::blendedFireDeadlineMs(
        clockDue, visionFireAt, true, 1.0, priorSd, /*base=*/0.5, maxSd);
    QVERIFY2(std::abs(converged - visionFireAt) < 1.0,
             qPrintable(QStringLiteral("as vision noise->0 the fuse must converge to the vision crossing; got %1")
                            .arg(converged)));
}

// --- Preview smoothness: FrameDecoder async JPEG decode ---------------------------------------

namespace {
// Encode a solid-color test image to base64 JPEG the way the sidecar's preview line carries it.
QByteArray makeBase64Jpeg(int w, int h, const QColor& color)
{
    QImage src(w, h, QImage::Format_RGB32);
    src.fill(color);
    QByteArray jpeg;
    QBuffer buf(&jpeg);
    buf.open(QIODevice::WriteOnly);
    src.save(&buf, "JPEG", 90);
    buf.close();
    return jpeg.toBase64();
}
} // namespace

void AutomationEngineTests::frameDecoderDecodesOffThreadAndDeliversReadyImage()
{
    FrameDecoder decoder;
    const QThread* ownerThread = QThread::currentThread();

    QImage received;
    QThread* deliveryThread = nullptr;
    int receivedFrameNumber = -999;
    bool got = false;
    QObject::connect(&decoder, &FrameDecoder::decoded, &decoder,
                     [&](const QImage& img, int frameNumber) {
                         received = img;
                         receivedFrameNumber = frameNumber;
                         deliveryThread = QThread::currentThread();
                         got = true;
                     });

    const QByteArray payload = makeBase64Jpeg(1280, 720, QColor(12, 200, 90));
    decoder.submit(payload, 4242);

    // Spin the owner event loop until the queued decoded() lands (worker thread does the decode).
    QElapsedTimer timer;
    timer.start();
    while (!got && timer.elapsed() < 3000) {
        QCoreApplication::processEvents(QEventLoop::AllEvents, 20);
    }

    QVERIFY2(got, "FrameDecoder must emit decoded() for a valid base64 JPEG");
    QCOMPARE(received.width(), 1280);
    QCOMPARE(received.height(), 720);
    // The ready image is delivered ON the owner (GUI) thread, so the GUI thread only swaps a decoded
    // frame — it never runs the JPEG IDCT itself.
    QCOMPARE(deliveryThread, ownerThread);
    QCOMPARE(decoder.decodedCount(), quint64(1));
    // FRAME-ID JOIN: the decoder frame number submitted with the payload is carried through the
    // worker and re-emitted with decoded(), so the overlay can join the bbox to this exact frame.
    QCOMPARE(receivedFrameNumber, 4242);
}

void AutomationEngineTests::frameDecoderDropsOldestUnderBurst()
{
    FrameDecoder decoder;

    int deliveredCount = 0;
    QImage last;
    QObject::connect(&decoder, &FrameDecoder::decoded, &decoder,
                     [&](const QImage& img) { last = img; ++deliveredCount; });

    // Pre-encode ONE payload so the burst loop is just a mutex store + notify (microseconds) — far
    // faster than a JPEG decode — guaranteeing most submits land while the worker is still busy on an
    // earlier one. Encoding per-iteration on the main thread would (wrongly) pace the producer to the
    // consumer and hide the drop behavior. Fire synchronously (no event-loop turns between submits).
    const QByteArray payload = makeBase64Jpeg(1280, 720, QColor(20, 60, 200));
    const int burst = 200;
    for (int i = 0; i < burst; ++i) {
        decoder.submit(payload, i);
    }

    // Wait for the decoder to fully quiesce (every submit either decoded or dropped — nothing in
    // flight) so the accounting invariant is measured at rest, not mid-decode.
    QElapsedTimer timer;
    timer.start();
    while (decoder.decodedCount() + decoder.droppedCount() < quint64(burst)
           && timer.elapsed() < 3000) {
        QCoreApplication::processEvents(QEventLoop::AllEvents, 20);
    }
    // Flush any trailing queued decoded() deliveries to the lambda.
    for (int i = 0; i < 5; ++i) {
        QCoreApplication::processEvents(QEventLoop::AllEvents, 20);
    }

    QCOMPARE(decoder.submittedCount(), quint64(burst));
    // At least one frame decoded, and the mailbox dropped the middle of the burst (bounded backlog):
    // decoded frames must be far fewer than submitted.
    QVERIFY2(decoder.decodedCount() >= 1, "at least one burst frame must decode");
    QVERIFY2(decoder.droppedCount() > 0, "drop-oldest must discard superseded burst frames");
    QVERIFY2(decoder.decodedCount() < quint64(burst),
             "a burst must not decode every frame — the queue is 1-deep drop-oldest");
    QCOMPARE(decoder.submittedCount(), decoder.decodedCount() + decoder.droppedCount());
    QVERIFY(deliveredCount >= 1);
}

void AutomationEngineTests::frameDecoderPresentationMailboxIsBoundedAndNewestWins()
{
    FrameDecoder decoder;
    int deliveredCount = 0;
    int deliveredFrame = -1;
    QObject::connect(&decoder, &FrameDecoder::decoded, &decoder,
                     [&](const QImage&, int frameNumber) {
                         ++deliveredCount;
                         deliveredFrame = frameNumber;
                     });

    // Let each input decode fully while deliberately NOT pumping the owner/GUI
    // event loop. The first decode queues one wake-up; every later decoded image
    // must replace the one-slot presentation mailbox instead of queuing another
    // QImage-owning callback.
    const QByteArray payload = makeBase64Jpeg(320, 180, QColor(90, 40, 210));
    constexpr int kFrames = 8;
    for (int i = 0; i < kFrames; ++i) {
        decoder.submit(payload, 100 + i);
        QElapsedTimer timer;
        timer.start();
        while (decoder.decodedCount() < quint64(i + 1) && timer.elapsed() < 3000) {
            QThread::msleep(1);
        }
        QCOMPARE(decoder.decodedCount(), quint64(i + 1));
    }

    const FrameDecoderStats beforeDelivery = decoder.stats();
    QCOMPARE(beforeDelivery.submitted, quint64(kFrames));
    QCOMPARE(beforeDelivery.decodeMailboxDropped, quint64(0));
    QCOMPARE(beforeDelivery.decoded, quint64(kFrames));
    QCOMPARE(beforeDelivery.presented, quint64(0));
    QCOMPARE(beforeDelivery.presentationMailboxDropped, quint64(kFrames - 1));
    QCOMPARE(deliveredCount, 0);

    QElapsedTimer deliveryTimer;
    deliveryTimer.start();
    while (deliveredCount == 0 && deliveryTimer.elapsed() < 3000) {
        QCoreApplication::processEvents(QEventLoop::AllEvents, 20);
    }
    QCOMPARE(deliveredCount, 1);
    QCOMPARE(deliveredFrame, 100 + kFrames - 1);

    const FrameDecoderStats afterDelivery = decoder.stats();
    QCOMPARE(afterDelivery.presented, quint64(1));
    QCOMPARE(afterDelivery.presentationMailboxDropped, quint64(kFrames - 1));
    QCOMPARE(afterDelivery.decoded,
             afterDelivery.presented + afterDelivery.presentationMailboxDropped);
}

void AutomationEngineTests::frameDecoderIgnoresGarbageWithoutEmitting()
{
    FrameDecoder decoder;
    bool got = false;
    QObject::connect(&decoder, &FrameDecoder::decoded, &decoder,
                     [&](const QImage&) { got = true; });

    decoder.submit(QByteArrayLiteral("!!!! not base64 !!!!"), 1);
    decoder.submit(QByteArray("hello world, not a jpeg").toBase64(), 2);

    QElapsedTimer timer;
    timer.start();
    while (timer.elapsed() < 500) {
        QCoreApplication::processEvents(QEventLoop::AllEvents, 20);
    }
    QVERIFY2(!got, "non-JPEG payloads must be dropped, never emitted (no crash, no partial frame)");
    QCOMPARE(decoder.decodedCount(), quint64(0));
}

void AutomationEngineTests::previewChunksReassembleStrictlyInOrder()
{
    PreviewFrameChunkAssembler chunks;
    const auto first = chunks.push(1001, 42, 0, 3, QByteArrayView("QUJD", 4));
    QVERIFY(first.accepted);
    QVERIFY(!first.complete);
    QCOMPARE(chunks.nextChunk(), 1);

    // A telemetry line is handled outside the assembler; leaving it idle must not
    // disturb the in-order preview state between stdout records.
    const auto second = chunks.push(1001, 42, 1, 3, QByteArrayView("REVG", 4));
    QVERIFY(second.accepted);
    QVERIFY(!second.complete);
    const auto third = chunks.push(1001, 42, 2, 3, QByteArrayView("Rw==", 4));
    QVERIFY(third.accepted);
    QVERIFY(third.complete);
    QCOMPARE(third.frameNumber, 42);
    QCOMPARE(third.jpegBase64, QByteArray("QUJDREVGRw=="));
    QCOMPARE(chunks.bufferedBytes(), qsizetype(0));
}

void AutomationEngineTests::previewChunksDropIncompleteOnNewerFrameAndEnforceCaps()
{
    PreviewFrameChunkAssembler chunks;
    QVERIFY(chunks.push(10, 20, 0, 2, QByteArrayView("old", 3)).accepted);
    QVERIFY(chunks.push(11, 21, 0, 2, QByteArrayView("new", 3)).accepted);

    // Late continuation of the superseded frame can never splice into frame 11.
    QVERIFY(!chunks.push(10, 20, 1, 2, QByteArrayView("bad", 3)).accepted);
    const auto complete = chunks.push(11, 21, 1, 2, QByteArrayView("est", 3));
    QVERIFY(complete.complete);
    QCOMPARE(complete.jpegBase64, QByteArray("newest"));

    QByteArray oversized(PreviewFrameChunkAssembler::kMaxChunkBytes + 1, 'A');
    QVERIFY(!chunks.push(12, 22, 0, 1, QByteArrayView(oversized)).accepted);
    QVERIFY(!chunks.push(12, 22, 0, PreviewFrameChunkAssembler::kMaxChunkCount + 1,
                         QByteArrayView("x", 1)).accepted);
    // Missing index zero is invalid; only a newer, complete sequence may recover.
    QVERIFY(!chunks.push(13, 23, 1, 2, QByteArrayView("x", 1)).accepted);
    QVERIFY(chunks.push(14, 0, 0, 1, QByteArrayView("ok", 2)).complete);
}

void AutomationEngineTests::previewChunkWireParserAvoidsJsonRoundTripAndRejectsMalformedRecords()
{
    const QByteArray line = QByteArrayLiteral(
        "{\"event\":\"frame_chunk\",\"frame_number\":42,\"chunk_frame_id\":1001,"
        "\"chunk_index\":1,\"chunk_count\":3,\"jpeg_b64\":\"REVG\"}");
    const PreviewFrameChunkWireRecord parsed = parsePreviewFrameChunkLine(QByteArrayView(line));
    QVERIFY(parsed.valid);
    QCOMPARE(parsed.frameNumber, 42);
    QCOMPARE(parsed.chunkFrameId, 1001);
    QCOMPARE(parsed.chunkIndex, 1);
    QCOMPARE(parsed.chunkCount, 3);
    QCOMPARE(parsed.payload, QByteArrayView("REVG", 4));

    // The fast path is deliberately exact. Unknown ordering/shape falls back to
    // QJsonDocument in RemotePlaySession; malformed bounds never reach reassembly.
    QVERIFY(!parsePreviewFrameChunkLine(QByteArrayView(
        "{\"event\":\"frame_chunk\",\"chunk_frame_id\":1}")).valid);
    QVERIFY(!parsePreviewFrameChunkLine(QByteArrayView(
        "{\"event\":\"frame_chunk\",\"frame_number\":42,\"chunk_frame_id\":1001,"
        "\"chunk_index\":3,\"chunk_count\":3,\"jpeg_b64\":\"REVG\"}")).valid);
    QVERIFY(!parsePreviewFrameChunkLine(QByteArrayView(
        "{\"event\":\"frame_chunk\",\"frame_number\":42,\"chunk_frame_id\":0,"
        "\"chunk_index\":0,\"chunk_count\":1,\"jpeg_b64\":\"REVG\"}")).valid);
}

void AutomationEngineTests::productionSidecarPolicyAlwaysRequiresCompiledExecutable()
{
    // Production cannot be redirected to omitted/plain Python modules by removing
    // an environment variable. Development preserves both source and opt-in modes.
    QVERIFY(shouldUseCompiledSidecar(true, false));
    QVERIFY(shouldUseCompiledSidecar(true, true));
    QVERIFY(!shouldUseCompiledSidecar(false, false));
    QVERIFY(shouldUseCompiledSidecar(false, true));

    // The production requirement is scoped to no-card Remote Play. Capture card
    // remains selected and development retains its explicit fallback lane.
    QVERIFY(shouldRequireRemotePlayFramePipe(true, false));
    QVERIFY(!shouldRequireRemotePlayFramePipe(true, true));
    QVERIFY(!shouldRequireRemotePlayFramePipe(false, false));
    QVERIFY(!shouldRequireRemotePlayFramePipe(false, true));

    // A capture-card OrionStream is input-only even if the parent inherited a
    // decoder-pipe request. No-card production requires export; development may
    // opt in explicitly. The 120 value is only a jitter-safe gate above a 60 Hz
    // source, not a request to synthesize or duplicate frames.
    QVERIFY(!shouldEnableRemotePlayFrameExport(true, true, true));
    QVERIFY(!shouldEnableRemotePlayFrameExport(true, false, true));
    QVERIFY(shouldEnableRemotePlayFrameExport(false, true, false));
    QVERIFY(shouldEnableRemotePlayFrameExport(false, false, true));
    QVERIFY(!shouldEnableRemotePlayFrameExport(false, false, false));
    QCOMPARE(kRemotePlayFrameExportGateFps, 120);

    QCOMPARE(streamWindowWatchdogIntervalMs(1'000, 35'000),
             kStreamWindowWatchdogFastMs);
    QCOMPARE(streamWindowWatchdogIntervalMs(35'000, 35'000),
             kStreamWindowWatchdogFastMs);
    QCOMPARE(streamWindowWatchdogIntervalMs(35'001, 35'000),
             kStreamWindowWatchdogSteadyMs);
    QCOMPARE(streamWindowWatchdogIntervalMs(1'000, 0),
             kStreamWindowWatchdogSteadyMs);
}

void AutomationEngineTests::meterBoxRingJoinsBboxToItsOwnFrame()
{
    // FRAME-ID JOIN: the overlay must draw the bbox that was detected on the EXACT preview frame it
    // is painting, not the latest bbox (which belongs to a newer frame and caused drift/flicker).
    MeterBoxRing ring;
    QVERIFY(ring.empty());

    // Record three detections on distinct decoder frames, sliding a clean 2px/frame in x AND y.
    const QRect box10(100, 200, 40, 12);
    const QRect box13(106, 206, 40, 12);   // +6px over 3 frames = 2px/frame
    const QRect box16(112, 212, 40, 12);   // +6px over 3 frames = 2px/frame
    ring.record(10, box10);
    QVERIFY(!ring.empty());
    ring.record(13, box13);
    ring.record(16, box16);

    QRect out;

    // 1) Exact match: frame N returns the box recorded for frame N, never extrapolated.
    QVERIFY2(ring.lookup(10, out), "exact frame must join");
    QCOMPARE(out, box10);
    QVERIFY(ring.lookup(16, out));
    QCOMPARE(out, box16);

    // 2) Between detections: a preview frame with no exact record joins the nearest EARLIER box
    //    VELOCITY-EXTRAPOLATED to this frame's position (never a later one — the box never jumps
    //    ahead of the picture). Frame 14 = box13 pushed 1 frame of slide (2px) -> (108,208). The
    //    old behaviour drew the STALE box13 as-is; extrapolation kills the visible trailing lag.
    QVERIFY2(ring.lookup(14, out), "an in-between frame within the window must join+extrapolate");
    QCOMPARE(out, QRect(108, 208, 40, 12));

    // 3) No recorded box for the frame -> return none (draw NOTHING rather than smear a stale box).
    //    Frame 5 predates every record; frame 99 is far beyond the join window past the newest (16).
    QVERIFY2(!ring.lookup(5, out), "a frame before any detection must return none");
    QVERIFY2(!ring.lookup(99, out), "a frame far beyond the newest detection must return none (no stale smear)");

    // The two-frame bridge advances only the centre; the third missing frame
    // clears instead of smearing a stale lock.
    QVERIFY(ring.lookup(16 + MeterBoxRing::kJoinWindow, out));
    QCOMPARE(out, QRect(116, 216, 40, 12));
    QVERIFY2(!ring.lookup(16 + MeterBoxRing::kJoinWindow + 1, out),
             "beyond the join window the newest box is too stale to draw");

    // 5) Invalid ids are ignored on record and rejected on lookup.
    QRect ignored;
    ring.record(-1, QRect(0, 0, 5, 5));
    QVERIFY2(!ring.lookup(-1, ignored), "a negative frame id never joins");

    // 6) A SINGLE detection can't measure velocity -> the box draws AS-IS (no extrapolation) on a
    //    later in-window frame, preserving the old nearest-earlier fallback when there's no history.
    MeterBoxRing lone;
    const QRect only(300, 400, 40, 12);
    lone.record(50, only);
    QVERIFY(lone.lookup(52, out));
    QCOMPARE(out, only);
    QVERIFY(!lone.lookup(53, out));

    // A noisy slide is capped per bridged frame so a torn sample cannot fling
    // the presentation lock across the preview.
    MeterBoxRing fast;
    fast.record(0, QRect(0, 0, 40, 12));
    fast.record(1, QRect(40, 0, 40, 12));    // 40px/frame in x
    QVERIFY(fast.lookup(1 + 2, out));
    QCOMPARE(out.x(), 40 + 2 * MeterBoxRing::kMaxBridgePxPerFrame);
    QCOMPARE(out.size(), QSize(40, 12));

    // Duplicate telemetry for one decoder frame replaces, rather than appends,
    // and a sidecar/session reset clears the old frame-id namespace completely.
    ring.record(16, QRect(120, 220, 40, 12));
    QVERIFY(ring.lookup(16, out));
    QCOMPARE(out, QRect(120, 220, 40, 12));
    ring.clear();
    QVERIFY(ring.empty());
    QVERIFY(!ring.lookup(16, out));
    ring.record(1, QRect(10, 20, 40, 12));
    QVERIFY(ring.lookup(1, out));
    QCOMPARE(out, QRect(10, 20, 40, 12));
}

void AutomationEngineTests::meterOverlayUsesGenuineBoxesAndAspectFitGeometry()
{
    DetectionResult r = readyMeterSample(60.0, -1.0);
    r.frameAgeMs = 10.0;
    QVERIFY(isGenuineMeterOverlayDetection(r, 50.0));
    r.rejectionReason = QStringLiteral("green_not_found");
    QVERIFY(isGenuineMeterOverlayDetection(r, 50.0));
    r.rejectionReason = QStringLiteral("stale_or_memory");
    QVERIFY(!isGenuineMeterOverlayDetection(r, 50.0));
    r.rejectionReason.clear();
    r.stage = QStringLiteral("coast");
    QVERIFY(!isGenuineMeterOverlayDetection(r, 50.0));
    r.stage.clear();
    r.staleFrame = true;
    QVERIFY(!isGenuineMeterOverlayDetection(r, 50.0));
    r.staleFrame = false;
    r.frameAgeMs = 51.0;
    QVERIFY(!isGenuineMeterOverlayDetection(r, 50.0));
    // A release event is not an overlay-invalidating event. If the detector is
    // still genuinely tracking the receding meter, freshness remains authority
    // for the box (there is intentionally no post-release blackout input here).
    r.frameAgeMs = 10.0;
    r.fillPct = 84.7;
    r.stage = QStringLiteral("track");
    r.rejectionReason.clear();
    QVERIFY(isGenuineMeterOverlayDetection(r, 50.0));
    QCOMPARE(meterOverlayBoxAction(true, true),
             MeterOverlayBoxAction::UpdateFromJoinedBox);
    QCOMPARE(meterOverlayBoxAction(true, false),
             MeterOverlayBoxAction::Clear);
    QCOMPARE(meterOverlayBoxAction(false, true),
             MeterOverlayBoxAction::Clear);

    // 16:9 capture in a 4:3 preview is letterboxed: one 0.8 scale
    // on both axes and a 96px vertical offset. Width/height never stretch.
    QCOMPARE(mapCaptureBoxAspectFit(QRect(100, 200, 40, 20),
                                    QSize(1280, 720), QSize(1024, 768)),
             QRect(80, 256, 32, 16));
    QCOMPARE(mapCaptureBoxAspectFit(QRect(300, 150, 90, 30),
                                    QSize(1920, 1080), QSize(1280, 720)),
             QRect(200, 100, 60, 20));
    QCOMPARE(mapCaptureBoxAspectFit(QRect(10, 20, 30, 40),
                                    QSize(1280, 720), QSize(1280, 720)),
             QRect(10, 20, 30, 40));
    // Transform both edges and round outward. Independently rounding x/width
    // clipped this 3px source box to 2px at the 0.8 letterbox scale.
    QCOMPARE(mapCaptureBoxAspectFit(QRect(0, 0, 3, 3),
                                    QSize(1280, 720), QSize(1024, 768)),
             QRect(0, 96, 3, 3));
}

void AutomationEngineTests::meterOverlayContinuityLeaseIsShotScopedAndFailClosed()
{
    constexpr quint64 epoch = 91;
    constexpr qint64 startMs = 10'000;
    MeterOverlayContinuityLease lease;

    DetectionResult genuine = readyMeterSample(42.0, -1.0);
    genuine.frameAgeMs = 6.0;
    genuine.frameNumber = 100;
    genuine.stage = QStringLiteral("track");
    genuine.gameplayStructureVerified = true;
    genuine.gameplayStructureEpoch = epoch;
    QCOMPARE(lease.observe(genuine, 50.0, startMs, true, epoch, true, true),
             MeterOverlayContinuityObservation::GenuineStructural);
    QVERIFY(lease.active());
    QCOMPARE(lease.shotEpoch(), epoch);

    // Fill is rejected, position is reader-trusted. It may move the visual box
    // only under the already-proven shot lease and may not extend its deadline.
    DetectionResult trusted = genuine;
    trusted.frameNumber++;
    trusted.x += 40;
    trusted.rejectionReason = QStringLiteral("strip_truncated");
    trusted.gameplayStructureVerified = false;
    trusted.gameplayStructureEpoch = 0;
    QCOMPARE(lease.observe(trusted, 50.0, startMs + 300,
                           true, epoch, true, true),
             MeterOverlayContinuityObservation::TrustedPosition);
    QVERIFY(lease.maintain(startMs + MeterOverlayContinuityLease::kMaxContinuityMs,
                           true, epoch, true));
    QVERIFY(!lease.maintain(startMs + MeterOverlayContinuityLease::kMaxContinuityMs + 1,
                            true, epoch, true));

    // A trusted-looking payload cannot create a lease by itself.
    QCOMPARE(lease.observe(trusted, 50.0, startMs + 700,
                           true, epoch, true, true),
             MeterOverlayContinuityObservation::None);
    QVERIFY(!lease.active());

    // Reacquire, then prove every hard boundary is immediate: disarm, physical
    // epoch change, or source/integrity failure. Duplicate frames never refresh.
    QCOMPARE(lease.observe(genuine, 50.0, startMs + 800,
                           true, epoch, true, true),
             MeterOverlayContinuityObservation::GenuineStructural);
    QCOMPARE(lease.observe(genuine, 50.0, startMs + 900,
                           true, epoch, true, false),
             MeterOverlayContinuityObservation::None);
    QVERIFY(lease.maintain(startMs + 900, true, epoch, true));
    QVERIFY(!lease.maintain(startMs + 901, false, epoch, true));

    QCOMPARE(lease.observe(genuine, 50.0, startMs + 1'000,
                           true, epoch, true, true),
             MeterOverlayContinuityObservation::GenuineStructural);
    QVERIFY(!lease.maintain(startMs + 1'001, true, epoch + 1, true));
    QCOMPARE(lease.observe(genuine, 50.0, startMs + 1'100,
                           true, epoch, true, true),
             MeterOverlayContinuityObservation::GenuineStructural);
    QVERIFY(!lease.maintain(startMs + 1'101, true, epoch, false));

    // Coast/memory remains ineligible even under an active lease.
    QCOMPARE(lease.observe(genuine, 50.0, startMs + 1'200,
                           true, epoch, true, true),
             MeterOverlayContinuityObservation::GenuineStructural);
    trusted.rejectionReason = QStringLiteral("meter_memory");
    trusted.stage = QStringLiteral("coast");
    QCOMPARE(lease.observe(trusted, 50.0, startMs + 1'220,
                           true, epoch, true, true),
             MeterOverlayContinuityObservation::None);
}

void AutomationEngineTests::meterOverlayPresentationTrackerIsBoundedContainedAndResettable()
{
    const QSize preview(1280, 720);
    MeterOverlayPresentationTracker tracker;

    const QRect firstRaw(100, 300, 18, 64);
    const QRect firstDrawn = tracker.update(firstRaw, 7, preview, 100);
    QVERIFY(tracker.valid());
    QCOMPARE(firstDrawn, firstRaw);
    QVERIFY(firstDrawn.width() < firstDrawn.height());

    // Every genuine observation is authoritative. Even a one-pixel move is
    // rendered on its exact joined frame rather than delayed by a deadband.
    const QRect jitterRaw(101, 300, 18, 64);
    const QRect jitterDrawn = tracker.update(jitterRaw, 7, preview, 101);
    QCOMPARE(jitterDrawn, jitterRaw);

    QRect previous = jitterDrawn;
    for (int i = 1; i <= 8; ++i) {
        const QRect raw(101 + i * 3, 300 + i, 18, 64);
        const QRect drawn = tracker.update(raw, 7, preview, 101 + i);
        QCOMPARE(drawn, raw);
        QVERIFY(drawn.x() >= previous.x());
        QVERIFY(drawn.y() >= previous.y());
        previous = drawn;
    }

    // A large detector jump is a new visual identity, not motion to trail across the court.
    const QRect jumpedRaw(700, 120, 18, 64);
    const QRect jumpedDrawn = tracker.update(jumpedRaw, 7, preview, 110);
    QCOMPARE(jumpedDrawn, jumpedRaw);

    // A new physical shot token also snaps immediately even when the displacement is small
    // enough that an ordinary update would be smoothed.
    const QRect nextShotRaw(706, 124, 18, 64);
    const QRect nextShotDrawn = tracker.update(nextShotRaw, 8, preview, 111);
    QCOMPARE(nextShotDrawn, nextShotRaw);

    // Detector extent changes are shown immediately and exactly.
    const QRect sizeJitterRaw(708, 124, 20, 66);
    const QRect sizeJitterDrawn = tracker.update(sizeJitterRaw, 8, preview, 112);
    QCOMPARE(sizeJitterDrawn, sizeJitterRaw);

    // Growth cannot be hidden by a previous presentation size.
    const QRect guardExhaustedRaw(709, 124, 20, 72);
    const QRect guardExhaustedDrawn = tracker.update(guardExhaustedRaw, 8, preview, 113);
    QCOMPARE(guardExhaustedDrawn, guardExhaustedRaw);

    const QRect shapeCutRaw(710, 124, 34, 110);
    const QRect shapeCutDrawn = tracker.update(shapeCutRaw, 8, preview, 114);
    QCOMPARE(shapeCutDrawn, shapeCutRaw);

    const QRect afterGapRaw(716, 128, 34, 110);
    const QRect afterGapDrawn = tracker.update(afterGapRaw, 8, preview, 121);
    QCOMPARE(afterGapDrawn, afterGapRaw);

    tracker.reset();
    QVERIFY(!tracker.valid());
    const QRect relockRaw(200, 500, 12, 48);
    const QRect relockDrawn = tracker.update(relockRaw, 9, preview, 1);
    QCOMPARE(relockDrawn, relockRaw);

    // A malformed out-of-bounds rectangle is clipped, never shifted onto
    // unrelated pixels or inflated to preserve its old dimensions.
    QCOMPARE(tracker.update(QRect(-3, 710, 10, 20), 9, preview, 2),
             QRect(0, 710, 7, 10));
}

// ===================== Phase-2 #8: earlier-only console-tick snap =========================

void AutomationEngineTests::fusedTickSnapEarlierOnlyRespectsEpsilon()
{
    // [Phase-2 A2(c)] The snap floors the fused deadline to the latest instant whose press
    // arrives epsilon BEFORE an input-tick edge: earlier-only (never later than unsnapped,
    // never more than one tick earlier), exact target phase, and inert on invalid inputs.
    const double P = 1000.0 / 60.0;
    const double eps = 5.5;
    const double edges[] = { 0.0, 3.7, 5.0, 12.2 };
    const double fires[] = { 1000.0, 1003.3, 1009.99, 1016.0, 250000.25 };
    for (const double edge : edges) {
        for (const double tFire : fires) {
            const double snapped = AutomationEngine::earlierOnlyTickSnapMs(tFire, edge, eps, P);
            QVERIFY2(snapped <= tFire + 1e-9,
                     qPrintable(QStringLiteral("earlier-only violated: t=%1 edge=%2 snapped=%3")
                                    .arg(tFire).arg(edge).arg(snapped)));
            QVERIFY2(tFire - snapped < P + 1e-9,
                     qPrintable(QStringLiteral("snap must stay within one tick: shift=%1")
                                    .arg(tFire - snapped)));
            // Epsilon respected: the snapped press phase sits exactly (edge - eps) mod P.
            double ph = std::fmod(snapped - (edge - eps), P);
            if (ph < 0.0) {
                ph += P;
            }
            const double phaseErr = std::min(ph, P - ph);
            QVERIFY2(phaseErr < 1e-6,
                     qPrintable(QStringLiteral("press phase must land eps before the edge; err=%1")
                                    .arg(phaseErr)));
        }
    }
    // A deadline already ON the target phase is untouched (no churn).
    const double onPhase = 120.0 * P + (5.0 - eps);
    QCOMPARE(AutomationEngine::earlierOnlyTickSnapMs(onPhase, 5.0, eps, P), onPhase);
    // Invalid inputs -> unchanged (telemetry not ready / garbage never moves a deadline).
    QCOMPARE(AutomationEngine::earlierOnlyTickSnapMs(1000.0, 5.0, eps, 0.0), 1000.0);
    QCOMPARE(AutomationEngine::earlierOnlyTickSnapMs(1000.0, 5.0, eps, -1.0), 1000.0);
    const double nan = std::numeric_limits<double>::quiet_NaN();
    QCOMPARE(AutomationEngine::earlierOnlyTickSnapMs(1000.0, nan, eps, P), 1000.0);
    QCOMPARE(AutomationEngine::earlierOnlyTickSnapMs(1000.0, 5.0, nan, P), 1000.0);
}


// ===================== Phase-2 #9: grading v2 (ORION_GRADE_V2) =============================

struct V2Post { double fill; double gs; double ge; };

// Configure an engine for grading-v2 shots: Standstill feedforward clock 250ms (a deterministic
// release), meter self-grade path (no banner), grade_v2 per the flag.
static void applyV2Config(AutomationEngine& engine, bool gradeV2)
{
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.bannerCalibration = false;
    config.gradeV2Enabled = gradeV2;
    LearningData learning;
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 250.0);
    engine.applyConfig(config, learning);
}

// Drive ONE full graded Standstill on `engine` (must be Idle): hold at holdFill (velocity 0 ->
// the 250ms feedforward clock owns the release), then feed the post-release frames (static
// bbox, 20ms apart, per-frame green band), resolve the grade, and return to Idle. Returns every
// fusedDiagnostic line seen (the "GradeV2:" contract surface).
static QStringList driveV2GradedShot(AutomationEngine& engine, double holdFill,
                                     const QVector<V2Post>& post)
{
    QSignalSpy diag(&engine, &AutomationEngine::fusedDiagnostic);
    const double clockMs = engine.config().shotTypeFeedforwardMs
                               .value(QStringLiteral("Standstill"), 250.0);
    const double learnedOffsetMs = engine.config().shotTypeLearnedOffsetMs
                                       .value(QStringLiteral("Standstill"), 0.0);
    if (!driveAuthorizedFeedforwardRelease(engine,
                                            std::max(150.0, clockMs - learnedOffsetMs),
                                            holdFill)) {
        return {};
    }
    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    ControllerState neutral;
    for (const auto& p : post) {
        DetectionResult r = readyMeterSample(p.fill, -1.0);
        r.velocityPctS = 0.0;
        r.greenStartPct = p.gs;
        r.greenEndPct = p.ge;
        r.greenCenterPct = 0.5 * (p.gs + p.ge);
        engine.updateDetection(r);
        engine.process(physical);
        engine.advanceTestClock(20);
    }
    for (int k = 0; k < 75; ++k) {                         // resolve the grade (soft/hard deadline)
        engine.process(physical);
        engine.advanceTestClock(50);
    }
    for (int k = 0; k < 40; ++k) {                         // release Square, drain cooldown -> Idle
        engine.process(neutral);
        engine.advanceTestClock(25);
    }
    QStringList lines;
    for (int i = 0; i < diag.count(); ++i) {
        lines << diag.at(i).at(0).toString();
    }
    return lines;
}

static QString v2Line(const QStringList& lines, const QString& prefix = QStringLiteral("GradeV2:"))
{
    for (const QString& l : lines) {
        if (l.startsWith(prefix)) {
            return l;
        }
    }
    return QString();
}

// Case R trajectory: post-release rise 60 -> 76 at 0.4 pct/ms (20ms frames), freeze at 80 well
// below the [86,94] green band. Local-slope math: censored (<79) samples 60/68/76 fit slope
// 0.4 -> err = -(90 - 80)/0.4 = -25ms -> sole-writer trim 0.25 * -25 = -6.25ms.
static QVector<V2Post> caseRPost()
{
    QVector<V2Post> post;
    post << V2Post{60.0, 86.0, 94.0} << V2Post{68.0, 86.0, 94.0} << V2Post{76.0, 86.0, 94.0};
    for (int i = 0; i < 8; ++i) {
        post << V2Post{80.0, 86.0, 94.0};
    }
    return post;
}

void AutomationEngineTests::gradeV2CaseGExcellentNoTrim()
{
    // Case G: monotone rise -> freeze INSIDE the green band -> EXCELLENT, err 0, and (dead
    // zone) NO learning update of any kind.
    AutomationEngine engine;
    applyV2Config(engine, true);
    QVector<V2Post> post;
    post << V2Post{70.0, 86.0, 94.0} << V2Post{80.0, 86.0, 94.0} << V2Post{88.0, 86.0, 94.0};
    for (int i = 0; i < 8; ++i) {
        post << V2Post{90.0, 86.0, 94.0};
    }
    const QStringList lines = driveV2GradedShot(engine, 50.0, post);
    const QString line = v2Line(lines);
    QVERIFY2(!line.isEmpty(), "a GradeV2: diagnostic line must be emitted");
    QVERIFY2(line.contains(QStringLiteral("case=G")), qPrintable(line));
    QVERIFY2(line.contains(QStringLiteral("verdict=EXCELLENT")), qPrintable(line));
    QCOMPARE(engine.config().shotTypeLearnedOffsetMs.value(QStringLiteral("Standstill"), 0.0), 0.0);
}

void AutomationEngineTests::gradeV2CaseREarlyMagnitudeFromLocalSlope()
{
    // Case R: EARLY with magnitude from the LOCAL rise slope at the freeze (known slope 0.4
    // pct/ms, gap green-center-to-F_stop 10pp -> err -25ms -> offset trim -6.25ms), and the
    // sole-writer contract: the legacy feedforward clock must NOT also move.
    AutomationEngine engine;
    applyV2Config(engine, true);
    const double clockBefore =
        engine.config().shotTypeFeedforwardMs.value(QStringLiteral("Standstill"), 0.0);
    const QStringList lines = driveV2GradedShot(engine, 50.0, caseRPost());
    const QString line = v2Line(lines);
    QVERIFY2(!line.isEmpty(), "a GradeV2: diagnostic line must be emitted");
    QVERIFY2(line.contains(QStringLiteral("case=R")), qPrintable(line));
    QVERIFY2(line.contains(QStringLiteral("verdict=EARLY")), qPrintable(line));
    const double off = engine.config().shotTypeLearnedOffsetMs.value(QStringLiteral("Standstill"), 0.0);
    QVERIFY2(std::abs(off - (-6.25)) < 0.8,
             qPrintable(QStringLiteral("known slope must yield err -25 -> trim -6.25; got %1")
                            .arg(off)));
    QCOMPARE(engine.config().shotTypeFeedforwardMs.value(QStringLiteral("Standstill"), 0.0),
             clockBefore);   // sole writer: the ACQUIRE->LOCK/clock learners stayed frozen
}

void AutomationEngineTests::gradeV2CaseDLateDirectionOnly()
{
    // Case D: rise -> cap >= 97 -> deflate -> freeze is LATE, DIRECTION-ONLY (+10ms): Part-0
    // M4 proved F_stop is a per-type rest CONSTANT uncorrelated with overtime, so two very
    // different deflate depths must produce the IDENTICAL trim (+2.5ms).
    auto runDeflate = [](double rest) -> double {
        AutomationEngine engine;
        applyV2Config(engine, true);
        QVector<V2Post> post;
        post << V2Post{70.0, 86.0, 94.0} << V2Post{85.0, 86.0, 94.0} << V2Post{97.0, 86.0, 94.0}
             << V2Post{100.0, 86.0, 94.0} << V2Post{100.0, 86.0, 94.0};
        // deflate toward the rest point in a few frames, then freeze there
        post << V2Post{rest + 16.0, 86.0, 94.0} << V2Post{rest + 4.0, 86.0, 94.0};
        for (int i = 0; i < 8; ++i) {
            post << V2Post{rest, 86.0, 94.0};
        }
        const QStringList lines = driveV2GradedShot(engine, 50.0, post);
        const QString line = v2Line(lines);
        if (line.isEmpty() || !line.contains(QStringLiteral("case=D"))
            || !line.contains(QStringLiteral("verdict=LATE"))) {
            return std::numeric_limits<double>::quiet_NaN();
        }
        return engine.config().shotTypeLearnedOffsetMs.value(QStringLiteral("Standstill"), 0.0);
    };
    const double shallowRest = runDeflate(75.0);
    const double deepRest = runDeflate(56.0);
    QVERIFY2(std::isfinite(shallowRest) && std::isfinite(deepRest),
             "both deflates must classify Case D / LATE");
    QVERIFY2(std::abs(shallowRest - 2.5) < 0.3,
             qPrintable(QStringLiteral("direction-only trim must be +10*0.25=2.5; got %1")
                            .arg(shallowRest)));
    QVERIFY2(std::abs(shallowRest - deepRest) < 1e-9,
             qPrintable(QStringLiteral("the deflate DEPTH must not change the trim: %1 vs %2")
                            .arg(shallowRest).arg(deepRest)));
}

void AutomationEngineTests::gradeV2DeadZoneReportsWithoutUpdate()
{
    // Dead zone: err in (-10, +6)ms -> the grade is REPORTED (GradeV2 line, dead=1) but no
    // learning update fires. Fast rise (1.0 pct/ms) freezing 8pp below green center -> err -8.
    AutomationEngine engine;
    applyV2Config(engine, true);
    QVector<V2Post> post;
    post << V2Post{30.0, 86.0, 94.0} << V2Post{50.0, 86.0, 94.0} << V2Post{70.0, 86.0, 94.0}
         << V2Post{81.0, 86.0, 94.0};
    for (int i = 0; i < 8; ++i) {
        post << V2Post{82.0, 86.0, 94.0};
    }
    const QStringList lines = driveV2GradedShot(engine, 50.0, post);
    const QString line = v2Line(lines);
    QVERIFY2(!line.isEmpty(), "a GradeV2: diagnostic line must be emitted");
    QVERIFY2(line.contains(QStringLiteral("dead=1")), qPrintable(line));
    QCOMPARE(engine.config().shotTypeLearnedOffsetMs.value(QStringLiteral("Standstill"), 0.0), 0.0);
}

void AutomationEngineTests::gradeV2ArtifactStreakFreezesUpdates()
{
    // v2 artifact guard: >= 6 consecutive same-sign errs with stdev < 3ms (here: 6 IDENTICAL
    // -25ms grades) trips the freeze -> the next shots apply NO update, and the guard logs a
    // GradeV2Guard diagnostic.
    AutomationEngine engine;
    applyV2Config(engine, true);
    bool sawGuard = false;
    for (int shot = 0; shot < 6; ++shot) {
        const QStringList lines = driveV2GradedShot(engine, 50.0, caseRPost());
        QVERIFY2(!v2Line(lines).isEmpty(),
                 qPrintable(QStringLiteral("shot %1 must grade").arg(shot)));
        if (!v2Line(lines, QStringLiteral("GradeV2Guard:")).isEmpty()) {
            sawGuard = true;
        }
    }
    QVERIFY2(sawGuard, "the 6th identical same-sign grade must trip the artifact guard");
    const double frozenAt =
        engine.config().shotTypeLearnedOffsetMs.value(QStringLiteral("Standstill"), 0.0);
    QVERIFY2(std::abs(frozenAt - (6 * -6.25)) < 2.0,
             qPrintable(QStringLiteral("six applied trims expected before the freeze; got %1")
                            .arg(frozenAt)));
    for (int shot = 0; shot < 2; ++shot) {
        const QStringList lines = driveV2GradedShot(engine, 50.0, caseRPost());
        const QString line = v2Line(lines);
        QVERIFY2(line.contains(QStringLiteral("frozen=1")), qPrintable(line));
    }
    QCOMPARE(engine.config().shotTypeLearnedOffsetMs.value(QStringLiteral("Standstill"), 0.0),
             frozenAt);   // frozen shots moved nothing
}

void AutomationEngineTests::gradeV2FlagOffKeepsLegacyGrading()
{
    // Flag OFF = byte-identical legacy: the deflate trajectory grades through the legacy
    // settled-fill rules (LATE -> feedforward clock shortens, ACQUIRE offset moves) and NO
    // GradeV2 diagnostic is emitted.
    AutomationEngine engine;
    applyV2Config(engine, false);
    const double clockBefore =
        engine.config().shotTypeFeedforwardMs.value(QStringLiteral("Standstill"), 0.0);
    QVector<V2Post> post;
    post << V2Post{70.0, 86.0, 94.0} << V2Post{85.0, 86.0, 94.0} << V2Post{97.0, 86.0, 94.0}
         << V2Post{100.0, 86.0, 94.0} << V2Post{100.0, 86.0, 94.0}
         << V2Post{72.0, 86.0, 94.0} << V2Post{60.0, 86.0, 94.0};
    for (int i = 0; i < 8; ++i) {
        post << V2Post{56.0, 86.0, 94.0};
    }
    const QStringList lines = driveV2GradedShot(engine, 50.0, post);
    QVERIFY2(v2Line(lines).isEmpty(), "no GradeV2 line may be emitted with the flag OFF");
    const double clockAfter =
        engine.config().shotTypeFeedforwardMs.value(QStringLiteral("Standstill"), 0.0);
    QVERIFY2(clockAfter < clockBefore - 5.0,
             qPrintable(QStringLiteral("legacy deflate-LATE must shorten the clock: %1 -> %2")
                            .arg(clockBefore).arg(clockAfter)));
}

// ===========================================================================================
// Ceiling stack (2026-07 perfect-green build): H6 plateau-aim, H4 template arrival (+H5
// press-t0), warmup-only bandit lead. Every flag default OFF -> byte-identical.
// ===========================================================================================

void AutomationEngineTests::plateauAimAimsPlateauCenterNotGreenCenter()
{
    // [ORION_PLATEAU_AIM] H6: GREEN = MAKE and the ~50ms cap-hold plateau sits in the green band
    // at fill=100, so the flag must aim the APEX (target=100) and shift the crossing +½·capHold
    // (t(fill=100)+25ms) — NOT the green dead-top/center estimate the per-type path uses.
    auto runShot = [](bool plateau) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.plateauAimEnabled = plateau;
        LearningData learning;
        engine.applyConfig(config, learning);
        armToHolding(engine);
        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        engine.advanceTestClock(160);
        // green-confirmed rising samples well below the fire floor -> the shot HOLDS and the
        // holding tick stamps target/crossing diagnostics without releasing.
        engine.updateDetection(readyMeterSample(66.0, -1.0));
        engine.advanceTestClock(16);
        engine.updateDetection(readyMeterSample(70.0, -1.0));
        engine.advanceTestClock(16);
        engine.updateDetection(readyMeterSample(74.0, -1.0));
        engine.process(physical);
        return engine.context();
    };
    const ShotContext on = runShot(true);
    const ShotContext off = runShot(false);
    QCOMPARE(off.plateauShiftMs, 0.0);                       // flag OFF: no shift, dead-top aim
    QVERIFY2(off.targetPct < 99.0,
             qPrintable(QStringLiteral("flag OFF must keep the green dead-top aim (<99); got %1")
                            .arg(off.targetPct)));
    QCOMPARE(on.targetPct, 100.0);                           // flag ON: the apex is the target
    QCOMPARE(on.plateauShiftMs, 25.0);                       // +½ · plateauCapHoldMs (50ms)
    QCOMPARE(on.targetModeAtRelease, QStringLiteral("plateau_cap"));
}

void AutomationEngineTests::plateauAimRequiresConfirmedGreenAndDefaultsOff()
{
    // Fire off low-σ CONFIRMED green only: with the flag ON but NO green window ever seen
    // (contested), the plateau shift must stay disengaged. And the flag itself defaults OFF.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.plateauAimEnabled = true;
    LearningData learning;
    engine.applyConfig(config, learning);
    armToHolding(engine);
    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.advanceTestClock(160);
    DetectionResult s = readyMeterSample(66.0, -1.0);
    s.greenStartPct = s.greenEndPct = s.greenCenterPct = -1.0;   // contested: no green window
    s.greenConfidence = 0.0;
    engine.updateDetection(s);
    engine.advanceTestClock(16);
    DetectionResult s2 = s;
    s2.fillPct = 70.0;
    engine.updateDetection(s2);
    engine.process(physical);
    QCOMPARE(engine.context().plateauShiftMs, 0.0);
    QVERIFY(engine.context().targetModeAtRelease != QStringLiteral("plateau_cap"));
    // default-constructed settings keep every ceiling-stack flag OFF (byte-identical guard)
    AutomationEngine dflt;
    AppConfigData dfltCfg;
    dflt.applyConfig(dfltCfg, LearningData{});
    QVERIFY(!dflt.config().plateauAimEnabled);
    QVERIFY(!dflt.config().templateArrivalEnabled);
    QVERIFY(!dflt.config().pressT0Enabled);
    QVERIFY(!dflt.config().banditLeadEnabled);
}

void AutomationEngineTests::templateArrivalLearnsAndPredictsDeterministicReplay()
{
    // [ORION_TEMPLATE_ARRIVAL] H4 core invariant: the shot is a deterministic replay when read
    // as TIME-AT-FILL crossings — one completed shot learns a template, and the NEXT shot's
    // early crossing-vector (through ~fill 50, the first ~120-160ms) must match it and predict
    // the green-arrival t@96 to ~ms accuracy (offline LOO σ 14-16ms; exact replay -> ~0 here).
    TemplateArrivalEstimator est;
    est.configure(4, 4, false);
    const double v = 0.2;   // %/ms deterministic rise
    // shot A: fill 5 -> 100 at t0 = 1000; t@96 = 1000 + (96-5)/0.2 = 1455
    est.beginShot(QStringLiteral("Standstill"), -1.0);
    for (int i = 0;; ++i) {
        const double t = 1000.0 + i * 16.0;
        const double fill = 5.0 + v * (t - 1000.0);
        est.addSample(std::min(fill, 100.0), t);
        if (fill >= 100.0) {
            break;
        }
    }
    est.endShot();
    QCOMPARE(est.templateCount(QStringLiteral("Standstill")), 1);
    // shot B: the SAME animation replayed at t0 = 5000; feed only the EARLY rise (to fill ~52)
    est.beginShot(QStringLiteral("Standstill"), -1.0);
    for (int i = 0;; ++i) {
        const double t = 5000.0 + i * 16.0;
        const double fill = 5.0 + v * (t - 5000.0);
        est.addSample(fill, t);
        if (fill >= 52.0) {
            break;
        }
    }
    QVERIFY2(est.matched(), "the early crossing-vector must select the learned template");
    const double trueT96 = 5000.0 + (96.0 - 5.0) / v;   // 5455
    const double pred = est.predictArrivalMs(96.0);
    QVERIFY2(std::abs(pred - trueT96) < 4.0,
             qPrintable(QStringLiteral("deterministic replay must predict t@96 ~exactly; "
                                       "pred=%1 true=%2").arg(pred).arg(trueT96)));
    // target > 96 extrapolates along the template's terminal slope (plateau-aim interop)
    const double pred100 = est.predictArrivalMs(100.0);
    QVERIFY2(pred100 > pred + 10.0 && pred100 < pred + 40.0,
             qPrintable(QStringLiteral("t@100 must extend past t@96 by ~(4pp/v)=20ms; got +%1")
                            .arg(pred100 - pred)));
}

void AutomationEngineTests::templateArrivalPressT0BreaksShapeTies()
{
    // [ORION_PRESS_T0] H5: the press->first-crossing interval is the EARLY discriminator. Two
    // animations with IDENTICAL crossing shapes but different press offsets are ONE cluster
    // without press-t0 (shape tie) and TWO clusters with it — and a new shot selects by press.
    auto feedShot = [](TemplateArrivalEstimator& e, double press, double meterAt) {
        e.beginShot(QStringLiteral("Standstill"), press);
        for (int i = 0;; ++i) {
            const double t = meterAt + i * 16.0;
            const double fill = 5.0 + 0.2 * (t - meterAt);
            e.addSample(std::min(fill, 100.0), t);
            if (fill >= 100.0) {
                break;
            }
        }
        e.endShot();
    };
    TemplateArrivalEstimator noPress;
    noPress.configure(4, 4, false);
    feedShot(noPress, 1000.0, 1300.0);   // press offset 300
    feedShot(noPress, 5000.0, 5100.0);   // press offset 100, identical shape
    QCOMPARE(noPress.templateCount(QStringLiteral("Standstill")), 1);   // shape tie -> folded
    TemplateArrivalEstimator withPress;
    withPress.configure(4, 4, true);
    feedShot(withPress, 1000.0, 1300.0);
    feedShot(withPress, 5000.0, 5100.0);
    QCOMPARE(withPress.templateCount(QStringLiteral("Standstill")), 2); // press splits them
    // a new shot with press offset ~300 must select the FIRST template
    withPress.beginShot(QStringLiteral("Standstill"), 9000.0);
    for (int i = 0;; ++i) {
        const double t = 9300.0 + i * 16.0;
        const double fill = 5.0 + 0.2 * (t - 9300.0);
        withPress.addSample(fill, t);
        if (fill >= 45.0) {
            break;
        }
    }
    QVERIFY(withPress.matched());
    QCOMPARE(withPress.matchedIdx(), 0);
}

void AutomationEngineTests::templateArrivalBlendsCrossingInEngine()
{
    // Engine wiring: shot 1's crossings are learned at shot 2's beginShot; shot 2's holding
    // tick must stamp the matched template + a blended crossing prior (w = σl²/(σl²+σt²) ≈ 0.71
    // with the 16/25ms defaults). Flag OFF (default) keeps templateMatchedIdx at -1 for the
    // identical drive (byte-identical guard).
    struct DriveOut {
        int tmplCount = 0;
        int matchedIdx = -2;
        double arrivalMs = -2.0;
        double blendW = -1.0;
        HoldState shot1State = HoldState::Idle;
        double shot1Peak = 0.0;
        HoldState drainedState = HoldState::Holding;
        HoldState shot2State = HoldState::Idle;
    };
    auto drive = [](bool enabled) {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.templateArrivalEnabled = enabled;
        LearningData learning;
        engine.applyConfig(config, learning);
        ControllerState pressed;
        pressed.buttons |= XINPUT_GAMEPAD_X;
        ControllerState released;
        DriveOut out;
        // shot 1: feed the FULL deterministic rise via updateDetection only (no holding ticks ->
        // nothing fires; the estimator + sampler still ingest every genuine sample).
        armToHolding(engine);
        out.shot1State = engine.context().state;
        engine.advanceTestClock(160);
        for (double fill = 20.0; fill <= 99.0; fill += 3.2) {   // 0.2 %/ms at 16ms steps
            engine.updateDetection(readyMeterSample(fill, -1.0));
            engine.advanceTestClock(16);
        }
        out.shot1Peak = engine.context().peakFillPct;
        engine.process(released);          // user releases -> shot ends
        for (int i = 0; i < 12 && engine.context().state != HoldState::Idle; ++i) {
            engine.advanceTestClock(400.0);   // run out release pulse + cooldown to Idle
            engine.process(released);
        }
        for (int i = 0; i < 8; ++i) {         // flush the X-button history so the square
            engine.advanceTestClock(16.0);    // latch (squareLatchedUntilRelease_) clears
            engine.process(released);
        }
        out.drainedState = engine.context().state;
        // shot 2: the SAME animation; feed the early rise then one holding tick for diagnostics.
        armToHolding(engine);              // beginShot folds shot 1 into the template store
        out.shot2State = engine.context().state;
        engine.advanceTestClock(160);
        for (double fill = 20.0; fill <= 52.0; fill += 3.2) {
            engine.updateDetection(readyMeterSample(fill, -1.0));
            engine.advanceTestClock(16);
        }
        engine.process(pressed);
        out.tmplCount = engine.templateArrivalEstimator().templateCount(QStringLiteral("Standstill"));
        out.matchedIdx = engine.context().templateMatchedIdx;
        out.arrivalMs = engine.context().templateArrivalMs;
        out.blendW = engine.context().templateBlendWeight;
        return out;
    };
    const DriveOut on = drive(true);
    QCOMPARE(on.shot1State, HoldState::Holding);
    QVERIFY2(on.shot1Peak > 90.0,
             qPrintable(QStringLiteral("shot 1's samples must ingest (peak>90); got %1")
                            .arg(on.shot1Peak)));
    QCOMPARE(on.drainedState, HoldState::Idle);
    QCOMPARE(on.shot2State, HoldState::Holding);
    QVERIFY2(on.tmplCount >= 1,
             "shot 1 must have learned a Standstill template at shot 2's beginShot");
    QVERIFY2(on.matchedIdx >= 0, "shot 2's early rise must match the template");
    QVERIFY2(on.arrivalMs > 0.0, "a matched template must predict an arrival");
    QVERIFY2(on.blendW > 0.5 && on.blendW < 0.9,
             qPrintable(QStringLiteral("inverse-variance blend weight ~0.71 expected; got %1")
                            .arg(on.blendW)));
    const DriveOut off = drive(false);
    QCOMPARE(off.matchedIdx, -1);
    QCOMPARE(off.arrivalMs, -1.0);
    QCOMPARE(off.blendW, 0.0);
}

void AutomationEngineTests::banditLeadTunerConvergesOnBestGreenArm()
{
    // [ORION_BANDIT_LEAD] direct: only the +2ms arm greens (others EARLY) -> after minPulls per
    // arm the tuner must LOCK on +2ms, expose the early/late asymmetry, and keep applying the
    // converged lead outside calibration. Unlocked + not exploring -> offset stays 0.
    BanditLeadTuner t;
    t.configure(2, 50);
    QCOMPARE(t.currentOffsetMs(false), 0.0);     // unlocked, exploration not allowed -> inert
    t.noteRelease(false);                        // non-calibration release latches nothing
    t.noteGrade(1);
    QCOMPARE(t.grades(), 0);
    int guard = 0;
    while (!t.locked() && ++guard < 100) {
        const double off = t.currentOffsetMs(true);
        t.noteRelease(true);
        t.noteGrade(off == 2.0 ? 1 : 0);         // GREEN only on the +2ms arm; EARLY otherwise
    }
    QVERIFY2(t.locked(), "the tuner must lock once every arm has minPulls grades");
    QCOMPARE(t.lockedOffsetMs(), 2.0);
    QCOMPARE(t.currentOffsetMs(false), 2.0);     // converged lead applies everywhere once locked
    int earlySum = 0;
    for (int i = 0; i < BanditLeadTuner::kArms; ++i) {
        if (BanditLeadTuner::armOffsetMs(i) != 2.0) {
            earlySum += t.armEarly(i);
        }
    }
    QVERIFY2(earlySum > 0, "the non-optimal arms' EARLY tallies expose the asymmetry");
}

void AutomationEngineTests::releaseWindowDiagnosticNeverFeedsBandit()
{
    // Even an explicitly enabled calibration bandit must not consume a detector-only release
    // position label. It is not an NBA 2K gameplay outcome/reward signal.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.banditLeadEnabled = true;
    config.calibrationMode = true;               // warmup: exploration allowed
    LearningData learning;
    engine.applyConfig(config, learning);
    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.setPhysicalShotEpoch(501);
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    engine.advanceTestClock(160);
    engine.process(physical);
    engine.updateDetection(readyMeterSample(94.0, 1.0));   // imminent -> predictive release
    engine.process(physical);
    QVERIFY(engine.context().state == HoldState::Releasing
            || engine.context().state == HoldState::Cooldown);
    QCOMPARE(engine.context().banditLeadOffsetMs, 0.0);
    const int releaseSeq = engine.context().releaseSeq;
    QVERIFY(releaseSeq > 0);

    QSignalSpy diagnostics(&engine, &AutomationEngine::releaseWindowDiagnostic);
    DetectionResult diagnostic;
    diagnostic.detected = false;
    diagnostic.greenGradeLabel = 1;
    diagnostic.greenGradeSeq = 7;
    diagnostic.greenGradeReleaseSeq = releaseSeq;
    diagnostic.greenGradePhysicalShotEpoch = engine.lastReleaseMarkerPhysicalShotEpoch_;
    diagnostic.greenGradeShotAttempt = engine.lastReleaseMarkerShotAttempt_;
    diagnostic.greenGradeReleaseProxy = false;
    diagnostic.greenGradeWindowConfidence = 1.0;
    diagnostic.greenGradeStartPct = 91.0;
    diagnostic.greenGradeFillAtRelease = 96.0;
    engine.updateDetection(diagnostic);
    QCOMPARE(diagnostics.count(), 1);
    QCOMPARE(engine.banditLeadTuner().grades(), 0);
}

void AutomationEngineTests::releaseWindowDiagnosticRequiresMatchingReleaseMarkerAndNeverLearns()
{
    // A delayed shot-1 diagnostic arriving after shot 2 cannot attach to shot 2. A valid
    // command-early diagnostic may be logged, but never becomes a gameplay miss/learner input.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.freezeCalibration = true;
    config.banditLeadEnabled = false;
    LearningData learning;
    engine.applyConfig(config, learning);

    QSignalSpy diagnostics(&engine, &AutomationEngine::releaseWindowDiagnostic);
    QSignalSpy learnerUpdates(&engine, &AutomationEngine::shotOutcomeLearned);
    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.setPhysicalShotEpoch(601);
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    engine.advanceTestClock(160);
    engine.process(physical);
    engine.updateDetection(readyMeterSample(94.0, 1.0));
    engine.process(physical);
    const int shot1ReleaseSeq = engine.context().releaseSeq;
    const quint64 shot1PhysicalEpoch = engine.lastReleaseMarkerPhysicalShotEpoch_;
    const quint64 shot1Attempt = engine.lastReleaseMarkerShotAttempt_;
    QVERIFY(shot1ReleaseSeq > 0);

    // Begin and release shot 2 before shot 1's delayed diagnostic arrives.
    engine.reset();
    engine.setPhysicalShotEpoch(602);
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    engine.advanceTestClock(160);
    engine.process(physical);
    engine.updateDetection(readyMeterSample(94.0, 1.0));
    engine.process(physical);
    const int releaseSeq = engine.context().releaseSeq;
    const quint64 currentPhysicalEpoch = engine.lastReleaseMarkerPhysicalShotEpoch_;
    const quint64 currentAttempt = engine.lastReleaseMarkerShotAttempt_;
    QVERIFY(releaseSeq > shot1ReleaseSeq);

    auto diagnostic = [&](int diagnosticSeq, int nativeReleaseSeq, bool proxy,
                          double windowConf, int label = 0) {
        DetectionResult result;
        result.detected = false; // diagnostics normally arrive on an idle/follow-through frame
        result.greenGradeLabel = label;
        result.greenGradeSeq = diagnosticSeq;
        result.greenGradeReleaseSeq = nativeReleaseSeq;
        const bool oldRelease = nativeReleaseSeq == shot1ReleaseSeq;
        result.greenGradePhysicalShotEpoch = oldRelease
            ? shot1PhysicalEpoch : currentPhysicalEpoch;
        result.greenGradeShotAttempt = oldRelease ? shot1Attempt : currentAttempt;
        result.greenGradeReleaseProxy = proxy;
        result.greenGradeWindowConfidence = windowConf;
        result.greenGradeStartPct = 91.0;
        result.greenGradeFillAtRelease = 96.0;
        engine.updateDetection(result);
    };

    diagnostic(1, shot1ReleaseSeq, false, 1.0); // delayed shot 1 after shot 2 released
    diagnostic(2, releaseSeq, true, 1.0);      // inferred peak, no native release marker
    diagnostic(3, releaseSeq, false, 0.5);     // fewer than three exposed window samples
    QCOMPARE(diagnostics.count(), 0);

    diagnostic(4, releaseSeq, false, 0.75, 0); // command was early vs detected window
    QCOMPARE(diagnostics.count(), 1);
    const QList<QVariant> args = diagnostics.takeFirst();
    QCOMPARE(args.at(0).toInt(), releaseSeq);
    QCOMPARE(args.at(1).toString(), QStringLiteral("Standstill"));
    QCOMPARE(args.at(2).toInt(), 0);      // COMMAND_EARLY diagnostic, not a game miss
    QCOMPARE(args.at(3).toDouble(), 96.0);
    QCOMPARE(args.at(4).toDouble(), 91.0);

    diagnostic(5, releaseSeq, false, 1.0); // same release is deduped
    QCOMPARE(diagnostics.count(), 0);
    QCOMPARE(learnerUpdates.count(), 0);
    QCOMPARE(engine.banditLeadTuner().grades(), 0);
}

