void AutomationEngineTests::calibrationReleaseWindowDiagnosticUsesSeparateMarkerJoinAndNeverLearns()
{
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    config.banditLeadEnabled = true;
    config.calibrationMode = true;
    engine.applyConfig(config, LearningData{});
    engine.setLatencyCalibrationMode(true);

    QSignalSpy markers(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy diagnostics(&engine, &AutomationEngine::releaseWindowDiagnostic);
    QSignalSpy learnerUpdates(&engine, &AutomationEngine::shotOutcomeLearned);
    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;
    constexpr quint64 shotEpoch = 13'601;
    engine.setPhysicalShotEpoch(shotEpoch);
    engine.process(square);

    int frame = 1;
    for (const double fill : {10.0, 14.0, 18.0, 22.0, 26.0, 30.0}) {
        engine.advanceTestClock(20.0);
        DetectionResult sample = calibrationOwnershipSample(fill, frame++, shotEpoch);
        sample.greenStartPct = 80.0;
        sample.greenEndPct = 100.0;
        sample.greenCenterPct = 90.0;
        engine.updateDetection(sample);
        engine.process(square);
        if (markers.count() == 1) {
            break;
        }
    }
    QCOMPARE(markers.count(), 1);
    const int releaseSeq = markers.at(0).at(0).toInt();
    QVERIFY(releaseSeq > 0);
    QVERIFY(markers.at(0).at(2).toBool());
    const quint64 shotAttempt = engine.context().armToken;
    QCOMPARE(markers.at(0).at(5).toULongLong(), shotEpoch);
    QCOMPARE(markers.at(0).at(6).toULongLong(), shotAttempt);

    DetectionResult diagnostic;
    diagnostic.detected = false;
    diagnostic.greenGradeLabel = 1;
    diagnostic.greenGradeSeq = 91;
    diagnostic.greenGradeReleaseSeq = releaseSeq;
    diagnostic.greenGradePhysicalShotEpoch = shotEpoch;
    diagnostic.greenGradeShotAttempt = shotAttempt;
    diagnostic.greenGradeReleaseProxy = false;
    diagnostic.greenGradeWindowConfidence = 1.0;
    diagnostic.greenGradeStartPct = 80.0;
    diagnostic.greenGradeFillAtRelease = 90.0;
    engine.updateDetection(diagnostic);

    QCOMPARE(diagnostics.count(), 1);
    const QList<QVariant> args = diagnostics.takeFirst();
    QCOMPARE(args.at(0).toInt(), releaseSeq);
    QCOMPARE(args.at(1).toString(), QStringLiteral("Standstill"));
    QCOMPARE(args.at(2).toInt(), 1);
    QCOMPARE(learnerUpdates.count(), 0);
    QCOMPARE(engine.banditLeadTuner().grades(), 0);
}

void AutomationEngineTests::leaseGateFlagOffAlwaysAllowsFire()
{
    // Flag OFF (the shipping default until the 07-15 server work): the gate is
    // transparent — fire is allowed with NO lease, an EXPIRED lease, a STALE
    // lease, even after a kill verdict. This is the "identical when off" guarantee.
    LeaseGate gate;
    QVERIFY(!gate.enabled());
    QVERIFY(gate.fireAllowed(0, 1000));
    gate.recordHeartbeatOk(/*lease_expires_at*/ 1500, /*mono*/ 0, /*epoch*/ 1000);
    QVERIFY(gate.fireAllowed(0, 2000));                       // expired lease: still allowed (flag off)
    QVERIFY(gate.fireAllowed(LeaseGate::kDefaultMaxStalenessMs * 3, 1200));  // stale: still allowed
    gate.recordHeartbeatKill();
    QVERIFY(gate.fireAllowed(0, 1000));                       // revoked: still allowed (flag off)
}

void AutomationEngineTests::leaseGateEnvFlagParsesTruthyValues()
{
    const QByteArray saved = qgetenv("ORION_LEASE_GATED_FIRE");
    const bool wasSet = qEnvironmentVariableIsSet("ORION_LEASE_GATED_FIRE");
#ifdef ORION_PRODUCTION_BUILD
    // Production authority cannot be disabled through an attacker-controlled
    // process environment, including explicit falsy or malformed values.
    qunsetenv("ORION_LEASE_GATED_FIRE");
    QVERIFY(LeaseGate::enabledFromEnvironment());
    qputenv("ORION_LEASE_GATED_FIRE", "0");
    QVERIFY(LeaseGate::enabledFromEnvironment());
    qputenv("ORION_LEASE_GATED_FIRE", "banana");
    QVERIFY(LeaseGate::enabledFromEnvironment());
#else
    qunsetenv("ORION_LEASE_GATED_FIRE");
    QVERIFY(!LeaseGate::enabledFromEnvironment());            // DEFAULT OFF
    qputenv("ORION_LEASE_GATED_FIRE", "0");
    QVERIFY(!LeaseGate::enabledFromEnvironment());
    qputenv("ORION_LEASE_GATED_FIRE", "1");
    QVERIFY(LeaseGate::enabledFromEnvironment());
    qputenv("ORION_LEASE_GATED_FIRE", "true");
    QVERIFY(LeaseGate::enabledFromEnvironment());
    qputenv("ORION_LEASE_GATED_FIRE", "banana");
    QVERIFY(!LeaseGate::enabledFromEnvironment());            // unknown value != enabled
#endif
    if (wasSet) {
        qputenv("ORION_LEASE_GATED_FIRE", saved);
    } else {
        qunsetenv("ORION_LEASE_GATED_FIRE");
    }
}

void AutomationEngineTests::automationAccessRequiresAuthenticationAndLease()
{
    using Policy = AutomationAccessPolicy;

    QVERIFY(Policy::localDevBypassEligible(true, false, false));
    QVERIFY(!Policy::localDevBypassEligible(true, true, false));
    QVERIFY(!Policy::localDevBypassEligible(true, false, true));

    // The original bypass: an unlocked integrity state alone is not authority.
    QVERIFY(!Policy::allowed(false, false, false, false, true));
    QVERIFY(!Policy::allowed(false, false, false, true, true));

    // Authenticated development may run with the optional lease gate disabled,
    // but an integrity lock still wins.
    QVERIFY(Policy::allowed(true, false, false, false, true));
    QVERIFY(!Policy::allowed(true, false, true, false, true));

    // Once enabled (always in production), the lease must itself be live.
    QVERIFY(!Policy::allowed(true, false, false, true, false));
    QVERIFY(Policy::allowed(true, false, false, true, true));

    // This lane is compiled unreachable in production by localDevAllowed(); it
    // remains explicit here so developer source-tree fixtures stay usable.
    QVERIFY(Policy::allowed(false, true, true, true, false));
}

void AutomationEngineTests::leaseGateBlocksWithoutAnyLease()
{
    // Flag ON + no lease ever granted => fail CLOSED. This is the CRIT-1 kill
    // shot: forcing authenticated_=true grants no lease, so fire stays blocked.
    LeaseGate gate;
    gate.setEnabled(true);
    QVERIFY(!gate.fireAllowed(0, 1000));
    QCOMPARE(gate.stateText(0, 1000), QStringLiteral("No lease"));
}

void AutomationEngineTests::leaseGateActivationSeedsBoundedLease()
{
    // Activation seeds a lease, but only a heartbeat-sized window — the 30-day
    // token expiry must NOT become 30 days of offline fire.
    LeaseGate gate;
    gate.setEnabled(true);
    const qint64 epoch0 = 1'800'000'000;
    gate.recordActivation(/*tokenExpires*/ epoch0 + 86400 * 30, /*mono*/ 0, epoch0);
    QVERIFY(gate.fireAllowed(0, epoch0));
    QVERIFY(gate.fireAllowed(1000, epoch0 + LeaseGate::kFallbackLeaseTtlS - 1));
    QVERIFY(!gate.fireAllowed(1000, epoch0 + LeaseGate::kFallbackLeaseTtlS));   // capped at the fallback TTL
    // A token already expired at activation time never grants a lease.
    LeaseGate expired;
    expired.setEnabled(true);
    expired.recordActivation(/*tokenExpires*/ epoch0 - 1, /*mono*/ 0, epoch0);
    QVERIFY(!expired.fireAllowed(0, epoch0));
}

void AutomationEngineTests::leaseGateHeartbeatRefreshesAndExpires()
{
    LeaseGate gate;
    gate.setEnabled(true);
    const qint64 epoch0 = 1'800'000'000;
    gate.recordHeartbeatOk(/*lease_expires_at*/ epoch0 + 900, /*mono*/ 0, epoch0);
    QVERIFY(gate.fireAllowed(0, epoch0));
    QVERIFY(gate.fireAllowed(5 * 60 * 1000, epoch0 + 899));   // inside TTL + staleness
    QVERIFY(!gate.fireAllowed(5 * 60 * 1000, epoch0 + 900));  // server lease expiry (wall clock)
    // A fresh heartbeat re-opens the window.
    gate.recordHeartbeatOk(epoch0 + 1800, 10 * 60 * 1000, epoch0 + 900);
    QVERIFY(gate.fireAllowed(11 * 60 * 1000, epoch0 + 1000));
    // A backend response without lease_expires_at cannot mint client authority.
    LeaseGate missingExpiry;
    missingExpiry.setEnabled(true);
    missingExpiry.recordHeartbeatOk(/*lease_expires_at*/ 0, /*mono*/ 0, epoch0);
    QVERIFY(!missingExpiry.fireAllowed(0, epoch0));
    QCOMPARE(missingExpiry.stateText(0, epoch0), QStringLiteral("No lease"));
}

void AutomationEngineTests::leaseGateRejectsExpiredHeartbeatReplay()
{
    LeaseGate gate;
    gate.setEnabled(true);
    const qint64 epoch0 = 1'800'000'000;
    const qint64 expiredAt = epoch0 + 30;

    // Prove the replay fixture is a cryptographically valid heartbeat, not a
    // malformed-signature case that the controller rejects earlier.
    if (ed25519Available()) {
        const QByteArray seed(32, '\x36');
        const QByteArray pub = ed25519DerivePublicKey(seed);
        const QString licenseKey = QStringLiteral("ORION-REPLAY-FIXTURE");
        const QString machineId = QStringLiteral("machine-replay-fixture");
        const QByteArray message = QStringLiteral("%1:%2:%3")
                                       .arg(licenseKey, machineId).arg(expiredAt).toUtf8();
        const QByteArray signature = ed25519Sign(seed, message).toBase64(
            QByteArray::Base64UrlEncoding | QByteArray::OmitTrailingEquals);
        QVERIFY(LeaseGate::verifyLeaseSignature(
            pub, licenseKey, machineId, expiredAt, signature));
    }

    // Establish authority, then present an otherwise authentic heartbeat whose
    // signed expiry is no longer in the future. It must revoke the live lease,
    // not silently replace it with a client-generated 15-minute window.
    gate.recordHeartbeatOk(epoch0 + 900, /*mono*/ 0, epoch0);
    QVERIFY(gate.fireAllowed(1, epoch0 + 1));
    gate.recordHeartbeatOk(expiredAt, /*mono*/ 30'000, expiredAt);
    QVERIFY(!gate.fireAllowed(30'000, epoch0 + 30));
    QCOMPARE(gate.stateText(30'000, epoch0 + 30), QStringLiteral("No lease"));

    // Replaying the same expired signed lease cannot refresh either clock or
    // resurrect authority, regardless of how often the attacker repeats it.
    for (int replay = 1; replay <= 5; ++replay) {
        const qint64 replayEpoch = epoch0 + 30 + (replay * 60);
        const qint64 replayMono = 30'000 + (replay * 60'000);
        gate.recordHeartbeatOk(expiredAt, replayMono, replayEpoch);
        QVERIFY(!gate.fireAllowed(replayMono, replayEpoch));
        QCOMPARE(gate.stateText(replayMono, replayEpoch), QStringLiteral("No lease"));
    }
}

void AutomationEngineTests::leaseGateStaleHeartbeatFailsClosedDespiteClockRollback()
{
    // Anti-rollback: the server said the lease lasts a while, but if no
    // successful heartbeat lands within the MONOTONIC staleness window, fire is
    // blocked even when the (attacker-settable) wall clock still reads "valid".
    LeaseGate gate;
    gate.setEnabled(true);
    const qint64 epoch0 = 1'800'000'000;
    gate.recordHeartbeatOk(/*lease_expires_at*/ epoch0 + 86400, /*mono*/ 0, epoch0);
    QVERIFY(gate.fireAllowed(gate.maxStalenessMs(), epoch0 + 60));          // boundary: exactly max staleness
    QVERIFY(!gate.fireAllowed(gate.maxStalenessMs() + 1, epoch0 + 60));     // one ms past: fail closed
    // Winding the wall clock BACK does not help once monotonically stale.
    QVERIFY(!gate.fireAllowed(gate.maxStalenessMs() + 1, epoch0 - 86400));
    QCOMPARE(gate.stateText(gate.maxStalenessMs() + 1, epoch0 + 60), QStringLiteral("Lease stale"));
}

void AutomationEngineTests::leaseGateKillVerdictRevokesImmediately()
{
    // Revoke-fast: an authoritative kill verdict on the heartbeat drops the
    // lease NOW (no waiting for expiry/staleness).
    LeaseGate gate;
    gate.setEnabled(true);
    const qint64 epoch0 = 1'800'000'000;
    gate.recordHeartbeatOk(epoch0 + 900, 0, epoch0);
    QVERIFY(gate.fireAllowed(1000, epoch0 + 1));
    gate.recordHeartbeatKill();
    QVERIFY(!gate.fireAllowed(1001, epoch0 + 1));
    QCOMPARE(gate.stateText(1001, epoch0 + 1), QStringLiteral("No lease"));
    // ...and a later heartbeat can re-grant (server-controlled, not client-controlled).
    gate.recordHeartbeatOk(epoch0 + 1800, 2000, epoch0 + 2);
    QVERIFY(gate.fireAllowed(2500, epoch0 + 3));
}

void AutomationEngineTests::leaseGateSignatureRoundTripAndRejection()
{
    // 07-15 signed-lease contract: Ed25519 over "license_key:machine_id:lease_expires_at",
    // base64url signature. Round-trips with the correct key, rejects tampering.
    if (!ed25519Available()) {
        QSKIP("libcrypto with Ed25519 EVP support unavailable in this test environment");
    }
    const QByteArray seed(32, '\x42');
    const QByteArray pub = ed25519DerivePublicKey(seed);
    QCOMPARE(pub.size(), 32);
    const QString licenseKey = QStringLiteral("ORION-TEST-KEY-1234");
    const QString machineId = QStringLiteral("machine-abcdef");
    const qint64 leaseExpiresAt = 1'800'000'900;
    const QByteArray message = QStringLiteral("%1:%2:%3")
                                   .arg(licenseKey, machineId).arg(leaseExpiresAt).toUtf8();
    const QByteArray sig = ed25519Sign(seed, message);
    QCOMPARE(sig.size(), 64);
    const QByteArray sigB64 = sig.toBase64(QByteArray::Base64UrlEncoding | QByteArray::OmitTrailingEquals);
    QVERIFY(LeaseGate::verifyLeaseSignature(pub, licenseKey, machineId, leaseExpiresAt, sigB64));
    // Tampered expiry, wrong machine, wrong key, garbage/empty sig: all rejected.
    QVERIFY(!LeaseGate::verifyLeaseSignature(pub, licenseKey, machineId, leaseExpiresAt + 1, sigB64));
    QVERIFY(!LeaseGate::verifyLeaseSignature(pub, licenseKey, QStringLiteral("other-machine"), leaseExpiresAt, sigB64));
    const QByteArray otherPub = ed25519DerivePublicKey(QByteArray(32, '\x24'));
    QVERIFY(!LeaseGate::verifyLeaseSignature(otherPub, licenseKey, machineId, leaseExpiresAt, sigB64));
    QVERIFY(!LeaseGate::verifyLeaseSignature(pub, licenseKey, machineId, leaseExpiresAt, QByteArrayLiteral("not-base64!!")));
    QVERIFY(!LeaseGate::verifyLeaseSignature(pub, licenseKey, machineId, leaseExpiresAt, QByteArray()));
    // The verify key is now embedded.
    QVERIFY(!LeaseGate::leaseVerifyPublicKey().isEmpty());
}

void AutomationEngineTests::activateResponseParsesLeaseTokenFields()
{
    // CRIT-1: the /api/activate session token is no longer discarded — the
    // client keeps token + tid + expires to seed the fire lease.
    const QByteArray payload = QByteArrayLiteral(
        "{\"ok\":true,\"token\":\"tok-opaque\",\"tid\":\"11111111-2222-3333-4444-555555555555\","
        "\"expires\":1800086400,\"license_key_suffix\":\"ABCD\"}");
    const LicenseResult r = parseActivateResponse(payload);
    QVERIFY(r.ok);
    QCOMPARE(r.token, QStringLiteral("tok-opaque"));
    QCOMPARE(r.tokenId, QStringLiteral("11111111-2222-3333-4444-555555555555"));
    QCOMPARE(r.tokenExpiresEpochS, qint64(1800086400));
    // Alternate "token_id" spelling is accepted too.
    const LicenseResult alt = parseActivateResponse(QByteArrayLiteral(
        "{\"success\":true,\"access_token\":\"tok2\",\"token_id\":\"tid-2\",\"expires\":123}"));
    QVERIFY(alt.ok);
    QCOMPARE(alt.token, QStringLiteral("tok2"));
    QCOMPARE(alt.tokenId, QStringLiteral("tid-2"));
    QCOMPARE(alt.tokenExpiresEpochS, qint64(123));
    // Failure payloads stay failures with no phantom lease fields.
    const LicenseResult bad = parseActivateResponse(QByteArrayLiteral("{\"ok\":false,\"error\":\"invalid_key\"}"));
    QVERIFY(!bad.ok);
    QCOMPARE(bad.tokenExpiresEpochS, qint64(0));
}

void AutomationEngineTests::licenseCheckResponseParsesLeaseFields()
{
    // The heartbeat is the authoritative lease: lease_expires_at (and the
    // future lease_sig) must survive parsing; a kill verdict keeps its error code.
    const LicenseResult ok = parseLicenseCheckResponse(QByteArrayLiteral(
        "{\"ok\":true,\"license_key\":\"K\",\"machine_id\":\"M\",\"lease_expires_at\":1800000900,"
        "\"tier\":\"standard\",\"lease_sig\":\"c2lnbmF0dXJl\"}"));
    QVERIFY(ok.ok);
    QCOMPARE(ok.leaseExpiresAtEpochS, qint64(1800000900));
    QCOMPARE(ok.leaseSig, QByteArrayLiteral("c2lnbmF0dXJl"));
    const LicenseResult kill = parseLicenseCheckResponse(QByteArrayLiteral(
        "{\"ok\":false,\"error\":\"revoked\",\"message\":\"license revoked\"}"));
    QVERIFY(!kill.ok);
    QCOMPARE(kill.error, QStringLiteral("revoked"));
    QCOMPARE(kill.leaseExpiresAtEpochS, qint64(0));
    // Transport garbage parses to a non-kill (empty error) fail-soft result.
    const LicenseResult garbage = parseLicenseCheckResponse(QByteArrayLiteral("not json"));
    QVERIFY(!garbage.ok);
    QVERIFY(garbage.error.isEmpty());
}

