void AutomationEngineTests::spkiPinMatchesGtsWe1BothCertVariants()
{
    // The WE1 KEY appears in (at least) two different certificate DERs: the one
    // Cloudflare serves (GTS Root R4 issuer) and Google's published cross-sign
    // (GlobalSign R4 issuer). The SPKI pin must match BOTH — that rotation
    // resilience is the entire point of MED-3.
    const auto liveCerts = QSslCertificate::fromData(QByteArray(kGtsWe1LivePem), QSsl::Pem);
    const auto publishedCerts = QSslCertificate::fromData(QByteArray(kGtsWe1PublishedPem), QSsl::Pem);
    QCOMPARE(liveCerts.size(), 1);
    QCOMPARE(publishedCerts.size(), 1);
    const QString we1Pin = QStringLiteral("908769e8d34477cc2cba0632c88605b22d7294c0840f78596d247c645b1afc0e");
    QCOMPARE(certificateSpkiSha256Hex(liveCerts.first()), we1Pin);
    QCOMPARE(certificateSpkiSha256Hex(publishedCerts.first()), we1Pin);
    QVERIFY(productionApiPinnedSpkiSha256().contains(we1Pin));
    QCOMPARE(productionApiPinnedCertificateSha256(), we1Pin);   // "pinning enabled" marker == primary pin
    // Chain-shaped input (leaf position irrelevant: ANY chain cert may match).
    QString detail;
    QVERIFY(certificateChainMatchesPinnedSpki(liveCerts, &detail));
    QVERIFY(certificateChainMatchesPinnedSpki(publishedCerts, nullptr));
    const auto mixedChain = QSslCertificate::fromData(
        QByteArray(kUnpinnedSelfSignedPem) + '\n' + QByteArray(kGtsWe1LivePem), QSsl::Pem);
    QCOMPARE(mixedChain.size(), 2);
    QVERIFY(certificateChainMatchesPinnedSpki(mixedChain, nullptr));
}

void AutomationEngineTests::spkiPinFailsClosedOnUnpinnedChain()
{
    // MED-3 restores a REAL pin: the old code returned true ("advisory") on any
    // mismatch. An unpinned chain — or no chain at all — must now fail closed.
    const auto unpinned = QSslCertificate::fromData(QByteArray(kUnpinnedSelfSignedPem), QSsl::Pem);
    QCOMPARE(unpinned.size(), 1);
    QString detail;
    QVERIFY(!certificateChainMatchesPinnedSpki(unpinned, &detail));
    QVERIFY(detail.contains(QStringLiteral("No certificate")));
    QVERIFY(!certificateChainMatchesPinnedSpki({}, &detail));
    QVERIFY(!replyMatchesPinnedCertificate(nullptr, &detail));
}

// === C1: safe-mode auto-recovery policy (SafeModeRecoveryTracker) =======================
void AutomationEngineTests::safeModeAutoRecoversAfterStabilityWindowBounded()
{
    // The watchdog SAFE-MODE latch must auto-recover after a continuous run of healthy
    // stream ticks — and stay bounded so a genuine crash loop still requires a manual reset.
    SafeModeRecoveryTracker t;
    t.configure(30'000, 2);
    t.onEnterSafeMode();

    // (a) Continuous health for the stability window -> exactly one auto-recovery, AT the
    // window boundary and not a tick before.
    qint64 now = 1'000'000;
    QVERIFY(!t.observe(true, now));                 // starts the health run
    QVERIFY(!t.observe(true, now + 29'000));        // inside the window -> keep waiting
    QVERIFY(t.observe(true, now + 30'000));         // window met -> auto-exit NOW
    QCOMPARE(t.autoRecoveries(), 1);

    // (b) An unhealthy tick RESETS the continuous-health run (a crash-looping stream that
    // blips healthy between crashes never accumulates the window).
    t.onEnterSafeMode();
    now += 100'000;
    QVERIFY(!t.observe(true, now));
    QVERIFY(!t.observe(true, now + 29'000));
    QVERIFY(!t.observe(false, now + 29'500));       // stall -> run resets
    QVERIFY(!t.observe(true, now + 30'000));        // fresh run starts here...
    QVERIFY(!t.observe(true, now + 59'000));        // ...so the old anchor no longer counts
    QVERIFY(t.observe(true, now + 60'000));         // full window from the fresh anchor
    QCOMPARE(t.autoRecoveries(), 2);

    // (c) BOUNDED: the budget (2) is spent — a third latch never auto-recovers, no matter
    // how healthy the stream looks. Manual exitSafeMode() is the only way out (the genuine
    // crash-loop protection the latch exists for).
    t.onEnterSafeMode();
    now += 1'000'000;
    QVERIFY(!t.observe(true, now));
    QVERIFY(!t.observe(true, now + 30'000));
    QVERIFY(!t.observe(true, now + 300'000));
    QCOMPARE(t.autoRecoveries(), 2);

    // (d) Entering safe mode resets any stale pending health run: health accumulated BEFORE
    // the latch must not count toward the post-latch stability window.
    SafeModeRecoveryTracker fresh;
    fresh.configure(30'000, 2);
    QVERIFY(!fresh.observe(true, 500'000));         // pre-latch health...
    fresh.onEnterSafeMode();                        // ...is discarded here
    QVERIFY(!fresh.observe(true, 531'000));         // would pass if the stale anchor survived
    QCOMPARE(fresh.autoRecoveries(), 0);
}

// === C2: global clock EMAs must freeze under freeze_calibration =========================
void AutomationEngineTests::globalClockEmasFrozenUnderCalibrationFreeze()
{
    // The globalAppearToTipMs / globalHoldToReleaseMs / globalRiseVelocityPctMs EMAs update on
    // every clean vision-timed release — previously gated ONLY on the autonomous/shadow flag,
    // NOT on calibrationFrozen, so a long frozen session still slowly drifted the shared clock.
    // With freeze_calibration ON (the shipped live default via ORION_FREEZE_CAL) they must hold;
    // freeze OFF keeps learning exactly as before (covered by
    // globalTimingLearnsFromCleanVisionReleaseOnlyWhenEnabled).
    auto greenSample = [](double fill) {
        DetectionResult r = readyMeterSample(fill, -1.0);
        r.greenStartPct = 86.0; r.greenEndPct = 98.0; r.greenCenterPct = 92.0;
        return r;
    };
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.maximumHoldMs = 5000.0;
    config.tempoFallbackTimeoutMs = 5000.0;
    config.autonomousVisionShadow = true;        // learner would be active...
    config.freezeCalibration = true;             // ...but the freeze must now gate it
    LearningData learning;                        // globals start 0 (unseeded)
    engine.applyConfig(config, learning);
    const double v0 = engine.config().globalRiseVelocityPctMs;

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    engine.advanceTestClock(160);
    engine.process(physical);
    for (int i = 0; i < 5; ++i) {                 // confirm the green window below target
        engine.updateDetection(greenSample(70.0));
        engine.process(physical);
        engine.advanceTestClock(20);
    }
    engine.updateDetection(greenSample(96.0));    // cross -> vision-timed release
    engine.process(physical);
    QVERIFY2(engine.shotsReleased() >= 1 || engine.context().state == HoldState::Releasing
                 || engine.context().state == HoldState::Cooldown,
             "drive must produce a vision-timed release for the freeze assertion to mean anything");
    QCOMPARE(engine.config().globalAppearToTipMs, 0.0);      // frozen: never seeded
    QCOMPARE(engine.config().globalHoldToReleaseMs, 0.0);    // frozen: never seeded
    QCOMPARE(engine.config().globalRiseVelocityPctMs, v0);   // frozen: EMA untouched
}

// === D1: a held-Square tempo shot must ALWAYS release, even under a flapping stick ======
void AutomationEngineTests::tempoHeldSquareFlappingStickAlwaysReleases()
{
    // THE release contract: "I only HOLD my button — there must be NO glitch where I hold and
    // the bot won't release." Before this fix, leaning the left stick >= 65% while holding
    // Square flapped the classified type for 3 frames -> lsCancelRequested() -> abort("ls_cancel")
    // with NO release -> the still-held Square re-armed a fresh TempoSquare ~24ms later with
    // RESET safety caps -> abort+re-arm FOREVER; the button never released. While the physical
    // Square is HELD a tempo shot is now never ls-cancellable (it behaves like a ButtonShot),
    // so the normal bounded release paths (vision / feedforward clock / no-meter blind-fire cap)
    // always fire within the max-hold bound.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.tempoRemapEnabled = true;
    config.minimumHoldMs = 0.0;
    LearningData learning;                        // Standstill FF default (460ms) stays armed
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;         // neutral LS at arm -> Standstill tempo
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);
    QCOMPARE(engine.context().mode, ShotMode::TempoSquare);

    // Flap the left stick HARD every frame (alternating full-left/full-right, magnitude far
    // above lsCancelThresholdPct AND a changed classified type every frame) while the Square
    // stays held and NO meter is ever fed. Drive well past every clock/cap.
    ControllerState output;
    for (int i = 0; i < 260 && engine.shotsAborted() == 0; ++i) {
        physical.leftStickX = (i % 2 == 0) ? -110 : 110;
        physical.leftStickY = 0;
        output = engine.process(physical);
        engine.advanceTestClock(16);
    }
    QCOMPARE(engine.shotsReleased(), 0);
    QCOMPARE(engine.shotsAborted(), 1);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("no_meter_abort"));
    QVERIFY(!output.square());
    QCOMPARE(output.rightStickY, 127); // detector abort cannot leak the remapped Square
    const int attempts = engine.shotsAttempted();
    for (int i = 0; i < 10; ++i) {
        output = engine.process(physical);
        QVERIFY(!output.square());
        QCOMPARE(output.rightStickY, 127);
    }
    QCOMPARE(engine.shotsAttempted(), attempts); // held Square cannot rearm after abort

    // Releasing the same physical press completes the manual Tempo gesture, but
    // never converts the fail-closed abort into a bot-owned release or a new shot.
    ControllerState neutral;
    output = engine.process(neutral);
    output = engine.process(neutral);
    output = engine.process(neutral);
    QVERIFY(!output.square());
    QCOMPARE(output.rightStickY, -127);
    QCOMPARE(engine.shotsAttempted(), attempts);
    QCOMPARE(engine.shotsReleased(), 0);
}

// === D2: tempo's hold clock anchors at the press-commit, not the detection confirm ======
void AutomationEngineTests::tempoHoldClockAnchorsAtPressNotDetectionConfirm()
{
    // Tempo routes press -> Armed (detection confirm / tempoFallbackTimeoutMs) -> Holding, and
    // holdStartMs was stamped only on the Armed->Holding transition — so every hold-anchored
    // clock (feedforward blind-fire, commit floors, timeout) ran the WHOLE Armed dwell later
    // than the ButtonShot path (live: blind-fire net ~2.2s vs ~1.7-1.8s). The hold clock is now
    // anchored at armTimestampMs (the press-commit beginShot stamped), so with a 400ms Armed
    // dwell the 600ms hold-start clock still fires ~600ms after the press, not ~1000ms.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.tempoRemapEnabled = true;
    config.minimumHoldMs = 0.0;
    config.tempoFallbackTimeoutMs = 400.0;        // Armed dwell: no meter -> confirm at +400ms
    config.feedforwardAnchor = QStringLiteral("hold_start");
    LearningData learning;
    // Only the NORMAL bucket carries the clock — the tempo bucket must fall back to it (D3),
    // exactly as a fresh tempo profile would on shot 1.
    learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 600.0);
    engine.applyConfig(config, learning);

    ControllerState physical;
    physical.buttons |= XINPUT_GAMEPAD_X;         // neutral LS -> Standstill tempo
    engine.process(physical);
    engine.advanceTestClock(220);
    engine.process(physical);                     // tempo armed -> Armed (needs confirm)
    QCOMPARE(engine.context().mode, ShotMode::TempoSquare);
    const double armMs = engine.context().armTimestampMs;

    // NO meter: Armed falls through to Holding at the 400ms fallback; the blind hold clock
    // (600 minus the small lead) must then be measured from the PRESS-commit, so the release
    // fires ~armMs+540..600 — well before the old (arm + 400 dwell + ~540) ≈ armMs+940.
    ControllerState output;
    for (int i = 0; i < 220 && engine.shotsAborted() == 0; ++i) {
        output = engine.process(physical);
        engine.advanceTestClock(16);
    }
    Q_UNUSED(armMs);
    QCOMPARE(engine.shotsReleased(), 0);
    QCOMPARE(engine.shotsAborted(), 1);
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("no_meter_abort"));
    QVERIFY(!output.square());
    QCOMPARE(output.rightStickY, 127);
}

// === D3: |tempo lookups fall back to the normal-type calibration until learned ==========
void AutomationEngineTests::tempoOffsetFallsBackToNormalTypeUntilLearned()
{
    // The "<type>|tempo" bucket's offset lookup previously returned the generic 0 when the tempo
    // key was unlearned — a calibrated Standstill (+100ms learned offset) fired ~100ms differently
    // the moment tempo mode was toggled. An unlearned tempo bucket must now read the NORMAL
    // type's offset (button parity). Two identical tempo engines differing only by the NORMAL
    // bucket's learned offset: the +100 one fires its (identical, fallback) clock earlier.
    auto makeEngine = [](AutomationEngine& engine, double normalLearnedOffsetMs) {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.tempoRemapEnabled = true;
        config.minimumHoldMs = 0.0;
        config.tempoFallbackTimeoutMs = 100.0;    // short Armed dwell, same for both
        config.feedforwardAnchor = QStringLiteral("hold_start");
        LearningData learning;
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 600.0);
        learning.shotTypeLearnedOffsetMs.insert(QStringLiteral("Standstill"),
                                                normalLearnedOffsetMs);
        // NO "Standstill|tempo" keys anywhere: every tempo read must fall back.
        engine.applyConfig(config, learning);
    };
    AutomationEngine a, b;
    makeEngine(a, 0.0);       // fires its blind clock at ~press+600-(lead)
    makeEngine(b, 100.0);     // must fire ~100ms EARLIER via the normal-bucket offset fallback
    ControllerState held;
    held.buttons |= XINPUT_GAMEPAD_X;
    auto drive = [&held](AutomationEngine& e, int frames) {
        for (int i = 0; i < frames; ++i) {
            e.process(held);
            e.advanceTestClock(16);
        }
    };
    a.process(held); b.process(held);
    a.advanceTestClock(220); b.advanceTestClock(220);
    a.process(held); b.process(held);             // both tempo-armed
    QCOMPARE(a.context().mode, ShotMode::TempoSquare);
    QCOMPARE(b.context().mode, ShotMode::TempoSquare);
    // Neither the learned clock nor its offset may substitute for the meter.
    drive(a, 220); drive(b, 220);
    QCOMPARE(a.shotsReleased(), 0);
    QCOMPARE(b.shotsReleased(), 0);
    QCOMPARE(a.shotsAborted(), 1);
    QCOMPARE(b.shotsAborted(), 1);
    QCOMPARE(a.context().releaseReasonCode, QStringLiteral("no_meter_abort"));
    QCOMPARE(b.context().releaseReasonCode, QStringLiteral("no_meter_abort"));
}

void AutomationEngineTests::userLogDisabledIsInertAndTouchesNoFiles()
{
    // [ORION_USER_LOG] (5b) With the flag OFF (the shipped default) the user-log sink must be
    // completely inert: nothing buffered, nothing written, no file created — which is what keeps
    // the shipped build byte-identical, including logs/orion_native.log (the sink never touches
    // the diagnostic stream or its file in ANY mode; the only writer of orion_native.log is the
    // untouched flushPendingLogs diagnostic queue).
    UserFacingLog log;
    QCOMPARE(log.enabled(), false);                       // default OFF
    log.append(QStringLiteral("must be dropped"));
    QCOMPARE(log.pendingLines().size(), 0);

    QTemporaryDir dir;
    QVERIFY(dir.isValid());
    QVERIFY(!log.flushTo(dir.path()));                    // nothing to write
    QVERIFY(!QFile::exists(dir.path() + QStringLiteral("/") + UserFacingLog::fileName()));
    QVERIFY(!QFile::exists(dir.path() + QStringLiteral("/orion_native.log")));   // never touched

    // Env parsing (applyConfig-independent). SHIPPED DEFAULT FLIPPED 2026-08-04: unset now means
    // ON, because the human-readable log is the one artifact a customer can read and send to
    // support, and it was previously OFF for everyone except the dev rig. An EXPLICIT 0/false/
    // off/no still disables it -- that opt-out is what this half pins.
    const QByteArray saved = qgetenv("ORION_USER_LOG");
    qunsetenv("ORION_USER_LOG");
    QVERIFY2(UserFacingLog::envEnabled(),
             "unset must now mean ON: shipping this OFF left customers with no readable log");
    qputenv("ORION_USER_LOG", "0");
    QVERIFY2(!UserFacingLog::envEnabled(), "an explicit 0 must still disable the user log");
    qputenv("ORION_USER_LOG", "false");
    QVERIFY(!UserFacingLog::envEnabled());
    qputenv("ORION_USER_LOG", "1");
    QVERIFY(UserFacingLog::envEnabled());
    qputenv("ORION_USER_LOG", "true");
    QVERIFY(UserFacingLog::envEnabled());
    if (saved.isEmpty()) {
        qunsetenv("ORION_USER_LOG");
    } else {
        qputenv("ORION_USER_LOG", saved);
    }
}

void AutomationEngineTests::userLogEnabledWritesReadableLocalLines()
{
    // [ORION_USER_LOG] (5b) Enabled sink: plain-language lines under a readable LOCAL wall-clock
    // stamp (yyyy-MM-dd HH:mm:ss — not the diagnostic log's UTC ISO), written append-only to its
    // OWN logs/orion_user.log and to no other file.
    // Deterministic format check first.
    const QDateTime t(QDate(2026, 7, 18), QTime(14, 5, 9));
    QCOMPARE(UserFacingLog::formatLine(t, QStringLiteral("Hello  there ")),
             QStringLiteral("2026-07-18 14:05:09  Hello there"));

    UserFacingLog log;
    log.setEnabled(true);
    log.append(QStringLiteral("Connected — the console stream is live."));
    log.append(QStringLiteral(
        "Release command accepted by the local controller route — meter at 92% "
        "(aiming for 96%). Console/game receipt is not confirmed."));
    QCOMPARE(log.pendingLines().size(), 2);

    QTemporaryDir dir;
    QVERIFY(dir.isValid());
    QVERIFY(log.flushTo(dir.path()));
    QCOMPARE(log.pendingLines().size(), 0);               // drained
    QVERIFY(!QFile::exists(dir.path() + QStringLiteral("/orion_native.log")));   // own file only

    QFile file(dir.path() + QStringLiteral("/") + UserFacingLog::fileName());
    QVERIFY(file.open(QIODevice::ReadOnly | QIODevice::Text));
    QStringList lines = QString::fromUtf8(file.readAll()).split(QLatin1Char('\n'), Qt::SkipEmptyParts);
    file.close();
    QCOMPARE(lines.size(), 2);
    const QRegularExpression stamp(QStringLiteral("^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}  \\S"));
    for (const QString& line : lines) {
        QVERIFY2(stamp.match(line).hasMatch(),
                 qPrintable(QStringLiteral("user-log line must start with a local timestamp: %1").arg(line)));
    }
    QVERIFY(lines.at(0).endsWith(QStringLiteral("Connected — the console stream is live.")));
    QVERIFY(lines.at(1).contains(QStringLiteral("meter at 92%")));

    // A second flush APPENDS (append-only stream, mirrors the diagnostic log's contract).
    log.append(QStringLiteral("Disconnected from the console."));
    QVERIFY(log.flushTo(dir.path()));
    QVERIFY(file.open(QIODevice::ReadOnly | QIODevice::Text));
    lines = QString::fromUtf8(file.readAll()).split(QLatin1Char('\n'), Qt::SkipEmptyParts);
    file.close();
    QCOMPARE(lines.size(), 3);
    QVERIFY(lines.at(2).endsWith(QStringLiteral("Disconnected from the console.")));
}

void AutomationEngineTests::userReleaseLogRequiresTransportConfirmation()
{
    UserFacingReleaseTracker tracker;

    // Issuance only stages the local-route result. It must never turn local
    // acceptance into a claim that the console or game received the command.
    tracker.stage(42, 92.0, 96.0, QStringLiteral("Standstill"), true, 8.0);
    QVERIFY(tracker.pending());
    QCOMPARE(tracker.pendingSeq(), 42);

    const QString failed = tracker.fail(
        42, UserReleaseFailureReason::TransportNotConfirmed);
    QVERIFY(failed.contains(QStringLiteral("NOT delivered")));
    QVERIFY(failed.contains(QStringLiteral("not confirmed"), Qt::CaseInsensitive));
    QVERIFY(!failed.contains(QStringLiteral("timed and released"), Qt::CaseInsensitive));
    QVERIFY(!tracker.pending());

    tracker.stage(43, 94.0, 97.0, QStringLiteral("Tempo Standstill"), false, 0.0);
    const QString mismatched = tracker.confirm(44);
    QVERIFY(mismatched.contains(QStringLiteral("NOT confirmed")));
    QVERIFY(!mismatched.contains(QStringLiteral("timed and released"), Qt::CaseInsensitive));
    QVERIFY(!tracker.pending());

    tracker.stage(45, 95.0, 97.0, QStringLiteral("Tempo Standstill"), true, 7.6);
    const QString confirmed = tracker.confirm(45);
    QVERIFY(confirmed.contains(QStringLiteral("accepted by the local controller route")));
    QVERIFY(confirmed.contains(QStringLiteral("meter at 95%")));
    QVERIFY(confirmed.contains(QStringLiteral("Court probe RTT: 8 ms")));
    QVERIFY(confirmed.contains(QStringLiteral("Console/game receipt is not confirmed")));
    QVERIFY(!confirmed.contains(QStringLiteral("Shot timed and released"), Qt::CaseInsensitive));
    QVERIFY(!confirmed.contains(QStringLiteral("NOT delivered")));
    QVERIFY(!tracker.pending());

    tracker.stage(46, 90.0, 96.0, QStringLiteral("Standstill"), false, 0.0);
    const QString disconnected = tracker.failPending(
        UserReleaseFailureReason::VirtualControllerDisconnected);
    QVERIFY(disconnected.contains(QStringLiteral("NOT delivered")));
    QVERIFY(disconnected.contains(QStringLiteral("virtual controller disconnected")));
    QVERIFY(!disconnected.contains(QStringLiteral("timed and released"), Qt::CaseInsensitive));

    const QString writeFailed = UserFacingReleaseTracker::failureNotice(
        UserReleaseFailureReason::PreciseWriteFailed);
    QVERIFY(writeFailed.contains(QStringLiteral("NOT delivered")));
    QVERIFY(writeFailed.contains(QStringLiteral("precise controller write failed")));
    QVERIFY(!writeFailed.contains(QStringLiteral("timed and released"), Qt::CaseInsensitive));
}

void AutomationEngineTests::userMeterVisibilityUsesGenuineRawOverlayState()
{
    constexpr qint64 freshMs = 120;
    constexpr qint64 seenAtMs = 1000;

    // A current genuine raw detection is visible regardless of shot state. In
    // particular, an accepted->idle_overlay engine transition after release is
    // not an input to this policy and cannot emit a false disappearance.
    QVERIFY(userMeterVisibleFromRawEvidence(true, seenAtMs, seenAtMs, freshMs));
    QCOMPARE(userMeterVisibilityNotice(true, true),
             UserMeterVisibilityNotice::None);

    // Brief raw-detector gaps retain the same bounded overlay visibility and do
    // not flap the user log. Only expiry of genuine raw evidence emits loss.
    QVERIFY(userMeterVisibleFromRawEvidence(false, seenAtMs, seenAtMs + freshMs - 1,
                                            freshMs));
    QCOMPARE(userMeterVisibilityNotice(true, true),
             UserMeterVisibilityNotice::None);
    QVERIFY(!userMeterVisibleFromRawEvidence(false, seenAtMs, seenAtMs + freshMs,
                                             freshMs));
    QCOMPARE(userMeterVisibilityNotice(true, false),
             UserMeterVisibilityNotice::NoLongerVisible);

    QCOMPARE(userMeterVisibilityNotice(false, true),
             UserMeterVisibilityNotice::Detected);
    QVERIFY(!userMeterVisibleFromRawEvidence(false, 0, seenAtMs, freshMs));
    QVERIFY(!userMeterVisibleFromRawEvidence(false, seenAtMs, seenAtMs - 1, freshMs));
}

// ===========================================================================================
// [ORION_HORIZON_DEBIAS] tests
//
// Returns the timestamp of the last sample, which is also the `atMs` a decision is taken at.
// ===========================================================================================
double AutomationEngineTests::feedLinearRise(orion::AutomationEngine& engine, double baseMs,
                                             double startFillPct, double slopePctPerMs,
                                             int samples, double dtMs)
{
    engine.sampler_.reset();
    double lastMs = baseMs;
    for (int i = 0; i < samples; ++i) {
        lastMs = baseMs + dtMs * static_cast<double>(i);
        engine.sampler_.addSample(startFillPct + slopePctPerMs * (lastMs - baseMs), lastMs);
    }
    // Everything liveMeterCrossingAuthoritative() needs, and nothing that would let the
    // registration branch take over (regModelId stays empty -> regTrajectory is false, so
    // these tests exercise the pure-sampler path the correction acts on).
    engine.shot_.anchorValidMs = baseMs;
    engine.shot_.confidence = 1.0;
    engine.shot_.fillPct = startFillPct + slopePctPerMs * (lastMs - baseMs);
    return lastMs;
}

// The correction pivots on the engine's measured lead, so a test that wants it live must make
// the lead genuinely authoritative — not merely set a number. Returns the pivot in ms.
double AutomationEngineTests::primeLeadPivot(orion::AutomationEngine& engine, double atMs,
                                             double leadMs)
{
    engine.measuredLatencyMs_ = leadMs;
    engine.measuredLatencySdMs_ = 2.0;
    engine.measuredLatencyN_ = 6;
    engine.measuredLatencyAuthorityKind_ = QStringLiteral("validated");
    engine.measuredLatencyAuthorityMs_ = leadMs;
    engine.measuredLatencyAuthoritySdMs_ = 2.0;
    engine.measuredLeadTelemetryPresent_ = true;
    engine.measuredLeadEverValid_ = true;
    engine.measuredLeadEpochReady_ = true;
    engine.measuredLeadLastUpdateMs_ = atMs;
    return leadMs;
}

// ===========================================================================================
// [ORION_CONTESTED_DEADLINE] tests
// ===========================================================================================
void AutomationEngineTests::stageContestedFarDisagreement(
    orion::AutomationEngine& engine, double now, double slopePctPerMs,
    double endFillPct, double leadMs, double regTipMs, double regSigmaMs)
{
    // Pin the engine clock so the sampler window sits at positive timestamps. A fresh engine's
    // elapsed clock starts at ~0, and a fit anchored before zero is rejected outright
    // (liveMeterCrossingAuthoritative requires shot_.anchorValidMs >= 0), which would silently
    // route the whole fixture down the registration-solo branch instead of the contested one.
    engine.testClockMs_ = now;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    primeLeadPivot(engine, now, leadMs);

    engine.shot_.state = HoldState::Holding;
    engine.shot_.mode = ShotMode::ButtonShot;
    engine.shot_.shotType = QStringLiteral("Standstill");
    engine.shot_.holdStartMs = now - 10.0;
    engine.shot_.physicalShotEpoch = 5;
    engine.shot_.armToken = 2;
    engine.shot_.visionEpoch = 7;
    engine.shot_.meterDetected = true;
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.lastFreshAcceptMs = now;
    engine.shot_.firstFreshAcceptMs = now;
    engine.shot_.sawFreshMeterThisShot = true;
    engine.shot_.meterSeenThisShot = true;
    engine.shot_.frameAgeMs = 0.0;

    // The INDEPENDENT half of the proof: the sampler is fed DetectionResult fills and nothing
    // else, so no registration number can move this fit. feedLinearRise also stamps
    // shot_.fillPct / anchorValidMs / confidence from the same detector trajectory.
    constexpr int kSamples = 8;
    constexpr double kDtMs = 16.7;
    const double spanMs = kDtMs * static_cast<double>(kSamples - 1);
    feedLinearRise(engine, now - spanMs, endFillPct - slopePctPerMs * spanMs,
                   slopePctPerMs, kSamples, kDtMs);

    // The DISPUTED half: registration's own tip, which is what the missed deadline is computed
    // from. Chosen to fail the fusion compatibility test against the fit above.
    engine.shot_.regTipMs = regTipMs;
    engine.shot_.regTipAbsMs = now + regTipMs;
    engine.shot_.regConf = 1.0;
    engine.shot_.regSigmaMs = regSigmaMs;
    engine.shot_.regN = 16;
    engine.shot_.regModelId = QStringLiteral("contested-deadline-model");
    engine.shot_.regModelVersion = QStringLiteral("1");

    engine.lastPhysical_.buttons |= XINPUT_GAMEPAD_X;
}

void AutomationEngineTests::contestedTipDeadlineHoldsWhileMeasuredRunwayRemains()
{
    // LIVE REPRO: 2026-08-04 orion_native.log, physical_epoch=5, ButtonShot.
    //
    //   12:32:16.992  source=registration+sampler_far  reg_tip_eta=234.986  smp_tip_eta=442.520
    //   12:32:17.116  source=registration              reg_tip_eta=105.471  smp_tip_eta=-1.000
    //   12:32:17.148  TIP DEADLINE DECISION: disposition=rejected_missed
    //                 source=registration_far_disagreement tip_eta_ms=73.135
    //                 command_eta_ms=-216.865 predictor_sigma_ms=66.365 fill_pct=47.39
    //                 -> Shot automation aborted: live_tip_deadline_missed
    //
    // The two sources disagreed by ~290 ms, the far-horizon rule handed the decision to the one
    // the engine had just labelled far-disagreeing, and its tip minus a 290 ms lead put the
    // command 216 ms in the past. Meanwhile the meter itself was at 47.39% climbing 0.146 pp/ms
    // -- roughly 360 ms of runway. Nothing was missed. The shot was destroyed on the reading the
    // engine trusted least, while the reading it could measure said there was still time.
    AutomationEngine engine;
    constexpr double now = 100'000.0;
    constexpr double kLeadMs = 290.0;
    constexpr double kSlopePctPerMs = 0.146;
    constexpr double kFillPct = 47.39;
    constexpr double kRegTipMs = 73.135;
    stageContestedFarDisagreement(engine, now, kSlopePctPerMs, kFillPct, kLeadMs,
                                  kRegTipMs, /*regSigmaMs=*/58.0);

    // The fixture has to reproduce the live DECISION, not merely the live numbers -- otherwise a
    // future fusion change could silently route this test through a different branch and it would
    // keep passing while covering nothing.
    const auto decision = engine.canonicalAutonomousTipDecision(now);
    QCOMPARE(decision.source, QStringLiteral("registration_far_disagreement"));
    QVERIFY2(decision.valid, "fixture must produce a VALID decision or a different branch runs");
    const double fireAtMs = decision.tipAbsMs - engine.measuredLeadForActuationMs();
    QVERIFY2(fireAtMs <= now,
             qPrintable(QStringLiteral("fixture must put the command deadline in the past, got %1")
                            .arg(fireAtMs - now)));

    ControllerState output = engine.lastPhysical_;
    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy abortSpy(&engine, &AutomationEngine::shotAborted);
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    engine.processAutonomousLiveMeterHolding(output, now);

    // The whole fix, in four assertions: the shot survives, nothing is released, the physical
    // DOWN is untouched, and the engine says WHY it is still waiting.
    QCOMPARE(abortSpy.count(), 0);
    QCOMPARE(markerSpy.count(), 0);
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("owned_square_contested_tip_estimate"));
    QVERIFY2(output.square(),
             "holding is not releasing: the owned physical DOWN must survive untouched");

    QString heldLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.contains(QStringLiteral("disposition=contested_runway_remains"))) {
            heldLine = line;
        }
        QVERIFY2(!line.contains(QStringLiteral("disposition=rejected_missed")),
                 qPrintable(QStringLiteral("still reported a miss: %1").arg(line)));
    }
    QVERIFY2(!heldLine.isEmpty(), "the contested hold must be attributable in the log");
    bool ok = false;
    const double runwayMs = diagField(heldLine, QStringLiteral("meter_runway_ms"), &ok);
    QVERIFY(ok);
    // The proof that is actually load-bearing: the runway the DETECTOR measured exceeds the lead.
    QVERIFY2(runwayMs > kLeadMs,
             qPrintable(QStringLiteral("held without proving runway: %1 vs lead %2")
                            .arg(runwayMs).arg(kLeadMs)));
}

void AutomationEngineTests::contestedTipDeadlineFailsClosedOnEveryArm()
{
    // Each arm below fails if the guard is replaced by an unconditional `return true`, which is
    // the only way "never weaken fail-closed" can be checked rather than asserted.

    // --- ARM 1/4: the FLAT regime. This is the arm that matters most.
    //
    // Registration is untrustworthy precisely when the fill is flat-holding (2026-08-03: 46 of 66
    // catastrophic prediction errors were registration-source over a flat meter, claiming a median
    // 151 ms sigma against a median 249 ms actual error). Note the trap: on a flat meter the
    // runway ARITHMETIC alone would happily say "hold" -- (100-47.39)/0.04 = 1315 ms, far more
    // than the 290 ms lead. It is the rise FLOOR, not the runway, that must refuse. If the floor
    // is ever removed this arm is the one that catches it.
    {
        AutomationEngine engine;
        constexpr double now = 100'000.0;
        constexpr double kFlatSlopePctPerMs = 0.04;   // inside the flat band, below the floor
        stageContestedFarDisagreement(engine, now, kFlatSlopePctPerMs, /*endFillPct=*/47.39,
                                      /*leadMs=*/290.0, /*regTipMs=*/73.135,
                                      /*regSigmaMs=*/58.0);
        const auto decision = engine.canonicalAutonomousTipDecision(now);
        QCOMPARE(decision.source, QStringLiteral("registration_far_disagreement"));
        QVERIFY(decision.valid);
        // The trap is real: naive runway says there is plenty of time.
        QVERIFY((100.0 - engine.context().fillPct) / kFlatSlopePctPerMs > 290.0);

        ControllerState output = engine.lastPhysical_;
        QSignalSpy abortSpy(&engine, &AutomationEngine::shotAborted);
        QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
        engine.processAutonomousLiveMeterHolding(output, now);
        QCOMPARE(abortSpy.count(), 1);
        QCOMPARE(markerSpy.count(), 0);
        QCOMPARE(engine.context().state, HoldState::Idle);
        QCOMPARE(engine.context().releaseReasonCode,
                 QStringLiteral("live_tip_deadline_missed"));
    }

    // --- ARM 2/4: contested source, rising meter, but NO RUNWAY LEFT. fill 88.0 at 0.146 pp/ms
    // leaves 82 ms of travel against a 290 ms lead: the deadline is genuinely gone and must abort.
    {
        AutomationEngine engine;
        constexpr double now = 100'000.0;
        stageContestedFarDisagreement(engine, now, /*slopePctPerMs=*/0.146, /*endFillPct=*/88.0,
                                      /*leadMs=*/290.0, /*regTipMs=*/210.0,
                                      /*regSigmaMs=*/20.0);
        const auto decision = engine.canonicalAutonomousTipDecision(now);
        QCOMPARE(decision.source, QStringLiteral("registration_far_disagreement"));
        QVERIFY(decision.valid);

        ControllerState output = engine.lastPhysical_;
        QSignalSpy abortSpy(&engine, &AutomationEngine::shotAborted);
        QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
        engine.processAutonomousLiveMeterHolding(output, now);
        QCOMPARE(abortSpy.count(), 1);
        QCOMPARE(markerSpy.count(), 0);
        QCOMPARE(engine.context().state, HoldState::Idle);
        QCOMPARE(engine.context().releaseReasonCode,
                 QStringLiteral("live_tip_deadline_missed"));
    }

    // --- ARM 3/4: the wait is BOUNDED. The same shot that holds above must still return physical
    // control at the existing absolute Button hold ceiling; a contested estimate that never
    // resolves cannot hold a shot open forever.
    {
        AutomationEngine engine;
        constexpr double now = 100'000.0;
        stageContestedFarDisagreement(engine, now, /*slopePctPerMs=*/0.146, /*endFillPct=*/47.39,
                                      /*leadMs=*/290.0, /*regTipMs=*/73.135,
                                      /*regSigmaMs=*/58.0);
        engine.shot_.holdStartMs = now - (engine.config_.maxHoldMs + 100.0);

        ControllerState output = engine.lastPhysical_;
        QSignalSpy abortSpy(&engine, &AutomationEngine::shotAborted);
        QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
        engine.processAutonomousLiveMeterHolding(output, now);
        QCOMPARE(abortSpy.count(), 1);
        QCOMPARE(markerSpy.count(), 0);
        QCOMPARE(engine.context().state, HoldState::Idle);
        QCOMPARE(engine.context().releaseReasonCode,
                 QStringLiteral("live_tip_deadline_missed"));
    }

    // --- ARM 4/4: the predicate itself, on the exact live numbers. Only the one source the
    // engine has already rated far-disagreeing may reach the hold; every other label -- including
    // the mirror `sampler_near_disagreement`, where the deadline IS the sampler and proving
    // runway from the sampler would be circular -- must abort.
    {
        TemporalSampler::CrossingFit fit;
        fit.n = 8;
        fit.slopePctPerMs = 0.146;
        constexpr double kFill = 47.39;
        constexpr double kLead = 290.0;
        QVERIFY(AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            QStringLiteral("registration_far_disagreement"), fit, kFill, kLead));
        for (const QString& source : {QStringLiteral("sampler_near_disagreement"),
                                      QStringLiteral("registration"),
                                      QStringLiteral("registration+sampler_far"),
                                      QStringLiteral("sampler+registration_near"),
                                      QStringLiteral("sampler"),
                                      QStringLiteral("none"), QString()}) {
            QVERIFY2(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
                         source, fit, kFill, kLead),
                     qPrintable(QStringLiteral("non-contested source reached the hold: %1")
                                    .arg(source)));
        }

        const QString contested = QStringLiteral("registration_far_disagreement");
        // Too few samples to measure motion at all -- the same width bar the flat guard uses.
        TemporalSampler::CrossingFit thin = fit;
        thin.n = 3;
        QVERIFY(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, thin, kFill, kLead));
        // Exactly at the rise floor passes; a hair below it does not. This is the boundary the
        // flat-regime arm above depends on.
        TemporalSampler::CrossingFit atFloor = fit;
        atFloor.slopePctPerMs = AutomationEngine::kProvenRiseSlopePctPerMs;
        QVERIFY(AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, atFloor, kFill, kLead));
        TemporalSampler::CrossingFit belowFloor = fit;
        belowFloor.slopePctPerMs = AutomationEngine::kProvenRiseSlopePctPerMs - 1e-6;
        QVERIFY(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, belowFloor, kFill, kLead));
        // The floor is strictly above the flat guard's ceiling, so the two predicates are
        // disjoint: nothing the flat guard would veto can ever reach the rising side.
        QVERIFY(AutomationEngine::kProvenRiseSlopePctPerMs
                > AutomationEngine::kFlatMeterSlopePctPerMs);
        TemporalSampler::CrossingFit flat = fit;
        flat.slopePctPerMs = AutomationEngine::kFlatMeterSlopePctPerMs;
        QVERIFY(AutomationEngine::registrationSoloContradictedByFlatMeter(flat));
        QVERIFY(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, flat, kFill, kLead));
        // A physically impossible slope must not manufacture runway by dividing by a huge number.
        TemporalSampler::CrossingFit absurd = fit;
        absurd.slopePctPerMs = 9.0;
        QVERIFY(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, absurd, kFill, kLead));
        // NaN slope, meter already at the tip, and a non-positive lead all fail closed.
        TemporalSampler::CrossingFit nan = fit;
        nan.slopePctPerMs = std::numeric_limits<double>::quiet_NaN();
        QVERIFY(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, nan, kFill, kLead));
        QVERIFY(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, fit, 100.0, kLead));
        QVERIFY(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, fit, kFill, 0.0));
        // And the exact boundary of the runway test itself: equal is NOT enough.
        const double exactRunwayMs = (100.0 - kFill) / fit.slopePctPerMs;
        QVERIFY(!AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, fit, kFill, exactRunwayMs));
        QVERIFY(AutomationEngine::contestedTipDeadlineOutrunByMeasuredRunway(
            contested, fit, kFill, exactRunwayMs - 1.0));
    }
}

void AutomationEngineTests::horizonDebiasInertWithoutAMeasuredLeadPivot()
{
    orion::AutomationEngine engine;
    const double base = 100'000.0;
    const double atMs = feedLinearRise(engine, base, 30.0, 0.2, 8, 16.7);

    // The pivot IS the measured lead. An engine that has not yet earned lead authority has no
    // pivot, and a correction with no pivot must never touch a real deadline: with no lead the
    // decision has to be byte-identical to the feature being off.
    const auto cold = engine.canonicalAutonomousTipDecision(atMs);
    QVERIFY2(cold.samplerAuthoritative, "fixture must produce an authoritative fit");
    QCOMPARE(cold.horizonDebiasMs, 0.0);

    engine.config_.samplerHorizonDebiasEnabled = false;
    const auto disabled = engine.canonicalAutonomousTipDecision(atMs);
    QCOMPARE(disabled.horizonDebiasMs, 0.0);
    // Byte-identical, not merely "close": this is the revert path.
    QCOMPARE(cold.tipAbsMs, disabled.tipAbsMs);

    // Give the engine a real, validated lead and the correction engages. 133ms is well inside
    // the fixture's 233ms horizon, so the crossing must be pulled EARLIER.
    engine.config_.samplerHorizonDebiasEnabled = true;
    primeLeadPivot(engine, atMs, 133.1);
    const auto warm = engine.canonicalAutonomousTipDecision(atMs);
    QVERIFY2(warm.horizonDebiasMs > 0.0,
             "a horizon well beyond the lead must be pulled earlier once the pivot exists");
    QVERIFY(warm.tipAbsMs < cold.tipAbsMs);
}

void AutomationEngineTests::horizonDebiasPullsLongHorizonsEarlyAndShortHorizonsLate()
{
    orion::AutomationEngine engine;
    // The correction ships OFF; these tests opt in explicitly so they describe the
    // behaviour that is waiting on a live pivot calibration, not the shipped default.
    engine.config_.samplerHorizonDebiasEnabled = true;
    const double base = 100'000.0;
    const double atMs = feedLinearRise(engine, base, 30.0, 0.2, 8, 16.7);

    // True horizon of the fixture: last fill 53.38 at 0.2%/ms -> (100 - 53.38)/0.2 = 233.1ms.
    const double rawHorizon = 233.1;
    const double k = engine.config_.samplerHorizonBiasMsPerMs;

    // Horizon LONGER than the lead: the linear fit is at its most over-extrapolated, so the tip
    // is pulled EARLIER. This is the arm that matters now that the authority lease lets tokens
    // arm further ahead — a longer horizon is exactly where the measured bias is largest.
    primeLeadPivot(engine, atMs, rawHorizon - 100.0);
    const auto longH = engine.canonicalAutonomousTipDecision(atMs);
    QVERIFY(std::abs(longH.horizonDebiasMs - k * 100.0) < 0.5);
    QVERIFY(longH.tipAbsMs < atMs + rawHorizon);

    // Horizon SHORTER than the lead: the fit has barely extrapolated, so it carries less bias
    // than the lead assumes and the tip is pushed LATER. Both arms are required — a one-sided
    // correction would just be a disguised mean shift.
    primeLeadPivot(engine, atMs, rawHorizon + 100.0);
    const auto shortH = engine.canonicalAutonomousTipDecision(atMs);
    QVERIFY(std::abs(shortH.horizonDebiasMs + k * 100.0) < 0.5);
    QVERIFY(shortH.tipAbsMs > atMs + rawHorizon);

    // The clamp bounds a wild fit; it must bind and never be exceeded. At the shipped slope the
    // clamp is unreachable from any legal pivot (0.22 * (233.1 - 30) = 44.7 < 45), which is
    // itself worth stating — so force it with an absurd slope rather than pretend otherwise.
    primeLeadPivot(engine, atMs, 30.0);
    const auto unclamped = engine.canonicalAutonomousTipDecision(atMs);
    QVERIFY2(unclamped.horizonDebiasMs < engine.config_.samplerHorizonDebiasMaxMs,
             "shipped slope must not be able to reach the clamp from a legal pivot");
    engine.config_.samplerHorizonBiasMsPerMs = 1.0;
    const auto clamped = engine.canonicalAutonomousTipDecision(atMs);
    QCOMPARE(clamped.horizonDebiasMs, engine.config_.samplerHorizonDebiasMaxMs);
}

void AutomationEngineTests::horizonDebiasIsMeanNeutralAtItsOwnReference()
{
    orion::AutomationEngine engine;
    const double base = 100'000.0;
    const double atMs = feedLinearRise(engine, base, 30.0, 0.2, 8, 16.7);

    // THE load-bearing property. The already-learned lead encodes whatever mean bias the old
    // predictor had. If this correction moved the MEAN aim point, every shot would fire early
    // until the lead re-converged — exactly the regression this change exists to avoid. The
    // command is submitted when the remaining horizon equals the lead, so pivoting on the lead
    // makes the correction identically zero on the decision that fires: the mean is preserved
    // and only the horizon-dependent spread is removed.
    engine.config_.samplerHorizonDebiasEnabled = false;
    const auto off = engine.canonicalAutonomousTipDecision(atMs);

    engine.config_.samplerHorizonDebiasEnabled = true;
    const double horizonMs = off.samplerFit.crossingMs - atMs;
    primeLeadPivot(engine, atMs, horizonMs);                         // lead == this horizon
    const auto on = engine.canonicalAutonomousTipDecision(atMs);

    QVERIFY(std::abs(on.horizonDebiasMs) < 1e-9);
    QCOMPARE(on.tipAbsMs, off.tipAbsMs);

    // POSITIVE CONTROL. Without this the test passes vacuously if the correction never engages
    // at all — "unchanged at the pivot" is only meaningful if it demonstrably changes elsewhere.
    primeLeadPivot(engine, atMs, horizonMs - 80.0);
    const auto movedPivot = engine.canonicalAutonomousTipDecision(atMs);
    QVERIFY2(std::abs(movedPivot.horizonDebiasMs) > 1.0,
             "correction must be live, or the zero-at-pivot assertion above proves nothing");
    QVERIFY(movedPivot.tipAbsMs < off.tipAbsMs);
}

void AutomationEngineTests::horizonDebiasNeverManufacturesACrossingInThePast()
{
    orion::AutomationEngine engine;
    // The correction ships OFF; these tests opt in explicitly so they describe the
    // behaviour that is waiting on a live pivot calibration, not the shipped default.
    engine.config_.samplerHorizonDebiasEnabled = true;
    const double base = 100'000.0;
    // Near-tip fixture: 8 samples at 0.2%/ms spans 116.9ms, so start at 64.62 to LAND on 88.0
    // -> exactly 60ms of horizon left. The last sample must stay below the 100% target or
    // predictCrossing short-circuits ("already at/above target") and never fits at all.
    const double atMs = feedLinearRise(engine, base, 64.62, 0.2, 8, 16.7);
    primeLeadPivot(engine, atMs, 30.0);
    // The clamp is opened out of the way so the SIGN of the guard is what gets tested, not the
    // clamp. The shipped 0.22 with a 45ms clamp cannot reach this state from any legal pivot,
    // so the guard is proven here rather than left as an untested claim.
    engine.config_.samplerHorizonDebiasMaxMs = 200.0;

    // POSITIVE CONTROL first: at a slope that does NOT consume the whole horizon the correction
    // must genuinely apply. Otherwise the refusal asserted below would be indistinguishable from
    // the feature simply being inert on this fixture.
    engine.config_.samplerHorizonBiasMsPerMs = 0.5;
    const auto applied = engine.canonicalAutonomousTipDecision(atMs);
    QVERIFY(std::abs(applied.horizonDebiasMs - 15.0) < 0.5);   // 0.5 * (60 - 30)
    QVERIFY(applied.tipAbsMs > atMs);

    // Now an absurd slope: the correction (2.0 * (60 - 30) = 60ms) exactly consumes the whole
    // remaining horizon and would land the tip ON `now`.
    engine.config_.samplerHorizonBiasMsPerMs = 2.0;
    const auto d = engine.canonicalAutonomousTipDecision(atMs);
    QVERIFY2(d.samplerAuthoritative, "near-tip fixture must still be authoritative");
    // The correction is refused wholesale rather than clamped to `now`: a tip at/behind the
    // present carries no information a caller can act on, and fail-closed means declining to
    // speak, not inventing a deadline.
    QVERIFY(std::abs(d.horizonDebiasMs) < 1e-12);   // QCOMPARE fuzzy-compares against 0 badly
    QVERIFY(d.tipAbsMs > atMs);
}

void AutomationEngineTests::releaseLandingReportsPeakDistinctFromSubmitFill()
{
    orion::AutomationEngine engine;
    QSignalSpy diag(&engine, &orion::AutomationEngine::engineDiagnostic);

    // The bug this line exists to close: "Release timing:"'s peakFill is sampled when the
    // command is SUBMITTED, before the meter has travelled, so it equalled fillAtRel on all
    // 475 releases ever logged. Reproduce the real geometry — submit at ~47%, land at ~97%
    // after a full lead of travel — and require the log to distinguish the two.
    engine.meterCapActive_ = true;
    engine.meterCapSeq_ = 4'242;
    engine.meterCapShotType_ = QStringLiteral("Standstill");
    engine.meterCapFillAtReleasePct_ = 47.2;
    engine.meterCapPeakFillPct_ = 97.4;
    engine.meterCapSamples_.clear();          // no settled run -> the graded=0 evidence path

    engine.evaluatePostReleaseMeter();

    QString landing;
    for (const auto& call : diag) {
        const QString line = call.at(0).toString();
        if (line.startsWith(QStringLiteral("Release landing:"))) {
            landing = line;
        }
    }
    QVERIFY2(!landing.isEmpty(),
             "a release must emit landing evidence even when it cannot be graded");
    QVERIFY(landing.contains(QStringLiteral("seq=4242")));
    QVERIFY(landing.contains(QStringLiteral("peak_fill=97.40")));
    QVERIFY(landing.contains(QStringLiteral("fill_at_rel=47.20")));
    // travel_pp is the whole point: peak - submit-fill is the distance the meter covered during
    // the lead, which divided by the meter velocity reads back the TRUE lead. A zero here means
    // the instrumentation has regressed to snapshotting the submit frame again.
    QVERIFY(landing.contains(QStringLiteral("travel_pp=50.20")));
}

// ---------------------------------------------------------------------------------------------
// [ORION_USER_LEAD] Shot Lead — the shipped, user-tuned actuation lead.
//
// The engine's own measured authority is not a shippable default: latency_estimator.py timestamps
// the meter's first UPWARD crossing of f_stop while the shot actually locks after the overshoot,
// so the label reads ~70-80ms short and the posterior walks the lead DOWN across a session. The
// user, however, has a complete feedback loop the engine does not — the game renders a per-shot
// TIMING banner — so the shipped design is a hand-tuned setting seeded from this install's own
// landing measurement.
// ---------------------------------------------------------------------------------------------

void AutomationEngineTests::userShotLeadReplacesTheDriftingMeasuredAuthority()
{
    orion::AutomationEngine engine;

    // BASELINE FIRST. With nothing configured a fresh install must behave EXACTLY as it did
    // before this control existed — otherwise the "0 = not configured" contract is a fiction and
    // every rig silently changed timing on upgrade.
    orion::AppConfigData unconfigured;
    QCOMPARE(unconfigured.actuationLeadMs, 0.0);
    QCOMPARE(unconfigured.actuationLeadUserSet, false);
    engine.applyConfig(unconfigured, orion::LearningData{});
    engine.measuredLatencyAuthorityMs_ = 227.6;   // the estimator's real, short, drifting number
    QCOMPARE(engine.measuredLeadForActuationMs(), 227.6);

    // Configured: the user's value IS the lead. It REPLACES the authority rather than nudging it —
    // the banner reports the total end-to-end result, so what they converge on is the whole lead.
    orion::AppConfigData config;
    config.actuationLeadMs = 300.0;
    config.actuationLeadUserSet = true;
    engine.applyConfig(config, orion::LearningData{});
    QCOMPARE(engine.measuredLeadForActuationMs(), 300.0);

    // And it is INDEPENDENT of the posterior's drift. This is the entire point: the same session
    // that walked 300 -> 266 -> 245 and brought LATE verdicts back must now leave the lead alone.
    engine.measuredLatencyAuthorityMs_ = 180.0;
    QCOMPARE(engine.measuredLeadForActuationMs(), 300.0);
    engine.measuredLatencyAuthorityMs_ = 420.0;
    QCOMPARE(engine.measuredLeadForActuationMs(), 300.0);

    // DIRECTION, asserted against the scheduler's own arithmetic rather than a comment: the fire
    // deadline is `tip - lead`, so a LARGER lead fires EARLIER. The UI copy ("landing LATE? raise
    // this") is only correct because of this, so it is pinned here.
    engine.measuredLatencyAuthorityMs_ = 227.6;
    const double smallLeadMs = engine.measuredLeadForActuationMs();
    config.actuationLeadMs = 340.0;
    engine.applyConfig(config, orion::LearningData{});
    const double largeLeadMs = engine.measuredLeadForActuationMs();
    constexpr double kTipAbsMs = 100'000.0;
    QVERIFY2(kTipAbsMs - largeLeadMs < kTipAbsMs - smallLeadMs,
             "a larger Shot Lead must fire EARLIER, or the UI guidance is inverted");

    // Out-of-band values degrade to "not configured" (the pre-existing path), never to a lead the
    // authority gate elsewhere would reject. Ignored, not clamped — same policy as the env vars.
    config.actuationLeadMs = 40.0;
    engine.applyConfig(config, orion::LearningData{});
    QCOMPARE(engine.measuredLeadForActuationMs(), 227.6);
    config.actuationLeadMs = 900.0;
    engine.applyConfig(config, orion::LearningData{});
    QCOMPARE(engine.measuredLeadForActuationMs(), 227.6);
}

void AutomationEngineTests::userShotLeadExtendedRangeRoundTrips()
{
#ifdef ORION_PRODUCTION_BUILD
    QSKIP("settings path redirects to the per-user data dir in production builds");
#endif
    // [ORION_USER_LEAD 2026-08-08] Cap raised 450 -> 800 (kActuationLeadMaxMs +
    // RemapConfig::actuationLeadMaxMs + LeadCalibrationPolicy::kMaxLeadMs, all in
    // lockstep): the injected Meter Delay adds to the total the TIMING banner
    // reports, so the owner's 250ms delay on a ~290ms baseline needs ~540 — the old
    // cap pinned the slider. This pins the exact failure mode of any stale clamp
    // left behind: a persisted 780 must LOAD as 780 (not 450, the old cap; not 800,
    // a wrong clamp), and the engine must CONSUME it as the in-band replacement lead.
    QTemporaryDir dir;
    QVERIFY(dir.isValid());
    writeSettingsJson(dir.path(), QJsonObject{
        {QStringLiteral("actuation_lead_ms"), 780.0},
        {QStringLiteral("actuation_lead_user_set"), true},
    });
    AppConfig cfg(dir.path());
    QVERIFY(cfg.load());
    QCOMPARE(cfg.data().actuationLeadMs, 780.0);
    QVERIFY(cfg.data().actuationLeadUserSet);

    AutomationEngine engine;
    engine.applyConfig(cfg.data(), orion::LearningData{});
    engine.measuredLatencyAuthorityMs_ = 227.6;
    QCOMPARE(engine.measuredLeadForActuationMs(), 780.0);

    // Band edges are still enforced by the load path: above-cap clamps down to the
    // new cap, and the sub-floor clamp-up to 150 is untouched.
    writeSettingsJson(dir.path(), QJsonObject{
        {QStringLiteral("actuation_lead_ms"), 900.0},
    });
    AppConfig over(dir.path());
    QVERIFY(over.load());
    QCOMPARE(over.data().actuationLeadMs, 800.0);
    writeSettingsJson(dir.path(), QJsonObject{
        {QStringLiteral("actuation_lead_ms"), 40.0},
    });
    AppConfig under(dir.path());
    QVERIFY(under.load());
    QCOMPARE(under.data().actuationLeadMs, 150.0);
}

void AutomationEngineTests::devLeadEnvOverrideStillBeatsTheUserShotLead()
{
    // ORION_LEAD_FLOOR_MS / ORION_LEAD_BIAS_MS exist so a live batch can SWEEP the lead without a
    // rebuild. A setting that replaces the lead outright would silently out-rank the value being
    // swept, so the env override wins whole — with either var present this path is byte-identical
    // to its pre-Shot-Lead behaviour.
    const QByteArray savedFloor = qgetenv("ORION_LEAD_FLOOR_MS");
    const bool hadFloor = qEnvironmentVariableIsSet("ORION_LEAD_FLOOR_MS");
    const QByteArray savedBias = qgetenv("ORION_LEAD_BIAS_MS");
    const bool hadBias = qEnvironmentVariableIsSet("ORION_LEAD_BIAS_MS");
    const auto restore = qScopeGuard([&] {
        if (hadFloor) { qputenv("ORION_LEAD_FLOOR_MS", savedFloor); } else { qunsetenv("ORION_LEAD_FLOOR_MS"); }
        if (hadBias) { qputenv("ORION_LEAD_BIAS_MS", savedBias); } else { qunsetenv("ORION_LEAD_BIAS_MS"); }
    });

    orion::AutomationEngine engine;
    orion::AppConfigData config;
    config.actuationLeadMs = 200.0;      // a user value the dev sweep must NOT be dragged to
    config.actuationLeadUserSet = true;

    // The dev rig's actual numbers from run_orion.local.ps1.
    qputenv("ORION_LEAD_FLOOR_MS", "290");
    qputenv("ORION_LEAD_BIAS_MS", "62");
    engine.applyConfig(config, orion::LearningData{});
    engine.measuredLatencyAuthorityMs_ = 227.6;
    // 227.6 + 62 = 289.6, floored to 290 — exactly what the rig produces today.
    QCOMPARE(engine.measuredLeadForActuationMs(), 290.0);

    // The floor alone is enough to claim the override: a sweep that only pins a floor must not be
    // quietly beaten by a lower setting.
    qunsetenv("ORION_LEAD_BIAS_MS");
    engine.applyConfig(config, orion::LearningData{});
    QCOMPARE(engine.measuredLeadForActuationMs(), 290.0);

    // Remove the env and the SETTING takes over on the very next apply. The override is recomputed
    // per apply and never latched, or a single dev launch would poison the user's install.
    qunsetenv("ORION_LEAD_FLOOR_MS");
    engine.applyConfig(config, orion::LearningData{});
    QCOMPARE(engine.measuredLeadForActuationMs(), 200.0);
}

void AutomationEngineTests::userShotLeadNeverManufacturesAuthorityForAnUnschedulableShot()
{
    // FAIL-CLOSED. The Shot Lead re-scales an ALREADY-VALID lead; it must never create one. A
    // 300ms setting on a shot with no measured authority still yields no lead and no release —
    // the same contract the floor/bias corrections were deliberately written to preserve.
    orion::AutomationEngine engine;
    orion::AppConfigData config;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    config.actuationLeadMs = 300.0;
    config.actuationLeadUserSet = true;
    engine.applyConfig(config, orion::LearningData{});

    engine.measuredLatencyAuthorityMs_ = 0.0;
    QCOMPARE(engine.measuredLeadForActuationMs(), 0.0);

    // POSITIVE CONTROL: the same engine with authority present does produce the user's lead, so
    // the zero above is the fail-closed gate and not the setting simply being inert here.
    engine.measuredLatencyAuthorityMs_ = 227.6;
    QCOMPARE(engine.measuredLeadForActuationMs(), 300.0);
    engine.measuredLatencyAuthorityMs_ = 0.0;

    // BEHAVIOURAL, not just arithmetic: with no authority a live tip decision must reserve
    // nothing. updateAutonomousTipReservation refuses on `leadMs <= 0`, which is the gate that
    // keeps an unschedulable shot unschedulable.
    const double now = engine.engineNowMs();
    AutomationEngine::AutonomousTipDecision decision;
    decision.tipAbsMs = now + 400.0;
    decision.source = QStringLiteral("sampler");
    engine.shot_.physicalShotEpoch = 5'301;
    engine.shot_.armToken = 5'302;
    engine.shot_.visionEpoch = 11;
    engine.updateAutonomousTipReservation(decision, now);
    QVERIFY2(!engine.tipReservation_.active,
             "no measured authority must stay unschedulable no matter what the user set");
}

void AutomationEngineTests::landingMeasurementIsDiagnosticOnlyAndSeedComesFromValidatedAuthority()
{
    // [ORION_USER_LEAD 2026-08-08] THE SEED'S INSTRUMENT CHANGED; this test used to pin the
    // opposite and was deliberately rewritten. It previously asserted that
    // actuationLeadMeasured publishes the landing travel_pp/velocity median after
    // actuationLeadSeedMinSamples clean landings ("the seed is measured, not guessed ... this
    // install's true end-to-end lead"). That claim is REFUTED: the release does not move the
    // meter (2026-08-04 -- release fill uncorrelated with peak/f_stop), so travel_pp/velocity
    // is a capture-side, circular quantity; and live on 2026-08-08 its median drifted
    // 225 -> 300 within seven minutes while captioned "Shot lead measured on your setup",
    // on the same session whose marker-anchored validated estimator measured 197.1 +/- 3.2.
    //
    // New contract, both halves revert-traced:
    //   1. landings NEVER publish actuationLeadMeasured (the diagnostic line remains);
    //   2. the validated estimator authority publishes it from telemetry ingestion, with 1 ms
    //      hysteresis so a refining posterior does not churn the UI per frame.
    orion::AutomationEngine engine;
    orion::AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, orion::LearningData{});
    QSignalSpy measured(&engine, &orion::AutomationEngine::actuationLeadMeasured);
    QSignalSpy diag(&engine, &orion::AutomationEngine::engineDiagnostic);

    // --- Half 1: landings alone, deeper than the old publication gate.
    engine.meterCapRiseVelocityPctPerMs_ = 0.18;
    const auto landing = [&](double travelPp) {
        engine.meterCapActive_ = true;
        engine.meterCapSeq_ = 1;
        engine.meterCapShotType_ = QStringLiteral("Standstill");
        engine.meterCapFillAtReleasePct_ = 40.0;
        engine.meterCapPeakFillPct_ = 40.0 + travelPp;
        engine.meterCapSamples_.clear();
        engine.evaluatePostReleaseMeter();
    };
    for (int i = 0; i < engine.config_.actuationLeadSeedMinSamples + 2; ++i) {
        landing(54.0);
    }
    bool sawLeadMeasurementLine = false;
    for (const QList<QVariant>& row : diag) {
        if (row.at(0).toString().startsWith(QStringLiteral("Lead measurement:"))) {
            sawLeadMeasurementLine = true;
        }
    }
    QVERIFY2(sawLeadMeasurementLine,
             "the travel_pp/velocity median must keep its diagnostic line for offline analysis");
    QCOMPARE(measured.count(), 0);   // the refuted proxy must never publish the seed again

    // --- Half 2: a validated authority snapshot publishes the seed from ingestion.
    int frame = 1;
    engine.updateDetection(strictLiveMeterSample(1.0, frame++, 4'201, 197.1, 3.2, 6));
    QCOMPARE(measured.count(), 1);
    QVERIFY(std::abs(measured.at(0).at(0).toDouble() - 197.1) < 1e-6);
    QCOMPARE(measured.at(0).at(1).toInt(), 6);

    // Hysteresis: an unchanged posterior must not republish per telemetry frame...
    engine.advanceTestClock(20.0);
    engine.updateDetection(strictLiveMeterSample(2.0, frame++, 4'201, 197.1, 3.2, 6));
    QCOMPARE(measured.count(), 1);
    // ...but a >=1 ms move does, carrying the new value and count.
    engine.advanceTestClock(20.0);
    engine.updateDetection(strictLiveMeterSample(3.0, frame++, 4'201, 198.4, 3.2, 7));
    QCOMPARE(measured.count(), 2);
    QVERIFY(std::abs(measured.at(1).at(0).toDouble() - 198.4) < 1e-6);
    QCOMPARE(measured.at(1).at(1).toInt(), 7);
}

void AutomationEngineTests::measuredSeedRefusesToOverwriteAConfiguredShotLead()
{
    // THE PRODUCT PROMISE, as a predicate the seeding path actually calls. "Hand-tune it once and
    // it is plug-and-play from then on" is worthless if a later measurement can move it back.
    orion::AppConfigData fresh;
    QVERIFY2(orion::actuationLeadAcceptsMeasuredSeed(fresh),
             "a never-configured install is exactly what the measurement is for");

    orion::AppConfigData userTuned;
    userTuned.actuationLeadMs = 284.0;
    userTuned.actuationLeadUserSet = true;
    QVERIFY2(!orion::actuationLeadAcceptsMeasuredSeed(userTuned),
             "a value the user chose is never silently overwritten");

    // Even a user who lands back on the measured number keeps their latch: the promise is about
    // authorship, not about the value being different.
    orion::AppConfigData userTunedToSameValue;
    userTunedToSameValue.actuationLeadMs = 302.0;
    userTunedToSameValue.actuationLeadUserSet = true;
    QVERIFY(!orion::actuationLeadAcceptsMeasuredSeed(userTunedToSameValue));

    // Already seeded but never touched: still locked, so the number under the slider cannot drift
    // while the user is reading the game's banner and drawing conclusions from it.
    orion::AppConfigData alreadySeeded;
    alreadySeeded.actuationLeadMs = 302.0;
    alreadySeeded.actuationLeadUserSet = false;
    QVERIFY2(!orion::actuationLeadAcceptsMeasuredSeed(alreadySeeded),
             "seeding is a one-time event, not a running auto-calibration");

    // An explicit reset is the ONE way back to measured — the escape hatch that keeps the latch
    // from being a trap when a user moves rig or network.
    orion::AppConfigData afterReset = userTuned;
    afterReset.actuationLeadMs = 0.0;
    afterReset.actuationLeadUserSet = false;
    QVERIFY(orion::actuationLeadAcceptsMeasuredSeed(afterReset));
}

void AutomationEngineTests::shotLeadConflictDiagnosedAtConfigAndOnMissedDeadline()
{
    // [ORION_LEAD_CONFLICT] THE 2026-08-08 SHIP-BLOCKER SIGNATURE. Tip Timing manually floored
    // at effective 314 (canonical 240) + Shot Lead 320 means the phase member's command deadline
    // is behind `now` on the first tick it can exist: 81 shots aborted live_tip_deadline_missed
    // across two sessions with nothing naming the two-knob conflict, while the decision line
    // dressed the user's 320 as "lead_kind=factory/validated". The engine must name the pair at
    // config time, name it again on every resulting miss, and label the lead's true source.
    AutomationEngine engine;
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    QSignalSpy conflictSpy(&engine, &AutomationEngine::shotLeadConflictDiagnosed);

    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    config.actuationLeadMs = 320.0;
    config.actuationLeadUserSet = true;
    config.tipPhaseAimFrozen = true;
    config.tipTimingUserSet = true;
    LearningData learning;
    learning.learnedPhasePhysicalMs = 240.0;   // the Tip Timing card's floor entry, canonical
    engine.applyConfig(config, learning);

    // effective constant = 240 + (393 - 319) = 314; usable max = 314 - 30 = 284 < 320.
    QVERIFY(std::abs(engine.effectiveTipPhaseConstantMsForTests() - 314.0) < 1e-9);
    const auto countConflictLines = [&]() {
        int n = 0;
        for (const QList<QVariant>& row : diagSpy) {
            if (row.at(0).toString().startsWith(QStringLiteral("SHOT LEAD CONFLICT:"))) {
                ++n;
            }
        }
        return n;
    };
    QCOMPARE(countConflictLines(), 1);
    QCOMPARE(conflictSpy.count(), 1);
    QVERIFY(std::abs(conflictSpy.at(0).at(0).toDouble() - 320.0) < 1e-9);
    QVERIFY(std::abs(conflictSpy.at(0).at(1).toDouble() - 284.0) < 1e-9);

    // De-dup: an identical re-apply must not warn again -- settings save churn is constant.
    engine.applyConfig(config, learning);
    QCOMPARE(countConflictLines(), 1);

    // A schedulable pair stays silent (250 < 284): the advisory names impossibilities only.
    AppConfigData fixed = config;
    fixed.actuationLeadMs = 250.0;
    engine.applyConfig(fixed, learning);
    QCOMPARE(countConflictLines(), 1);
    // ...and re-creating the conflict warns again (the fixed pair re-armed the latch).
    engine.applyConfig(config, learning);
    QCOMPARE(countConflictLines(), 2);

    // --- The live miss. Hand-stuffed exactly like the unschedulable-lead attribution test: a
    // VALID decision whose command deadline is already past the first time it is computed.
    const double now = engine.engineNowMs();
    engine.measuredLatencyMs_ = 230.0;
    engine.measuredLatencySdMs_ = 2.0;
    engine.measuredLatencyN_ = 6;
    engine.measuredLatencyAuthorityKind_ = QStringLiteral("validated");
    engine.measuredLatencyAuthorityMs_ = 230.0;      // present, and replaced by the user's 320
    engine.measuredLatencyAuthoritySdMs_ = 2.0;
    engine.measuredLeadTelemetryPresent_ = true;
    engine.measuredLeadEverValid_ = true;
    engine.measuredLeadEpochReady_ = true;
    engine.measuredLeadLastUpdateMs_ = now;

    engine.shot_.state = HoldState::Holding;
    engine.shot_.mode = ShotMode::ButtonShot;
    engine.shot_.shotType = QStringLiteral("Standstill");
    engine.shot_.holdStartMs = now - 10.0;
    engine.shot_.physicalShotEpoch = 9'501;
    engine.shot_.armToken = 9'502;
    engine.shot_.visionEpoch = 7;
    engine.shot_.meterDetected = true;
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.lastFreshAcceptMs = now;
    engine.shot_.firstFreshAcceptMs = now;
    engine.shot_.anchorValidMs = now;
    engine.shot_.sawFreshMeterThisShot = true;
    engine.shot_.meterSeenThisShot = true;
    engine.shot_.frameAgeMs = 0.0;
    engine.shot_.fillPct = 40.7;
    engine.shot_.confidence = 1.0;
    engine.shot_.regTipMs = 296.0;                   // tip_eta 296 vs lead 320 -> command_eta -24
    engine.shot_.regTipAbsMs = now + engine.shot_.regTipMs;
    engine.shot_.regConf = 1.0;
    engine.shot_.regSigmaMs = 2.0;
    engine.shot_.regN = 16;
    engine.shot_.regModelId = QStringLiteral("timing-audit-model");
    engine.shot_.regModelVersion = QStringLiteral("1");

    engine.lastPhysical_.buttons |= XINPUT_GAMEPAD_X;
    ControllerState output = engine.lastPhysical_;
    engine.processAutonomousLiveMeterHolding(output, now);

    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("live_tip_deadline_missed"));
    QString abortLine;
    QString missConflictLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("TIP DEADLINE DECISION:"))) {
            abortLine = line;
        } else if (line.startsWith(QStringLiteral("SHOT LEAD CONFLICT: lead "))) {
            missConflictLine = line;
        }
    }
    QVERIFY(!abortLine.isEmpty());
    // The mislabel fix: lead_kind keeps naming the authority; lead_source names the VALUE. The
    // production log asserted "lead_kind=validated lead_ms=320.000" for a user-typed 320.
    QVERIFY2(abortLine.contains(QStringLiteral("lead_source=user")),
             qPrintable(QStringLiteral("missing/wrong lead_source in: %1").arg(abortLine)));
    QVERIFY2(missConflictLine.contains(QStringLiteral("lead 320ms"))
                 && missConflictLine.contains(QStringLiteral("#1 this session")),
             qPrintable(QStringLiteral("missing miss-site conflict line, got: %1")
                            .arg(missConflictLine)));
    QCOMPARE(conflictSpy.count(), 3);   // first apply + re-created conflict + the miss
    QCOMPARE(conflictSpy.at(2).at(2).toInt(), 1);
}

