void AutomationEngineTests::meterDelayLeadStarvationSuppressesVisibleExtrapolatorArm()
{
    // THE 2026-08-08 SQUEAKER KILLER. With 250ms of applied meter delay and the matching
    // 540ms lead, the only schedulable estimates are pre-anchor long-horizon extrapolations
    // of the DELAYED video — the two that armed live fired at fill 13-18 and landed ~300ms
    // early on the visible meter. The engine must refuse the arm, hold the owned output
    // (fail-closed: no token, no release, physical DOWN preserved), and name the refusal
    // once with the delay arithmetic.
    AutomationEngine engine;
    engine.setMeterDelayCondition(250.0, true);
    const double now = stuffDelayStarvationShot(engine);

    ControllerState output = engine.lastPhysical_;
    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    QSignalSpy conflictSpy(&engine, &AutomationEngine::shotLeadConflictDiagnosed);

    // The decision itself is withdrawn, not merely unscheduled: both arm sites (tick and
    // subtick mirror) share this one predicate through decision.valid.
    const auto decision = engine.canonicalAutonomousTipDecision(now);
    QVERIFY2(!decision.valid, "starved visible-source decision must not be valid");
    QVERIFY(decision.delayStarvedVisibleSource);

    engine.processAutonomousLiveMeterHolding(output, now);

    QCOMPARE(markerSpy.count(), 0);
    QVERIFY2(engine.schedFireDeadlineMs_ < 0.0, "no precise-fire token may arm");
    QCOMPARE(engine.context().state, HoldState::Holding);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("owned_square_trajectory_unresolved"));
    QVERIFY2(output.square(), "owned physical DOWN must be held; no synthetic UP");

    QString starvedLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("SHOT LEAD CONFLICT: meter delay "))) {
            starvedLine = line;
        }
    }
    QVERIFY2(starvedLine.contains(QStringLiteral(
                 "meter delay 250ms starves lead 540ms")),
             qPrintable(QStringLiteral("missing starved line, got: %1").arg(starvedLine)));
    QVERIFY2(starvedLine.contains(QStringLiteral("registration")),
             qPrintable(QStringLiteral("starved line must name the source: %1")
                            .arg(starvedLine)));
    // [ORION_METER_DELAY_LEAD_KEYING 2026-08-09] The number here was "<=73ms" (max meter delay,
    // computed as usableMax - (lead - appliedDelay) = 363 - 290). Both the number and the advice
    // it carried were wrong, and are now corrected:
    //   * the arithmetic assumed the operator had folded the applied delay into Shot Lead. This
    //     fixture is the case where they HAD (540 = loop 290 + delay 250), but the 2026-08-09
    //     owner session is the case where they had not (lead 295, applied 175) and the same
    //     formula over-reported the room by exactly the applied delay;
    //   * and the advice it produced did not work even here: lowering the delay to 73 while the
    //     lead stays 540 leaves 540 > 363, so visibleEvidenceLeadStarvedByMeterDelay() still
    //     trips and the shot still aborts.
    // The delay's contribution to the lead is now an explicit term, so the loop component is
    // exact (540 - offset 0 = 540) and the honest headroom above the 363 ceiling is +0.
    QVERIFY2(starvedLine.contains(QStringLiteral("Offset headroom for this Tip Timing is +0ms")),
             qPrintable(QStringLiteral("starved line must carry the offset headroom: %1")
                            .arg(starvedLine)));
    QVERIFY2(!starvedLine.contains(QStringLiteral("delayed video")),
             qPrintable(QStringLiteral("the delayed-video premise is refuted: %1")
                            .arg(starvedLine)));
    // The spy was created after the fixture's applyConfig, so the config-time advisory is not
    // in it; exactly ONE conflict signal — the starved refusal — must have fired here.
    QCOMPARE(conflictSpy.count(), 1);

    // Once per shot: a second tick in the same shot stays quiet.
    engine.processAutonomousLiveMeterHolding(output, now + 4.0);
    int starvedLines = 0;
    for (const QList<QVariant>& row : diagSpy) {
        if (row.at(0).toString().startsWith(
                QStringLiteral("SHOT LEAD CONFLICT: meter delay "))) {
            ++starvedLines;
        }
    }
    QCOMPARE(starvedLines, 1);
}

void AutomationEngineTests::meterDelayLeadStarvationInertAtZeroDelay()
{
    // THE REGRESSION GUARD THE GATE MUST PASS: with 0ms applied delay the engine is
    // bit-identical to the pre-delay build EVEN with the same conflicted 540ms lead — the
    // same registration estimate stays valid, is not flagged, and arms a precise-fire token
    // exactly as today. (Whether a 540ms lead is wise at delay 0 is the existing conflict
    // advisory's business, not this gate's.)
    AutomationEngine engine;
    const double now = stuffDelayStarvationShot(engine);

    const auto decision = engine.canonicalAutonomousTipDecision(now);
    QVERIFY2(decision.valid, "zero-delay decision must stay valid");
    QVERIFY(!decision.delayStarvedVisibleSource);

    ControllerState output = engine.lastPhysical_;
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    engine.processAutonomousLiveMeterHolding(output, now);

    QVERIFY2(engine.schedFireDeadlineMs_ >= 0.0,
             "the same estimate must arm at zero applied delay");
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("release_scheduled"));
    for (const QList<QVariant>& row : diagSpy) {
        QVERIFY2(!row.at(0).toString().startsWith(
                     QStringLiteral("SHOT LEAD CONFLICT: meter delay ")),
                 "no starved line may appear at zero applied delay");
    }
}

void AutomationEngineTests::shotLeadConflictAbortAndConfigWarningNameAppliedMeterDelay()
{
    // The PHASE member's honest death under delay, now with the delay named. Mirrors the live
    // 23:07:26 abort: the anchor is witnessed in the DELAYED video, so the phase deadline is
    // already past on the first tick it exists (tip_eta 368 vs lead 540). The abort must keep
    // its truthful unschedulable_lead attribution AND both conflict surfaces must carry the
    // applied delay and the max schedulable delay (363 - 290 = 73ms).
    AutomationEngine engine;
    engine.setMeterDelayCondition(250.0, true);
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    const double now = stuffDelayStarvationShot(engine);

    // Config-time advisory (applyConfig ran inside the fixture, delay already applied).
    QString configLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("SHOT LEAD CONFLICT: Shot Lead "))) {
            configLine = line;
        }
    }
    // [ORION_METER_DELAY_LEAD_KEYING 2026-08-09] Was "max meter delay for this pair is 73ms";
    // see the identical correction note in
    // meterDelayLeadStarvationSuppressesVisibleExtrapolatorArm(). The delay's lead contribution
    // is now the explicit delayed-condition offset (0 here), so the loop component of this 540ms
    // lead is 540 and the headroom above the 363ms ceiling is +0.
    QVERIFY2(configLine.contains(QStringLiteral(
                 "Meter delay 250ms is applied; the delayed condition is reached with the "
                 "Shot Lead offset, and this pair leaves +0ms of offset headroom.")),
             qPrintable(QStringLiteral("config advisory missing delay context: %1")
                            .arg(configLine)));

    // Replace the registration estimate with a witnessed phase anchor 25ms ago: the phase
    // member dates the tip at +368 (constant 393), which cannot precede a 540ms lead.
    engine.shot_.regTipMs = 0.0;
    engine.shot_.regTipAbsMs = -1.0;
    engine.shot_.regConf = 0.0;
    engine.shot_.regModelId.clear();
    engine.shot_.regModelVersion.clear();
    engine.shot_.fillPct = 40.7;
    engine.shot_.fillPhaseAnchorMs = now - 25.0;
    engine.shot_.fillPhaseAnchorLevelPct = 30.0;

    ControllerState output = engine.lastPhysical_;
    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy abortSpy(&engine, &AutomationEngine::shotAborted);
    engine.processAutonomousLiveMeterHolding(output, now);

    QCOMPARE(markerSpy.count(), 0);
    QCOMPARE(engine.context().releaseReasonCode,
             QStringLiteral("live_tip_deadline_missed"));
    QCOMPARE(abortSpy.count(), 1);
    QCOMPARE(engine.context().state, HoldState::Idle);

    QString abortLine;
    QString missConflictLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("TIP DEADLINE DECISION:"))) {
            abortLine = line;
        } else if (line.startsWith(QStringLiteral("SHOT LEAD CONFLICT: lead "))) {
            missConflictLine = line;
        }
    }
    QVERIFY2(abortLine.contains(QStringLiteral("source=phase")),
             qPrintable(QStringLiteral("phase member must own the decision: %1")
                            .arg(abortLine)));
    QVERIFY2(abortLine.contains(QStringLiteral(
                 "reservation_disposition=unschedulable_lead")),
             qPrintable(QStringLiteral("wrong attribution in: %1").arg(abortLine)));
    QVERIFY2(missConflictLine.contains(QStringLiteral("lead 540ms"))
                 && missConflictLine.contains(QStringLiteral(
                     "Meter delay 250ms is applied; delayed-condition offset headroom for this "
                     "lead/Tip Timing is +0ms.")),
             qPrintable(QStringLiteral("miss conflict line missing delay context: %1")
                            .arg(missConflictLine)));
}

// ─── [ORION_METER_DELAY_LEAD_KEYING 2026-08-09] ─────────────────────────────────────────────
// Fixture: a shot that the phase member CAN schedule, so the tests below observe the consumed
// lead rather than an abort. Deliberately separate from stuffDelayStarvationShot (whose whole
// point is a lead past the ceiling). Base Shot Lead 295 ms is the owner's live 2026-08-09 value.
double AutomationEngineTests::stuffSchedulableDelayShot(orion::AutomationEngine& engine,
                                                        double baseLeadMs, double delayOffsetMs,
                                                        double tipEtaMs)
{
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    config.actuationLeadMs = baseLeadMs;
    config.actuationLeadUserSet = true;
    config.meterDelayLeadOffsetMs = delayOffsetMs;
    engine.applyConfig(config, LearningData{});

    engine.advanceTestClock(120'000.0);
    const double now = engine.engineNowMs();
    engine.measuredLatencyMs_ = 240.0;
    engine.measuredLatencySdMs_ = 2.0;
    engine.measuredLatencyN_ = 6;
    engine.measuredLatencyAuthorityKind_ = QStringLiteral("validated");
    engine.measuredLatencyAuthorityMs_ = 240.0;   // present, and replaced by the user's lead
    engine.measuredLatencyAuthoritySdMs_ = 2.0;
    engine.measuredLeadTelemetryPresent_ = true;
    engine.measuredLeadEverValid_ = true;
    engine.measuredLeadEpochReady_ = true;
    engine.measuredLeadLastUpdateMs_ = now;

    engine.shot_.state = HoldState::Holding;
    engine.shot_.mode = ShotMode::ButtonShot;
    engine.shot_.shotType = QStringLiteral("Standstill");
    engine.shot_.holdStartMs = now - 10.0;
    engine.shot_.physicalShotEpoch = 9'701;
    engine.shot_.armToken = 9'702;
    engine.shot_.visionEpoch = 7;
    engine.shot_.meterDetected = true;
    engine.shot_.lastSampleGenuineAccept = true;
    engine.shot_.lastFreshAcceptMs = now;
    engine.shot_.firstFreshAcceptMs = now;
    engine.shot_.anchorValidMs = now;
    engine.shot_.sawFreshMeterThisShot = true;
    engine.shot_.meterSeenThisShot = true;
    engine.shot_.frameAgeMs = 0.0;
    engine.shot_.fillPct = 13.5;
    engine.shot_.confidence = 1.0;
    // tipEtaMs is a parameter because the arming horizon is ~122 ms: a caller that asserts on
    // the ARM must hand in a tip whose command_eta (tipEta - consumed lead) lands inside it,
    // while a caller that only reads the reservation line can use any horizon it likes.
    engine.shot_.regTipMs = tipEtaMs;
    engine.shot_.regTipAbsMs = now + engine.shot_.regTipMs;
    engine.shot_.regConf = 1.0;
    engine.shot_.regSigmaMs = 2.0;
    engine.shot_.regN = 16;
    engine.shot_.regModelId = QStringLiteral("timing-audit-model");
    engine.shot_.regModelVersion = QStringLiteral("1");
    engine.lastPhysical_.buttons |= XINPUT_GAMEPAD_X;
    return now;
}

void AutomationEngineTests::meterDelayLeadOffsetInertAtZeroDelay()
{
    // THE GUARD ON THE WORKING PATH. The owner's delay-OFF sessions are the ONLY configuration
    // that currently lands (settled_fill median 94.3 over 35 graded landings, 2026-08-09
    // 13:38-13:41). Nothing about the offset may reach them: with no applied delay the consumed
    // lead is the operator's Shot Lead to the millisecond, whatever the offset is set to, and
    // whatever sign it has.
    for (const double offsetMs : {0.0, 120.0, -80.0, 400.0, -200.0}) {
        AutomationEngine engine;
        stuffSchedulableDelayShot(engine, 295.0, offsetMs, /*tipEtaMs=*/350.0);
        QCOMPARE(engine.appliedMeterDelayLeadOffsetMs(), 0.0);
        QCOMPARE(engine.measuredLeadForActuationMs(), 295.0);
        QCOMPARE(engine.actuationLeadSourceLabel(295.0), QStringLiteral("user"));
    }

    // ...and the shot still arms exactly as it does today.
    AutomationEngine engine;
    const double now = stuffSchedulableDelayShot(engine, 295.0, 120.0, /*tipEtaMs=*/350.0);
    ControllerState output = engine.lastPhysical_;
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    engine.processAutonomousLiveMeterHolding(output, now);
    QVERIFY2(engine.schedFireDeadlineMs_ >= 0.0,
             "the delay-0 arm must be unchanged by a configured offset");
    for (const QList<QVariant>& row : diagSpy) {
        QVERIFY2(!row.at(0).toString().startsWith(
                     QStringLiteral("METER DELAY LEAD UNCALIBRATED:")),
                 "no delay-condition advisory may appear at zero applied delay");
    }
}

void AutomationEngineTests::meterDelayLeadOffsetKeysConsumedLeadWhenDelayApplied()
{
    // THE FIX ITSELF. With a delay applied, the consumed lead becomes base + offset — and it
    // does so through measuredLeadForActuationMs(), which is the single accessor the
    // reservation, both arm sites, the deadline decision and every conflict surface read. That
    // is what "end to end" means here: there is no second place to teach.
    AutomationEngine engine;
    const double now = stuffSchedulableDelayShot(engine, 295.0, 60.0, /*tipEtaMs=*/600.0);
    engine.setMeterDelayCondition(175.0, true);

    QCOMPARE(engine.appliedMeterDelayLeadOffsetMs(), 60.0);
    QCOMPARE(engine.measuredLeadForActuationMs(), 355.0);
    // Provenance must survive the keying: the value is still the operator's, not the authority's
    // (the 240 ms posterior is present and deliberately out-ranked).
    QCOMPARE(engine.actuationLeadSourceLabel(355.0), QStringLiteral("user"));

    // The scheduler consumes it: the reservation is created against the keyed lead.
    ControllerState output = engine.lastPhysical_;
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    engine.processAutonomousLiveMeterHolding(output, now);
    QString reservationLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("TIP RESERVATION:"))) {
            reservationLine = line;
        }
    }
    QVERIFY2(reservationLine.contains(QStringLiteral("lead_ms=355.000")),
             qPrintable(QStringLiteral("reservation must consume the keyed lead: %1")
                            .arg(reservationLine)));

    // Negative offsets are honoured too — the correction's SIGN is an empirical property of the
    // console under load, not something this code may assume.
    AutomationEngine down;
    stuffSchedulableDelayShot(down, 295.0, -45.0, /*tipEtaMs=*/600.0);
    down.setMeterDelayCondition(175.0, true);
    QCOMPARE(down.measuredLeadForActuationMs(), 250.0);

    // Dropping the delay restores the delay-0 lead within the same session, with no re-apply.
    // This is the case a hand-typed Shot Lead can never cover: OffenseDefense mode and the
    // D-Pad-Up bypass both toggle the condition mid-session.
    down.setMeterDelayCondition(0.0, true);
    QCOMPARE(down.measuredLeadForActuationMs(), 295.0);
}

void AutomationEngineTests::meterDelayLeadOffsetPastCeilingStillAbortsFailClosed()
{
    // THE OFFSET MAY NOT BUY AN UNSCHEDULABLE FIRE. Because the offset lands inside
    // measuredLeadForActuationMs(), an offset that pushes the consumed lead past the
    // visible-evidence ceiling trips the pre-existing starvation predicate and the shot dies
    // through the pre-existing fail-closed path — it does not sneak a blind release through.
    AutomationEngine engine;
    stuffSchedulableDelayShot(engine, 295.0, 0.0, /*tipEtaMs=*/600.0);
    const double usableMax = engine.maxSchedulableTipLeadMs();
    QVERIFY(usableMax > 295.0);

    // Just inside the ceiling: schedulable, no starvation.
    const double insideOffset = usableMax - 295.0 - 1.0;
    AutomationEngine inside;
    stuffSchedulableDelayShot(inside, 295.0, insideOffset, /*tipEtaMs=*/600.0);
    inside.setMeterDelayCondition(175.0, true);
    QVERIFY2(!inside.visibleEvidenceLeadStarvedByMeterDelay(
                 inside.measuredLeadForActuationMs()),
             "an offset inside the ceiling must stay schedulable");

    // One millisecond past it: starved, and the engine says so.
    AutomationEngine over;
    const double now =
        stuffSchedulableDelayShot(over, 295.0, usableMax - 295.0 + 1.0, /*tipEtaMs=*/600.0);
    over.setMeterDelayCondition(175.0, true);
    QVERIFY2(over.visibleEvidenceLeadStarvedByMeterDelay(over.measuredLeadForActuationMs()),
             "an offset past the ceiling must starve exactly like a hand-typed lead would");

    ControllerState output = over.lastPhysical_;
    QSignalSpy markerSpy(&over, &AutomationEngine::releaseMarker);
    over.processAutonomousLiveMeterHolding(output, now);
    QCOMPARE(markerSpy.count(), 0);
    QVERIFY2(over.schedFireDeadlineMs_ < 0.0,
             "no precise-fire token may arm from an unschedulable offset");
    QVERIFY2(output.square(), "owned physical DOWN must be held; no synthetic UP");

    // The reported headroom is exactly the ceiling minus the delay-0 lead, so the operator can
    // read the largest offset that still schedules straight off the number.
    QCOMPARE(inside.maxMeterDelayLeadOffsetMs(), usableMax - 295.0);
}

void AutomationEngineTests::meterDelayUncalibratedLeadIsDiagnosed()
{
    // THE SILENT FAILURE, MADE LOUD. 2026-08-09 13:33-13:34: delay 175 applied, Shot Lead left
    // at its delay-0 value of 295, eight graded landings all mistimed (settled_fill 83.61/83.61/
    // 52.70/83.61/52.68/50.42/52.70/52.69 against peak_fill 98-100) — and not one diagnostic,
    // because the only predicate that could object keys on lead > usable max and 295 is not.
    AutomationEngine engine;
    const double now = stuffSchedulableDelayShot(engine, 295.0, 0.0, /*tipEtaMs=*/350.0);
    engine.setMeterDelayCondition(175.0, true);

    ControllerState output = engine.lastPhysical_;
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    engine.processAutonomousLiveMeterHolding(output, now);

    QString advisory;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("METER DELAY LEAD UNCALIBRATED:"))) {
            advisory = line;
        }
    }
    QVERIFY2(advisory.contains(QStringLiteral("meter delay 175ms is applied")),
             qPrintable(QStringLiteral("advisory must name the applied delay: %1").arg(advisory)));
    QVERIFY2(advisory.contains(QStringLiteral("delay-0 lead (295ms)")),
             qPrintable(QStringLiteral("advisory must name the lead in force: %1").arg(advisory)));
    QVERIFY2(advisory.contains(QStringLiteral("headroom +")),
             qPrintable(QStringLiteral("advisory must hand over the headroom: %1").arg(advisory)));
    // It must NOT arm anything or change the shot: this is a diagnostic, and the shot that
    // triggered it still schedules exactly as it did before the line existed.
    QVERIFY2(engine.schedFireDeadlineMs_ >= 0.0,
             "the advisory must not change scheduling");

    // Once per delay value: a second tick, and a third, stay quiet.
    engine.processAutonomousLiveMeterHolding(output, now + 4.0);
    engine.processAutonomousLiveMeterHolding(output, now + 8.0);
    int advisories = 0;
    for (const QList<QVariant>& row : diagSpy) {
        if (row.at(0).toString().startsWith(QStringLiteral("METER DELAY LEAD UNCALIBRATED:"))) {
            ++advisories;
        }
    }
    QCOMPARE(advisories, 1);

    // A calibrated condition says nothing at all.
    AutomationEngine tuned;
    const double tunedNow = stuffSchedulableDelayShot(tuned, 295.0, 60.0, /*tipEtaMs=*/600.0);
    tuned.setMeterDelayCondition(175.0, true);
    ControllerState tunedOut = tuned.lastPhysical_;
    QSignalSpy tunedSpy(&tuned, &AutomationEngine::engineDiagnostic);
    tuned.processAutonomousLiveMeterHolding(tunedOut, tunedNow);
    for (const QList<QVariant>& row : tunedSpy) {
        QVERIFY2(!row.at(0).toString().startsWith(
                     QStringLiteral("METER DELAY LEAD UNCALIBRATED:")),
                 "a calibrated delayed condition must not warn");
    }
}

void AutomationEngineTests::meterDelayLeadOffsetHeadroomArithmeticIsOffsetBased()
{
    // THE ADVICE BUG, PINNED. maxMeterDelayForLeadMs() used to subtract meterDelayAppliedMs_ —
    // i.e. it assumed the operator had already folded the applied delay into Shot Lead. The
    // 2026-08-09 owner had not (Shot Lead 295 with 175 applied), so the app told them they had
    // 271 ms of room (391.3 - (295 - 175)) on a rig whose real headroom over that lead was 96.
    // The delay's lead contribution is now the explicit offset, so the loop component is exact.
    AutomationEngine engine;
    stuffSchedulableDelayShot(engine, 295.0, 0.0, /*tipEtaMs=*/600.0);
    const double usableMax = engine.maxSchedulableTipLeadMs();
    engine.setMeterDelayCondition(175.0, true);

    // Offset 0: the loop component is the whole 295, headroom = usableMax - 295. The OLD
    // arithmetic would have returned usableMax - 120, i.e. 175 ms too generous.
    QCOMPARE(engine.maxMeterDelayForLeadMs(295.0), usableMax - 295.0);
    QVERIFY2(std::abs(engine.maxMeterDelayForLeadMs(295.0) - (usableMax - 120.0)) > 100.0,
             "the applied delay must no longer be credited back into the loop component");

    // With a calibrated offset the loop component is still 295 — the offset is subtracted, not
    // the applied delay — so the number does not move when the operator tunes the offset.
    AutomationEngine tuned;
    stuffSchedulableDelayShot(tuned, 295.0, 60.0, /*tipEtaMs=*/600.0);
    tuned.setMeterDelayCondition(175.0, true);
    QCOMPARE(tuned.maxMeterDelayForLeadMs(355.0), usableMax - 295.0);
    QCOMPARE(tuned.maxMeterDelayLeadOffsetMs(), usableMax - 295.0);

    // And at delay 0 the accessor is the plain ceiling-minus-lead: no delay term anywhere.
    tuned.setMeterDelayCondition(0.0, true);
    QCOMPARE(tuned.maxMeterDelayForLeadMs(295.0), usableMax - 295.0);

    // CALL-SITE CONSISTENCY, observed on the EMITTED LINE (a bug caught re-reading the patch,
    // so it gets a test that can actually catch it again). maxMeterDelayForLeadMs() subtracts
    // the in-force offset from whatever lead it is handed, so every caller must hand it the
    // KEYED lead. Two of the three call sites already hold the keyed lead; the config-time
    // advisory holds the RAW setting and must add the term itself, or it over-reports the
    // headroom by exactly the offset — the same class of mistake as the original bug.
    //
    // Base lead 385 (above the 363 ceiling, so the advisory fires), offset +60, delay applied.
    //   correct: loop = (385 + 60) - 60 = 385  -> headroom max(0, 363 - 385) = +0ms
    //   raw-lead bug: loop = 385 - 60 = 325    -> headroom 363 - 325        = +38ms
    AutomationEngine advisory;
    advisory.setMeterDelayCondition(175.0, true);
    QSignalSpy advisorySpy(&advisory, &AutomationEngine::engineDiagnostic);
    AppConfigData advisoryConfig;
    advisoryConfig.remotePlayInputSource = QStringLiteral("square");
    advisoryConfig.autonomousVision = true;
    advisoryConfig.measuredLeadEnabled = true;
    advisoryConfig.actuationLeadMs = 385.0;
    advisoryConfig.actuationLeadUserSet = true;
    advisoryConfig.meterDelayLeadOffsetMs = 60.0;
    advisory.applyConfig(advisoryConfig, LearningData{});
    QString advisoryLine;
    for (const QList<QVariant>& row : advisorySpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("SHOT LEAD CONFLICT: Shot Lead "))) {
            advisoryLine = line;
        }
    }
    QVERIFY2(!advisoryLine.isEmpty(), "the config-time advisory must fire above the ceiling");
    QVERIFY2(advisoryLine.contains(QStringLiteral("leaves +0ms of offset headroom")),
             qPrintable(QStringLiteral("config advisory must key the lead it measures: %1")
                            .arg(advisoryLine)));
}

void AutomationEngineTests::pressTipObservationUnderDelayIsLoggedButNotLearned()
{
    // Drive the Phase-A collector directly with a landing that is perfect in every respect
    // EXCEPT that a meter delay was applied for the shot, and check the two halves separately:
    // the line is emitted (census) and the learner does not move (no cross-condition poisoning).
    const auto runOne = [](double appliedDelayMs, QString* lineOut) {
        AutomationEngine engine;
        engine.applyConfig(AppConfigData{}, LearningData{});
        engine.advanceTestClock(120'000.0);
        const double now = engine.engineNowMs();
        engine.measuredLFixedMs_ = 180.0;                 // V (l_fixed) -> H confidence
        engine.meterCapPhysicalEpoch_ = 9'801;
        engine.meterCapPressWallMs_ = now - 800.0;
        engine.meterCapPhaseStopMs_ = now;                // stop confirmed, capture-aligned
        engine.meterCapPhaseStopConfirmed_ = true;
        engine.meterCapAppliedDelayMs_ = appliedDelayMs;
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
        engine.emitPressTipObservation(
            7, QStringLiteral("Standstill"), /*graded=*/true, /*greenObserved=*/true,
            QVector<AutomationEngine::MeterCalSample>{});
        for (const QList<QVariant>& row : diagSpy) {
            const QString line = row.at(0).toString();
            if (line.startsWith(QStringLiteral("PRESS-TIP OBSERVATION:"))) {
                *lineOut = line;
            }
        }
        return engine.pressAnchoredLearnedWeight(QStringLiteral("Standstill"));
    };

    // Delay 0: unchanged — H confidence, accepted, and the learner takes the sample. This is
    // the guard on the working path; the collector must keep working exactly as it does today.
    QString cleanLine;
    const double cleanWeight = runOne(0.0, &cleanLine);
    QVERIFY2(cleanLine.contains(QStringLiteral("applied_delay_ms=0")), qPrintable(cleanLine));
    QVERIFY2(cleanLine.contains(QStringLiteral("confidence=H")), qPrintable(cleanLine));
    QVERIFY2(cleanLine.contains(QStringLiteral("accepted=1")), qPrintable(cleanLine));
    QVERIFY2(cleanWeight > 0.0, "a clean delay-0 landing must reach the learner");

    // Delay 175: the SAME landing, logged in full (same confidence, so the census can still
    // see it was a good read) but refused by the learner.
    QString delayedLine;
    const double delayedWeight = runOne(175.0, &delayedLine);
    QVERIFY2(delayedLine.contains(QStringLiteral("applied_delay_ms=175")),
             qPrintable(delayedLine));
    QVERIFY2(delayedLine.contains(QStringLiteral("confidence=H")), qPrintable(delayedLine));
    QVERIFY2(delayedLine.contains(QStringLiteral("accepted=0")), qPrintable(delayedLine));
    QCOMPARE(delayedWeight, 0.0);
}

void AutomationEngineTests::tempoRemapGatesOnBridgeLive()
{
    // [ORION_TEMPO_BRIDGE_LIVE task #36] The remap must never eat a Square press the
    // packet-bridge intercept cannot back. Four regimes:
    //   A. wired + NOT live  -> plain Button pass-through + ONE attributed log line;
    //   B. wired + live      -> the remap engages exactly as before;
    //   C. wired + live state but STALE health beat -> pass-through (dead backend);
    //   D. unwired (standalone/unit engine) -> legacy toggle-only behavior, which is what
    //      keeps every pre-existing tempo test bit-identical.
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.tempoRemapEnabled = true;
    config.meterEnabled = true;
    config.minimumHoldMs = 0.0;
    config.fixedHoldMs = 650.0;
    LearningData learning;

    {   // A: THE FILED SYMPTOM -- meter delay is engaged (owner turned it on) but the backend
        // is NOT actually intercepting (no service / sniff-only install). The remap must not
        // eat a Square press the bridge cannot back.
        // [FIX 2026-08-09] This case previously also asserted delay-NOT-engaged, which made
        // the gate block tempo on every delay-off shot. Delay-off is regime E below.
        AutomationEngine engine;
        engine.applyConfig(config, learning);
        engine.setMeterDelayCondition(250.0, true);
        engine.setTempoRemapBridgeState(true, false, QStringLiteral("Locked"));
        engine.noteTempoRemapBridgeHealthBeat();
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        auto output = engine.process(physical);
        QVERIFY2(output.square(), "not-live: the press must reach the console");
        QCOMPARE(output.rightStickY, 0);

        engine.advanceTestClock(220);
        output = engine.process(physical);
        QVERIFY2(output.square(), "not-live: the hold stays a Button gesture");
        QCOMPARE(output.rightStickY, 0);
        QCOMPARE(engine.shotsAttempted(), 1);
        QCOMPARE(engine.context().mode, ShotMode::ButtonShot);

        int passthroughLines = 0;
        QString line;
        for (const QList<QVariant>& row : diagSpy) {
            if (row.at(0).toString().startsWith(QStringLiteral("Tempo remap: passthrough"))) {
                ++passthroughLines;
                line = row.at(0).toString();
            }
        }
        QCOMPARE(passthroughLines, 1);   // once per press edge, not per tick
        QCOMPARE(line, QStringLiteral(
            "Tempo remap: passthrough because bridge-not-live (delay_state=Locked applied_ms=250)"));
    }

    {   // E: [REGRESSION 2026-08-09] meter delay OFF entirely. The owner is simply not using
        // the delay feature; tempo remap does not ride the delay intercept and MUST still
        // engage. Shipping the broader gate silently disabled tempo remap for every
        // delay-off shot, which is how it reached the owner's rig toggled-on-but-inert.
        AutomationEngine engine;
        engine.applyConfig(config, learning);
        engine.setTempoRemapBridgeState(false, false, QStringLiteral("Standby"));
        engine.noteTempoRemapBridgeHealthBeat();
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        auto output = engine.process(physical);
        engine.advanceTestClock(220);
        output = engine.process(physical);
        QCOMPARE(engine.shotsAttempted(), 1);
        QCOMPARE(engine.context().mode, ShotMode::TempoSquare);
        QVERIFY2(!output.square(), "delay-off: the remap still owns Square");
        QCOMPARE(output.rightStickY, 127);
        for (const QList<QVariant>& row : diagSpy) {
            QVERIFY2(!row.at(0).toString().startsWith(QStringLiteral("Tempo remap: passthrough")),
                     "delay-off must NOT log a bridge-not-live passthrough");
        }
    }

    {   // B: bridge live (delay Locked, service echo applying, fresh beat) -> remap engages.
        AutomationEngine engine;
        engine.applyConfig(config, learning);
        engine.setMeterDelayCondition(250.0, true);
        engine.setTempoRemapBridgeState(true, true, QStringLiteral("Locked"));
        engine.noteTempoRemapBridgeHealthBeat();
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        auto output = engine.process(physical);
        engine.advanceTestClock(220);
        output = engine.process(physical);
        QCOMPARE(engine.shotsAttempted(), 1);
        QCOMPARE(engine.context().mode, ShotMode::TempoSquare);
        QVERIFY2(!output.square(), "live: the remap owns Square");
        QCOMPARE(output.rightStickY, 127);   // RS down-load
        for (const QList<QVariant>& row : diagSpy) {
            QVERIFY2(!row.at(0).toString().startsWith(
                         QStringLiteral("Tempo remap: passthrough")),
                     "live: no passthrough line may appear");
        }
    }

    {   // C: live-looking state but the backend stopped beating -> pass-through.
        AutomationEngine engine;
        engine.applyConfig(config, learning);
        engine.advanceTestClock(120'000.0);  // deterministic clock far from 0
        engine.setMeterDelayCondition(250.0, true);
        engine.setTempoRemapBridgeState(true, true, QStringLiteral("Locked"));
        engine.noteTempoRemapBridgeHealthBeat();
        engine.advanceTestClock(6'000.0);    // > kTempoRemapBridgeHealthFreshMs
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        auto output = engine.process(physical);
        QVERIFY2(output.square(), "stale health: the press must reach the console");
        QCOMPARE(output.rightStickY, 0);
        QString line;
        for (const QList<QVariant>& row : diagSpy) {
            if (row.at(0).toString().startsWith(QStringLiteral("Tempo remap: passthrough"))) {
                line = row.at(0).toString();
            }
        }
        QCOMPARE(line, QStringLiteral(
            "Tempo remap: passthrough because bridge-not-live (delay_state=Locked applied_ms=250)"));
    }

    {   // D: unwired engine -> legacy remap, bit-identical (the guard for every old test).
        AutomationEngine engine;
        engine.applyConfig(config, learning);
        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        auto output = engine.process(physical);
        engine.advanceTestClock(220);
        output = engine.process(physical);
        QCOMPARE(engine.context().mode, ShotMode::TempoSquare);
        QVERIFY(!output.square());
        QCOMPARE(output.rightStickY, 127);
    }
}

void AutomationEngineTests::shotLeadUsableMaxClampReflectsAppliedDelay()
{
    // [ORION_LEAD_CONFLICT_UI task #48] The shipped indicator line
    // (orion::shotLeadUsableMaxWarningLine, bound by ShotLeadUsableMaxIndicator through
    // OrionAppController::shotLeadUsableMaxWarning).
    using orion::shotLeadUsableMaxWarningLine;

    // Inside the usable range: silent — at delay 0 (full range) AND with a delay applied
    // (an applied delay alone is not a conflict).
    QCOMPARE(shotLeadUsableMaxWarningLine(300.0, 407.0, 0.0), QString());
    QCOMPARE(shotLeadUsableMaxWarningLine(405.0, 407.0, 250.0), QString());

    // The 2026-08-08 live pair (delay 250, lead 540, usable 407): red, and the delay is named.
    // [ORION_METER_DELAY_LEAD_KEYING 2026-08-09] The second clause used to read "or lower the
    // meter delay to 117 ms", from usableMax - (lead - applied). That advice is refuted twice:
    // the subtraction assumes the operator folded the applied delay into Shot Lead (on
    // 2026-08-09 they had not — lead 295, applied 175 — and the number came out 96 ms too
    // generous), and lowering the delay does not restore schedulability anyway because the
    // starvation predicate compares the LEAD to the ceiling. Clamping Shot Lead is the only
    // move that works, so it is the only move the indicator offers.
    const QString warn = shotLeadUsableMaxWarningLine(540.0, 407.0, 250.0);
    QVERIFY2(warn.contains(QStringLiteral("Above usable max (407 ms with 250 ms delay)")),
             qPrintable(warn));
    QVERIFY2(warn.contains(QStringLiteral("shots will abort")), qPrintable(warn));
    QVERIFY2(warn.contains(QStringLiteral("Clamp Shot Lead to 407 ms")), qPrintable(warn));
    QVERIFY2(warn.contains(QStringLiteral("Meter Delay Lead Offset")), qPrintable(warn));
    QVERIFY2(!warn.contains(QStringLiteral("lower the meter delay")), qPrintable(warn));

    // Same conflicted lead at delay 0: still a warning (the phase deadline is past at ANY
    // delay — usable max is delay-independent in total-lead terms; the 2026-08-08
    // verification refuted extending it by the delay) but with no delay clause to blame.
    const QString warn0 = shotLeadUsableMaxWarningLine(540.0, 407.0, 0.0);
    QVERIFY2(warn0.contains(QStringLiteral("Above usable max (407 ms)")), qPrintable(warn0));
    QVERIFY2(!warn0.contains(QStringLiteral("delay")), qPrintable(warn0));

    // Engine linkage: the usable max the indicator quotes IS maxSchedulableTipLeadMs(),
    // unchanged by the applied delay; what the delay changes is the ABORT reality — the
    // starvation gate engages above the max at delay 250 and the indicator's clamp value
    // (== usable max) restores schedulability.
    AutomationEngine engine;
    engine.applyConfig(AppConfigData{}, LearningData{});
    const double usableMax = engine.maxSchedulableTipLeadMs();
    QVERIFY(usableMax > 0.0);
    engine.setMeterDelayCondition(250.0, true);
    QCOMPARE(engine.maxSchedulableTipLeadMs(), usableMax);
    QVERIFY(engine.visibleEvidenceLeadStarvedByMeterDelay(usableMax + 1.0));
    QVERIFY2(!engine.visibleEvidenceLeadStarvedByMeterDelay(usableMax),
             "the clamp-to-safe value must be schedulable under the same delay");
    engine.setMeterDelayCondition(0.0, true);
    QVERIFY2(!engine.visibleEvidenceLeadStarvedByMeterDelay(usableMax + 1.0),
             "the starvation gate stays inert at zero applied delay");
}

void AutomationEngineTests::scServiceStartTriesBothNames()
{
    // [ORION_PACKET_BRIDGE_NAMES task #64] The candidate list the sc.exe path consumes is
    // the ratified migration-window list, current name first.
    const QStringList candidates = orion::packetBridgeServiceNameCandidates();
    QCOMPARE(candidates, QStringList({QStringLiteral("VeniceNetSvc"),
                                      QStringLiteral("NexusVisionSvc")}));

    // Wave-3 install: only VeniceNetSvc registered — found, and probed FIRST.
    QStringList probedOrder;
    const QString wave3 = orion::resolveInstalledPacketBridgeServiceName(
        candidates, [&probedOrder](const QString& name) {
            probedOrder.append(name);
            return name == QLatin1String("VeniceNetSvc");
        });
    QCOMPARE(wave3, QStringLiteral("VeniceNetSvc"));
    QCOMPARE(probedOrder, QStringList({QStringLiteral("VeniceNetSvc")}));

    // Legacy install: only NexusVisionSvc registered — the fallback MUST keep working.
    probedOrder.clear();
    const QString legacy = orion::resolveInstalledPacketBridgeServiceName(
        candidates, [&probedOrder](const QString& name) {
            probedOrder.append(name);
            return name == QLatin1String("NexusVisionSvc");
        });
    QCOMPARE(legacy, QStringLiteral("NexusVisionSvc"));
    QCOMPARE(probedOrder, candidates);

    // Neither registered: empty verdict -> the sniff-only debug fallback path.
    QCOMPARE(orion::resolveInstalledPacketBridgeServiceName(
                 candidates, [](const QString&) { return false; }),
             QString());
}

// [ORION_PRESS_ANCHOR] Shared stuffing for the press-anchored member: a dated press for the
// fixture's physical epoch (9601), a V estimate, and `n` accepted H-confidence observations
// of `pressToTipMs` fed through the REAL learner entry point (never a hand-set median), so
// every test exercises the same windowed-median/MAD path production will.
void AutomationEngineTests::stuffPressAnchoredCalibration(orion::AutomationEngine& engine,
                                                          double now, double pressAgoMs,
                                                          double pressToTipMs, int n)
{
    engine.pressWallEpoch_ = 9'601;
    engine.pressWallMsForEpoch_ = now - pressAgoMs;
    engine.measuredLFixedMs_ = 180.0;   // V estimate (l_fixed)
    for (int i = 0; i < n; ++i) {
        engine.recordPressToTipObservation(QStringLiteral("Standstill"), pressToTipMs, 1.0);
    }
}

void AutomationEngineTests::pressAnchoredDisabledByDefault()
{
    // The Phase-B gate: with press_anchored_predictor_enabled at its default (OFF), the
    // delay-0 decision path is byte-identical to the pre-scaffold build even when a dated
    // press, a V estimate, and a fully converged calibration are all present. In the
    // delay-STARVED regime the [ORION_PRESS_ANCHOR_BOOTSTRAP 2026-08-09] exception runs the
    // member unflagged — there the flag default no longer implies abstention.
    QCOMPARE(AppConfigData{}.pressAnchoredPredictorEnabled, false);
    QCOMPARE(AppConfigData{}.pressAnchoredPredictorMinSamples, 30);

    {   // delay 250 (starved): the bootstrap exception runs the member UNFLAGGED; with real
        // calibration at/above the floor it adopts exactly as if the flag were on — the
        // owner-directed alternative to "no delayed shot can ever fire".
        AutomationEngine engine;
        engine.setMeterDelayCondition(250.0, true);
        const double now = stuffDelayStarvationShot(engine);
        stuffPressAnchoredCalibration(engine, now, 400.0, 592.0, 40);
        QVERIFY2(!engine.config_.pressAnchoredEnabled,
                 "fixture applyConfig must leave the member disabled by default");
        const auto decision = engine.canonicalAutonomousTipDecision(now);
        QVERIFY2(decision.valid,
                 "starved decision must be rescued by the wall-anchored member");
        QCOMPARE(decision.source, QStringLiteral("press_anchored"));
        QVERIFY(decision.pressAnchoredPrimary);
        QVERIFY(!decision.delayStarvedVisibleSource);
    }
    {   // delay 0: registration keeps the decision, untouched.
        AutomationEngine engine;
        const double now = stuffDelayStarvationShot(engine);
        stuffPressAnchoredCalibration(engine, now, 400.0, 592.0, 40);
        const auto decision = engine.canonicalAutonomousTipDecision(now);
        QVERIFY(decision.valid);
        QCOMPARE(decision.source, QStringLiteral("registration"));
        QVERIFY(!decision.pressAnchoredPrimary);
        QCOMPARE(decision.pressAnchoredTipAbsMs, -1.0);
    }
}

void AutomationEngineTests::pressAnchoredPredictorAbstainsUntilMinSamples()
{
    // Sub-floor observation weight: OUTSIDE the delay-starved regime the member abstains
    // entirely (no telemetry fields, no adoption). INSIDE the starved regime the
    // [ORION_PRESS_ANCHOR_BOOTSTRAP 2026-08-09] exception fires the best-known value at the
    // sub-floor weight, labelled press_anchored_boot so the log carries the provenance; the
    // floor crossing then reverts the label to press_anchored.
    {   // delay 0, flag ON, sub-floor: the strict abstention is unchanged (the in-video
        // chain owns the decision and no press-anchored telemetry is published).
        AutomationEngine engine;
        const double now = stuffDelayStarvationShot(engine);
        engine.config_.pressAnchoredEnabled = true;
        stuffPressAnchoredCalibration(engine, now, 400.0, 592.0, 29);
        const auto decision = engine.canonicalAutonomousTipDecision(now);
        QVERIFY(decision.valid);
        QCOMPARE(decision.source, QStringLiteral("registration"));
        QVERIFY(!decision.pressAnchoredPrimary);
        QCOMPARE(decision.pressAnchoredTipAbsMs, -1.0);
    }

    AutomationEngine engine;
    engine.setMeterDelayCondition(250.0, true);
    const double now = stuffDelayStarvationShot(engine);
    engine.config_.pressAnchoredEnabled = true;
    stuffPressAnchoredCalibration(engine, now, 400.0, 592.0, 29);   // one short of the floor

    const auto starved = engine.canonicalAutonomousTipDecision(now);
    QVERIFY2(starved.valid,
             "in the starved regime the sub-floor bootstrap must rescue the decision");
    QCOMPARE(starved.source, QStringLiteral("press_anchored_boot"));
    QVERIFY(starved.pressAnchoredPrimary);
    QVERIFY(!starved.delayStarvedVisibleSource);

    // The 30th observation crosses the floor: same member, first-class label.
    engine.recordPressToTipObservation(QStringLiteral("Standstill"), 592.0, 1.0);
    const auto adopted = engine.canonicalAutonomousTipDecision(now);
    QVERIFY2(adopted.valid, "at the floor the wall-anchored member must adopt");
    QCOMPARE(adopted.source, QStringLiteral("press_anchored"));
    QVERIFY(adopted.pressAnchoredPrimary);
    QVERIFY(!adopted.delayStarvedVisibleSource);
}

void AutomationEngineTests::pressAnchoredPredictorConvergesToTrueMedian()
{
    // 50 observations from a known distribution (550..598 in 2ms steps, each value twice;
    // true median 574) fed through the real learner entry point: the learned constant must
    // land on the distribution's median exactly (windowed weighted median, zero prior
    // weight), the accumulated weight must count every observation, and the MAD-derived
    // sigma must be plausible for the spread and floored against false precision.
    AutomationEngine engine;
    engine.applyConfig(AppConfigData{}, LearningData{});
    const QString type = QStringLiteral("Standstill");
    for (int i = 0; i < 50; ++i) {
        const double value = 550.0 + 2.0 * (i % 25);
        engine.recordPressToTipObservation(type, value, 1.0);
    }
    const double learned = engine.pressAnchoredLearnedTipMs(type);
    QVERIFY2(std::abs(learned - 574.0) <= 2.0,
             qPrintable(QStringLiteral("learned %1 vs true median 574").arg(learned)));
    QCOMPARE(engine.pressAnchoredLearnedWeight(type), 50.0);
    const double sigma = engine.pressAnchoredLearnedSigmaMs(type);
    // MAD of the uniform-ish 550..598 grid is ~12 -> sigma ~18; anything in [8, 60) proves
    // the estimator ran (factory sigma is exactly 60, the floor exactly 8).
    QVERIFY2(sigma >= 8.0 && sigma < 60.0,
             qPrintable(QStringLiteral("sigma %1 outside plausible band").arg(sigma)));

    // M-confidence observations contribute at half weight, per the collection design.
    engine.recordPressToTipObservation(type, 574.0, 0.5);
    QCOMPARE(engine.pressAnchoredLearnedWeight(type), 50.5);
}

void AutomationEngineTests::pressAnchoredPredictorSchedulesAtHighDelay()
{
    // THE CAPABILITY THE MEMBER EXISTS FOR (task #51): applied delay 250 starves every
    // in-video source (the same fixture meterDelayLeadStarvationSuppressesVisibleExtrapolatorArm
    // pins), but the press-wall-anchored member is delay-immune and must schedule a fire —
    // not abort as unschedulable_lead, not hold in silence.
    AutomationEngine engine;
    engine.setMeterDelayCondition(250.0, true);
    const double now = stuffDelayStarvationShot(engine);
    engine.config_.pressAnchoredEnabled = true;
    // Press 400ms ago, learned press->tip 592, V 180, delay 250:
    //   tip_abs_visible = now - 400 + 592 + 180 + 250 = now + 622
    //   command_eta     = 622 - 540 (lead) = +82ms -> inside the arm horizon.
    stuffPressAnchoredCalibration(engine, now, 400.0, 592.0, 30);

    const auto decision = engine.canonicalAutonomousTipDecision(now);
    QVERIFY2(decision.valid, "the wall-anchored member must produce a valid decision");
    QCOMPARE(decision.source, QStringLiteral("press_anchored"));
    QVERIFY(decision.pressAnchoredPrimary);
    QVERIFY(!decision.delayStarvedVisibleSource);
    QVERIFY2(std::abs(decision.tipAbsMs - (now + 622.0)) <= 1.0,
             qPrintable(QStringLiteral("tip_abs %1 vs expected %2")
                            .arg(decision.tipAbsMs)
                            .arg(now + 622.0)));

    ControllerState output = engine.lastPhysical_;
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
    engine.processAutonomousLiveMeterHolding(output, now);

    QVERIFY2(engine.schedFireDeadlineMs_ >= 0.0,
             "a precise-fire token must arm from the press-anchored deadline");
    QCOMPARE(engine.context().releaseReasonCode, QStringLiteral("release_scheduled"));
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        QVERIFY2(!line.startsWith(QStringLiteral("SHOT LEAD CONFLICT: meter delay ")),
                 "no starvation diagnostic may fire for a shot that actually scheduled");
        QVERIFY2(!line.contains(QStringLiteral("unschedulable_lead")),
                 qPrintable(QStringLiteral("unschedulable_lead leaked: %1").arg(line)));
    }
}

void AutomationEngineTests::validatedAuthorityDisagreementWithUserShotLeadWarnsOnce()
{
    // [ORION_LEAD_CONFLICT] 2026-08-08 05:41:34Z: the sidecar minted validated 197.1 sd=3.2 n=6
    // while the engine kept firing with the user's 320 -- a 123 ms disagreement surfaced
    // nowhere, because the in-band Shot Lead replaces the authority unconditionally. The
    // advisory must speak once per changed pair, never adopt, and stay silent inside 3*sd.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    config.actuationLeadMs = 320.0;
    config.actuationLeadUserSet = true;
    engine.applyConfig(config, LearningData{});
    QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
    QSignalSpy badge(&engine, &AutomationEngine::leadAuthorityDisagreementDiagnosed);

    const auto disagreementLines = [&]() {
        int n = 0;
        for (const QList<QVariant>& row : diag) {
            if (row.at(0).toString().startsWith(
                    QStringLiteral("SHOT LEAD DISAGREEMENT:"))) {
                ++n;
            }
        }
        return n;
    };

    int frame = 1;
    engine.updateDetection(strictLiveMeterSample(1.0, frame++, 4'301, 197.1, 3.2, 6));
    QCOMPARE(disagreementLines(), 1);
    QCOMPARE(badge.count(), 1);
    QVERIFY(std::abs(badge.at(0).at(0).toDouble() - 320.0) < 1e-9);
    QVERIFY(std::abs(badge.at(0).at(1).toDouble() - 197.1) < 1e-6);

    // The same posterior refining by a hair must not re-warn (10 ms de-dup grid).
    engine.advanceTestClock(20.0);
    engine.updateDetection(strictLiveMeterSample(2.0, frame++, 4'301, 197.6, 3.1, 7));
    QCOMPARE(disagreementLines(), 1);

    // An authority within 3*sd of the replacing lead is not a disagreement (318 vs 320,
    // band +/- 9.6): agreement must never be badged.
    engine.advanceTestClock(20.0);
    engine.updateDetection(strictLiveMeterSample(3.0, frame++, 4'301, 318.0, 3.2, 8));
    QCOMPARE(disagreementLines(), 1);
    QCOMPARE(badge.count(), 1);
}

void AutomationEngineTests::tipTimingFreezeDivergenceWarnsAndPersistsMeasuredMedian()
{
    // [ORION_AIM_FREEZE] 2026-08-08: the manual Tip Timing (canonical 240 -- the card's floor)
    // sat 70 ms below the live median (310.2) for a whole session, and the freeze both said
    // nothing and re-persisted 240, discarding the session's own measurement at the last
    // instruction. The manual value must KEEP winning the aim and the persisted aim slot
    // (tipPhaseAimFrozenPersistsUserValue pins that contract); what changes is visibility:
    // one divergence warning per pair, and the measured median persisted SEPARATELY so the
    // next session can warn at restore before a single landing.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.autonomousVision = true;
    config.tipPhaseAimFrozen = true;
    config.tipTimingUserSet = true;
    LearningData learning;
    learning.learnedPhasePhysicalMs = 240.0;
    engine.applyConfig(config, learning);
    QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
    QSignalSpy aimPersist(&engine, &AutomationEngine::phaseConstantUpdated);
    QSignalSpy measuredPersist(&engine, &AutomationEngine::phaseMeasuredMedianUpdated);

    const double anchorLevel = engine.config_.tipPhaseAnchorPct;
    for (int i = 0; i < 30; ++i) {
        engine.meterCapPhaseAnchorMs_ = 1'000.0;
        engine.meterCapPhaseAnchorLevelPct_ = anchorLevel;
        engine.meterCapPhaseStopMs_ = 1'000.0 + 310.0;
        engine.meterCapPhaseStopConfirmed_ = true;
        engine.recordPhaseConstantSample();
    }

    const auto divergenceLines = [](QSignalSpy& spy) {
        int n = 0;
        for (const QList<QVariant>& row : spy) {
            if (row.at(0).toString().startsWith(QStringLiteral("TIP TIMING DIVERGENCE:"))) {
                ++n;
            }
        }
        return n;
    };
    QCOMPARE(divergenceLines(diag), 1);   // once per pair, not once per landing

    // The aim stays the manual value (existing contract) ...
    QVERIFY(std::abs(engine.effectiveTipPhaseConstantMsForTests() - 314.0) < 1e-9);
    QVERIFY(aimPersist.count() > 0);
    QVERIFY(std::abs(aimPersist.last().at(0).toDouble() - 240.0) < 1e-9);
    // ... while the measurement persists separately, un-swallowed.
    QVERIFY(measuredPersist.count() > 0);
    QVERIFY(std::abs(measuredPersist.last().at(0).toDouble() - 310.0) < 1e-9);

    // Restore leg: the next session carries the measured slot and confronts the manual value
    // at applyConfig, before any landing exists.
    AutomationEngine restarted;
    QSignalSpy restartDiag(&restarted, &AutomationEngine::engineDiagnostic);
    LearningData restartLearning;
    restartLearning.learnedPhasePhysicalMs = 240.0;
    restartLearning.measuredPhasePhysicalMs = measuredPersist.last().at(0).toDouble();
    restarted.applyConfig(config, restartLearning);
    QCOMPARE(divergenceLines(restartDiag), 1);
}

// ---------------------------------------------------------------------------------------------
// [ORION_BRIDGE_TOKEN] Packet-bridge bearer token selection.
//
// Regression cover for the "Network card is permanently empty" bug: an elevated run had hardened
// %PROGRAMDATA%\NexusVision\nexus_bridge.token to {SYSTEM, Administrators, INTERACTIVE:R}, so
// every later UNELEVATED debug run failed to reopen it for writing, published no token at all,
// and left the old file on disk. The client happily read that 10-hour-old file and authenticated
// with a dead session's secret, which the bridge answered with a bare "unauthorized" forever.
//
// The fix publishes the debug-mode token to the per-user-private %LOCALAPPDATA% instead (same
// security property, no elevation) and stamps every record with the publishing pid so the client
// can tell a live token from a corpse. These tests pin that decision.
// ---------------------------------------------------------------------------------------------

namespace {

orion::BridgeTokenRecord makeTokenRecord(const QString& path, const QString& token, qint64 pid,
                                         qint64 startedMs, bool ownerAlive)
{
    const QJsonObject obj{
        {QStringLiteral("v"), 1},
        {QStringLiteral("token"), token},
        {QStringLiteral("pid"), static_cast<double>(pid)},
        {QStringLiteral("started_ms"), static_cast<double>(startedMs)},
    };
    orion::BridgeTokenRecord record = orion::parseBridgeTokenRecord(
        path, QJsonDocument(obj).toJson(QJsonDocument::Compact));
    record.ownerAlive = ownerAlive;
    return record;
}

const QString kDebugTokenPath =
    QStringLiteral("C:/Users/tester/AppData/Local/NexusVision/nexus_bridge.token");
const QString kServiceTokenPath = QStringLiteral("C:/ProgramData/NexusVision/nexus_bridge.token");

}  // namespace

void AutomationEngineTests::bridgeTokenPrefersLiveDebugRecordOverStaleServiceFile()
{
    // Exactly the shipped failure: yesterday's elevated ProgramData token is still on disk while
    // today's unelevated debug bridge publishes to LOCALAPPDATA.
    QVector<orion::BridgeTokenRecord> records{
        makeTokenRecord(kDebugTokenPath, QStringLiteral("live-token"), 8128,
                        1'785'835'833'619LL, /*ownerAlive=*/true),
        makeTokenRecord(kServiceTokenPath, QStringLiteral("stale-token"), 4242,
                        1'785'800'787'000LL, /*ownerAlive=*/false),
    };

    const orion::BridgeTokenSelection selection = orion::selectBridgeToken(records);

    QCOMPARE(selection.token, QStringLiteral("live-token"));
    QCOMPARE(selection.path, kDebugTokenPath);
    QVERIFY2(selection.staleRejected, "the dead ProgramData record must be reported as rejected");
    // The diagnostic is the whole point of the fix: it must name the file it ignored, so nobody
    // has to reverse-engineer this from an mtime again.
    QVERIFY(selection.diagnostic.contains(kServiceTokenPath));
    QVERIFY(selection.diagnostic.contains(QStringLiteral("stale")));

    // Order must not matter: selection is by liveness and recency, not by candidate position.
    std::reverse(records.begin(), records.end());
    QCOMPARE(orion::selectBridgeToken(records).token, QStringLiteral("live-token"));
}

void AutomationEngineTests::bridgeTokenRefusesToAuthenticateWithOnlyStaleRecords()
{
    // If every record is a corpse, sending one guarantees a rejection whose message hides the real
    // cause. Emit no token at all and say why instead.
    const QVector<orion::BridgeTokenRecord> records{
        makeTokenRecord(kServiceTokenPath, QStringLiteral("stale-token"), 4242,
                        1'785'800'787'000LL, /*ownerAlive=*/false),
    };

    const orion::BridgeTokenSelection selection = orion::selectBridgeToken(records);

    QVERIFY2(selection.token.isEmpty(), "a stale token must never be sent to the bridge");
    QVERIFY(selection.staleRejected);
    QVERIFY(selection.diagnostic.contains(QStringLiteral("pid 4242")));
    QVERIFY(selection.diagnostic.contains(QStringLiteral("nexus_svc.log")));
}

void AutomationEngineTests::bridgeTokenKeepsUnreachableServicePublisherAlive()
{
    // The service runs as LocalSystem. If probing its pid ever fails closed, a perfectly healthy
    // service-mode token would be discarded as stale and packet capture would break for everyone
    // who DID install the service — the exact opposite of this fix's intent. `ownerAlive` is
    // therefore "not provably dead", and the default must be alive.
    orion::BridgeTokenRecord record = orion::parseBridgeTokenRecord(
        kServiceTokenPath,
        QByteArray(R"({"v":1,"token":"svc-token","pid":990,"started_ms":1785835833619})"));
    QVERIFY2(record.ownerAlive, "an unprobed record must default to alive, not stale");
    QVERIFY(record.structured);
    QCOMPARE(record.pid, 990LL);
    QCOMPARE(record.startedMs, 1'785'835'833'619LL);

    const orion::BridgeTokenSelection selection =
        orion::selectBridgeToken(QVector<orion::BridgeTokenRecord>{record});
    QCOMPARE(selection.token, QStringLiteral("svc-token"));
    QVERIFY(!selection.staleRejected);
}

void AutomationEngineTests::bridgeTokenParsesLegacyRawFileAsUnverifiableFallback()
{
    // A pre-v1 bridge wrote the bare token. Still usable, but it carries no pid, so it must be
    // marked unstructured and must lose to any live structured record.
    const orion::BridgeTokenRecord legacy =
        orion::parseBridgeTokenRecord(kServiceTokenPath, QByteArray("  4cc40ed8deadbeef\n"));
    QVERIFY(legacy.exists);
    QVERIFY2(!legacy.structured, "a raw token has no freshness metadata");
    QCOMPARE(legacy.token, QStringLiteral("4cc40ed8deadbeef"));

    const orion::BridgeTokenSelection legacyOnly =
        orion::selectBridgeToken(QVector<orion::BridgeTokenRecord>{legacy});
    QCOMPARE(legacyOnly.token, QStringLiteral("4cc40ed8deadbeef"));
    QVERIFY(legacyOnly.diagnostic.contains(QStringLiteral("legacy")));

    const QVector<orion::BridgeTokenRecord> mixed{
        legacy,
        makeTokenRecord(kDebugTokenPath, QStringLiteral("live-token"), 8128,
                        1'785'835'833'619LL, /*ownerAlive=*/true),
    };
    QCOMPARE(orion::selectBridgeToken(mixed).token, QStringLiteral("live-token"));

    // A missing or empty file is not a token and must not be selected.
    orion::BridgeTokenRecord absent;
    absent.path = kDebugTokenPath;
    const orion::BridgeTokenSelection none =
        orion::selectBridgeToken(QVector<orion::BridgeTokenRecord>{absent});
    QVERIFY(none.token.isEmpty());
    QVERIFY(none.diagnostic.contains(QStringLiteral("absent")));
}

void AutomationEngineTests::bridgeTokenCandidatePathsCoverBothPublishLocations()
{
    // The client must look wherever nexus_svc is allowed to publish, or the unelevated fix is
    // unreachable. Both directories, per-user first.
    const QStringList paths = orion::bridgeTokenCandidatePaths();
    QCOMPARE(paths.size(), 2);
    for (const QString& path : paths) {
        QVERIFY(path.endsWith(QStringLiteral("/NexusVision/nexus_bridge.token")));
    }
    const QByteArray localAppData = qgetenv("LOCALAPPDATA");
    if (!localAppData.isEmpty()) {
        QVERIFY2(paths.at(0).startsWith(QString::fromLocal8Bit(localAppData)),
                 "the per-user (unelevated debug) location must be probed first");
    }
    const QByteArray programData = qgetenv("PROGRAMDATA");
    if (!programData.isEmpty()) {
        QVERIFY(paths.at(1).startsWith(QString::fromLocal8Bit(programData)));
    }
}

// ---------------------------------------------------------------------------
// [ORION_METER_DELAY_ARM_STATE] service hello features / disarmed refusal
// ---------------------------------------------------------------------------
// nexus_svc greets with {"event":"hello","version":N,"features":[...]} and
// advertises "meter_delay" ONLY when started armed (--arm-meter-delay /
// ORION_METER_DELAY_ARMED=1 — it ships DISARMED); while disarmed it answers
// every delay verb with {"event":"error","msg":"meter_delay_disarmed",...}.
// Until 2026-08-08 the bridge read only `version` from the hello and dumped the
// refusal into the generic error path, so the app had no way to know the delay
// it displayed as "Armed" was not being applied. These tests drive the REAL
// handleLine through the test seam (the constructor starts no worker thread).

void AutomationEngineTests::meterDelayHelloWithoutFeaturesDegradesToUnknown()
{
    // Pure parse: an older (pre-v3) service greets without a features array.
    const orion::BridgeHelloInfo parsed = orion::parseBridgeHello(
        QJsonObject{{QStringLiteral("event"), QStringLiteral("hello")},
                    {QStringLiteral("version"), 2}});
    QCOMPARE(parsed.version, 2);
    QVERIFY2(!parsed.hasFeatures,
             "an absent features field must be reported as absent, not as empty-armed");
    QVERIFY(!parsed.advertisesMeterDelay());

    // Wiring: the version handshake still lands, and the arm state degrades to
    // Unknown — never Armed, never Disarmed — so the UI can say "cannot confirm".
    orion::NetworkBridge bridge;
    bridge.ingestLineForTesting(QByteArrayLiteral(R"({"event":"hello","version":2})"));
    QCOMPARE(bridge.serviceVersion(), 2);
    QCOMPARE(bridge.meterDelayServiceState(),
             orion::NetworkBridge::MeterDelayServiceState::Unknown);
}

void AutomationEngineTests::meterDelayHelloFeaturesReportArmDisarmState()
{
    orion::NetworkBridge bridge;
    QSignalSpy stateSpy(&bridge, &orion::NetworkBridge::meterDelayServiceStateChanged);
    QVERIFY(stateSpy.isValid());

    // Armed service: features advertises meter_delay (sent only when the operator
    // armed the intercept out of band).
    bridge.ingestLineForTesting(
        QByteArrayLiteral(R"({"event":"hello","version":3,"features":["meter_delay"]})"));
    QCOMPARE(bridge.serviceVersion(), 3);
    QCOMPARE(bridge.meterDelayServiceState(),
             orion::NetworkBridge::MeterDelayServiceState::Armed);
    QCOMPARE(stateSpy.count(), 1);

    // Disarmed service: the SAME v3 hello with an EMPTY features array is the
    // shipping default. Connected must not read as armed.
    bridge.ingestLineForTesting(
        QByteArrayLiteral(R"({"event":"hello","version":3,"features":[]})"));
    QCOMPARE(bridge.meterDelayServiceState(),
             orion::NetworkBridge::MeterDelayServiceState::Disarmed);
    QCOMPARE(stateSpy.count(), 2);
}

void AutomationEngineTests::meterDelayDisarmedErrorIsDistinctFromGenericBridgeError()
{
    orion::NetworkBridge bridge;
    QSignalSpy stateSpy(&bridge, &orion::NetworkBridge::meterDelayServiceStateChanged);
    QSignalSpy connSpy(&bridge, &orion::NetworkBridge::connectionChanged);
    QVERIFY(stateSpy.isValid());
    QVERIFY(connSpy.isValid());

    // The per-verb refusal (nexus_svc _armed_delay_or_error) must produce the
    // DISTINCT disarmed state...
    const QByteArray refusal = QByteArrayLiteral(
        R"({"event":"error","msg":"meter_delay_disarmed","cmd":"set_meter_delay",)"
        R"("detail":"the inbound meter delay ships DISARMED."})");
    bridge.ingestLineForTesting(refusal);
    QCOMPARE(bridge.meterDelayServiceState(),
             orion::NetworkBridge::MeterDelayServiceState::Disarmed);
    QCOMPARE(stateSpy.count(), 1);
    // ...and must NOT fall into the generic "Bridge: <msg>" connectionChanged path.
    QCOMPARE(connSpy.count(), 0);

    // Live, the refusal repeats once per ~150 ms keepalive verb; the signal is
    // transition-deduped so a log census is one line per transition, not per tick.
    bridge.ingestLineForTesting(refusal);
    QCOMPARE(stateSpy.count(), 1);

    // A generic error still takes the generic path and does not touch the arm state.
    bridge.ingestLineForTesting(
        QByteArrayLiteral(R"({"event":"error","msg":"invalid_delay_ms"})"));
    QCOMPARE(bridge.meterDelayServiceState(),
             orion::NetworkBridge::MeterDelayServiceState::Disarmed);
    QCOMPARE(stateSpy.count(), 1);
    QCOMPARE(connSpy.count(), 1);
}

// ---------------------------------------------------------------------------
// [ORION_ABORT_IDENTITY] + [ORION_COURT_POSITION] instrumentation
// ---------------------------------------------------------------------------

namespace {

// Every "Shot abort identity:" line a spy captured, in order.
QStringList abortIdentityLines(const QSignalSpy& diag)
{
    QStringList out;
    for (const auto& call : diag) {
        const QString line = call.at(0).toString();
        if (line.startsWith(QStringLiteral("Shot abort identity:"))) {
            out.append(line);
        }
    }
    return out;
}

QStringList releaseLandingLines(const QSignalSpy& diag)
{
    QStringList out;
    for (const auto& call : diag) {
        const QString line = call.at(0).toString();
        if (line.startsWith(QStringLiteral("Release landing:"))) {
            out.append(line);
        }
    }
    return out;
}

// Value of a key=value field, space-delimited. Returns a null QString when the key is absent,
// which is what makes "the field is MISSING" distinguishable from "the field is -1".
QString diagField(const QString& line, const char* key)
{
    const QString needle = QLatin1String(key) + QLatin1Char('=');
    const int at = line.indexOf(needle);
    if (at < 0) {
        return QString();
    }
    const int from = at + needle.size();
    const int end = line.indexOf(QLatin1Char(' '), from);
    return end < 0 ? line.mid(from) : line.mid(from, end - from);
}

// A detection whose bbox carries the frame size it was measured in, so the engine can
// frame-normalize it. readyMeterSample() deliberately leaves bboxFrameWidth/Height at 0
// (as a sidecar that never sent bbox_wh would), which is the -1 sentinel case.
DetectionResult withCourtPosition(DetectionResult sample, int centerX, int centerY)
{
    sample.bboxFrameWidth = 1280;
    sample.bboxFrameHeight = 720;
    sample.x = centerX - sample.width / 2;
    sample.y = centerY - sample.height / 2;
    return sample;
}

}  // namespace

void AutomationEngineTests::shotAbortIdentityCarriesTheClassifiedShotType()
{
    // WHY A BUCKET CAN VANISH WITHOUT ANYONE NOTICING. The abort identity line named the epoch,
    // the attempt, the site and the court position -- but never the SHOT TYPE. Every fire-side
    // line carries one, so a shot type that stops arming stops appearing in the log entirely,
    // and there is no way to tell "the user stopped taking that shot" from "that shot never
    // arms any more". In the 2026-08-04 batch "No Dip" appeared zero times as a fire AND zero
    // times as a classified attempt; the one real attempt (physical_epoch=30, the only L2-held
    // press in the batch) aborted as an untyped `live_tip_deadline_missed`, which is precisely
    // the shape that reads as a missing shot rather than a failing one.

    // --- A No Dip abort must SAY No Dip. L2 held with a neutral left stick is the No Dip
    // signature classifyShotType keys on, and the underscore rendering matches the existing
    // `bucket=` and OWNED-SHOT UNRESOLVED `shot_type=` fields so one parser reads all three.
    // REVERT-TRACE: drop the shotType argument at the abort() call site (or return the field to
    // being unconditional on shot_.shotType) and this QCOMPARE reports Standstill or nothing.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.minimumHoldMs = 0.0;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        int frame = 1;
        const quint64 epoch = 9'781;
        ControllerState held;
        held.buttons |= XINPUT_GAMEPAD_X;
        held.l2 = 200;                 // >= 150, and the left stick stays neutral -> No Dip
        promoteStrictAutonomousSquare(engine, held, frame, epoch);
        QCOMPARE(engine.context().shotType, QStringLiteral("No Dip"));
        engine.abort(QStringLiteral("live_tip_deadline_missed"));

        QCOMPARE(aborted.count(), 1);
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"), QStringLiteral("abort"));
        QCOMPARE(diagField(ids.at(0), "reason"),
                 QStringLiteral("live_tip_deadline_missed"));
        QCOMPARE(diagField(ids.at(0), "shot_type"), QStringLiteral("No_Dip"));
        // APPEND-ONLY: the five original fields keep their exact names and order, so every
        // existing reader of this line is unaffected by the new one.
        QVERIFY2(ids.at(0).indexOf(QStringLiteral("physical_epoch="))
                     < ids.at(0).indexOf(QStringLiteral("shot_type=")),
                 "shot_type must be APPENDED, never inserted among the original fields");
    }

    // --- A fade abort must report the fade, not the default. Two things at once: the field
    // reports the ENGINE'S classification rather than a constant, and it does so from a
    // PRE-OWNERSHIP site, which is the half that was most invisible. A pre-ownership abort has
    // no ShotContext at all, so before this field it carried no hint of which shot was being
    // attempted; pendingSquareShotType_ is the provisional classification taken at the press and
    // is the only one that exists there.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.minimumHoldMs = 0.0;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        int frame = 1;
        const quint64 epoch = 9'783;
        engine.updateDetection(strictLiveMeterSample(1.0, frame++, 0));
        ControllerState held;
        held.buttons |= XINPUT_GAMEPAD_X;
        held.leftStickX = 120;         // right of the movingSquareThreshold -> Right Fade
        engine.setPhysicalShotEpoch(epoch);
        engine.process(held);
        for (int i = 0; i < 20 && aborted.isEmpty(); ++i) {
            engine.advanceTestClock(70.0);
            engine.updateDetection(strictLiveMeterSample(67.4, frame++, epoch));
            engine.process(held);
        }

        QCOMPARE(aborted.count(), 1);
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"), QStringLiteral("square_proof_timeout"));
        QCOMPARE(diagField(ids.at(0), "shot_type"), QStringLiteral("Right_Fade"));
    }

    // --- FAIL-CLOSED HALF. ShotContext::shotType DEFAULTS to "Standstill", so an abort raised
    // against a context that was never OWNED would otherwise report the most common bucket for
    // an attempt the engine never typed at all -- inventing exactly the datum this field exists
    // to supply, and doing it in the direction that would make a No Dip that never armed look
    // like a Standstill that did. An un-owned abort must say `unclassified`, and must SAY it
    // rather than omit the field: a reader has to separate "never typed" from "old build".
    // REVERT-TRACE: pass abortedShotType unconditionally at the abort() call site and this
    // block reports Standstill; return QString() from abortShotTypeToken and the field vanishes.
    QCOMPARE(AutomationEngine::abortShotTypeToken(QString()),
             QStringLiteral("unclassified"));
    QCOMPARE(AutomationEngine::abortShotTypeToken(QStringLiteral("   ")),
             QStringLiteral("unclassified"));
    QCOMPARE(AutomationEngine::abortShotTypeToken(QStringLiteral("No Dip")),
             QStringLiteral("No_Dip"));
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.minimumHoldMs = 0.0;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        // Nothing was ever owned, so shot_.state is Idle and shot_.shotType is still the
        // struct's "Standstill" default rather than a classification of anything.
        QCOMPARE(engine.context().shotType, QStringLiteral("Standstill"));
        engine.abort(QStringLiteral("detector_authority_lost_abort"));

        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"), QStringLiteral("abort"));
        QCOMPARE(diagField(ids.at(0), "shot_type"), QStringLiteral("unclassified"));
        QVERIFY2(!diagField(ids.at(0), "shot_type").isNull(),
                 "shot_type must be emitted even when the site has no classification");
    }

    // --- A pending candidate that HAS been classified reports that classification, even though
    // it never became a ShotContext. The value here is a real answer from classifyShotType (a
    // tempo stick shot with a neutral left stick IS a Standstill), which is what separates this
    // from the un-owned case above: the sentinel is for absence of a classification, not for
    // absence of ownership.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        config.greenConfirmFastPath = true;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        engine.setAutomaticLatencyCalibrationMode(true);
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        ControllerState physical;
        physical.rightStickY = 127;          // TempoStick, never classified
        physical.buttons |= XINPUT_GAMEPAD_B;
        physical.dpad = 0x01;
        physical.l2 = 20;
        physical.r2 = 30;
        const quint64 staleEpoch = 9'785;
        engine.setPhysicalShotEpoch(staleEpoch);
        engine.process(physical);
        engine.advanceTestClock(260.0);
        engine.process(physical);
        int frame = 1;
        for (const double fill : {10.0, 14.0}) {
            engine.advanceTestClock(20.0);
            engine.updateDetection(calibrationOwnershipSample(fill, frame++, staleEpoch));
            engine.process(physical);
        }
        engine.setArmed(false);
        engine.updateDetection(calibrationOwnershipSample(18.0, frame++, staleEpoch));
        engine.setArmed(true);
        engine.updateDetection(calibrationOwnershipSample(22.0, frame++, staleEpoch));
        engine.process(physical);

        QCOMPARE(aborted.count(), 1);
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"),
                 QStringLiteral("cancel_latency_calibration"));
        QCOMPARE(diagField(ids.at(0), "shot_type"), QStringLiteral("Standstill"));
    }
}

void AutomationEngineTests::shotAbortIdentityIsEmittedFromEveryAbortSite()
{
    // WHAT THIS PINS. `emit shotAborted(...)` happens from five distinct sites, but only
    // abort() used to also emit the "Shot abort identity:" line. The other four are the
    // PRE-OWNERSHIP sites, and they are not hypothetical: in logs/orion_native.log.1, across
    // the era in which the identity line already existed, every abort()-routed reason is 1:1
    // with an identity line while all 23 `ownership_proof_incomplete` aborts have none. Those
    // aborts cannot be joined to a shot, so every arming analysis silently drops them.
    //
    // Each block below drives ONE site and asserts that site's abort is joinable. The `site=`
    // field is what makes "all five" checkable rather than inferred from reason strings, which
    // overlap across sites (ownership_proof_incomplete and ownership_proof_timeout are each
    // raised from two different sites).

    // --- SITE 1/5: cancelPendingLatencyCalibrationOwnership -> latency_calibration_cancelled.
    // This site clears both pending-epoch fields before the abort is emitted, so it is also the
    // regression guard for capturing the epoch on the way past instead of after it is gone.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        config.greenConfirmFastPath = true;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        engine.setAutomaticLatencyCalibrationMode(true);
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        ControllerState physical;
        physical.rightStickY = 127;          // TempoStick
        physical.buttons |= XINPUT_GAMEPAD_B;
        physical.dpad = 0x01;
        physical.l2 = 20;
        physical.r2 = 30;
        const quint64 staleEpoch = 9'701;
        engine.setPhysicalShotEpoch(staleEpoch);
        engine.process(physical);
        engine.advanceTestClock(260.0);
        engine.process(physical);
        int frame = 1;
        for (const double fill : {10.0, 14.0}) {
            engine.advanceTestClock(20.0);
            engine.updateDetection(calibrationOwnershipSample(fill, frame++, staleEpoch));
            engine.process(physical);
        }
        engine.setArmed(false);
        engine.updateDetection(calibrationOwnershipSample(18.0, frame++, staleEpoch));
        engine.setArmed(true);
        engine.updateDetection(calibrationOwnershipSample(22.0, frame++, staleEpoch));
        engine.process(physical);

        QCOMPARE(aborted.count(), 1);
        QCOMPARE(aborted.at(0).at(0).toString(),
                 QStringLiteral("latency_calibration_cancelled"));
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"),
                 QStringLiteral("cancel_latency_calibration"));
        QCOMPARE(diagField(ids.at(0), "reason"),
                 QStringLiteral("latency_calibration_cancelled"));
        QCOMPARE(diagField(ids.at(0), "physical_epoch"), QString::number(staleEpoch));
        // Pre-ownership: no ShotContext exists, so these are the explicit -1 "not applicable"
        // sentinel and NOT 0 -- abort() emits a genuine 0 schedule_token when no fire was
        // scheduled, so 0 has to keep meaning "none was in play".
        QCOMPARE(diagField(ids.at(0), "shot_attempt"), QStringLiteral("-1"));
        QCOMPARE(diagField(ids.at(0), "release_seq"), QStringLiteral("-1"));
        QCOMPARE(diagField(ids.at(0), "schedule_token"), QStringLiteral("-1"));
    }

    // --- SITE 2/5: reportPendingStickFault -> ownership_proof_incomplete (stick).
    // One lambda serves four call sites (epoch_superseded, proof_incomplete and both
    // proof_timeout stick paths), so patching it covers all of them.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        config.greenConfirmFastPath = true;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        ControllerState physical;
        physical.rightStickY = 127;
        physical.buttons |= XINPUT_GAMEPAD_B;
        physical.dpad = 0x04;
        physical.l2 = 20;
        physical.r2 = 30;
        ControllerState neutral = physical;
        neutral.rightStickY = 0;

        auto heartbeat = [](int frameNumber) {
            DetectionResult sample = strictLiveMeterSample(1.0, frameNumber, 1, 70.0, 2.0, 6);
            sample.detected = false;
            sample.fillPct = 0.0;
            sample.confidence = 0.0;
            sample.stage = QStringLiteral("no_meter");
            sample.gameplayStructureVerified = false;
            sample.gameplayStructureEpoch = 0;
            sample.greenStartPct = -1.0;
            sample.greenEndPct = -1.0;
            sample.greenCenterPct = -1.0;
            return sample;
        };

        int frame = 1;
        const quint64 retiredEpoch = 9'711;
        engine.updateDetection(strictLiveMeterSample(1.0, frame++, retiredEpoch, 70.0, 2.0, 6));
        engine.setPhysicalShotEpoch(retiredEpoch);
        engine.process(physical);
        for (const double deltaMs : {100.0, 100.0, 60.0}) {
            engine.advanceTestClock(deltaMs);
            engine.updateDetection(heartbeat(frame++));
            engine.process(physical);
        }
        for (const double fill : {10.0, 14.0}) {   // two proof frames only -- never three
            engine.advanceTestClock(20.0);
            engine.updateDetection(
                strictLiveMeterSample(fill, frame++, retiredEpoch, 70.0, 2.0, 6));
            engine.process(physical);
        }
        engine.process(neutral);                   // physical neutral retires the epoch

        QCOMPARE(aborted.count(), 1);
        QCOMPARE(aborted.at(0).at(0).toString(),
                 QStringLiteral("ownership_proof_incomplete"));
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"), QStringLiteral("pending_stick_fault"));
        QCOMPARE(diagField(ids.at(0), "reason"),
                 QStringLiteral("ownership_proof_incomplete"));
        // The pending epoch is still live at the emit -- clearPendingStickCandidate() runs
        // only after the fault lambda returns -- so this abort really is joinable to the
        // physical gesture that raised it.
        QCOMPARE(diagField(ids.at(0), "physical_epoch"), QString::number(retiredEpoch));
    }

    // --- SITE 3/5: Square ownership proof timeout / stale-meter block.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.minimumHoldMs = 0.0;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        int frame = 1;
        const quint64 epoch = 9'721;
        engine.updateDetection(strictLiveMeterSample(1.0, frame++, 0));
        ControllerState held;
        held.buttons |= XINPUT_GAMEPAD_X;
        engine.setPhysicalShotEpoch(epoch);
        engine.process(held);
        // A frozen carry-over meter: no ownership episode can ever open against it.
        for (int i = 0; i < 20 && aborted.isEmpty(); ++i) {
            engine.advanceTestClock(70.0);
            engine.updateDetection(strictLiveMeterSample(67.4, frame++, epoch));
            engine.process(held);
        }

        QCOMPARE(aborted.count(), 1);
        QCOMPARE(aborted.at(0).at(0).toString(),
                 QStringLiteral("ownership_blocked_stale_meter"));
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"), QStringLiteral("square_proof_timeout"));
        QCOMPARE(diagField(ids.at(0), "reason"),
                 QStringLiteral("ownership_blocked_stale_meter"));
        QCOMPARE(diagField(ids.at(0), "physical_epoch"), QString::number(epoch));
    }

    // --- SITE 4/5: Square early release with incomplete strict proof. This is the highest
    // volume unattributed abort in the live log.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        ControllerState regular;
        regular.buttons |= XINPUT_GAMEPAD_X;
        int frame = 1;
        const quint64 epoch = 9'731;
        engine.updateDetection(strictLiveMeterSample(1.0, frame++, epoch, 70.0, 2.0, 6));
        engine.setPhysicalShotEpoch(epoch);
        engine.process(regular);
        engine.advanceTestClock(20.0);
        engine.updateDetection(strictLiveMeterSample(5.0, frame++, epoch, 70.0, 2.0, 6));
        engine.process(regular);
        engine.advanceTestClock(120.0);
        DetectionResult gone = strictLiveMeterSample(0.0, frame++, epoch, 70.0, 2.0, 6);
        gone.detected = false;
        gone.confidence = 0.0;
        gone.stage = QStringLiteral("no_meter");
        gone.rejectionReason = QStringLiteral("roi_not_found");
        gone.gameplayStructureVerified = false;
        gone.gameplayStructureEpoch = 0;
        engine.updateDetection(gone);
        engine.process(regular);
        ControllerState neutral;
        engine.process(neutral);
        engine.process(neutral);
        engine.process(neutral);

        QCOMPARE(aborted.count(), 1);
        QCOMPARE(aborted.at(0).at(0).toString(),
                 QStringLiteral("ownership_proof_incomplete"));
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"), QStringLiteral("square_early_release"));
        QCOMPARE(diagField(ids.at(0), "reason"),
                 QStringLiteral("ownership_proof_incomplete"));
        QCOMPARE(diagField(ids.at(0), "physical_epoch"), QString::number(epoch));
    }

    // --- SITE 5/5: abort(). Already emitted an identity line before this change; it is here so
    // "all five sites" is a property the suite actually checks, and to pin that routing it
    // through the shared emitter left its four original fields byte-identical.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.tempoFallbackTimeoutMs = 5000.0;
        config.minimumHoldMs = 0.0;
        config.maximumHoldMs = 300.0;
        LearningData learning;
        learning.shotTypeFeedforwardMs.insert(QStringLiteral("Standstill"), 0.0);
        AutomationEngine engine;
        engine.applyConfig(config, learning);
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        auto stuckSample = []() {
            DetectionResult r = readyMeterSample(80.0);
            r.rejectionReason = QStringLiteral("stale_or_memory");
            r.greenStartPct = -1.0;
            r.greenEndPct = -1.0;
            r.greenCenterPct = -1.0;
            r.greenConfidence = 0.0;
            r.velocityPctS = 0.0;
            r.etaToGreenMs = -1.0;
            return r;
        };

        ControllerState physical;
        physical.buttons |= XINPUT_GAMEPAD_X;
        engine.process(physical);
        engine.advanceTestClock(220);
        engine.process(physical);
        engine.advanceTestClock(160);
        DetectionResult genuineAppear = stuckSample();
        genuineAppear.rejectionReason.clear();
        engine.updateDetection(genuineAppear);
        engine.process(physical);
        engine.updateDetection(stuckSample());
        engine.process(physical);
        engine.advanceTestClock(960);
        engine.updateDetection(stuckSample());
        engine.process(physical);

        QCOMPARE(engine.context().releaseReasonCode,
                 QStringLiteral("detector_authority_lost_abort"));
        QCOMPARE(aborted.count(), 1);
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "site"), QStringLiteral("abort"));
        QCOMPARE(diagField(ids.at(0), "reason"),
                 QStringLiteral("detector_authority_lost_abort"));
        // An OWNED shot: the identity fields are real values, not sentinels. This is the
        // contrast that makes -1 readable as "no shot existed" at the other four sites.
        QVERIFY2(diagField(ids.at(0), "shot_attempt") != QStringLiteral("-1"),
                 "an owned shot must report its real arm token, never the absent-sentinel");
        QCOMPARE(diagField(ids.at(0), "release_seq"), QStringLiteral("0"));
        // 0, not -1: no fire was scheduled, but a schedule token field was applicable.
        QCOMPARE(diagField(ids.at(0), "schedule_token"), QStringLiteral("0"));
    }
}

void AutomationEngineTests::courtPositionIsStampedOnAbortAndLandingLines()
{
    // WHAT THIS PINS. The bot has no court-position signal anywhere: classifyShotType() reads
    // only the sticks and L2, detframes `zone` is unpopulated on every row, and pose is off in
    // production. But the shot meter is PLAYER-anchored -- over the 4,560 green-confirmed rows
    // of logs/batch_20260803/detframes_batch.csv the frame-normalized bbox centre spans
    // x/W 0.054-0.989 -- so the meter's own normalized position IS a court-position proxy, and
    // it already arrives on every detection. These fields make it a permanent per-shot column
    // so the half-court question is answerable from any future batch.

    // --- A detection that carries bbox_wh yields a real normalized position on the abort line.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.minimumHoldMs = 0.0;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        int frame = 1;
        const quint64 epoch = 9'741;
        engine.updateDetection(strictLiveMeterSample(1.0, frame++, 0));
        ControllerState held;
        held.buttons |= XINPUT_GAMEPAD_X;
        engine.setPhysicalShotEpoch(epoch);
        engine.process(held);
        // Meter parked far LEFT (x/W = 320/1280 = 0.25, y/H = 360/720 = 0.50) and static, so
        // the position is unambiguous and the in-lock jump is exactly 0.
        for (int i = 0; i < 20 && aborted.isEmpty(); ++i) {
            engine.advanceTestClock(70.0);
            engine.updateDetection(withCourtPosition(
                strictLiveMeterSample(67.4, frame++, epoch), 320, 360));
            engine.process(held);
        }

        QCOMPARE(aborted.count(), 1);
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "meter_x"), QStringLiteral("0.2500"));
        QCOMPARE(diagField(ids.at(0), "meter_y"), QStringLiteral("0.5000"));
        // A static meter: consecutive normalized centres are identical, so the max in-lock
        // single-frame jump is 0 -- and 0 is emitted, not the -1 "no run" sentinel.
        QCOMPARE(diagField(ids.at(0), "meter_jump"), QStringLiteral("0.0000"));
    }

    // --- The same drive with a MOVING meter must report the jump it actually made, which is
    // what separates a genuine court-position effect from a meter still sliding with the
    // player. Half a frame width of travel per frame in x.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.minimumHoldMs = 0.0;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        int frame = 1;
        const quint64 epoch = 9'751;
        engine.updateDetection(strictLiveMeterSample(1.0, frame++, 0));
        ControllerState held;
        held.buttons |= XINPUT_GAMEPAD_X;
        engine.setPhysicalShotEpoch(epoch);
        engine.process(held);
        int centerX = 128;                        // 0.1 of frame width, +0.1 each frame
        for (int i = 0; i < 20 && aborted.isEmpty(); ++i) {
            engine.advanceTestClock(70.0);
            engine.updateDetection(withCourtPosition(
                strictLiveMeterSample(67.4, frame++, epoch), centerX, 360));
            engine.process(held);
            centerX += 128;
        }

        QCOMPARE(aborted.count(), 1);
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        const double jump = diagField(ids.at(0), "meter_jump").toDouble();
        QVERIFY2(std::abs(jump - 0.1) < 1e-3,
                 qPrintable(QStringLiteral("a meter travelling 0.1 of frame width per frame "
                                           "must report meter_jump~0.1, got %1")
                                .arg(jump)));
    }

    // --- A sidecar that never sent bbox_wh must yield the -1 sentinel, never a fabricated
    // position computed against a wrong or zero frame size. readyMeterSample() leaves
    // bboxFrameWidth/Height at 0, so this is also what every pre-existing test sees, which is
    // why none of them changed behaviour.
    {
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        config.minimumHoldMs = 0.0;
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QSignalSpy aborted(&engine, &AutomationEngine::shotAborted);
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        int frame = 1;
        const quint64 epoch = 9'761;
        engine.updateDetection(strictLiveMeterSample(1.0, frame++, 0));
        ControllerState held;
        held.buttons |= XINPUT_GAMEPAD_X;
        engine.setPhysicalShotEpoch(epoch);
        engine.process(held);
        for (int i = 0; i < 20 && aborted.isEmpty(); ++i) {
            engine.advanceTestClock(70.0);
            engine.updateDetection(strictLiveMeterSample(67.4, frame++, epoch));
            engine.process(held);
        }

        QCOMPARE(aborted.count(), 1);
        const QStringList ids = abortIdentityLines(diag);
        QCOMPARE(ids.size(), 1);
        QCOMPARE(diagField(ids.at(0), "meter_x"), QStringLiteral("-1.0000"));
        QCOMPARE(diagField(ids.at(0), "meter_y"), QStringLiteral("-1.0000"));
        // The field must still be PRESENT. A missing field and a null position are different
        // facts and a reader has to be able to tell them apart.
        QVERIFY2(!diagField(ids.at(0), "meter_x").isNull(),
                 "meter_x must be emitted even when it has no value to report");
    }

    // --- The release-time court position reaches the "Release landing:" line. Driven through
    // the meter-capture state directly (as releaseLandingReportsPeakDistinctFromSubmitFill
    // does) so the assertion is about the instrumentation rather than about whether a
    // synthetic trajectory happens to settle.
    //
    // A settled frozen-marker run, whose bbox does not move -> graded=1.
    {
        AutomationEngine engine;
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        engine.meterCapActive_ = true;
        engine.meterCapSeq_ = 5'150;
        engine.meterCapShotType_ = QStringLiteral("Left Fade");   // NOTE: contains a space
        engine.meterCapFillAtReleasePct_ = 47.2;
        engine.meterCapPeakFillPct_ = 97.4;
        // 960/1280 = 0.75 -- a shot taken from the RIGHT side of the frame. Snapshotted at
        // release-command submit, which is the instant whose court position the shot belongs to.
        engine.meterCapNormXAtRel_ = 0.75;
        engine.meterCapNormYAtRel_ = 0.50;
        // [ORION_LANDING_FEATURES 2026-08-12] The pipeline state at the fire instant. These were
        // computed on every shot and written on none, so a graded landing could not be regressed
        // against the conditions that produced it.
        engine.meterCapRiseVelocityPctPerMs_ = 0.16840;
        engine.meterCapFrameAgeAtRelMs_ = 9.40;
        engine.meterCapNetworkOffsetAtRelMs_ = 23.50;
        engine.meterCapSamples_.clear();
        for (int i = 0; i < 4; ++i) {
            AutomationEngine::MeterCalSample s;
            s.accepted = true;
            s.confidence = 0.9;
            s.fillPct = 92.0;
            s.greenStartPct = 90.0;
            s.greenEndPct = 98.0;
            s.greenCenterPct = 94.0;
            s.tMs = 1'000.0 + 20.0 * i;
            s.bx = 960.0;                 // static bbox -> a settled run
            s.by = 360.0;
            s.nx = 0.75;                  // and therefore a zero normalized jump
            s.ny = 0.50;
            engine.meterCapSamples_.append(s);
        }

        engine.evaluatePostReleaseMeter();

        const QStringList landings = releaseLandingLines(diag);
        QVERIFY2(!landings.isEmpty(), "the shot must produce a Release landing: line");
        const QString landing = landings.last();
        QVERIFY2(landing.contains(QStringLiteral("graded=1")),
                 qPrintable(QStringLiteral("expected the graded path, got: %1").arg(landing)));
        QCOMPARE(diagField(landing, "meter_x"), QStringLiteral("0.7500"));
        QCOMPARE(diagField(landing, "meter_y"), QStringLiteral("0.5000"));
        QCOMPARE(diagField(landing, "meter_jump"), QStringLiteral("0.0000"));
        // Append-only contract: every pre-existing key survives with its own value.
        QCOMPARE(diagField(landing, "seq"), QStringLiteral("5150"));
        QCOMPARE(diagField(landing, "peak_fill"), QStringLiteral("97.40"));
        QCOMPARE(diagField(landing, "fill_at_rel"), QStringLiteral("47.20"));
        QCOMPARE(diagField(landing, "travel_pp"), QStringLiteral("50.20"));
        QVERIFY(!diagField(landing, "settled_fill").isNull());
        QVERIFY(!diagField(landing, "green_start").isNull());
        QVERIFY(!diagField(landing, "settled_n").isNull());
        // [ORION_LANDING_FEATURES 2026-08-12] The three at-fire features must reach the line with
        // the values latched at submit. Pinned because this exact class of diagnostic has been
        // lost twice: the capture-health tail was truncated for its entire life, and the courtwide
        // steal's veto reason is nulled before its own log statement reads it.
        QCOMPARE(diagField(landing, "vel_at_rel"), QStringLiteral("0.16840"));
        QCOMPARE(diagField(landing, "frame_age_ms"), QStringLiteral("9.40"));
        QCOMPARE(diagField(landing, "rtt_ms"), QStringLiteral("23.50"));
        // shot= must remain the LAST field. Its value legitimately contains a space, so it can
        // only be parsed as the rest of the line; appending after it would silently corrupt
        // every reader of the shot type.
        const int shotAt = landing.indexOf(QStringLiteral("shot="));
        QVERIFY(shotAt > landing.indexOf(QStringLiteral("meter_jump=")));
        QCOMPARE(landing.mid(shotAt), QStringLiteral("shot=Left Fade"));
    }

    // --- A meter that never settles takes the graded=0 evidence path, and must still carry the
    // court position plus the jump that PROVES it never settled.
    {
        AutomationEngine engine;
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

        engine.meterCapActive_ = true;
        engine.meterCapSeq_ = 5'151;
        engine.meterCapShotType_ = QStringLiteral("No Dip");
        engine.meterCapFillAtReleasePct_ = 40.0;
        engine.meterCapPeakFillPct_ = 90.0;
        engine.meterCapNormXAtRel_ = 0.25;
        engine.meterCapNormYAtRel_ = 0.60;
        engine.meterCapSamples_.clear();
        for (int i = 0; i < 4; ++i) {
            AutomationEngine::MeterCalSample s;
            s.accepted = true;
            s.confidence = 0.9;
            s.fillPct = 92.0;
            s.greenStartPct = 90.0;
            s.greenEndPct = 98.0;
            s.greenCenterPct = 94.0;
            s.tMs = 1'000.0 + 20.0 * i;
            s.bx = 300.0 + 200.0 * i;     // sliding bbox -> only length-1 runs -> not graded
            s.by = 430.0;
            s.nx = 0.25 + 0.1 * i;        // 0.1 of frame width per frame
            s.ny = 0.60;
            engine.meterCapSamples_.append(s);
        }

        engine.evaluatePostReleaseMeter();

        const QStringList landings = releaseLandingLines(diag);
        QVERIFY2(!landings.isEmpty(), "an ungraded shot must still emit landing evidence");
        const QString landing = landings.last();
        QVERIFY(landing.contains(QStringLiteral("graded=0")));
        QCOMPARE(diagField(landing, "meter_x"), QStringLiteral("0.2500"));
        QCOMPARE(diagField(landing, "meter_y"), QStringLiteral("0.6000"));
        const double jump = diagField(landing, "meter_jump").toDouble();
        QVERIFY2(std::abs(jump - 0.1) < 1e-3,
                 qPrintable(QStringLiteral("a meter sliding 0.1 of frame width per frame must "
                                           "report meter_jump~0.1, got %1").arg(jump)));
        QCOMPARE(diagField(landing, "seq"), QStringLiteral("5151"));
        QCOMPARE(diagField(landing, "peak_fill"), QStringLiteral("90.00"));
        QVERIFY(!diagField(landing, "samples_n").isNull());
        const int shotAt = landing.indexOf(QStringLiteral("shot="));
        QVERIFY(shotAt > landing.indexOf(QStringLiteral("meter_jump=")));
        QCOMPARE(landing.mid(shotAt), QStringLiteral("shot=No Dip"));
    }

    // --- The per-sample nx/ny must actually be FED from the detector, not merely exist on the
    // struct. This is the same wiring class as the KEYSTONE bx/by bug (a DetectionResult built
    // without x/y/width/height made every bbox centre 0, so a sliding meter looked settled).
    // Asserting on hand-built MeterCalSamples cannot catch that, so drive updateDetection().
    {
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("both");
        config.autonomousVision = true;
        engine.applyConfig(config, LearningData{});

        engine.meterCapActive_ = true;
        engine.meterCapSamples_.clear();
        engine.updateDetection(withCourtPosition(
            strictLiveMeterSample(60.0, 1, 5'900), 320, 360));   // x/W = 0.25
        engine.advanceTestClock(20.0);
        engine.updateDetection(withCourtPosition(
            strictLiveMeterSample(70.0, 2, 5'900), 960, 216));   // x/W = 0.75, y/H = 0.30

        QCOMPARE(engine.meterCapSamples_.size(), 2);
        QVERIFY2(std::abs(engine.meterCapSamples_.at(0).nx - 0.25) < 1e-9,
                 "the detector's bbox must reach MeterCalSample.nx frame-normalized");
        QVERIFY2(std::abs(engine.meterCapSamples_.at(0).ny - 0.50) < 1e-9,
                 "the detector's bbox must reach MeterCalSample.ny frame-normalized");
        QVERIFY(std::abs(engine.meterCapSamples_.at(1).nx - 0.75) < 1e-9);
        QVERIFY(std::abs(engine.meterCapSamples_.at(1).ny - 0.30) < 1e-9);
        // Pixel bx/by keep their existing meaning alongside the normalized pair.
        QCOMPARE(engine.meterCapSamples_.at(0).bx, 320.0);
        QCOMPARE(engine.meterCapSamples_.at(0).by, 360.0);

        // A detection WITHOUT bbox_wh must leave the sentinel rather than divide by zero.
        engine.advanceTestClock(20.0);
        engine.updateDetection(strictLiveMeterSample(80.0, 3, 5'900));
        QCOMPARE(engine.meterCapSamples_.size(), 3);
        QCOMPARE(engine.meterCapSamples_.at(2).nx, -1.0);
        QCOMPARE(engine.meterCapSamples_.at(2).ny, -1.0);
    }

    // --- The release-time snapshot must come from the SUBMIT instant, not from wherever the
    // player drifted to during the capture window. startPostReleaseMeterCapture() is the only
    // writer, and it copies the live position at that instant.
    {
        AutomationEngine engine;
        engine.lastMeterNormX_ = 0.31;
        engine.lastMeterNormY_ = 0.44;
        engine.shot_.releaseSeq = 77;
        engine.shot_.shotType = QStringLiteral("Standstill");
        engine.startPostReleaseMeterCapture(engine.engineNowMs());
        QCOMPARE(engine.meterCapNormXAtRel_, 0.31);
        QCOMPARE(engine.meterCapNormYAtRel_, 0.44);
        // The player keeps moving through the capture window; the snapshot must not follow.
        engine.lastMeterNormX_ = 0.90;
        engine.lastMeterNormY_ = 0.10;
        QCOMPARE(engine.meterCapNormXAtRel_, 0.31);
        QCOMPARE(engine.meterCapNormYAtRel_, 0.44);
    }
}

// ===========================================================================================
// [ORION_TIP_PHASE] tests
//
// The claim under test, measured on logs/diagnostics/detframes_20260804_074153.csv +
// _091503.csv (89 meter rises; 61 carrying a release with fill_at_release >= 40): the time from
// the fill's first upward crossing of 30% to the end of the meter's rise is 319.8 ms with rMAD
// 9.6, against the shipped sampler's +92.6 ms / rMAD 18.4 error over the same landings. These
// tests pin the mechanism, the fail-closed gates, and -- most importantly -- that the swap does
// not silently re-aim the bot.
// ===========================================================================================

double AutomationEngineTests::stagePhaseDecision(orion::AutomationEngine& engine, double baseMs,
                                                 double startFillPct, double slopePctPerMs,
                                                 double leadMs)
{
    const double lastMs = feedLinearRise(engine, baseMs, startFillPct, slopePctPerMs,
                                         /*samples=*/8, /*dtMs=*/16.0);
    // A shot-local green band, matching readyMeterSample's. feedLinearRise leaves it unset, which
    // is fine for a purely linear fit but makes liveMeterCrossingAuthoritative fail closed the
    // moment a decelerating sample turns the quadratic concave-down and trips usedPeakFallback.
    // These tests need the sampler to stay authoritative THROUGH a deceleration so the phase
    // member is being compared against a live rival rather than an absent one.
    engine.shot_.greenStartPct = 94.0;
    engine.shot_.greenEndPct = 98.0;
    primeLeadPivot(engine, lastMs, leadMs);
    return lastMs;
}

void AutomationEngineTests::tipPhaseAnchorDatesTheFirstUpwardCrossing()
{
    // The anchor is the ONE input this predictor has, so its accuracy is the whole ballgame:
    // every ms of anchor error is a ms of aim error. At 60 fps and ~0.18 %/ms the straddling
    // pair is ~16 ms apart, so snapping to the later frame would inject a uniform 0-16 ms error
    // into a constant whose entire claim is a 9.6 ms rMAD. It must interpolate.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    constexpr quint64 kEpoch = 9'101;
    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;
    int frame = 1;
    promoteStrictAutonomousSquare(engine, square, frame, kEpoch, 220.0, 2.0, 6, 0.0);

    // Straddle the 30% anchor with an exact pair: 26.0 then 34.0, 20 ms apart. The crossing is
    // therefore exactly half way -- 10 ms after the 26.0 sample.
    engine.advanceTestClock(20.0);
    DetectionResult below = strictLiveMeterSample(26.0, frame++, kEpoch, 220.0, 2.0, 6);
    below.frameAgeMs = 0.0;
    engine.updateDetection(below);
    engine.process(square);
    const double belowMs = engine.engineNowMs();
    QCOMPARE(engine.context().fillPhaseAnchorMs, -1.0);   // not yet crossed

    engine.advanceTestClock(20.0);
    DetectionResult above = strictLiveMeterSample(34.0, frame++, kEpoch, 220.0, 2.0, 6);
    above.frameAgeMs = 0.0;
    engine.updateDetection(above);
    engine.process(square);

    const double anchorMs = engine.context().fillPhaseAnchorMs;
    QVERIFY2(anchorMs >= 0.0, "the observed upward crossing of the anchor was never dated");
    // (30 - 26) / (34 - 26) = 0.5 of a 20 ms step.
    QVERIFY2(std::abs(anchorMs - (belowMs + 10.0)) < 0.001,
             qPrintable(QStringLiteral("anchor must be INTERPOLATED, not snapped: got %1, "
                                       "expected %2 (straddling samples at %3 and %4)")
                            .arg(anchorMs).arg(belowMs + 10.0).arg(belowMs)
                            .arg(belowMs + 20.0)));

    // FAIL-CLOSED HALF. A meter first seen ALREADY above the anchor cannot be dated, and must
    // not be guessed at. This is not a corner case: a lingering previous-shot meter is a genuine
    // raw detection that appears high, and "the fill is above 30 so the crossing was about here"
    // is exactly the inference that would hand a carryover's phase to a live shot. Exercised at
    // the unit rather than through a drive, because the ownership seed necessarily feeds low
    // fills first -- the case being pinned is a stream that never was below the anchor.
    // REVERT-TRACE: delete the `shot_.phasePrevFillPct < anchorPct` straddle requirement from
    // notePhaseAnchorSample and the second QCOMPARE fails -- 71.0 pairs with 62.0 and records a
    // fabricated crossing.
    AutomationEngine highFirst;
    highFirst.applyConfig(config, LearningData{});
    highFirst.notePhaseAnchorSample(62.0, 1'000.0);
    QCOMPARE(highFirst.context().fillPhaseAnchorMs, -1.0);   // no pair yet
    highFirst.notePhaseAnchorSample(71.0, 1'016.0);
    QCOMPARE(highFirst.context().fillPhaseAnchorMs, -1.0);   // a pair, but no CROSSING
    highFirst.notePhaseAnchorSample(80.0, 1'032.0);
    QCOMPARE(highFirst.context().fillPhaseAnchorMs, -1.0);

    // A DESCENDING pair through the anchor is not an upward crossing either -- that is a meter
    // deflating, and dating a shot from it would be nonsense.
    AutomationEngine descending;
    descending.applyConfig(config, LearningData{});
    descending.notePhaseAnchorSample(44.0, 1'000.0);
    descending.notePhaseAnchorSample(21.0, 1'016.0);
    QCOMPARE(descending.context().fillPhaseAnchorMs, -1.0);
}

void AutomationEngineTests::leadCalibrationConvergesAndNeverInvertsTheSign()
{
    // [ORION_LEAD_CALIBRATION] THE SIGN IS THE WHOLE TEST.
    //
    // The command is submitted at (predicted tip - lead) and becomes visible `lead` ms later, so a
    // LARGER lead submits EARLIER. A banner reading EARLY therefore means the lead is too BIG and
    // must come DOWN. The spec flags this as having been inverted in UI copy before, and getting
    // it backwards does not merely fail to converge -- it DIVERGES, walking the user away from
    // their correct lead while asking them to keep shooting.
    using P = LeadCalibrationPolicy;

    // EARLY must DECREASE the lead. LATE must INCREASE it.
    // REVERT-TRACE: flip the direction assignment in apply() and both of these fail.
    const LeadCalibrationState start = P::begin(300.0);
    QCOMPARE(start.leadMs, 300.0);
    QVERIFY2(P::apply(start, LeadVerdict::Early).leadMs < 300.0,
             "EARLY must DECREASE the lead -- a larger lead fires EARLIER");
    QVERIFY2(P::apply(start, LeadVerdict::Late).leadMs > 300.0,
             "LATE must INCREASE the lead");

    // A missed banner is not evidence: it must move nothing at all.
    const LeadCalibrationState skipped = P::apply(start, LeadVerdict::Skip);
    QCOMPARE(skipped.leadMs, start.leadMs);
    QCOMPARE(skipped.shots, start.shots);
    QCOMPARE(skipped.goodRun, start.goodRun);

    // Same-direction verdicts keep the step; a REVERSAL halves it. That is what converges this
    // in 10-15 shots instead of oscillating at fixed amplitude forever.
    LeadCalibrationState s = P::apply(start, LeadVerdict::Late);
    const double stepAfterFirst = s.stepMs;
    s = P::apply(s, LeadVerdict::Late);
    QCOMPARE(s.stepMs, stepAfterFirst);              // no reversal yet
    s = P::apply(s, LeadVerdict::Early);             // reversal
    QVERIFY2(s.stepMs < stepAfterFirst, "a reversal must halve the step");

    // Three CONSECUTIVE goods lock. A miss in between must break the run, or an
    // early-good-good-late sequence would sit one step from locking on a wrong value.
    LeadCalibrationState g = P::begin(300.0);
    g = P::apply(g, LeadVerdict::Good);
    g = P::apply(g, LeadVerdict::Good);
    QVERIFY(!g.locked);
    g = P::apply(g, LeadVerdict::Early);
    QCOMPARE(g.goodRun, 0);
    g = P::apply(g, LeadVerdict::Good);
    g = P::apply(g, LeadVerdict::Good);
    QVERIFY2(!g.locked, "a miss must genuinely reset the run, not merely pause it");
    g = P::apply(g, LeadVerdict::Good);
    QVERIFY2(g.locked, "three consecutive goods must lock");

    // Once locked nothing moves, so a user who keeps shooting cannot walk a converged value off.
    const LeadCalibrationState afterLock = P::apply(g, LeadVerdict::Early);
    QCOMPARE(afterLock.leadMs, g.leadMs);

    // IT MUST ACTUALLY CONVERGE. Simulate an oracle whose true lead is 268: every shot reads
    // EARLY while the lead is above it and LATE while below. Bisection must find it and lock.
    constexpr double kTrue = 268.0;
    LeadCalibrationState c = P::begin(300.0);
    int iterations = 0;
    while (!c.locked && iterations < 40) {
        c = P::apply(c, c.leadMs > kTrue ? LeadVerdict::Early : LeadVerdict::Late);
        ++iterations;
    }
    QVERIFY2(c.locked, "the bisection must terminate");
    QVERIFY2(iterations <= 15,
             qPrintable(QStringLiteral("must converge inside a usable session, took %1")
                            .arg(iterations)));
    QVERIFY2(std::abs(c.leadMs - kTrue) <= 4.0,
             qPrintable(QStringLiteral("must land near the true lead, got %1").arg(c.leadMs)));

    // Never outside the bounds the rest of the engine validates -- a lead it would then refuse
    // is worse than no calibration at all.
    LeadCalibrationState lo = P::begin(160.0);
    for (int i = 0; i < 30 && !lo.locked; ++i) {
        lo = P::apply(lo, LeadVerdict::Early);
    }
    QVERIFY(lo.leadMs >= P::kMinLeadMs);
    LeadCalibrationState hi = P::begin(440.0);
    for (int i = 0; i < 30 && !hi.locked; ++i) {
        hi = P::apply(hi, LeadVerdict::Late);
    }
    QVERIFY(hi.leadMs <= P::kMaxLeadMs);
}

void AutomationEngineTests::phaseLearnerShrinksTowardTheObservationBeforeTheWindowFills()
{
    // [ORION_PHASE_COLD_START] THE COLD START THIS FIXES. The owner tested on another build with
    // different jumpshots: "a rough cold start but tip timing started to work". Different
    // jumpshot ANIMATIONS have different lengths, so the constant is per-animation -- and the
    // learner used to publish nothing until 10 landings, then switch to the median in one step.
    // Its stated justification was that the seed is mean-neutral so waiting costs nothing, which
    // holds only while the seed matches the animation being played. On one it does not fit, the
    // old gate spent TEN mistimed shots before using anything it had already measured. Every new
    // install and every jumpshot change pays that.
    //
    // REVERT-TRACE: set tipPhaseLearnMinSamples to 0/1 (or restore the wait-for-window return)
    // and the partial-window assertions below fail.
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.autonomousVision = true;

    AutomationEngine engine;
    engine.applyConfig(config, LearningData{});
    const double seed = engine.config().tipPhaseSeedPhysicalMs;
    const int window = engine.config().tipPhaseLearnWindow;
    QCOMPARE(engine.config().tipPhaseLearnMinSamples, 3);

    // An animation ~40 ms LONGER than the seed -- the "different jumpshot" case.
    const double animationMs = seed + 40.0;
    auto land = [&](AutomationEngine& e) {
        e.meterCapPhaseAnchorMs_ = 1'000.0;
        e.meterCapPhaseAnchorLevelPct_ = 30.0;
        e.meterCapPhaseStopMs_ = 1'000.0 + animationMs;
        e.meterCapPhaseStopConfirmed_ = true;
        e.recordPhaseConstantSample();
    };

    // Below the floor the seed must stand: two landings cannot tell a new animation from spread.
    land(engine);
    QCOMPARE(engine.learnedPhasePhysicalMsForTests(), -1.0);
    land(engine);
    QCOMPARE(engine.learnedPhasePhysicalMsForTests(), -1.0);

    // At the floor it must ALREADY be moving -- that is the entire point.
    land(engine);
    const double atThree = engine.learnedPhasePhysicalMsForTests();
    QVERIFY2(atThree > seed,
             "the learner must move toward a clearly-different animation before the window fills");
    QVERIFY2(atThree < animationMs,
             "...but must not jump the whole way on three samples");
    // 3/10 of the way: 318 + 40*0.3 = 330.
    QVERIFY2(std::abs(atThree - (seed + 40.0 * 3.0 / window)) < 0.001,
             qPrintable(QStringLiteral("expected n/window shrinkage, got %1").arg(atThree)));

    // It must approach monotonically, not oscillate.
    double prev = atThree;
    for (int i = 4; i <= window; ++i) {
        land(engine);
        const double now = engine.learnedPhasePhysicalMsForTests();
        QVERIFY2(now >= prev - 0.001, "the estimate must not walk backwards while evidence grows");
        prev = now;
    }

    // At a full window it equals the median EXACTLY -- identical to the pre-change behaviour from
    // here on, so this only ever changed what happens before the window filled.
    QVERIFY2(std::abs(prev - animationMs) < 0.001,
             qPrintable(QStringLiteral("a full window must equal the median, got %1").arg(prev)));
}

void AutomationEngineTests::phaseSampleIsRecordedOnEveryLandingIncludingRejects()
{
    // [ORION_PHASE_PORTABILITY] The shipped animation constant is a property of the GAME, not the
    // machine, so it ships globally while the lead stays a per-machine slider. But the 2026-08-05
    // re-aim to 399 was derived on ONE rig with no second rig to check it against, and if any of
    // that +12 was absorbing this machine's lead being short, a correctly-tuned customer would
    // land LATE. The demo is meant to answer that -- many machines instead of one -- which only
    // works if a returned log CONTAINS the measurement.
    //
    // It did not. "Tip phase measurement:" publishes only once the learner's 10-sample window is
    // full, and a sample outside the plausibility band returns with no line at all -- so a demo
    // user's first nine shots and every mis-read stop were invisible. The per-frame CSV that
    // carries this offline is behind ORION_DETCSV, which no customer sets.
    //
    // REVERT-TRACE: move the PHASE SAMPLE emit back below the band check and the rejected case
    // below emits nothing.
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.autonomousVision = true;

    // A sample far outside the learn band: the learner must REFUSE it, and still record it.
    AutomationEngine rejected;
    rejected.applyConfig(config, LearningData{});
    QSignalSpy rejectedSpy(&rejected, &AutomationEngine::engineDiagnostic);
    rejected.meterCapPhaseAnchorMs_ = 1'000.0;
    rejected.meterCapPhaseAnchorLevelPct_ = 30.0;
    rejected.meterCapPhaseStopMs_ = 1'000.0 + 5'000.0;   // absurd; well past tipPhaseLearnMaxMs
    rejected.meterCapPhaseStopConfirmed_ = true;
    rejected.recordPhaseConstantSample();

    bool sawRejectedLine = false;
    for (int i = 0; i < rejectedSpy.count(); ++i) {
        const QString line = rejectedSpy.at(i).at(0).toString();
        if (line.startsWith(QStringLiteral("PHASE SAMPLE:"))) {
            sawRejectedLine = true;
            QVERIFY2(line.contains(QStringLiteral("accepted=0")),
                     "an out-of-band sample must be recorded as REJECTED, not silently dropped");
        }
    }
    QVERIFY2(sawRejectedLine,
             "every landing must emit PHASE SAMPLE, including ones the learner refuses -- "
             "a silent reject is exactly what made the demo useless as a portability probe");
    QCOMPARE(rejected.phaseConstantSampleCountForTests(), 0);   // and it must not be learned from

    // A plausible sample: recorded AND learned from, on the very first landing (long before the
    // 10-sample window that the older publish line waits for).
    AutomationEngine ok;
    ok.applyConfig(config, LearningData{});
    QSignalSpy okSpy(&ok, &AutomationEngine::engineDiagnostic);
    ok.meterCapPhaseAnchorMs_ = 1'000.0;
    ok.meterCapPhaseAnchorLevelPct_ = 30.0;
    ok.meterCapPhaseStopMs_ = 1'000.0 + 320.0;
    ok.meterCapPhaseStopConfirmed_ = true;
    ok.recordPhaseConstantSample();

    bool sawOkLine = false;
    for (int i = 0; i < okSpy.count(); ++i) {
        const QString line = okSpy.at(i).at(0).toString();
        if (line.startsWith(QStringLiteral("PHASE SAMPLE:"))) {
            sawOkLine = true;
            QVERIFY(line.contains(QStringLiteral("accepted=1")));
            QVERIFY2(line.contains(QStringLiteral("raw_ms=320.0")),
                     "the RAW animation measurement is the portability datum and must be logged");
            QVERIFY2(line.contains(QStringLiteral("anchor_pct=30.0")),
                     "the level is needed to interpret raw vs normalized");
        }
    }
    QVERIFY2(sawOkLine, "the FIRST landing must already emit a sample");
    QCOMPARE(ok.phaseConstantSampleCountForTests(), 1);
}

void AutomationEngineTests::tipPhaseTypeTrimIsSymmetricAndDefaultOff()
{
    // [ORION_TYPE_TRIM] One pooled animation constant is applied to every shot type, but the
    // measured anchor->stop animation is type-dependent (fade-labelled presses date ~4-6.5 ms
    // SHORTER than Standstill across base30+snap / base20+snap / base20+subframe; 500 PHASE
    // SAMPLE observations). The trim expresses that difference SYMMETRICALLY: added to the tip
    // decision, subtracted from the learner observation, so the pooled learner keeps estimating
    // the base animation and cannot fight the trim.
    //
    // DEFAULT-OFF LEG / REVERT-TRACE: flip the AppConfigData default to true and the inertness
    // assertions below fail — the flag ships OFF because every historical fade-labelled sample
    // is a stick-deflected press, not a confirmed deliberate fadeaway.
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.autonomousVision = true;

    // 1) Fresh install: flag OFF, measured map present but INERT — accessor returns exactly 0.
    {
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        QVERIFY2(!engine.config_.tipPhaseTypeTrimEnabled,
                 "tip_phase_type_trim must ship default OFF until a counted fade batch grades it");
        QCOMPARE(engine.config_.tipPhaseTypeTrims.value(QStringLiteral("Right Fade")), -6.0);
        QCOMPARE(engine.tipPhaseTypeTrimMsForTests(QStringLiteral("Right Fade")), 0.0);
        QCOMPARE(engine.tipPhaseTypeTrimMsForTests(QStringLiteral("Left Fade")), 0.0);

        // Decision inertness, bit for bit: same staging as tipPhaseLookupIsThePrimaryTipSource.
        engine.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0);
        constexpr double kBase = 40'000.0;
        constexpr double kSlope = 0.18;
        const double lastMs = stagePhaseDecision(engine, kBase, 40.0, kSlope, 300.0);
        const double samplerCrossingMs = kBase + (100.0 - 40.0) / kSlope;
        engine.shot_.fillPhaseAnchorMs = samplerCrossingMs - 379.0 + 20.0;
        engine.shot_.shotType = QStringLiteral("Right Fade");
        const auto d = engine.canonicalAutonomousTipDecision(lastMs);
        QCOMPARE(d.source, QStringLiteral("phase"));
        QVERIFY2(std::abs(d.tipAbsMs - (engine.shot_.fillPhaseAnchorMs + 379.0)) < 1e-9,
                 "flag OFF must leave the fade decision bit-identical to the pooled constant");
    }

    // 2) Flag ON: the decision moves by exactly the trim, for the exact label only.
    {
        AppConfigData on = config;
        on.tipPhaseTypeTrimEnabled = true;
        AutomationEngine engine;
        engine.applyConfig(on, LearningData{});
        QCOMPARE(engine.tipPhaseTypeTrimMsForTests(QStringLiteral("Right Fade")), -6.0);
        QCOMPARE(engine.tipPhaseTypeTrimMsForTests(QStringLiteral("Standstill")), 0.0);
        // No substring inheritance: an unmeasured type must get the pooled constant untouched.
        QCOMPARE(engine.tipPhaseTypeTrimMsForTests(QStringLiteral("Post Fade")), 0.0);

        engine.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0);
        constexpr double kBase = 40'000.0;
        constexpr double kSlope = 0.18;
        const double lastMs = stagePhaseDecision(engine, kBase, 40.0, kSlope, 300.0);
        const double samplerCrossingMs = kBase + (100.0 - 40.0) / kSlope;
        engine.shot_.fillPhaseAnchorMs = samplerCrossingMs - 379.0 + 20.0;
        engine.shot_.shotType = QStringLiteral("Right Fade");
        const auto d = engine.canonicalAutonomousTipDecision(lastMs);
        QCOMPARE(d.source, QStringLiteral("phase"));
        QVERIFY2(std::abs(d.tipAbsMs - (engine.shot_.fillPhaseAnchorMs + 379.0 - 6.0)) < 1e-9,
                 "flag ON must shorten a Right Fade tip by exactly the configured trim");

        // 3) Single-digit bound: an out-of-range entry clamps at the accessor, so a mis-entered
        // settings value can never move an aim by more than one green-window sliver.
        engine.config_.tipPhaseTypeTrims.insert(QStringLiteral("Right Fade"), -25.0);
        QCOMPARE(engine.tipPhaseTypeTrimMsForTests(QStringLiteral("Right Fade")), -9.0);
    }

    // 4) LEARNER SYMMETRY. A Right Fade whose animation genuinely runs 6 ms short must
    // normalise to the SAME base-scale value a Standstill produces, teaching the pooled
    // learner an identical constant — the trim and the learner cannot fight.
    {
        AppConfigData on = config;
        on.tipPhaseTypeTrimEnabled = true;
        AutomationEngine fade;
        fade.applyConfig(on, LearningData{});
        AutomationEngine still;
        still.applyConfig(config, LearningData{});   // control: flag OFF, Standstill
        const double base = fade.config().tipPhaseSeedPhysicalMs + 2.0;
        auto land = [](AutomationEngine& e, const QString& type, double animationMs) {
            e.meterCapPhaseAnchorMs_ = 1'000.0;
            e.meterCapPhaseAnchorLevelPct_ = 30.0;
            e.meterCapPhaseStopMs_ = 1'000.0 + animationMs;
            e.meterCapPhaseStopConfirmed_ = true;
            e.meterCapShotType_ = type;
            e.recordPhaseConstantSample();
        };
        for (int i = 0; i < 3; ++i) {
            land(fade, QStringLiteral("Right Fade"), base - 6.0);   // 6 ms short, as measured
            land(still, QStringLiteral("Standstill"), base);
        }
        QVERIFY2(std::abs(fade.learnedPhasePhysicalMsForTests()
                          - still.learnedPhasePhysicalMsForTests()) < 1e-9,
                 "a trimmed fade landing must teach the learner exactly what a standstill does");

        // And the band check runs on the type-normalised value: raw 239 sits below the 240
        // floor, but a Right Fade normalises to 245 and must be ACCEPTED — dropping it would
        // starve the learner of exactly the type the trim exists for.
        AutomationEngine bandEdge;
        bandEdge.applyConfig(on, LearningData{});
        QSignalSpy spy(&bandEdge, &AutomationEngine::engineDiagnostic);
        land(bandEdge, QStringLiteral("Right Fade"), 239.0);
        QCOMPARE(bandEdge.phaseConstantSampleCountForTests(), 1);
        bool sawTrimField = false;
        for (int i = 0; i < spy.count(); ++i) {
            const QString line = spy.at(i).at(0).toString();
            if (line.startsWith(QStringLiteral("PHASE SAMPLE:"))) {
                QVERIFY(line.contains(QStringLiteral("accepted=1")));
                sawTrimField = line.contains(QStringLiteral("type_trim_ms=-6.0"));
            }
        }
        QVERIFY2(sawTrimField,
                 "an active trim must be visible on the PHASE SAMPLE line for offline analysis");
    }
}

void AutomationEngineTests::shippedDefaultsMatchTheValidatedConfiguration()
{
    // THE SHIPPING RISK THIS CLOSES. Several load-bearing behaviours were default-OFF in code and
    // turned ON only by the dev launcher (which is gitignored). Every live measurement on this
    // rig -- including the batch that reached a 96.9% fire rate, 7/7 No Dip and 10/11 Go-To on
    // the phase predictor -- was therefore produced by a configuration NO CUSTOMER WOULD RUN.
    // Shipping that gap means shipping an untested product while believing it is a measured one.
    //
    // These assertions are deliberately about DEFAULTS, not about the features. Each feature has
    // its own behavioural tests; this pins that a fresh install gets them.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    LearningData learning;

    // Go-To must WAIT for a real meter rather than blind-fire. Go-To animations are variable
    // length, which is the entire reason the wait exists; the un-waited path was never measured.
    const QByteArray savedGoto = qgetenv("ORION_GOTO_METER_WAIT");
    qunsetenv("ORION_GOTO_METER_WAIT");
    engine.applyConfig(config, learning);
    QVERIFY2(engine.config_.gotoMeterWait,
             "a fresh install must get the Go-To meter wait that every measurement used");
    // ...and an explicit 0 must still force it off, so a launcher can A/B.
    qputenv("ORION_GOTO_METER_WAIT", "0");
    AutomationEngine forcedOff;
    forcedOff.applyConfig(config, learning);
    QVERIFY2(!forcedOff.config_.gotoMeterWait, "an explicit 0 must still disable the Go-To wait");
    if (savedGoto.isEmpty()) {
        qunsetenv("ORION_GOTO_METER_WAIT");
    } else {
        qputenv("ORION_GOTO_METER_WAIT", savedGoto);
    }

    // The tip-phase predictor and its ladder are the timing core; a default-off ladder would put
    // No Dip straight back onto the biased sampler it was rescued from.
    AutomationEngine fresh;
    fresh.applyConfig(config, learning);
    QVERIFY2(fresh.config_.tipPhaseEnabled, "the phase predictor must be on by default");
    QVERIFY2(fresh.config_.tipPhaseAnchorLadderCount > 0,
             "the anchor ladder must be on by default or No Dip loses the phase member");
    QVERIFY2(fresh.config_.tipPhaseImminentHoldBandPct > 0.0,
             "the imminent-anchor hold must be on by default");
}

void AutomationEngineTests::mutableStateNeverLivesBesideTheExecutableInProduction()
{
    // [ORION_DATA_DIR] THE SHIP BLOCKER. main.cpp sets rootDir = applicationDirPath() and a
    // production build deliberately refuses the dev root-dir redirection (that redirection is an
    // integrity hole when shipping). Everything writable then hung off the INSTALL directory --
    // settings.json, learning.json, logs/, status.json, calibration/ -- and the default install
    // location is {autopf}\Orion, i.e. Program Files, which a standard user cannot write.
    //
    // The failure mode is the nastiest kind: first run LOOKS fine because reads succeed, every
    // write silently fails, and the second launch comes up unconfigured. It cannot reproduce on
    // this dev rig, where rootDir is a writable checkout under the user's own profile.
    const QString root = QStringLiteral("C:/Program Files/Orion");
    const QString data = orionDataDir(root);

#ifdef ORION_PRODUCTION_BUILD
    QVERIFY2(data != root,
             "a production build must not keep mutable state in the install directory");
    QVERIFY2(!data.isEmpty(), "the data dir must resolve to something writable");
#else
    // DEV IS BYTE-IDENTICAL, and that is load-bearing: the rig's runbooks, the offline replay
    // harness and every log-scraping diagnostic in this repo address logs/ and settings.json
    // relative to the checkout. Moving them in a dev build would silently invalidate all of it.
    // REVERT-TRACE: drop the #else arm of orionDataDir() and this fails.
    QCOMPARE(data, root);
#endif

    // migrateLegacyStateFile must never clobber state the user already has in the new location,
    // and must be a strict no-op when the two paths coincide (every dev build).
    QTemporaryDir tmp;
    QVERIFY(tmp.isValid());
    const QString legacy = tmp.path() + QStringLiteral("/legacy.json");
    const QString fresh = tmp.path() + QStringLiteral("/fresh.json");
    {
        QFile f(legacy);
        QVERIFY(f.open(QIODevice::WriteOnly));
        f.write("{\"from\":\"legacy\"}");
    }
    {
        QFile f(fresh);
        QVERIFY(f.open(QIODevice::WriteOnly));
        f.write("{\"from\":\"already-migrated\"}");
    }
    migrateLegacyStateFile(legacy, fresh);
    QFile check(fresh);
    QVERIFY(check.open(QIODevice::ReadOnly));
    QVERIFY2(QString::fromUtf8(check.readAll()).contains(QStringLiteral("already-migrated")),
             "migration must never overwrite state the user already has in the data dir");
    check.close();

    // Same path in and out is a no-op rather than a self-copy.
    migrateLegacyStateFile(legacy, legacy);
    QVERIFY(QFileInfo::exists(legacy));

    // A genuinely absent target IS carried over.
    const QString target = tmp.path() + QStringLiteral("/carried.json");
    migrateLegacyStateFile(legacy, target);
    QVERIFY2(QFileInfo::exists(target), "an existing legacy file must be carried into the data dir");
}

void AutomationEngineTests::phaseAnchorImminentHoldIsNarrowAndRisingOnly()
{
    // [ORION_TIP_PHASE_IMMINENT] The live miss, 2026-08-04. Across 54 shots, 52 released on the
    // phase member at a median 170 ms after the meter appeared and a median fill of 42.6. Exactly
    // ONE released on the sampler -- a Go-To that fired 55 ms after appearance, on FOUR samples,
    // at fill 29.3, below the 30 anchor so no crossing had been observed. The meter appeared at
    // 18.3 climbing 0.227 %/ms and would have crossed the anchor ~3 ms later. The sampler beat
    // the phase member by one frame, and did it in the sampler's worst regime: furthest
    // extrapolation, fewest samples, carrying the +61-92 ms bias phase exists to replace. That
    // shot released at 29.3 into a green window starting at 95.4.
    //
    // This predicate decides ONLY whether to wait one frame for the better estimate. Every
    // condition is a refusal, so the failure direction is "release as before", never "hold".
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    AutomationEngine engine;
    engine.applyConfig(config, LearningData{});
    QCOMPARE(engine.config_.tipPhaseAnchorPct, 30.0);
    QCOMPARE(engine.config_.tipPhaseImminentHoldBandPct, 6.0);

    constexpr double kRising = 0.20;   // %/ms, the measured live rate

    // THE CASE IT EXISTS FOR: fill 29.3 rising, one frame short of the anchor.
    QVERIFY2(engine.phaseAnchorImminentForTests(29.3, 0.227),
             "the live sampler miss at fill 29.3 must be held for the imminent anchor");
    QVERIFY(engine.phaseAnchorImminentForTests(24.1, kRising));   // just inside the 6 pp band

    // NARROW. A meter stalled WELL below the anchor is not held -- it aborts on the existing
    // timeout exactly as before, rather than waiting for a crossing that is not coming.
    // REVERT-TRACE: widen tipPhaseImminentHoldBandPct and this starts holding meters at 15.
    QVERIFY2(!engine.phaseAnchorImminentForTests(23.9, kRising),
             "a meter more than the band below the anchor must not be held");
    QVERIFY(!engine.phaseAnchorImminentForTests(15.0, kRising));
    QVERIFY(!engine.phaseAnchorImminentForTests(1.0, kRising));

    // RISING ONLY. A flat or falling meter will never reach the anchor, so holding for it would
    // convert a one-frame wait into a hang that only ends at the maxHoldMs ceiling. This is the
    // condition that keeps the hold bounded in PRACTICE rather than only in principle.
    // REVERT-TRACE: drop the slope test and the flat/falling cases below start holding.
    QVERIFY2(!engine.phaseAnchorImminentForTests(29.3, 0.0),
             "a STALLED meter just below the anchor must never be held");
    QVERIFY2(!engine.phaseAnchorImminentForTests(29.3, -0.20),
             "a DEFLATING meter must never be held");

    // AT OR ABOVE THE ANCHOR is not this predicate's business: the crossing either already
    // happened, or the meter was first seen high and that is the ladder's problem.
    QVERIFY(!engine.phaseAnchorImminentForTests(30.0, kRising));
    QVERIFY(!engine.phaseAnchorImminentForTests(35.0, kRising));

    // Unreadable inputs fall through to the EXISTING behaviour (release), never to a hold.
    const double nan = std::numeric_limits<double>::quiet_NaN();
    QVERIFY(!engine.phaseAnchorImminentForTests(nan, kRising));
    QVERIFY(!engine.phaseAnchorImminentForTests(29.3, nan));

    // Disableable, and disabled means the pre-hold behaviour exactly.
    AutomationEngine off;
    off.applyConfig(config, LearningData{});
    off.config_.tipPhaseImminentHoldBandPct = 0.0;
    QVERIFY(!off.phaseAnchorImminentForTests(29.3, 0.227));
    AutomationEngine noPhase;
    noPhase.applyConfig(config, LearningData{});
    noPhase.config_.tipPhaseEnabled = false;
    QVERIFY2(!noPhase.phaseAnchorImminentForTests(29.3, 0.227),
             "with the phase member off there is no better estimate to wait for");
}

void AutomationEngineTests::rungImminentHoldExtendsToLadderRungsOnlyWhenFlagged()
{
    // [ORION_RUNG_IMMINENT] The measured live class this exists for (logs 2026-08-04..06):
    // 27 of 62 rejected_missed aborts were FIRST-TICK sampler kills (reservation_updates=1,
    // source=sampler, no witnessed crossing), 19 of them within ~5pp below a ladder rung.
    // In the first tip_phase_anchor_base20 batch (2026-08-06T05:21-05:46Z) this was 4 of the
    // 6 misses: e.g. a meter first seen at fill 21.96 is ABOVE the base-20 anchor, so the
    // base-only hold declines and the sampler (+61-92ms early bias) aborted the shot on its
    // first decision tick with lateness 4.65ms -- one witnessable rung-25 crossing away from
    // a phase estimate with ~122ms of post-crossing budget.
    constexpr double kRising = 0.20;   // %/ms, the measured live rate

    // DEFAULT OFF under the base20 constellation: the live kills stay kills. This leg failing
    // means the flag's default has silently flipped ON.
    AppConfigData base20;
    base20.remotePlayInputSource = QStringLiteral("square");
    base20.minimumHoldMs = 0.0;
    base20.autonomousVision = true;
    base20.measuredLeadEnabled = true;
    base20.tipPhaseAnchorBase20 = true;
    AutomationEngine off;
    off.applyConfig(base20, LearningData{});
    QCOMPARE(off.config_.tipPhaseAnchorPct, 20.0);
    QVERIFY2(!off.config_.tipPhaseRungImminentHold,
             "tip_phase_rung_imminent_hold must default OFF");
    QVERIFY2(!off.phaseAnchorImminentForTests(21.96, kRising),
             "flag OFF: a fill above the base anchor must not be held (today's behaviour)");
    QVERIFY(!off.phaseAnchorImminentForTests(38.94, kRising));
    // Below the base anchor the pre-flag behaviour is untouched.
    QVERIFY(off.phaseAnchorImminentForTests(18.0, kRising));

    // FLAG ON under base20 (rungs {25,30,35,40}, band 6.0): each live first-tick sampler kill
    // that sat within the band below a rung is now held for that rung's crossing.
    AppConfigData flagged = base20;
    flagged.tipPhaseRungImminentHold = true;
    AutomationEngine on;
    on.applyConfig(flagged, LearningData{});
    QCOMPARE(on.config_.tipPhaseAnchorLadderCount, 4);
    QVERIFY2(on.phaseAnchorImminentForTests(21.96, kRising),
             "the 2026-08-06T05:21:50Z live kill (fill 21.96, 3.04pp below rung 25) must hold");
    QVERIFY2(on.phaseAnchorImminentForTests(22.45, kRising),
             "the 2026-08-06T05:23:49Z live kill (fill 22.45) must hold");
    QVERIFY2(on.phaseAnchorImminentForTests(38.94, kRising),
             "the 2026-08-06T05:46:02Z live kill (fill 38.94, 1.06pp below rung 40) must hold");
    // ABOVE THE TOP RUNG no witnessable crossing remains: the 05:24:10Z kill (fill 53.23)
    // stays an abort. Holding there would wait for a crossing that can never be witnessed.
    QVERIFY2(!on.phaseAnchorImminentForTests(53.23, kRising),
             "a fill above the top rung has nothing to wait for and must not be held");
    QVERIFY(!on.phaseAnchorImminentForTests(40.0, kRising));   // top rung reached exactly
    // A level exactly reached is no longer witnessable (a straddle needs prevFill < level),
    // so the hold targets the NEXT rung -- 5pp up, still inside the 6pp band.
    QVERIFY(on.phaseAnchorImminentForTests(25.0, kRising));
    // The base-anchor behaviour is preserved verbatim below the base.
    QVERIFY(on.phaseAnchorImminentForTests(18.0, kRising));
    QVERIFY2(!on.phaseAnchorImminentForTests(13.9, kRising),
             "the band still bounds the hold at the bottom of the ladder");
    // RISING ONLY still binds: the same fills that hold while rising never hold stalled or
    // deflating -- this is what keeps the hold bounded in practice.
    QVERIFY(!on.phaseAnchorImminentForTests(21.96, 0.0));
    QVERIFY(!on.phaseAnchorImminentForTests(21.96, -0.20));
    QVERIFY(!on.phaseAnchorImminentForTests(38.94, 0.0));

    // FLAG ON under the default base-30 regime (rungs {35,40}): the base case is unchanged and
    // the same protection now covers the corridors below the rungs.
    AppConfigData base30;
    base30.remotePlayInputSource = QStringLiteral("square");
    base30.minimumHoldMs = 0.0;
    base30.autonomousVision = true;
    base30.measuredLeadEnabled = true;
    base30.tipPhaseRungImminentHold = true;
    AutomationEngine on30;
    on30.applyConfig(base30, LearningData{});
    QCOMPARE(on30.config_.tipPhaseAnchorPct, 30.0);
    QVERIFY2(on30.phaseAnchorImminentForTests(29.3, 0.227),
             "the original live sampler miss must still hold with the flag ON");
    QVERIFY2(on30.phaseAnchorImminentForTests(34.5, kRising),
             "base-30 + flag: the corridor below rung 35 is now protected");
    QVERIFY(on30.phaseAnchorImminentForTests(38.9, kRising));
    QVERIFY(!on30.phaseAnchorImminentForTests(40.0, kRising));
    QVERIFY(!on30.phaseAnchorImminentForTests(44.0, kRising));

    // The existing refusals still bind with the flag ON.
    AutomationEngine disabled;
    disabled.applyConfig(flagged, LearningData{});
    disabled.config_.tipPhaseEnabled = false;
    QVERIFY(!disabled.phaseAnchorImminentForTests(21.96, kRising));
    AutomationEngine noBand;
    noBand.applyConfig(flagged, LearningData{});
    noBand.config_.tipPhaseImminentHoldBandPct = 0.0;
    QVERIFY(!noBand.phaseAnchorImminentForTests(21.96, kRising));
}

void AutomationEngineTests::tipPhaseLadderRescuesAMeterFirstSeenAboveTheBaseAnchor()
{
    // [ORION_TIP_PHASE_LADDER] No Dip's meter is first seen at 32.4-37.3% fill -- measured across
    // the 2026-08-04 batches, and entirely above the 30 anchor, with every other shot type first
    // seen between 11.9 and 27.8. Its 30 crossing is therefore already history when the engine
    // first sees it, no straddling pair can exist, and the shot fell back to the biased
    // registration/sampler chain: phase drove 20/21 Standstill and 9/9 Go-To but only 2 of 4
    // No Dip.
    //
    // The ladder witnesses a HIGHER crossing the meter genuinely has not made yet. Nothing is
    // inferred; the straddle rules are unchanged, only the level moves.
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;

    // (1) THE RESCUE. First seen at 32 -- above 30, so 30 is unreachable -- then crossing 35.
    AutomationEngine noDip;
    noDip.applyConfig(config, LearningData{});
    QCOMPARE(noDip.config_.tipPhaseAnchorPct, 30.0);
    QCOMPARE(noDip.config_.tipPhaseAnchorLadderStepPct, 5.0);
    QCOMPARE(noDip.config_.tipPhaseAnchorLadderCount, 2);      // -> 35, 40
    noDip.notePhaseAnchorSample(32.0, 1'000.0);
    QCOMPARE(noDip.context().fillPhaseAnchorMs, -1.0);   // no pair yet
    noDip.notePhaseAnchorSample(38.0, 1'016.0);          // straddles 35, not 30
    QVERIFY2(noDip.context().fillPhaseAnchorMs >= 0.0,
             "a meter first seen above the base anchor must still be dated by the ladder");
    QCOMPARE(noDip.context().fillPhaseAnchorLevelPct, 35.0);
    // (35 - 32) / (38 - 32) = 0.5 of a 16 ms step -> 1008.0. Interpolated, not snapped.
    QVERIFY2(std::abs(noDip.context().fillPhaseAnchorMs - 1'008.0) < 0.001,
             qPrintable(QStringLiteral("ladder anchor must interpolate: got %1, expected 1008.0")
                            .arg(noDip.context().fillPhaseAnchorMs)));

    // (2) INERTNESS -- the property that protects every shot type that already works. An ordinary
    // meter seen below 30 must still be dated at 30, so its constant, and therefore its aim, is
    // untouched. Measured, this is every non-No-Dip type: first fills run 11.9-27.8.
    // REVERT-TRACE: iterate the ladder high-to-low instead and this reports 40.0.
    AutomationEngine ordinary;
    ordinary.applyConfig(config, LearningData{});
    ordinary.notePhaseAnchorSample(26.0, 1'000.0);
    ordinary.notePhaseAnchorSample(34.0, 1'016.0);
    QCOMPARE(ordinary.context().fillPhaseAnchorLevelPct, 30.0);
    QCOMPARE(ordinary.tipPhaseLevelAdjustmentMsForTests(30.0), 0.0);

    // (2b) THE LADDER MUST NOT BE A WAY OUT OF THE OVERSHOOT GATE. This is the bug the inertness
    // check actually caught. A 26 -> 44 carryover jump overshoots the 30 anchor by 14 pp and the
    // pre-ladder engine refused it. Testing each level independently and taking the first that
    // PASSES would admit it at 35 (overshoot only 9 pp) -- dating a shot that was previously
    // rejected, which is the ladder silently WEAKENING the provenance gate rather than extending
    // its reach. The guard is anchored to the lowest straddled level for exactly this reason.
    // REVERT-TRACE: evaluate straddleOvershootPlausible per-level inside the search loop and take
    // the first passing level; this QCOMPARE then reports 35.0 instead of -1.
    AutomationEngine gateJump;
    gateJump.applyConfig(config, LearningData{});
    gateJump.notePhaseAnchorSample(26.0, 1'000.0);
    gateJump.notePhaseAnchorSample(44.0, 1'016.0);
    QCOMPARE(gateJump.context().fillPhaseAnchorMs, -1.0);
    QCOMPARE(gateJump.context().fillPhaseAnchorLevelPct, -1.0);

    // (3) FAIL-CLOSED IS PRESERVED. A meter above the WHOLE ladder is still never dated -- the
    // carryover case that tipPhaseAnchorDatesTheFirstUpwardCrossing pins does not become
    // datable just because more levels exist.
    AutomationEngine aboveAll;
    aboveAll.applyConfig(config, LearningData{});
    aboveAll.notePhaseAnchorSample(62.0, 1'000.0);
    aboveAll.notePhaseAnchorSample(71.0, 1'016.0);
    aboveAll.notePhaseAnchorSample(80.0, 1'032.0);
    QCOMPARE(aboveAll.context().fillPhaseAnchorMs, -1.0);
    QCOMPARE(aboveAll.context().fillPhaseAnchorLevelPct, -1.0);

    // (4) THE OVERSHOOT GUARD STILL APPLIES, PER LEVEL. A carryover jump that clears a ladder
    // level by more than tipPhaseAnchorMaxOvershootPct is refused at that level too -- the
    // ladder must not become a way around the provenance gate.
    AutomationEngine jump;
    jump.applyConfig(config, LearningData{});
    jump.notePhaseAnchorSample(31.0, 1'000.0);   // above 30, below 35
    jump.notePhaseAnchorSample(90.0, 1'016.0);   // clears 35 by 55 pp and 40 by 50 pp
    QCOMPARE(jump.context().fillPhaseAnchorMs, -1.0);

    // (5) THE LEVEL ADJUSTMENT IS ZERO AT BASE AND NEGATIVE ABOVE IT, at the measured slope.
    // Two independent sessions gave -5.19 and -5.28 ms/pp (n=36, n=22); the shipped -5.235 is
    // their mean, so 30->40 shortens the constant by ~52 ms.
    AutomationEngine slope;
    slope.applyConfig(config, LearningData{});
    QCOMPARE(slope.tipPhaseLevelAdjustmentMsForTests(30.0), 0.0);
    QVERIFY2(std::abs(slope.tipPhaseLevelAdjustmentMsForTests(35.0) - (-26.175)) < 0.001,
             "a 5 pp later anchor must shorten the constant by the measured slope");
    QVERIFY2(std::abs(slope.tipPhaseLevelAdjustmentMsForTests(40.0) - (-52.35)) < 0.001,
             "a 10 pp later anchor must shorten the constant by ~52 ms");
    // An undated shot (-1.0) must contribute NO adjustment rather than a wild extrapolation.
    QCOMPARE(slope.tipPhaseLevelAdjustmentMsForTests(-1.0), 0.0);

    // (6) THE LADDER IS DISABLEABLE, and with it off the behaviour is exactly the pre-ladder one:
    // the same 32 -> 38 stream that was rescued in (1) records nothing at all.
    AutomationEngine off;
    off.applyConfig(config, LearningData{});
    off.config_.tipPhaseAnchorLadderCount = 0;
    off.notePhaseAnchorSample(32.0, 1'000.0);
    off.notePhaseAnchorSample(38.0, 1'016.0);
    QCOMPARE(off.context().fillPhaseAnchorMs, -1.0);
}

void AutomationEngineTests::tipPhaseAnchorRejectsACarryoverStraddleJump()
{
    // THE HOLE IN THE STRADDLE GUARD, and the live shot it cost.
    //
    // tipPhaseAnchorDatesTheFirstUpwardCrossing pins that a meter seen ONLY above the anchor is
    // never dated, on the grounds that a lingering previous-shot meter is a genuine detection
    // that appears high. A carryover does not have to stay above the anchor to defeat that: it
    // only has to be sampled once below it and once above it, and the interpolation across that
    // pair then manufactures an anchor for an animation that never ran.
    //
    // MEASURED (2026-08-04, physical_epoch=38). The detector had been reporting the previous
    // shot's meter parked at ~50% for the 2.2 s since that shot aborted. The next press was
    // granted ownership 42.7 ms later (416-1795 ms for every other attempt in the batch) on the
    // pair 28.7 -> 50.4, the phase member was primary on the FIRST reservation of the shot at
    // fill 50.43, and the release fired at fill 50.2 into a meter that then moved 1.1 pp:
    // peak_fill 51.36 against a 93.46-100 green, graded EARLY at -90.0 ms.
    //
    // The separation is what makes this checkable rather than fitted: across the 21 shots in
    // that batch whose anchor came from a real rise, the phase member first became primary at
    // fill 30.06-33.60 -- at most 3.60 pp past the anchor, one 60 fps frame at the meter's
    // measured 0.205-0.222 %/ms. The failure was 20.43 pp past it.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});
    QCOMPARE(engine.config_.tipPhaseAnchorMaxOvershootPct, 12.0);

    // REVERT-TRACE: delete `straddleOvershootPlausible` from notePhaseAnchorSample's condition
    // and this QCOMPARE fails -- 28.7 pairs with 50.4 and dates an anchor 6.6% of the way into
    // a step the meter never climbed.
    engine.notePhaseAnchorSample(28.7, 1'000.0);
    QCOMPARE(engine.context().fillPhaseAnchorMs, -1.0);   // below the anchor: no pair yet
    engine.notePhaseAnchorSample(50.4, 1'016.0);
    QCOMPARE(engine.context().fillPhaseAnchorMs, -1.0);   // a straddle, but a JUMP not a rise

    // FAIL-CLOSED HALF #1 -- the gate must WITHDRAW the member, not merely mis-date it. With no
    // anchor the phase branch of canonicalAutonomousTipDecision cannot run at all, so the
    // pre-existing registration/sampler chain owns the shot exactly as it did before this member
    // existed. Nothing here can move, extend, or manufacture a deadline.
    const auto withdrawn = engine.canonicalAutonomousTipDecision(1'020.0);
    QVERIFY2(!withdrawn.phasePrimary,
             "a rejected straddle must stand the phase member down, not hand it a bad anchor");
    QCOMPARE(withdrawn.phaseTipAbsMs, -1.0);

    // FAIL-CLOSED HALF #2 -- the gate must not eat the shots it was never about. A REAL crossing
    // at this meter's real rate (26.0 -> 34.0 over one 16 ms frame, 4.0 pp past the anchor,
    // above the healthy batch's 3.60 pp maximum and still nowhere near 12.0) is still dated, and
    // still interpolated rather than snapped.
    AutomationEngine clean;
    clean.applyConfig(config, LearningData{});
    clean.notePhaseAnchorSample(26.0, 1'000.0);
    clean.notePhaseAnchorSample(34.0, 1'016.0);
    QVERIFY2(std::abs(clean.context().fillPhaseAnchorMs - 1'008.0) < 0.001,
             qPrintable(QStringLiteral("a real crossing must still be dated by interpolation: "
                                       "expected 1008.0, got %1")
                            .arg(clean.context().fillPhaseAnchorMs)));

    // A DROPPED-FRAME BURST is the reason this bounds the overshoot in pp rather than the pair's
    // implied rate: three consecutive dropped frames is a 50 ms straddle covering ~10.5 pp at
    // 0.21 %/ms, which is a genuine crossing observed through a detection hiccup. A rate gate
    // would have to be told the cadence, and the cadence is exactly what is unreliable in the
    // case being caught. 29.0 -> 40.0 across 50 ms is that shot, and it must still be dated.
    AutomationEngine dropped;
    dropped.applyConfig(config, LearningData{});
    dropped.notePhaseAnchorSample(29.0, 1'000.0);
    dropped.notePhaseAnchorSample(40.0, 1'050.0);
    QVERIFY2(dropped.context().fillPhaseAnchorMs >= 0.0,
             "a real crossing seen across dropped frames must still date the shot");

    // And the shot is not condemned for the rest of its life by one bad pair: if the meter falls
    // back below the anchor and re-crosses cleanly, that crossing is dated. The gate only ever
    // removes evidence the engine should not have trusted.
    AutomationEngine recovers;
    recovers.applyConfig(config, LearningData{});
    recovers.notePhaseAnchorSample(28.7, 1'000.0);
    recovers.notePhaseAnchorSample(50.4, 1'016.0);
    QCOMPARE(recovers.context().fillPhaseAnchorMs, -1.0);
    recovers.notePhaseAnchorSample(27.0, 1'032.0);       // carryover drops away
    recovers.notePhaseAnchorSample(31.0, 1'048.0);       // the real rise crosses
    QVERIFY2(recovers.context().fillPhaseAnchorMs >= 0.0,
             "a clean re-crossing after a rejected jump must still date the shot");
}

void AutomationEngineTests::tipPhaseAnchorIsClearedByDetectorRelock()
{
    // A detector re-lock is a NEW trajectory episode -- that is the entire reason the relock
    // block in updateDetection exists. Carrying the previous episode's anchor across it is the
    // worst failure this predictor has available: a stale anchor plus a perfectly valid-looking
    // constant yields a confident ABSOLUTE tip for an animation the detector has only just
    // re-acquired, and nothing downstream can tell it is fiction.
    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    constexpr quint64 kEpoch = 9'102;
    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;
    int frame = 1;
    promoteStrictAutonomousSquare(engine, square, frame, kEpoch, 220.0, 2.0, 6, 0.0);
    // Stops at the straddling pair that dates the anchor (22 -> 31 crosses 30) rather than
    // driving on to 40. Carrying further let the synthetic rise -- which climbs ~0.45 %/ms,
    // roughly 2.4x the measured live rate -- advance the shot far enough that the aim constant
    // influenced whether an anchor survived to the assertion, so the fixture silently became
    // sensitive to a number it is not testing. It caught the 2026-08-05 re-aim (387 -> 399) that
    // way. The relock behaviour under test is unchanged; only the setup is now independent of
    // the aim.
    for (const double fill : {22.0, 31.0}) {
        engine.advanceTestClock(20.0);
        DetectionResult s = strictLiveMeterSample(fill, frame++, kEpoch, 220.0, 2.0, 6);
        s.frameAgeMs = 0.0;
        engine.updateDetection(s);
        engine.process(square);
    }
    QVERIFY2(engine.context().fillPhaseAnchorMs >= 0.0,
             "fixture never dated an anchor, so the reset below proves nothing");
    const double staleAnchorMs = engine.context().fillPhaseAnchorMs;

    // A silent >50 ms genuine-sample gap is the engine's own re-lock discontinuity test.
    engine.advanceTestClock(120.0);
    DetectionResult relock = strictLiveMeterSample(44.0, frame++, kEpoch, 220.0, 2.0, 6);
    relock.frameAgeMs = 0.0;
    relock.stage = QStringLiteral("acquire");
    engine.updateDetection(relock);
    engine.process(square);

    // REVERT-TRACE: remove the three fillPhaseAnchorMs/phasePrev* lines from the relock block in
    // updateDetection and this QCOMPARE fails -- the pre-relock anchor survives and dates the
    // replacement episode.
    QCOMPARE(engine.context().fillPhaseAnchorMs, -1.0);
    QVERIFY(staleAnchorMs >= 0.0);

    // ...and the first post-relock sample must not pair with the last PRE-relock one to
    // synthesise a crossing across the discontinuity. The new episode is already above the
    // anchor, so it stays undated and the shot falls back to the sampler.
    engine.advanceTestClock(20.0);
    DetectionResult next = strictLiveMeterSample(53.0, frame++, kEpoch, 220.0, 2.0, 6);
    next.frameAgeMs = 0.0;
    engine.updateDetection(next);
    engine.process(square);
    QCOMPARE(engine.context().fillPhaseAnchorMs, -1.0);
}

void AutomationEngineTests::tipPhaseLookupIsThePrimaryTipSource()
{
    // The substantive change: when the crossing was observed, the tip is a LOOKUP off that
    // crossing rather than an extrapolation of the fill curve.
    AutomationEngine engine;
    AppConfigData config;
    engine.applyConfig(config, LearningData{});
    engine.setTipPhaseConfigForTests(/*enabled=*/true, /*anchorPct=*/30.0,
                                     /*constantMs=*/379.0, /*seedPhysicalMs=*/318.0,
                                     /*sigmaMs=*/13.0);

    constexpr double kBase = 40'000.0;
    constexpr double kSlope = 0.18;          // the live rise, 0.174-0.188 %/ms across shot types
    const double lastMs = stagePhaseDecision(engine, kBase, /*startFill=*/40.0, kSlope,
                                             /*leadMs=*/300.0);
    // Sampler crossing in closed form: the rise is exactly linear, so the weighted fit lands on
    // the analytic root regardless of weights.
    const double samplerCrossingMs = kBase + (100.0 - 40.0) / kSlope;

    // Place the anchor so the phase tip sits comfortably inside the corroboration window.
    const double anchorMs = samplerCrossingMs - 379.0 + 20.0;
    engine.shot_.fillPhaseAnchorMs = anchorMs;

    const AutomationEngine::AutonomousTipDecision d =
        engine.canonicalAutonomousTipDecision(lastMs);

    QCOMPARE(d.source, QStringLiteral("phase"));
    QVERIFY(d.phasePrimary);
    QVERIFY2(std::abs(d.tipAbsMs - (anchorMs + 379.0)) < 1e-6,
             qPrintable(QStringLiteral("phase tip must be anchor + constant: got %1 expected %2")
                            .arg(d.tipAbsMs).arg(anchorMs + 379.0)));
    QCOMPARE(d.sigmaMs, 13.0);
    QCOMPARE(d.phaseSigmaMs, 13.0);
    QVERIFY(d.phaseAnchorMs == anchorMs);
    // The published weight must reproduce BY HAND from the two sigmas on the same decision --
    // the same identity reg_weight is held to. It is measured against the member the
    // pre-existing chain selected, which here is the sampler.
    QVERIFY2(d.samplerSigmaMs > 0.0, "fixture must leave an authoritative sampler to weigh against");
    const double phasePrec = 1.0 / (13.0 * 13.0);
    const double smpPrec = 1.0 / (d.samplerSigmaMs * d.samplerSigmaMs);
    QVERIFY2(std::abs(d.phaseWeight - phasePrec / (phasePrec + smpPrec)) < 1e-9,
             qPrintable(QStringLiteral("phase_weight must reproduce from the sigmas: %1 vs %2")
                            .arg(d.phaseWeight).arg(phasePrec / (phasePrec + smpPrec))));

    // FAIL-CLOSED HALF / REVERT-TRACE. With no observed crossing the member is absent entirely
    // and the pre-existing chain carries the shot byte-for-byte as before. Delete the
    // `shot_.fillPhaseAnchorMs >= 0.0` gate in canonicalAutonomousTipDecision and the
    // `phaseTipAbsMs == -1.0` assertion below fails: an unset (-1) anchor publishes a phase tip
    // of 378 ms, i.e. 379 ms after the epoch origin.
    AutomationEngine noAnchor;
    noAnchor.applyConfig(config, LearningData{});
    noAnchor.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0);
    const double lastMs2 = stagePhaseDecision(noAnchor, kBase, 40.0, kSlope, 300.0);
    QCOMPARE(noAnchor.shot_.fillPhaseAnchorMs, -1.0);
    const AutomationEngine::AutonomousTipDecision fallback =
        noAnchor.canonicalAutonomousTipDecision(lastMs2);
    QCOMPARE(fallback.source, QStringLiteral("sampler"));
    QVERIFY(!fallback.phasePrimary);
    QCOMPARE(fallback.phaseTipAbsMs, -1.0);
    QVERIFY2(std::abs(fallback.tipAbsMs - samplerCrossingMs) < 1.0,
             qPrintable(QStringLiteral("fallback must be the untouched sampler crossing: %1 vs %2")
                            .arg(fallback.tipAbsMs).arg(samplerCrossingMs)));

    // AND THE CARRYOVER PROOF. A dated crossing is not enough on its own: the T2 anchor-validity
    // gate is what distinguishes THIS shot's rising meter from a lingering previous-shot one
    // panning with the camera, which is a genuine raw detection that genuine-vs-echo cannot
    // reject. The phase member requires the same proof liveMeterCrossingAuthoritative already
    // demands, so an unproven episode falls back rather than dating a live shot off a carryover.
    // REVERT-TRACE: drop the `shot_.anchorValidMs >= 0.0` conjunct and this QCOMPARE fails.
    AutomationEngine unproven;
    unproven.applyConfig(config, LearningData{});
    unproven.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0);
    const double lastMs3 = stagePhaseDecision(unproven, kBase, 40.0, kSlope, 300.0);
    unproven.shot_.fillPhaseAnchorMs = samplerCrossingMs - 379.0 + 20.0;
    unproven.shot_.anchorValidMs = -1.0;   // episode never proven to be this shot's meter
    const AutomationEngine::AutonomousTipDecision carryover =
        unproven.canonicalAutonomousTipDecision(lastMs3);
    QCOMPARE(carryover.phaseTipAbsMs, -1.0);
    QVERIFY(!carryover.phasePrimary);
}

void AutomationEngineTests::tipPhaseYieldsToTheLiveMeterWhenTheyGrosslyDisagree()
{
    // THE FAIL-CLOSED HEART OF THIS CHANGE, and the reason the member is corroborated rather
    // than trusted outright.
    //
    // The constant is a calibrated property of ONE animation. Handed a meter that is not that
    // animation, an uncorroborated lookup is confidently wrong in BOTH directions -- and one of
    // those directions is a HELD release: the meter tops out while the lookup still claims
    // 150 ms of runway, so the command is submitted after the tip has already passed. That is a
    // guaranteed-late fire, which no part of this engine is allowed to produce. The live meter
    // therefore keeps a veto.
    AppConfigData config;
    constexpr double kBase = 40'000.0;
    constexpr double kSlope = 0.18;
    const double samplerCrossingMs = kBase + (100.0 - 40.0) / kSlope;

    auto decideWithAnchorOffset = [&](double phaseTipRelativeToSamplerMs) {
        AutomationEngine engine;
        engine.applyConfig(config, LearningData{});
        engine.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0);
        const double lastMs = stagePhaseDecision(engine, kBase, 40.0, kSlope, 300.0);
        engine.shot_.fillPhaseAnchorMs =
            samplerCrossingMs + phaseTipRelativeToSamplerMs - 379.0;
        return engine.canonicalAutonomousTipDecision(lastMs);
    };

    // 1) AGREEMENT (the live regime). Over 221 real reservation updates the disagreement runs
    // median +19.6 ms rMAD 21.4 at fill>=30, so a 20 ms offset is an ordinary shot and the
    // tighter member must win.
    const AutomationEngine::AutonomousTipDecision agree = decideWithAnchorOffset(-20.0);
    QCOMPARE(agree.source, QStringLiteral("phase"));

    // 2) THE GUARANTEED-LATE DIRECTION. The lookup claims the tip is 200 ms LATER than the
    // meter's own measured motion says. Holding for that would submit the command after the tip.
    // REVERT-TRACE: delete the contradictedByLiveMeter block and this QCOMPARE fails --
    // source comes back "phase" and tipAbsMs sits 200 ms past the sampler crossing.
    const AutomationEngine::AutonomousTipDecision tooLate = decideWithAnchorOffset(200.0);
    QCOMPARE(tooLate.source, QStringLiteral("sampler"));
    QVERIFY(!tooLate.phasePrimary);
    QVERIFY2(tooLate.tipAbsMs <= samplerCrossingMs + 1.0,
             qPrintable(QStringLiteral("a refused phase member must not still move the deadline "
                                       "late: tip=%1 sampler=%2")
                            .arg(tooLate.tipAbsMs).arg(samplerCrossingMs)));
    // The member is still PUBLISHED even when refused -- that is what makes the refusal
    // auditable from the log rather than invisible.
    QVERIFY(tooLate.phaseTipAbsMs > 0.0);

    // 3) The far-EARLY direction is refused on the same rule, so a mis-calibrated constant
    // cannot fire the whole session early either.
    const AutomationEngine::AutonomousTipDecision tooEarly = decideWithAnchorOffset(-200.0);
    QCOMPARE(tooEarly.source, QStringLiteral("sampler"));
    QVERIFY(!tooEarly.phasePrimary);
}

void AutomationEngineTests::tipPhaseNeverManufacturesADeadlineFromAStaleAnchor()
{
    // An absolute tip derived from a past event stays honest only while that event is recent
    // enough for the tip to still be ahead. Past the constant it is arithmetic about a shot that
    // has already happened, and must never present as a live deadline.
    AppConfigData config;
    AutomationEngine engine;
    engine.applyConfig(config, LearningData{});
    engine.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0);
    constexpr double kBase = 40'000.0;
    const double lastMs = stagePhaseDecision(engine, kBase, 40.0, 0.18, 300.0);

    // Anchor a full constant + 50 ms in the past -> the phase tip is already behind `lastMs`.
    engine.shot_.fillPhaseAnchorMs = lastMs - 379.0 - 50.0;
    const AutomationEngine::AutonomousTipDecision stale =
        engine.canonicalAutonomousTipDecision(lastMs);
    QVERIFY2(stale.source != QStringLiteral("phase"),
             "a phase tip already in the past must never be selected");
    QVERIFY(!stale.phasePrimary);

    // ...and with no other member available the decision must be INVALID, not merely different.
    // No blind release: the caller aborts rather than firing on arithmetic.
    // REVERT-TRACE: drop the `horizonMs > 0.0` half of horizonPlausible and this becomes a
    // valid deadline in the past.
    AutomationEngine solo;
    solo.applyConfig(config, LearningData{});
    solo.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0);
    solo.shot_.anchorValidMs = kBase;
    solo.shot_.confidence = 1.0;
    solo.shot_.fillPct = 95.0;
    solo.shot_.fillPhaseAnchorMs = kBase - 500.0;   // long past; sampler_ never fed -> no crossing
    primeLeadPivot(solo, kBase, 300.0);
    const AutomationEngine::AutonomousTipDecision blind =
        solo.canonicalAutonomousTipDecision(kBase);
    QVERIFY2(!blind.valid, "a stale anchor must not authorize a release on its own");
    QCOMPARE(blind.source, QStringLiteral("none"));
}

void AutomationEngineTests::tipPhaseDeadlineDoesNotChaseASingleFrameSlopeWobble()
{
    // THE OTHER HALF of autonomousFreshSampleMovesUnconfirmedDeadlineLater, and the mechanism
    // behind the whole variance reduction.
    //
    // The extrapolating chain must chase a slope change, because its estimate IS the slope. A
    // lookup off an already-observed crossing must not, because a mid-rise wobble carries no
    // information about when an animation that started 300 ms ago will end. That immunity is
    // precisely why the lookup measures rMAD 9.6 ms against the extrapolator's 18.4 ms on the
    // same 61 landings -- the meter easing in IS the deceleration, and it is already inside the
    // constant. Chasing it would be re-introducing the error this change removes.
    //
    // This is NOT the engine ignoring a dead meter: a meter that has genuinely stopped being the
    // calibrated animation is refused by the corroboration gate
    // (tipPhaseYieldsToTheLiveMeterWhenTheyGrosslyDisagree). This test is about jitter.
    AppConfigData config;
    AutomationEngine engine;
    engine.applyConfig(config, LearningData{});
    engine.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0);

    constexpr double kBase = 40'000.0;
    constexpr double kSlope = 0.18;
    const double lastMs = stagePhaseDecision(engine, kBase, /*startFill=*/40.0, kSlope,
                                             /*leadMs=*/300.0);
    const double samplerCrossingMs = kBase + (100.0 - 40.0) / kSlope;
    const double anchorMs = samplerCrossingMs - 379.0 + 20.0;
    engine.shot_.fillPhaseAnchorMs = anchorMs;

    const AutomationEngine::AutonomousTipDecision before =
        engine.canonicalAutonomousTipDecision(lastMs);
    QCOMPARE(before.source, QStringLiteral("phase"));

    // A 75% slope collapse on ONE frame -- the same wobble the extrapolating test uses.
    engine.sampler_.addSample(engine.shot_.fillPct + 0.045 * 16.0, lastMs + 16.0);
    engine.shot_.fillPct += 0.045 * 16.0;
    const AutomationEngine::AutonomousTipDecision after =
        engine.canonicalAutonomousTipDecision(lastMs + 16.0);

    QVERIFY2(after.source == QStringLiteral("phase"),
             qPrintable(QStringLiteral("one wobble frame must not unseat the member: got %1")
                            .arg(after.source)));
    QVERIFY2(std::abs(after.tipAbsMs - before.tipAbsMs) < 1e-6,
             qPrintable(QStringLiteral("an anchor-dated tip must not move on a slope wobble: "
                                       "%1 -> %2").arg(before.tipAbsMs).arg(after.tipAbsMs)));

    // ...while the member it replaced DID move, which is what makes this a real difference in
    // behaviour rather than a fixture that changed nothing. Asserted on the raw fit, which is
    // populated whether or not the fit stayed authoritative: at 60% fill a 75% collapse turns the
    // quadratic concave-down, and the engine correctly withdraws the sampler's authority
    // altogether. That is the sharpest possible version of the contrast -- the extrapolator
    // reacted so hard it stopped being usable, and the lookup did not move at all.
    QVERIFY2(after.samplerFit.slopePctPerMs < before.samplerFit.slopePctPerMs * 0.75,
             qPrintable(QStringLiteral("fixture did not actually decelerate the fit: %1 -> %2")
                            .arg(before.samplerFit.slopePctPerMs)
                            .arg(after.samplerFit.slopePctPerMs)));
    QVERIFY2(std::abs(after.samplerFit.crossingMs - before.samplerFit.crossingMs) > 1.0,
             qPrintable(QStringLiteral("the extrapolated crossing must have moved: %1 -> %2")
                            .arg(before.samplerFit.crossingMs)
                            .arg(after.samplerFit.crossingMs)));
}

void AutomationEngineTests::tipPhaseIsMeanNeutralAtTheFiringDecision()
{
    // THE NO-RE-TUNE CONTRACT, pinned as arithmetic.
    //
    // The command is submitted at fireAt = tip - lead. Measured on the 61 real landings, today's
    // release lands 87.0 ms after the anchor. The shipped constant must reproduce that within
    // the noise of the estimator itself (rMAD 9.6 ms), or this change is a silent re-aim wearing
    // a variance reduction's clothes.
    //
    //   fireAt - anchor = tipPhaseConstantMs - lead = 387.0 - 300.0 = 87.0 ms
    //   measured today  = 87.0 ms  (median over the same 61 landings)
    //   difference      = 0.0 ms -- EXACT, which is what "no re-tune" is supposed to mean.
    //
    // 387, not the design's 379. 379 came from the audit's arithmetic (318 physical + its
    // +61.0 sampler bias) and lands at anchor+79.0, i.e. 8 ms EARLY. It passed only because
    // the tolerance below is +-10. Two reasons that is the wrong number to ship: (a) an 8 ms
    // aim shift is precisely the silent re-aim this test exists to catch, and (b) the user is
    // separately observing the game's own banner read EARLY, with median peak_fill 98.17
    // against a 100 target -- so a further 8 ms early compounds the one error we can actually
    // see on screen. The tolerance stays at +-10 as a band, but the shipped value now sits at
    // the centre of it rather than at its edge.
    // RE-AIMED 2026-08-05: 87.0 -> 99.0, constant 387 -> 399. This test exists to catch a SILENT
    // re-aim; this one is deliberate, measured, and recorded here rather than slipped past.
    //
    // Two independent signals agreed on both direction and size. (1) Replaying the batch's own
    // detector-labelled rises put the animation constant at 402.0 ms at the 30% anchor (n=36,
    // rMAD 11.0) against an effective 385-386 in the engine -- and the measurement had climbed
    // 388 -> 391 -> 397 -> 402 across the session as the structure-proof and ladder fixes made
    // more shots DETECTABLE, so the old value had been fitted to a biased subset that excluded
    // the longer-animation shots. (2) The user independently reported the release landing JUST
    // SHORT of the tip, consistently, at every distance -- exactly what a 16 ms short constant
    // produces.
    //
    // +12 rather than the full +16 because the cost is asymmetric: green_end is always 100.0, so
    // the window sits BELOW the tip and an early release still lands inside it, while a late one
    // falls outside and the banner caps. 399 is ~1.3 standard errors below the measured median.
    constexpr double kObservedAnchorToReleaseMs = 93.0;
    constexpr double kFlatUserLeadMs = 300.0;

    AppConfigData config;
    AutomationEngine engine;
    engine.applyConfig(config, LearningData{});
    const double shippedConstantMs = engine.config().tipPhaseConstantMs;
    QCOMPARE(shippedConstantMs, 393.0);
    // ...and it must be the PHYSICAL measurement plus the aim offset, not a free parameter.
    QCOMPARE(engine.config().tipPhaseSeedPhysicalMs, 319.0);

    const double aimAtAnchorPlusMs = shippedConstantMs - kFlatUserLeadMs;
    QVERIFY2(std::abs(aimAtAnchorPlusMs - kObservedAnchorToReleaseMs) <= 10.0,
             qPrintable(QStringLiteral("shipping this predictor must not re-aim the bot: it "
                                       "fires at anchor+%1 where today it fires at anchor+%2 "
                                       "(delta %3 ms)")
                            .arg(aimAtAnchorPlusMs).arg(kObservedAnchorToReleaseMs)
                            .arg(aimAtAnchorPlusMs - kObservedAnchorToReleaseMs)));

    // And the sigma is the measured one, not an optimistic guess: rMAD 9.6, sd 15.0.
    QCOMPARE(engine.config().tipPhaseSigmaMs, 13.0);
    QVERIFY(engine.config().tipPhaseSigmaMs >= 9.6);
    QVERIFY(engine.config().tipPhaseSigmaMs <= 15.0);
}

void AutomationEngineTests::tipPhaseTelemetryIsAppendOnlyAndReproducesItsWeight()
{
    // The TIP RESERVATION line is parsed by key=value readers, so the new member may only be
    // APPENDED -- every pre-existing key keeps its name, its value and its position.
    const ReservationRun run = driveAutonomousRise(
        /*leadMs=*/196.0, /*leadSdMs=*/2.0, /*velocityPctPerMs=*/0.18, /*maxFrames=*/60);
    QVERIFY2(run.everHeld, "harness never reached the owned autonomous holding path");
    QVERIFY(!run.createdLine.isEmpty());

    // Every field that existed before this change still parses, and still precedes the new ones.
    const QStringList preExisting{
        QStringLiteral("tip_eta_ms"), QStringLiteral("command_eta_ms"),
        QStringLiteral("lead_ms"), QStringLiteral("predictor_sigma_ms"),
        QStringLiteral("fill_pct"), QStringLiteral("horizon_debias_ms"),
        QStringLiteral("reg_tip_eta_ms"), QStringLiteral("reg_sigma_ms"),
        QStringLiteral("smp_tip_eta_ms"), QStringLiteral("smp_sigma_ms"),
        QStringLiteral("reg_weight")};
    const int firstNewAt = run.createdLine.indexOf(QStringLiteral("phase_tip_eta_ms="));
    QVERIFY2(firstNewAt > 0, qPrintable(QStringLiteral("no phase member in: %1")
                                            .arg(run.createdLine)));
    for (const QString& key : preExisting) {
        bool ok = false;
        diagField(run.createdLine, key, &ok);
        QVERIFY2(ok, qPrintable(QStringLiteral("pre-existing key %1 stopped parsing: %2")
                                    .arg(key, run.createdLine)));
        QVERIFY2(run.createdLine.indexOf(key + QLatin1Char('=')) < firstNewAt,
                 qPrintable(QStringLiteral("key %1 moved AFTER the appended block").arg(key)));
    }
    for (const QString& key : {QStringLiteral("phase_sigma_ms"), QStringLiteral("phase_weight"),
                               QStringLiteral("phase_const_ms"), QStringLiteral("phase_primary")}) {
        bool ok = false;
        diagField(run.createdLine, key, &ok);
        QVERIFY2(ok, qPrintable(QStringLiteral("appended key %1 missing: %2")
                                    .arg(key, run.createdLine)));
    }

    // phase_weight must reproduce BY HAND from phase_sigma_ms and the sigma of the member the
    // pre-existing chain selected BEFORE the phase override -- the same identity reg_weight is
    // held to. The checkable lines are the ones where registration was absent (reg_tip_eta_ms
    // = -1), because then that incumbent is unambiguously the sampler and its own sigma is on
    // the line. A fused decision's sigma is a combination and is deliberately not a field.
    bool found = false;
    bool sawPhasePrimary = false;
    for (const QString& line : run.diagnostics) {
        if (!line.startsWith(QStringLiteral("TIP RESERVATION:"))) {
            continue;
        }
        if (diagField(line, QStringLiteral("phase_primary")) > 0.5) {
            sawPhasePrimary = true;
        }
        bool okP = false, okS = false, okW = false, okR = false;
        const double phaseSigma = diagField(line, QStringLiteral("phase_sigma_ms"), &okP);
        const double smpSigma = diagField(line, QStringLiteral("smp_sigma_ms"), &okS);
        const double weight = diagField(line, QStringLiteral("phase_weight"), &okW);
        const double regTip = diagField(line, QStringLiteral("reg_tip_eta_ms"), &okR);
        if (!okP || !okS || !okW || !okR || regTip >= 0.0
            || phaseSigma <= 0.0 || smpSigma <= 0.0 || weight < 0.0) {
            continue;
        }
        const double pp = 1.0 / (phaseSigma * phaseSigma);
        const double ps = 1.0 / (smpSigma * smpSigma);
        QVERIFY2(std::abs(weight - pp / (pp + ps)) < 5e-4,
                 qPrintable(QStringLiteral("phase_weight does not reproduce from the sigmas on "
                                           "its own line: %1").arg(line)));
        found = true;
        break;
    }
    QVERIFY2(found, "no reservation line published a checkable phase weight against the sampler");
    // ...and this harness is a genuine rise, so the member must actually have carried a decision
    // on it -- otherwise the whole block above is vacuous.
    QVERIFY2(sawPhasePrimary, "the phase member never won a decision on a clean owned rise");
}

void AutomationEngineTests::tipPhaseConstantLearnsPhysicalTermWithoutEatingTheAimOffset()
{
    // THE BUG THIS SEPARATION EXISTS TO PREVENT.
    //
    // The shipped constant is 387 = 318 physical + 69 aim-preservation offset. The learner's
    // observations are of the PHYSICAL quantity and converge on ~318-320. A learner that wrote
    // its median straight into the constant would therefore walk the aim 69 ms EARLIER across
    // its first full window -- a large silent re-aim that would look exactly like a calibration
    // in the log. The offset must survive learning untouched.
    //
    // NOTE ON 69: this is NOT "the sampler bias". That was measured twice and disagreed with
    // itself -- +61.0 by the audit (release-marker segmentation, n=54) and +92.6 by the
    // independent re-extraction (meter-rise segmentation, n=61). The offset is defined instead
    // by what it is FOR: the amount that leaves the firing decision exactly where it lands
    // today (anchor+87.0 at a flat 300 ms lead), which is 387 - 318 = 69. Defining it by the
    // observable rather than by either bias estimate is why this survives the two measurements
    // disagreeing.
    AppConfigData config;
    AutomationEngine engine;
    engine.applyConfig(config, LearningData{});
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

    QCOMPARE(engine.learnedPhasePhysicalMsForTests(), -1.0);
    QCOMPARE(engine.effectiveTipPhaseConstantMsForTests(), 393.0);   // seed carries the session

    // [ORION_PHASE_COLD_START] Nine landings now publish a SHRUNK estimate rather than nothing.
    // The old contract ("wait for the full window; the seed is mean-neutral so waiting costs
    // nothing") holds only while the seed matches the animation being played -- and on a
    // different jumpshot it does not, which is the rough cold start the owner hit on another
    // build. See phaseLearnerShrinksTowardTheObservationBeforeTheWindowFills.
    //
    // These particular samples are centred ON the seed (their median is 318.0 = the seed), so the
    // shrinkage moves nowhere and this test's own subject -- that the learner never eats the aim
    // offset -- is unaffected either way. That is deliberate: it keeps this test about the aim
    // offset and not about cold-start convergence.
    // Re-parameterised on the CONFIGURED window (raised 10 -> 20 on 2026-08-05): this test is
    // about the learner never eating the aim offset, not about the window size, so it must not
    // break every time the window is tuned. Feeds `window` samples whose median is the seed.
    const int learnWindow = engine.config().tipPhaseLearnWindow;
    QVector<double> observed;
    for (int i = 0; i < learnWindow; ++i) {
        // symmetric about 318 so the median is exactly the seed regardless of window size
        const double delta = static_cast<double>((i % 2 == 0) ? (i / 2 + 1) : -(i / 2 + 1));
        observed.append(engine.config().tipPhaseSeedPhysicalMs + delta);
    }
    for (int i = 0; i < learnWindow - 1; ++i) {
        engine.meterCapPhaseAnchorMs_ = 1'000.0;
        engine.meterCapPhaseStopMs_ = 1'000.0 + observed.at(i);
        engine.meterCapPhaseStopConfirmed_ = true;
        engine.recordPhaseConstantSample();
    }
    // One sample short of a full window the estimate is still SHRUNK (n/window of the way), and
    // with an odd sample count the partial median sits half a step off the seed -- so assert a
    // tolerance here, not an exact value. What this test is actually about is the line below it:
    // the aim offset must survive whatever the learner does to the physical term.
    QVERIFY2(std::abs(engine.learnedPhasePhysicalMsForTests() - 319.0) <= 1.0,
             "a partial window must stay near the seed when the samples are centred on it");
    QVERIFY2(std::abs(engine.effectiveTipPhaseConstantMsForTests() - 393.0) <= 1.0,
             "the aim offset must be preserved through the partial-window shrink");

    engine.meterCapPhaseAnchorMs_ = 1'000.0;
    engine.meterCapPhaseStopMs_ = 1'000.0 + observed.at(learnWindow - 1);
    engine.meterCapPhaseStopConfirmed_ = true;
    engine.recordPhaseConstantSample();

    // The samples are symmetric about the seed, so the median IS 318.0 for any window size.
    QCOMPARE(engine.learnedPhasePhysicalMsForTests(), 319.0);
    // THE ASSERTION THAT MATTERS. The effective constant is the learned PHYSICAL term plus the
    // untouched 61 ms aim offset -- NOT the raw median.
    // REVERT-TRACE: make effectiveTipPhaseConstantMs() return learnedPhasePhysicalMs_ directly
    // (the naive learner) and this fails with 319.0, a 69 ms silent re-aim.
    QCOMPARE(engine.effectiveTipPhaseConstantMsForTests(), 393.0);   // 319 physical + the 74 ms aim offset (393 - 319)
    QVERIFY2(engine.effectiveTipPhaseConstantMsForTests() > 370.0,
             "the learner ate the aim-preservation offset -- the bot now fires ~69 ms early");

    // The published line must expose both halves so the separation is auditable live.
    //
    // Takes the LAST line, not the first. Since [ORION_PHASE_COLD_START] the learner publishes
    // from tipPhaseLearnMinSamples onward (shrinking toward the observation) rather than only
    // once at a full window, so the earlier lines legitimately carry partial medians. The
    // full-window publish is the one this test is about.
    QString finalLine;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.startsWith(QStringLiteral("Tip phase measurement:"))) {
            finalLine = line;
        }
    }
    QVERIFY2(!finalLine.isEmpty(), "a full learning window published no measurement line");
    QCOMPARE(diagField(finalLine, QStringLiteral("physical_median_ms")), 319.0);
    // 74, not 69: the 2026-08-05 re-aim moved the constant 387 -> 392 while the seed physical
    // stayed 318, so the aim offset is 392 - 318 = 74. That the published line tracks it is the
    // point -- the separation between "learned physical" and "aim" must stay auditable live, and
    // an aim change must be visible in the log rather than hidden inside a constant.
    QCOMPARE(diagField(finalLine, QStringLiteral("aim_offset_ms")), 74.0);
    QCOMPARE(diagField(finalLine, QStringLiteral("effective_const_ms")), 393.0);
    QCOMPARE(diagField(finalLine, QStringLiteral("n")), static_cast<double>(learnWindow));
}

void AutomationEngineTests::tipPhaseLearnerDropsOutOfBandLandings()
{
    // Every gate DROPS rather than repairs, for the same reason recordLandingLeadSample does: a
    // repaired sample is a guess wearing a measurement's clothes, and this one feeds the aim.
    AppConfigData config;
    AutomationEngine engine;
    engine.applyConfig(config, LearningData{});

    // An unconfirmed stop is no evidence at all: the rise never demonstrably ended.
    engine.meterCapPhaseAnchorMs_ = 1'000.0;
    engine.meterCapPhaseStopMs_ = 1'320.0;
    engine.meterCapPhaseStopConfirmed_ = false;
    engine.recordPhaseConstantSample();
    QCOMPARE(engine.phaseConstantSamplesMs_.size(), 0);

    // An undated anchor likewise.
    engine.meterCapPhaseAnchorMs_ = -1.0;
    engine.meterCapPhaseStopMs_ = 1'320.0;
    engine.meterCapPhaseStopConfirmed_ = true;
    engine.recordPhaseConstantSample();
    QCOMPARE(engine.phaseConstantSamplesMs_.size(), 0);

    // Out of the physically observed band (the 61 landings spanned 281-383 ms) -> dropped, and
    // NOT clamped to the edge, which would quietly inject a fabricated observation.
    // REVERT-TRACE: replace the band return with a std::clamp and the size becomes 2.
    for (const double badMs : {90.0, 900.0}) {
        engine.meterCapPhaseAnchorMs_ = 1'000.0;
        engine.meterCapPhaseStopMs_ = 1'000.0 + badMs;
        engine.meterCapPhaseStopConfirmed_ = true;
        engine.recordPhaseConstantSample();
    }
    QCOMPARE(engine.phaseConstantSamplesMs_.size(), 0);

    // An in-band landing still lands.
    engine.meterCapPhaseAnchorMs_ = 1'000.0;
    engine.meterCapPhaseStopMs_ = 1'320.0;
    engine.meterCapPhaseStopConfirmed_ = true;
    engine.recordPhaseConstantSample();
    QCOMPARE(engine.phaseConstantSamplesMs_.size(), 1);
    QCOMPARE(engine.phaseConstantSamplesMs_.at(0), 320.0);
}

void AutomationEngineTests::doubleCountedPredictorBiasCorrectionIsNamedNotSilentlyResolved()
{
    // autonomousLeadBiasMs and samplerHorizonDebiasEnabled are two corrections for ONE physical
    // error -- the sampler's late extrapolation. The first cancels it by firing that much
    // earlier, the second by moving the crossing itself. Enabling both subtracts it twice and
    // the bot fires a full bias EARLY, which is the exact regression the de-bias was written to
    // prevent. That must be SAID, not silently resolved: both knobs are legitimate, which one is
    // right depends on whether the correction should travel between installs, and an engine that
    // quietly disabled one would make a live sweep of the other read as a null result for
    // reasons nothing logged.
    const QByteArray savedBias = qgetenv("ORION_LEAD_BIAS_MS");
    const bool hadBias = qEnvironmentVariableIsSet("ORION_LEAD_BIAS_MS");
    auto restore = qScopeGuard([&] {
        if (hadBias) {
            qputenv("ORION_LEAD_BIAS_MS", savedBias);
        } else {
            qunsetenv("ORION_LEAD_BIAS_MS");
        }
    });

    AppConfigData config;
    auto warningsFrom = [&](bool leadBias, bool horizonDebias) {
        if (leadBias) {
            qputenv("ORION_LEAD_BIAS_MS", "62");
        } else {
            qunsetenv("ORION_LEAD_BIAS_MS");
        }
        AutomationEngine engine;
        // Set BEFORE applyConfig: the guard lives inside it, and applyConfig assigns fields
        // individually rather than resetting config_, so this survives.
        engine.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0, horizonDebias);
        QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);
        engine.applyConfig(config, LearningData{});
        QStringList hits;
        for (const QList<QVariant>& row : diagSpy) {
            const QString line = row.at(0).toString();
            if (line.contains(QStringLiteral("double-counted predictor bias"))) {
                hits << line;
            }
        }
        return hits;
    };

    // Both on -> exactly one warning, and it must NAME both knobs so the reader can act.
    // REVERT-TRACE: delete the guard block in applyConfig and this QCOMPARE fails with 0.
    const QStringList both = warningsFrom(true, true);
    QCOMPARE(both.size(), 1);
    QVERIFY2(both.at(0).contains(QStringLiteral("autonomousLeadBiasMs=62")),
             qPrintable(both.at(0)));
    QVERIFY2(both.at(0).contains(QStringLiteral("samplerHorizonDebiasEnabled=1")),
             qPrintable(both.at(0)));

    // Either one alone is a legitimate configuration and must stay silent.
    QCOMPARE(warningsFrom(true, false).size(), 0);
    QCOMPARE(warningsFrom(false, true).size(), 0);
    QCOMPARE(warningsFrom(false, false).size(), 0);

    // ...and the guard must not have RESOLVED anything behind the operator's back.
    qputenv("ORION_LEAD_BIAS_MS", "62");
    AutomationEngine engine;
    engine.setTipPhaseConfigForTests(true, 30.0, 379.0, 318.0, 13.0, /*horizonDebias=*/true);
    engine.applyConfig(config, LearningData{});
    QCOMPARE(engine.config().autonomousLeadBiasMs, 62.0);
    QCOMPARE(engine.config().samplerHorizonDebiasEnabled, true);
}

void AutomationEngineTests::subtickArmEmitsReservationPromotionExactlyOnce()
{
    // [ORION_SILENT_FAIL S1] The subtick mirror is the DOMINANT arm path live (it runs on every
    // sidecar payload and reaches the schedule first), yet it never marked the reservation
    // promoted and never emitted the reservation_promoted line -- 35 of 68 released shots of the
    // 2026-08-08 session were invisible to the (physical_epoch, shot_attempt) promotion join.
    // Same trajectory as driveAutonomousRise, but with reevaluateScheduleOnFreshSample() called
    // between updateDetection and the 4 ms tick exactly as OrionAppController does, so the
    // SUBTICK site is the one that arms.
    //
    // REVERT-TRACE. Delete the subtick promotion block: the subtick arms without promoting and
    // the tick never re-arms (a token exists), so NO promotion line is emitted at all and the
    // QCOMPAREs below fail on 0. Hardcode any field and the identity checks against the run's
    // own epoch/token fail.
    constexpr quint64 kEpoch = 9'505;
    constexpr double kFrameMs = 1000.0 / 60.0;
    constexpr double kLeadMs = 196.0;

    AutomationEngine engine;
    AppConfigData config;
    config.remotePlayInputSource = QStringLiteral("square");
    config.minimumHoldMs = 0.0;
    config.autonomousVision = true;
    config.measuredLeadEnabled = true;
    engine.applyConfig(config, LearningData{});

    ControllerState square;
    square.buttons |= XINPUT_GAMEPAD_X;

    QSignalSpy markerSpy(&engine, &AutomationEngine::releaseMarker);
    QSignalSpy diagSpy(&engine, &AutomationEngine::engineDiagnostic);

    int frame = 1;
    ControllerState output = promoteStrictAutonomousSquare(
        engine, square, frame, kEpoch, kLeadMs, 2.0, 6, 6.0);

    quint64 armedScheduleToken = 0;
    double fill = 13.0;
    for (int i = 0; i < 60 && markerSpy.count() == 0; ++i) {
        engine.advanceTestClock(kFrameMs);
        fill = std::min(99.5, fill + 0.18 * kFrameMs);
        DetectionResult sample = strictLiveMeterSample(fill, frame++, kEpoch, kLeadMs, 2.0, 6);
        sample.frameAgeMs = 6.0;
        engine.updateDetection(sample);
        // The production order: the sidecar payload re-evaluates the schedule BEFORE the next
        // 4 ms tick can run. This is what makes the subtick site the arming site.
        engine.reevaluateScheduleOnFreshSample();
        if (engine.scheduledFireDeadlineMs() >= 0.0 && armedScheduleToken == 0) {
            armedScheduleToken = engine.scheduledFireToken();
        }
        output = engine.process(square);
        if (engine.scheduledFireDeadlineMs() >= 0.0) {
            const double deadline = engine.scheduledFireDeadlineMs();
            const quint64 token = engine.scheduledFireToken();
            const double untilMs = deadline - engine.engineNowMs();
            if (untilMs > 0.0) {
                engine.advanceTestClock(untilMs);
            }
            engine.confirmScheduledFire(token, deadline);
            output = engine.process(square);
        }
    }
    Q_UNUSED(output);
    QCOMPARE(markerSpy.count(), 1);
    QVERIFY2(armedScheduleToken > 0, "the subtick re-evaluation never armed a token");

    QStringList promoted;
    for (const QList<QVariant>& row : diagSpy) {
        const QString line = row.at(0).toString();
        if (line.contains(QStringLiteral("disposition=reservation_promoted"))) {
            promoted << line;
        }
    }
    // Exactly once per shot: the subtick emits it, and the tick's own guard (!promoted) can
    // never emit a second one for the same reservation.
    QCOMPARE(promoted.size(), 1);
    const QString line = promoted.first();
    QVERIFY2(line.contains(QStringLiteral("arm_site=subtick")),
             qPrintable(QStringLiteral("promotion must come from the subtick site: %1").arg(line)));
    // source= stays the PREDICTOR: it is what armed_source/promotion joins attribute shots by.
    // A literal "subtick" here would corrupt the per-predictor batch split this fix exists to
    // unbias.
    const QString source = diagToken(line, QStringLiteral("source"));
    QVERIFY2(!source.isEmpty() && source != QStringLiteral("subtick"), qPrintable(line));
    bool ok = false;
    const double epoch = diagField(line, QStringLiteral("physical_epoch"), &ok);
    QVERIFY(ok);
    QCOMPARE(static_cast<quint64>(epoch), kEpoch);
    const double scheduleToken = diagField(line, QStringLiteral("schedule_token"), &ok);
    QVERIFY(ok);
    QCOMPARE(static_cast<quint64>(scheduleToken), armedScheduleToken);
    const double commandEtaMs = diagField(line, QStringLiteral("command_eta_ms"), &ok);
    QVERIFY(ok);
    QVERIFY2(commandEtaMs > 0.0,
             qPrintable(QStringLiteral("promoted a deadline already in the past: %1").arg(line)));
}

namespace {

QStringList tipTokenKillLines(const QSignalSpy& diag)
{
    QStringList out;
    for (const auto& call : diag) {
        const QString line = call.at(0).toString();
        if (line.startsWith(QStringLiteral("TIP TOKEN KILL:"))) {
            out.append(line);
        }
    }
    return out;
}

}  // namespace

void AutomationEngineTests::directScheduleInvalidationEmitsAttributedTokenKill()
{
    // [ORION_SILENT_FAIL S3] The vision wrapper attributed its kills; the base primitive killed
    // armed unconfirmed tokens with NO record, and four call sites reach it directly. Fabricates
    // the minimal armed unconfirmed token (the calibrationPromotionFencesCopiedSchedule pattern)
    // so each block pins one caller's site string end-to-end through its public entry point.
    // requiresGenuineFrame stays FALSE so no earlier vision fence can claim the token first.
    //
    // REVERT-TRACE. Remove the emit from the primitive: every block fails on kills.size()==0.
    // Hardcode the site: blocks (a)-(c) fail against each other (three different strings).
    // Remove the wrapper's nullptr suppression: block (e) fails with 2 lines instead of 1.
    auto armFabricatedToken = [](AutomationEngine& engine, quint64 token) {
        engine.schedFireDeadlineMs_ = engine.engineNowMs() + 12.0;
        engine.schedFireToken_ = token;
        engine.schedFireConfirmedToken_ = 0;
        engine.schedFireActualMs_ = -1.0;
        engine.shot_.physicalShotEpoch = 4'242;
        engine.shot_.armToken = 7;
        engine.schedFirePhysicalShotEpoch_ = engine.shot_.physicalShotEpoch;
        engine.schedFireShotAttempt_ = engine.shot_.armToken;
    };

    {   // (a) sidecar process generation boundary -> site=sidecar_generation
        AutomationEngine engine;
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
        armFabricatedToken(engine, 771);
        engine.beginSidecarProcessGeneration();
        const QStringList kills = tipTokenKillLines(diag);
        QCOMPARE(kills.size(), 1);
        QVERIFY2(kills.first().contains(QStringLiteral("site=sidecar_generation")),
                 qPrintable(kills.first()));
        QCOMPARE(diagField(kills.first(), "token"), QStringLiteral("771"));
        QCOMPARE(diagField(kills.first(), "physical_epoch"), QStringLiteral("4242"));
        QCOMPARE(diagField(kills.first(), "shot_attempt"), QStringLiteral("7"));
        QVERIFY2(engine.scheduledFireDeadlineMs() < 0.0,
                 "the fence must still revoke the token exactly as before");
    }

    {   // (b) route re-attestation -> site=route_reattestation
        AutomationEngine engine;
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
        armFabricatedToken(engine, 772);
        engine.setControllerDeliveryRouteAttestation(401, LatencyControllerRoute::Pipe);
        const QStringList kills = tipTokenKillLines(diag);
        QCOMPARE(kills.size(), 1);
        QVERIFY2(kills.first().contains(QStringLiteral("site=route_reattestation")),
                 qPrintable(kills.first()));
        QCOMPARE(diagField(kills.first(), "token"), QStringLiteral("772"));
    }

    {   // (c) external cancel -> site=cancel_scheduled_fire
        AutomationEngine engine;
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
        armFabricatedToken(engine, 773);
        engine.cancelScheduledFire(773);
        const QStringList kills = tipTokenKillLines(diag);
        QCOMPARE(kills.size(), 1);
        QVERIFY2(kills.first().contains(QStringLiteral("site=cancel_scheduled_fire")),
                 qPrintable(kills.first()));
    }

    {   // (d) a caller that names no site still reports, as "unattributed" -- silence is gone
        // even for paths nobody thought to name. (authority_mode_change at applyConfig is
        // compile-time dead without ORION_ENABLE_DEV_NO_METER, so its string is wired but not
        // runtime-reachable in this build; it would flow through exactly this code.)
        AutomationEngine engine;
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
        armFabricatedToken(engine, 774);
        engine.invalidateUnconfirmedSchedule();
        const QStringList kills = tipTokenKillLines(diag);
        QCOMPARE(kills.size(), 1);
        QVERIFY2(kills.first().contains(QStringLiteral("site=unattributed")),
                 qPrintable(kills.first()));
    }

    {   // (e) the vision wrapper keeps its own attributed line and must NOT double-report
        AutomationEngine engine;
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
        armFabricatedToken(engine, 775);
        engine.schedFireRequiresGenuineFrame_ = true;
        engine.invalidateUnconfirmedVisionSchedule("test_wrapper_site");
        const QStringList kills = tipTokenKillLines(diag);
        QCOMPARE(kills.size(), 1);
        QVERIFY2(kills.first().contains(QStringLiteral("site=test_wrapper_site")),
                 qPrintable(kills.first()));
    }

    {   // (f) a CONFIRMED token is a submitted press, not a kill -- it must stay silent
        AutomationEngine engine;
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
        armFabricatedToken(engine, 776);
        engine.schedFireConfirmedToken_ = 776;
        engine.schedFireActualMs_ = engine.engineNowMs();
        engine.beginSidecarProcessGeneration();
        QVERIFY2(tipTokenKillLines(diag).isEmpty(),
                 "a confirmed submit is not a token kill and must not be reported as one");
    }

    {   // (g) calibration phase change -> site=calibration_phase, through the real manual-probe
        // tick path (the fence right before the cold L1 target is scheduled).
        AutomationEngine engine;
        AppConfigData config;
        config.remotePlayInputSource = QStringLiteral("square");
        config.minimumHoldMs = 0.0;
        config.autonomousVision = true;
        config.measuredLeadEnabled = true;
        engine.applyConfig(config, LearningData{});
        engine.setLatencyCalibrationMode(true);

        ControllerState square;
        square.buttons |= XINPUT_GAMEPAD_X;
        constexpr quint64 shotEpoch = 14'102;
        engine.setPhysicalShotEpoch(shotEpoch);
        engine.process(square);
        int frame = 1;
        // Climb with green geometry WITHHELD, exactly as the ownership/fence tests do: with a
        // green window visible from the start the cold L1 target schedules and fires during
        // the setup itself, and the shot is gone before the fence under test can run.
        for (const double fill : {10.0, 14.0, 18.0, 22.0}) {
            engine.advanceTestClock(20.0);
            engine.updateDetection(calibrationOwnershipOnlySample(fill, frame++, shotEpoch));
            engine.process(square);
        }
        QCOMPARE(engine.context().state, HoldState::Holding);
        QVERIFY(engine.context().latencyCalibrationProbe);

        // A stale copied token from before the phase change. Not a vision token, so only the
        // base primitive's callers can retire it; deadline far enough out that the due-consume
        // path cannot claim it while green geometry confirms.
        engine.schedFireDeadlineMs_ = engine.engineNowMs() + 400.0;
        engine.schedFireToken_ = 991;
        engine.schedFireConfirmedToken_ = 0;
        engine.schedFireActualMs_ = -1.0;
        engine.schedFirePhysicalShotEpoch_ = engine.context().physicalShotEpoch;
        engine.schedFireShotAttempt_ = engine.context().armToken;

        // Now let the meter's green window arrive. The first tick on which the calibration
        // branch finds trajectory + green geometry ready walks into the phase-change fence
        // with the stale token still armed.
        QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
        QStringList kills;
        for (int i = 0; i < 6 && kills.isEmpty(); ++i) {
            engine.advanceTestClock(20.0);
            engine.updateDetection(calibrationOwnershipSample(
                26.0 + 4.0 * i, frame++, shotEpoch));
            engine.process(square);
            kills = tipTokenKillLines(diag);
        }
        QVERIFY2(!kills.isEmpty(), "the calibration-phase fence must report its kill");
        QVERIFY2(kills.first().contains(QStringLiteral("site=calibration_phase")),
                 qPrintable(kills.join(QStringLiteral(" | "))));
        QCOMPARE(diagField(kills.first(), "token"), QStringLiteral("991"));
    }
}

void AutomationEngineTests::staleConfirmDropIsReportedNotSilent()
{
    // [ORION_SILENT_FAIL S4] A confirm reports a PHYSICALLY SUBMITTED press. When it arrives
    // after the token identity moved the engine correctly refuses it -- but used to refuse it
    // silently, so the real first press had no record and grading attached to the wrong edge
    // (the frozen-lease shape of 2026-08-04). The refusal must now be countable.
    //
    // REVERT-TRACE. Remove the emit: drops.size()==0 fails. Hardcode token/sched_token: the
    // QCOMPAREs against this run's own live token values fail (the token is not predictable
    // across runs of the arming fixture).
    AutomationEngine engine;
    ControllerState square;
    int frame = 1;
    armLiveAutonomousToken(engine, square, frame, 9'606);
    QVERIFY2(engine.scheduledFireDeadlineMs() >= 0.0, "setup must arm a live vision token");
    const quint64 armedToken = engine.scheduledFireToken();

    QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);
    auto dropLines = [&diag]() {
        QStringList out;
        for (const auto& call : diag) {
            const QString line = call.at(0).toString();
            if (line.startsWith(QStringLiteral("PRECISE FIRE CONFIRM DROPPED:"))) {
                out.append(line);
            }
        }
        return out;
    };

    // A confirm whose token identity has moved: dropped, but REPORTED.
    engine.confirmScheduledFire(armedToken + 40, engine.engineNowMs());
    QStringList drops = dropLines();
    QCOMPARE(drops.size(), 1);
    QVERIFY2(drops.first().contains(QStringLiteral("reason=identity_mismatch")),
             qPrintable(drops.first()));
    QCOMPARE(diagField(drops.first(), "token"), QString::number(armedToken + 40));
    QCOMPARE(diagField(drops.first(), "sched_token"), QString::number(armedToken));
    // The drop must remain a drop: the armed schedule is still unconfirmed.
    QVERIFY2(engine.schedFireConfirmedToken_ != armedToken + 40,
             "a stale confirm must never complete the armed schedule");
    QVERIFY(engine.schedFireActualMs_ < 0.0);

    // The matching confirm still lands, and it is not a drop.
    engine.confirmScheduledFire(armedToken, engine.engineNowMs());
    QCOMPARE(dropLines().size(), 1);
    QCOMPARE(engine.schedFireConfirmedToken_, armedToken);
}

void AutomationEngineTests::lowPeakSettledLandingStillEmitsGradedZeroEvidence()
{
    // [ORION_SILENT_FAIL S5] A capture that SETTLED (past the no_settled_run gate, which logs)
    // and then died on the low-peak/non-finite-median gate emitted nothing at all -- yet a
    // near-empty-bar misfire is exactly the shot a hand counter needs explained. Same
    // fabrication as courtPositionIsStampedOnAbortAndLandingLines: driven through the
    // meter-capture state directly so the assertion is about the instrumentation.
    //
    // REVERT-TRACE. Remove the emit: landings is empty. Hardcode peak/settled_n/median_fill:
    // the exact-value QCOMPAREs against this fixture's numbers fail.
    AutomationEngine engine;
    QSignalSpy diag(&engine, &AutomationEngine::engineDiagnostic);

    engine.meterCapActive_ = true;
    engine.meterCapSeq_ = 5'152;
    engine.meterCapShotType_ = QStringLiteral("Left Fade");   // space-bearing: pins shot= last
    engine.meterCapFillAtReleasePct_ = 12.6;
    engine.meterCapPeakFillPct_ = 18.4;                       // below meterMinPeakFillPct (25)
    engine.meterCapNormXAtRel_ = 0.25;
    engine.meterCapNormYAtRel_ = 0.60;
    engine.meterCapSamples_.clear();
    for (int i = 0; i < 4; ++i) {
        AutomationEngine::MeterCalSample s;
        s.accepted = true;
        s.confidence = 0.9;
        s.fillPct = 15.0;             // stable near-empty fill -> a SETTLED run
        s.greenStartPct = 90.0;
        s.greenEndPct = 98.0;
        s.greenCenterPct = 94.0;
        s.tMs = 1'000.0 + 20.0 * i;
        s.bx = 960.0;                 // static bbox -> settled
        s.by = 360.0;
        s.nx = 0.25;
        s.ny = 0.60;
        engine.meterCapSamples_.append(s);
    }
    QVERIFY2(engine.meterCapPeakFillPct_ < engine.config().meterMinPeakFillPct,
             "fixture must sit below the peak gate or this test proves nothing");

    engine.evaluatePostReleaseMeter();

    const QStringList landings = releaseLandingLines(diag);
    QCOMPARE(landings.size(), 1);
    const QString landing = landings.first();
    QVERIFY2(landing.contains(QStringLiteral("graded=0")), qPrintable(landing));
    QCOMPARE(diagField(landing, "reason"), QStringLiteral("low_peak_or_nan"));
    QCOMPARE(diagField(landing, "seq"), QStringLiteral("5152"));
    QCOMPARE(diagField(landing, "peak_fill"), QStringLiteral("18.40"));
    QCOMPARE(diagField(landing, "fill_at_rel"), QStringLiteral("12.60"));
    QCOMPARE(diagField(landing, "settled_n"), QStringLiteral("4"));
    QCOMPARE(diagField(landing, "samples_n"), QStringLiteral("4"));
    QCOMPARE(diagField(landing, "median_fill"), QStringLiteral("15.00"));
    QCOMPARE(diagField(landing, "green_center"), QStringLiteral("94.00"));
    // shot= stays LAST: its value legitimately contains a space and is parsed as the rest of
    // the line, exactly as the graded=1 and no_settled_run lines already guarantee.
    const int shotAt = landing.indexOf(QStringLiteral("shot="));
    QVERIFY(shotAt > landing.indexOf(QStringLiteral("meter_jump=")));
    QCOMPARE(landing.mid(shotAt), QStringLiteral("shot=Left Fade"));
}

